SELECT 'crq-grammar-73068678d66b7a7d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The tense is fixed by the pattern, not by the sentence: 前に always takes the plain present and 後で always takes た, however long ago it all happened.","point":"〜前に / 〜後で","before":[{"t":"The tense is fixed by the pattern, not by the sentence: "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" always takes the plain present and "},{"t":"後","r":"あと"},{"t":"で"},{"t":" always takes "},{"t":"た"},{"t":", however long ago it all happened."}],"after":[{"t":"The tense is fixed by the pattern, not by the sentence: "},{"t":"前","r":"まえ"},{"t":"に"},{"t":" always takes the plain present and "},{"t":"後","r":"あと"},{"t":"で"},{"t":" always takes "},{"t":"た"},{"t":", however long ago it all happened."}],"changes":[{"word":"前に","from":[{"t":"前","r":"ぜん"},{"t":"に"}],"to":[{"t":"前","r":"まえ"},{"t":"に"}],"why":"前に is まえに."}]}'::jsonb, '{"furigana":[{"t":"The tense is fixed by the pattern, not by the sentence: "},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" always takes the plain present and "},{"r":"あと","t":"後"},{"t":"で"},{"t":" always takes "},{"t":"た"},{"t":", however long ago it all happened."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '73068678d66b7a7dbd7209530b5e7a4e2343b9c3584be261778cd1eaf9ce416a' AND l.code = 'ja'
  AND g.segments = '[{"t":"The tense is fixed by the pattern, not by the sentence: "},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" always takes the plain present and "},{"r":"あと","t":"後"},{"t":"で"},{"t":" always takes "},{"t":"た"},{"t":", however long ago it all happened."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

