FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'c82f0dd502ebfc5c2c9cd3e6affdf7d1e1e0f09a1a42afe4d39c397db482d504' AND l.code = 'ja'
  AND g.segments = '[{"t":"が"},{"t":" identifies who or what performs an action or holds a state, and typically introduces something new. It is required with "},{"r":"ず","t":"好"},{"t":"き"},{"t":", "},{"r":"じょうず","t":"上手"},{"t":", "},{"t":"ある"},{"t":"/"},{"t":"いる"},{"t":" and question words: "},{"r":"だれ","t":"誰"},{"t":"が"},{"r":"らい","t":"来"},{"t":"ましたか"},{"t":"。"}]'::jsonb
