FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '95fc26c649c76599004ec5659d9182677dcf109ee79e4795f2ac98fa3a4e3ceb' AND l.code = 'ja'
  AND g.segments = '[{"t":"Because it is built on "},{"t":"た"},{"t":", "},{"t":"たら"},{"t":" always looks at B from a point where A is already finished. That is why it accepts requests and intentions that "},{"t":"と"},{"t":" rejects: "},{"r":"き","t":"着"},{"t":"いたら"},{"r":"でんわ","t":"電話"},{"t":"してください"},{"t":"."}]'::jsonb
