SELECT 'crq-grammar-8a27eedd9ac9869c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Japanese also has the \"suffering passive\", which English cannot do: 雨に降られた, \"I was rained on\". The verb is intransitive, so there is no object to promote; the passive is marking that it happened TO you.","point":"受身形 (passive)","before":[{"t":"Japanese also has the \"suffering passive\", which English cannot do: "},{"t":"雨","r":"あめ"},{"t":"に"},{"t":"降","r":"お"},{"t":"られた"},{"t":", \"I was rained on\". The verb is intransitive, so there is no object to promote; the passive is marking that it happened TO you."}],"after":[{"t":"Japanese also has the \"suffering passive\", which English cannot do: "},{"t":"雨","r":"あめ"},{"t":"に"},{"t":"降","r":"ふ"},{"t":"られた"},{"t":", \"I was rained on\". The verb is intransitive, so there is no object to promote; the passive is marking that it happened TO you."}],"changes":[{"word":"降られた","from":[{"t":"降","r":"お"},{"t":"られた"}],"to":[{"t":"降","r":"ふ"},{"t":"られた"}],"why":"Rain falls is ふる."}]}'::jsonb, '{"furigana":[{"t":"Japanese also has the \"suffering passive\", which English cannot do: "},{"r":"あめ","t":"雨"},{"t":"に"},{"r":"お","t":"降"},{"t":"られた"},{"t":", \"I was rained on\". The verb is intransitive, so there is no object to promote; the passive is marking that it happened TO you."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '8a27eedd9ac9869c42b661a503e1705c31ca1cb7bc9cb9784bbdb0a55554eff5' AND l.code = 'ja'
  AND g.segments = '[{"t":"Japanese also has the \"suffering passive\", which English cannot do: "},{"r":"あめ","t":"雨"},{"t":"に"},{"r":"お","t":"降"},{"t":"られた"},{"t":", \"I was rained on\". The verb is intransitive, so there is no object to promote; the passive is marking that it happened TO you."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

