SELECT 'crq-grammar-0726814b010faa74', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"へ emphasises the heading; に emphasises arrival. 東京に行く says you got there, 東京へ行く says you set off that way, a difference English does not mark at all.","point":"へ (toward)","before":[{"t":"へ"},{"t":" emphasises the heading; "},{"t":"に"},{"t":" emphasises arrival. "},{"t":"東","r":"とん"},{"t":"京に"},{"t":"行","r":"い"},{"t":"く"},{"t":" says you got there, "},{"t":"東","r":"とん"},{"t":"京へ"},{"t":"行","r":"い"},{"t":"く"},{"t":" says you set off that way, a difference English does not mark at all."}],"after":[{"t":"へ"},{"t":" emphasises the heading; "},{"t":"に"},{"t":" emphasises arrival. "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":"行","r":"い"},{"t":"く"},{"t":" says you got there, "},{"t":"東京","r":"とうきょう"},{"t":"へ"},{"t":"行","r":"い"},{"t":"く"},{"t":" says you set off that way, a difference English does not mark at all."}],"changes":[{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."}]}'::jsonb, '{"furigana":[{"t":"へ"},{"t":" emphasises the heading; "},{"t":"に"},{"t":" emphasises arrival. "},{"r":"とん","t":"東"},{"t":"京に"},{"r":"い","t":"行"},{"t":"く"},{"t":" says you got there, "},{"r":"とん","t":"東"},{"t":"京へ"},{"r":"い","t":"行"},{"t":"く"},{"t":" says you set off that way, a difference English does not mark at all."}]}'::jsonb, 'ai', 900, 'pending'
