SELECT 'crq-grammar-157e40d47d371a88', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The trap is that 〜いる and 〜える do not guarantee ichidan. 帰る, 入る, 走る and 切る all look ichidan and are godan. There is no rule that catches them; they are a short list you meet one at a time, and every learner conjugates 帰る wrongly at least once.","point":"Verb classes","before":[{"t":"The trap is that 〜"},{"t":"いる"},{"t":" and 〜"},{"t":"える"},{"t":" do not guarantee ichidan. "},{"t":"帰","r":"かえ"},{"t":"る"},{"t":", "},{"t":"入","r":"い"},{"t":"る"},{"t":", "},{"t":"走","r":"はし"},{"t":"る"},{"t":" and "},{"t":"切","r":"き"},{"t":"る"},{"t":" all look ichidan and are godan. There is no rule that catches them; they are a short list you meet one at a time, and every learner conjugates "},{"t":"帰","r":"かえ"},{"t":"る"},{"t":" wrongly at least once."}],"after":[{"t":"The trap is that 〜"},{"t":"いる"},{"t":" and 〜"},{"t":"える"},{"t":" do not guarantee ichidan. "},{"t":"帰","r":"かえ"},{"t":"る"},{"t":", 入","r":"はい"},{"t":"る,"},{"t":" "},{"t":"走","r":"はし"},{"t":"る"},{"t":" and "},{"t":"切","r":"き"},{"t":"る"},{"t":" all look ichidan and are godan. There is no rule that catches them; they are a short list you meet one at a time, and every learner conjugates "},{"t":"帰","r":"かえ"},{"t":"る"},{"t":" wrongly at least once."}],"changes":[{"word":", 入る,","from":[{"t":", "},{"t":"入","r":"い"},{"t":"る"},{"t":","}],"to":[{"t":", 入","r":"はい"},{"t":"る,"}],"why":"Enter is はいる."}]}'::jsonb, '{"furigana":[{"t":"The trap is that 〜"},{"t":"いる"},{"t":" and 〜"},{"t":"える"},{"t":" do not guarantee ichidan. "},{"r":"かえ","t":"帰"},{"t":"る"},{"t":", "},{"r":"い","t":"入"},{"t":"る"},{"t":", "},{"r":"はし","t":"走"},{"t":"る"},{"t":" and "},{"r":"き","t":"切"},{"t":"る"},{"t":" all look ichidan and are godan. There is no rule that catches them; they are a short list you meet one at a time, and every learner conjugates "},{"r":"かえ","t":"帰"},{"t":"る"},{"t":" wrongly at least once."}]}'::jsonb, 'ai', 900, 'pending'
