-- 〜なり: や否や
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-959634ea6ef726d1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Not a separate word after all: the dictionaries derive it from the assertive なり, turned into a conjunctive particle in the early modern period. 帰るなり寝てしまった.\n\nWhat separates it from や否や and が早いか is the surprise. なり reports the second thing as immediate and out of character, which is why the subject of both halves must be the same person.","point":"〜なり","before":[{"t":"Not a separate word after all: the dictionaries derive it from the assertive "},{"t":"なり"},{"t":", turned into a conjunctive particle in the early modern period. "},{"t":"帰","r":"かえ"},{"t":"るなり"},{"t":"寝","r":"ね"},{"t":"てしまった"},{"t":".\n\nWhat separates it from "},{"t":"や"},{"t":"否","r":"ひ"},{"t":"や"},{"t":" and "},{"t":"が"},{"t":"早","r":"はや"},{"t":"いか"},{"t":" is the surprise. "},{"t":"なり"},{"t":" reports the second thing as immediate and out of character, which is why the subject of both halves must be the same person."}],"after":[{"t":"Not a separate word after all: the dictionaries derive it from the assertive "},{"t":"なり"},{"t":", turned into a conjunctive particle in the early modern period. "},{"t":"帰","r":"かえ"},{"t":"るなり"},{"t":"寝","r":"ね"},{"t":"てしまった"},{"t":".\n\nWhat separates it from "},{"t":"や"},{"t":"否","r":"いな"},{"t":"や"},{"t":" and "},{"t":"が"},{"t":"早","r":"はや"},{"t":"いか"},{"t":" is the surprise. "},{"t":"なり"},{"t":" reports the second thing as immediate and out of character, which is why the subject of both halves must be the same person."}],"changes":[{"word":"や否や","from":[{"t":"や"},{"t":"否","r":"ひ"},{"t":"や"}],"to":[{"t":"や"},{"t":"否","r":"いな"},{"t":"や"}],"why":"bare 否 also hits the 否 of 安否/否定 in prose (ひ there); limit to や否や and the explicit いな mentions; か否か is covered by #73"}]}'::jsonb, '{"furigana":[{"t":"Not a separate word after all: the dictionaries derive it from the assertive "},{"t":"なり"},{"t":", turned into a conjunctive particle in the early modern period. "},{"r":"かえ","t":"帰"},{"t":"るなり"},{"r":"ね","t":"寝"},{"t":"てしまった"},{"t":".\n\nWhat separates it from "},{"t":"や"},{"r":"ひ","t":"否"},{"t":"や"},{"t":" and "},{"t":"が"},{"r":"はや","t":"早"},{"t":"いか"},{"t":" is the surprise. "},{"t":"なり"},{"t":" reports the second thing as immediate and out of character, which is why the subject of both halves must be the same person."}]}'::jsonb, 'ai', 900, 'pending'
