INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b811d24257464da5', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"病気で休む is resting in the circumstance of illness. Nothing has been added to make it causal.\n\nThat is why で takes only a noun and never a clause, and why から and ので exist. で names a circumstance; a reason with a verb in it needs a particle that can take a whole sentence.","point":"で (cause)","before":[{"t":"病気","r":"やまいけ"},{"t":"で"},{"t":"休","r":"やす"},{"t":"む"},{"t":" is resting in the circumstance of illness. Nothing has been added to make it causal.\n\nThat is why "},{"t":"で"},{"t":" takes only a noun and never a clause, and why "},{"t":"から"},{"t":" and "},{"t":"ので"},{"t":" exist. "},{"t":"で"},{"t":" names a circumstance; a reason with a verb in it needs a particle that can take a whole sentence."}],"after":[{"t":"病気","r":"びょうき"},{"t":"で"},{"t":"休","r":"やす"},{"t":"む"},{"t":" is resting in the circumstance of illness. Nothing has been added to make it causal.\n\nThat is why "},{"t":"で"},{"t":" takes only a noun and never a clause, and why "},{"t":"から"},{"t":" and "},{"t":"ので"},{"t":" exist. "},{"t":"で"},{"t":" names a circumstance; a reason with a verb in it needs a particle that can take a whole sentence."}],"changes":[{"word":"病気","from":[{"t":"病気","r":"やまいけ"}],"to":[{"t":"病気","r":"びょうき"}],"why":"Illness is びょうき. / 病気 is びょうき."}]}'::jsonb, '{"furigana":[{"r":"やまいけ","t":"病気"},{"t":"で"},{"r":"やす","t":"休"},{"t":"む"},{"t":" is resting in the circumstance of illness. Nothing has been added to make it causal.\n\nThat is why "},{"t":"で"},{"t":" takes only a noun and never a clause, and why "},{"t":"から"},{"t":" and "},{"t":"ので"},{"t":" exist. "},{"t":"で"},{"t":" names a circumstance; a reason with a verb in it needs a particle that can take a whole sentence."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'b811d24257464da507afd3a75775210df8ac9161e759586fc3d233785fcf910c' AND l.code = 'ja'
  AND g.segments = '[{"r":"やまいけ","t":"病気"},{"t":"で"},{"r":"やす","t":"休"},{"t":"む"},{"t":" is resting in the circumstance of illness. Nothing has been added to make it causal.\n\nThat is why "},{"t":"で"},{"t":" takes only a noun and never a clause, and why "},{"t":"から"},{"t":" and "},{"t":"ので"},{"t":" exist. "},{"t":"で"},{"t":" names a circumstance; a reason with a verb in it needs a particle that can take a whole sentence."}]'::jsonb
