-- 〜たら (conditional): 着いたら, 未然形, 着けば
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-744851637be771be', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"と, ば and なら descend from particles and a copula. たら descends from たり, the same auxiliary that gave the past tense た, and it is たり in its 未然形.\n\nThat completive sense is still inside it, which is why たら means \"once X has happened\" rather than a bare hypothesis, and why it takes a request or a command after an action verb where ば cannot: 駅に着いたら電話して is natural, 着けば電話して is not.","point":"〜たら (conditional)","before":[{"t":"と"},{"t":", "},{"t":"ば"},{"t":" and "},{"t":"なら"},{"t":" descend from particles and a copula. "},{"t":"たら"},{"t":" descends from "},{"t":"たり"},{"t":", the same auxiliary that gave the past tense "},{"t":"た"},{"t":", and it is "},{"t":"たり"},{"t":" in its "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":".\n\nThat completive sense is still inside it, which is why "},{"t":"たら"},{"t":" means \"once X has happened\" rather than a bare hypothesis, and why it takes a request or a command after an action verb where "},{"t":"ば"},{"t":" cannot: "},{"t":"駅","r":"えき"},{"t":"に"},{"t":"着","r":"き"},{"t":"いたら"},{"t":"電話","r":"でんわ"},{"t":"して"},{"t":" is natural, "},{"t":"着","r":"き"},{"t":"けば"},{"t":"電話","r":"でんわ"},{"t":"して"},{"t":" is not."}],"after":[{"t":"と"},{"t":", "},{"t":"ば"},{"t":" and "},{"t":"なら"},{"t":" descend from particles and a copula. "},{"t":"たら"},{"t":" descends from "},{"t":"たり"},{"t":", the same auxiliary that gave the past tense "},{"t":"た"},{"t":", and it is "},{"t":"たり"},{"t":" in its "},{"t":"未然形","r":"みぜんけい"},{"t":".\n\nThat completive sense is still inside it, which is why "},{"t":"たら"},{"t":" means \"once X has happened\" rather than a bare hypothesis, and why it takes a request or a command after an action verb where "},{"t":"ば"},{"t":" cannot: "},{"t":"駅","r":"えき"},{"t":"に"},{"t":"着","r":"つ"},{"t":"いたら"},{"t":"電話","r":"でんわ"},{"t":"して"},{"t":" is natural, "},{"t":"着","r":"つ"},{"t":"けば"},{"t":"電話","r":"でんわ"},{"t":"して"},{"t":" is not."}],"changes":[{"word":"着いたら","from":[{"t":"着","r":"き"},{"t":"いたら"}],"to":[{"t":"着","r":"つ"},{"t":"いたら"}],"why":"Arrive is つく. / 着く is つく."},{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."},{"word":"着けば","from":[{"t":"着","r":"き"},{"t":"けば"}],"to":[{"t":"着","r":"つ"},{"t":"けば"}],"why":"Arrive is つく."}]}'::jsonb, '{"furigana":[{"t":"と"},{"t":", "},{"t":"ば"},{"t":" and "},{"t":"なら"},{"t":" descend from particles and a copula. "},{"t":"たら"},{"t":" descends from "},{"t":"たり"},{"t":", the same auxiliary that gave the past tense "},{"t":"た"},{"t":", and it is "},{"t":"たり"},{"t":" in its "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":".\n\nThat completive sense is still inside it, which is why "},{"t":"たら"},{"t":" means \"once X has happened\" rather than a bare hypothesis, and why it takes a request or a command after an action verb where "},{"t":"ば"},{"t":" cannot: "},{"r":"えき","t":"駅"},{"t":"に"},{"r":"き","t":"着"},{"t":"いたら"},{"r":"でんわ","t":"電話"},{"t":"して"},{"t":" is natural, "},{"r":"き","t":"着"},{"t":"けば"},{"r":"でんわ","t":"電話"},{"t":"して"},{"t":" is not."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '744851637be771bee0f884da69905961a86d3d7d16a53644069d0f5bad0311e9' AND l.code = 'ja'
  AND g.segments = '[{"t":"と"},{"t":", "},{"t":"ば"},{"t":" and "},{"t":"なら"},{"t":" descend from particles and a copula. "},{"t":"たら"},{"t":" descends from "},{"t":"たり"},{"t":", the same auxiliary that gave the past tense "},{"t":"た"},{"t":", and it is "},{"t":"たり"},{"t":" in its "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":".\n\nThat completive sense is still inside it, which is why "},{"t":"たら"},{"t":" means \"once X has happened\" rather than a bare hypothesis, and why it takes a request or a command after an action verb where "},{"t":"ば"},{"t":" cannot: "},{"r":"えき","t":"駅"},{"t":"に"},{"r":"き","t":"着"},{"t":"いたら"},{"r":"でんわ","t":"電話"},{"t":"して"},{"t":" is natural, "},{"r":"き","t":"着"},{"t":"けば"},{"r":"でんわ","t":"電話"},{"t":"して"},{"t":" is not."}]'::jsonb
