-- 〜ほど: 疲れた
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-f6a384181639b134', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Still written 程 in formal prose and still a plain noun: 程度 is \"degree\", 身の程 is one''s station.\n\nBoth patterns are that noun. 死ぬほど疲れた measures tiredness against dying; 高いほどいい pairs two extents and lets them rise together. The \"the more, the more\" construction is not a special form but the predicate doubled around the noun: 高ければ高いほど repeats 高い, and ほど measures the second against the first.","point":"〜ほど","before":[{"t":"Still written "},{"t":"程","r":"ほど"},{"t":" in formal prose and still a plain noun: "},{"t":"程度","r":"ていど"},{"t":" is \"degree\", "},{"t":"身","r":"み"},{"t":"の"},{"t":"程","r":"ほど"},{"t":" is one''s station.\n\nBoth patterns are that noun. "},{"t":"死","r":"し"},{"t":"ぬほど"},{"t":"疲","r":"づか"},{"t":"れた"},{"t":" measures tiredness against dying; "},{"t":"高","r":"たか"},{"t":"いほどいい"},{"t":" pairs two extents and lets them rise together. The \"the more, the more\" construction is not a special form but the predicate doubled around the noun: "},{"t":"高","r":"たか"},{"t":"ければ"},{"t":"高","r":"たか"},{"t":"いほど"},{"t":" repeats "},{"t":"高","r":"たか"},{"t":"い"},{"t":", and "},{"t":"ほど"},{"t":" measures the second against the first."}],"after":[{"t":"Still written "},{"t":"程","r":"ほど"},{"t":" in formal prose and still a plain noun: "},{"t":"程度","r":"ていど"},{"t":" is \"degree\", "},{"t":"身","r":"み"},{"t":"の"},{"t":"程","r":"ほど"},{"t":" is one''s station.\n\nBoth patterns are that noun. "},{"t":"死","r":"し"},{"t":"ぬほど"},{"t":"疲","r":"つか"},{"t":"れた"},{"t":" measures tiredness against dying; "},{"t":"高","r":"たか"},{"t":"いほどいい"},{"t":" pairs two extents and lets them rise together. The \"the more, the more\" construction is not a special form but the predicate doubled around the noun: "},{"t":"高","r":"たか"},{"t":"ければ"},{"t":"高","r":"たか"},{"t":"いほど"},{"t":" repeats "},{"t":"高","r":"たか"},{"t":"い"},{"t":", and "},{"t":"ほど"},{"t":" measures the second against the first."}],"changes":[{"word":"疲れた","from":[{"t":"疲","r":"づか"},{"t":"れた"}],"to":[{"t":"疲","r":"つか"},{"t":"れた"}],"why":"Tired is つかれる."}]}'::jsonb, '{"furigana":[{"t":"Still written "},{"r":"ほど","t":"程"},{"t":" in formal prose and still a plain noun: "},{"r":"ていど","t":"程度"},{"t":" is \"degree\", "},{"r":"み","t":"身"},{"t":"の"},{"r":"ほど","t":"程"},{"t":" is one''s station.\n\nBoth patterns are that noun. "},{"r":"し","t":"死"},{"t":"ぬほど"},{"r":"づか","t":"疲"},{"t":"れた"},{"t":" measures tiredness against dying; "},{"r":"たか","t":"高"},{"t":"いほどいい"},{"t":" pairs two extents and lets them rise together. The \"the more, the more\" construction is not a special form but the predicate doubled around the noun: "},{"r":"たか","t":"高"},{"t":"ければ"},{"r":"たか","t":"高"},{"t":"いほど"},{"t":" repeats "},{"r":"たか","t":"高"},{"t":"い"},{"t":", and "},{"t":"ほど"},{"t":" measures the second against the first."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'f6a384181639b134b7966f5af115f311a005d96719c07af46f7ca9e7228b0f99' AND l.code = 'ja'
  AND g.segments = '[{"t":"Still written "},{"r":"ほど","t":"程"},{"t":" in formal prose and still a plain noun: "},{"r":"ていど","t":"程度"},{"t":" is \"degree\", "},{"r":"み","t":"身"},{"t":"の"},{"r":"ほど","t":"程"},{"t":" is one''s station.\n\nBoth patterns are that noun. "},{"r":"し","t":"死"},{"t":"ぬほど"},{"r":"づか","t":"疲"},{"t":"れた"},{"t":" measures tiredness against dying; "},{"r":"たか","t":"高"},{"t":"いほどいい"},{"t":" pairs two extents and lets them rise together. The \"the more, the more\" construction is not a special form but the predicate doubled around the noun: "},{"r":"たか","t":"高"},{"t":"ければ"},{"r":"たか","t":"高"},{"t":"いほど"},{"t":" repeats "},{"r":"たか","t":"高"},{"t":"い"},{"t":", and "},{"t":"ほど"},{"t":" measures the second against the first."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
