-- 〜について: 気が付く, 手に付く, 付く
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-778c6ca01da82e2d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"付く is the verb in 気が付く and 手に付く. について fastens the sentence onto a topic and then talks about it.\n\nThe attaching image is why について takes a topic rather than an object, and why it sits so comfortably in the language of reports and papers: this is the thing the discussion is fixed to.","point":"〜について","before":[{"t":"付","r":"づ"},{"t":"く"},{"t":" is the verb in "},{"t":"気","r":"げ"},{"t":"が"},{"t":"付","r":"づ"},{"t":"く"},{"t":" and "},{"t":"手","r":"て"},{"t":"に"},{"t":"付","r":"づ"},{"t":"く"},{"t":". "},{"t":"について"},{"t":" fastens the sentence onto a topic and then talks about it.\n\nThe attaching image is why "},{"t":"について"},{"t":" takes a topic rather than an object, and why it sits so comfortably in the language of reports and papers: this is the thing the discussion is fixed to."}],"after":[{"t":"付","r":"つ"},{"t":"く"},{"t":" is the verb in "},{"t":"気","r":"き"},{"t":"が"},{"t":"付","r":"つ"},{"t":"く"},{"t":" and "},{"t":"手","r":"て"},{"t":"に"},{"t":"付","r":"つ"},{"t":"く"},{"t":". "},{"t":"について"},{"t":" fastens the sentence onto a topic and then talks about it.\n\nThe attaching image is why "},{"t":"について"},{"t":" takes a topic rather than an object, and why it sits so comfortably in the language of reports and papers: this is the thing the discussion is fixed to."}],"changes":[{"word":"気が付く","from":[{"t":"気","r":"げ"},{"t":"が"},{"t":"付","r":"づ"},{"t":"く"}],"to":[{"t":"気","r":"き"},{"t":"が"},{"t":"付","r":"つ"},{"t":"く"}],"why":"気が付く is きがつく."},{"word":"手に付く","from":[{"t":"手","r":"て"},{"t":"に"},{"t":"付","r":"づ"},{"t":"く"}],"to":[{"t":"手","r":"て"},{"t":"に"},{"t":"付","r":"つ"},{"t":"く"}],"why":"付く is つく."},{"word":"付く","from":[{"t":"付","r":"づ"},{"t":"く"}],"to":[{"t":"付","r":"つ"},{"t":"く"}],"why":"付く is つく."}]}'::jsonb, '{"furigana":[{"r":"づ","t":"付"},{"t":"く"},{"t":" is the verb in "},{"r":"げ","t":"気"},{"t":"が"},{"r":"づ","t":"付"},{"t":"く"},{"t":" and "},{"r":"て","t":"手"},{"t":"に"},{"r":"づ","t":"付"},{"t":"く"},{"t":". "},{"t":"について"},{"t":" fastens the sentence onto a topic and then talks about it.\n\nThe attaching image is why "},{"t":"について"},{"t":" takes a topic rather than an object, and why it sits so comfortably in the language of reports and papers: this is the thing the discussion is fixed to."}]}'::jsonb, 'ai', 900, 'pending'
