SELECT 'crq-grammar-660d02e926bda926', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same 様 that gives ようだ and ように. ようがない says no manner of doing it exists at all.\n\nThat is stronger than できない, which says you cannot; ようがない says nobody could, because there is no method to reach for. 連絡しようがない is not reluctance or inability but the absence of any channel.","point":"〜ようがない","before":[{"t":"The same "},{"t":"様","r":"さま"},{"t":" that gives "},{"t":"ようだ"},{"t":" and "},{"t":"ように"},{"t":". "},{"t":"ようがない"},{"t":" says no manner of doing it exists at all.\n\nThat is stronger than "},{"t":"できない"},{"t":", which says you cannot; "},{"t":"ようがない"},{"t":" says nobody could, because there is no method to reach for. "},{"t":"連絡","r":"れんらく"},{"t":"しようがない"},{"t":" is not reluctance or inability but the absence of any channel."}],"after":[{"t":"The "},{"t":"same 様","r":"よう"},{"t":" that gives "},{"t":"ようだ"},{"t":" and "},{"t":"ように"},{"t":". "},{"t":"ようがない"},{"t":" says no manner of doing it exists at all.\n\nThat is stronger than "},{"t":"できない"},{"t":", which says you cannot; "},{"t":"ようがない"},{"t":" says nobody could, because there is no method to reach for. "},{"t":"連絡","r":"れんらく"},{"t":"しようがない"},{"t":" is not reluctance or inability but the absence of any channel."}],"changes":[{"word":"same 様","from":[{"t":"same "},{"t":"様","r":"さま"}],"to":[{"t":"same 様","r":"よう"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"}]}'::jsonb, '{"furigana":[{"t":"The same "},{"r":"さま","t":"様"},{"t":" that gives "},{"t":"ようだ"},{"t":" and "},{"t":"ように"},{"t":". "},{"t":"ようがない"},{"t":" says no manner of doing it exists at all.\n\nThat is stronger than "},{"t":"できない"},{"t":", which says you cannot; "},{"t":"ようがない"},{"t":" says nobody could, because there is no method to reach for. "},{"r":"れんらく","t":"連絡"},{"t":"しようがない"},{"t":" is not reluctance or inability but the absence of any channel."}]}'::jsonb, 'ai', 900, 'pending'
