-- 〜ずにはいられない: 得ない
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-2874a9ba42f51448', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ず is the Old Japanese negative, the same one in ざるを得ない and にかかわらず, carried inside an otherwise modern frame: いられない is the potential negative of いる, which the classical language did not form this way.\n\nSo the sentence says you cannot stay in the condition of not doing it. 笑わずにはいられない is not a decision to laugh but an inability to keep from it, which is why the pattern belongs to feelings that overtake the speaker rather than to choices.","point":"〜ずにはいられない","before":[{"t":"ず"},{"t":" is the Old Japanese negative, the same one in "},{"t":"ざるを"},{"t":"得","r":"う"},{"t":"ない"},{"t":" and "},{"t":"にかかわらず"},{"t":", carried inside an otherwise modern frame: "},{"t":"いられない"},{"t":" is the potential negative of "},{"t":"いる"},{"t":", which the classical language did not form this way.\n\nSo the sentence says you cannot stay in the condition of not doing it. "},{"t":"笑","r":"わら"},{"t":"わずにはいられない"},{"t":" is not a decision to laugh but an inability to keep from it, which is why the pattern belongs to feelings that overtake the speaker rather than to choices."}],"after":[{"t":"ず"},{"t":" is the Old Japanese negative, the same one in "},{"t":"ざるを"},{"t":"得","r":"え"},{"t":"ない"},{"t":" and "},{"t":"にかかわらず"},{"t":", carried inside an otherwise modern frame: "},{"t":"いられない"},{"t":" is the potential negative of "},{"t":"いる"},{"t":", which the classical language did not form this way.\n\nSo the sentence says you cannot stay in the condition of not doing it. "},{"t":"笑","r":"わら"},{"t":"わずにはいられない"},{"t":" is not a decision to laugh but an inability to keep from it, which is why the pattern belongs to feelings that overtake the speaker rather than to choices."}],"changes":[{"word":"得ない","from":[{"t":"得","r":"う"},{"t":"ない"}],"to":[{"t":"得","r":"え"},{"t":"ない"}],"why":"得ない is えない."}]}'::jsonb, '{"furigana":[{"t":"ず"},{"t":" is the Old Japanese negative, the same one in "},{"t":"ざるを"},{"r":"う","t":"得"},{"t":"ない"},{"t":" and "},{"t":"にかかわらず"},{"t":", carried inside an otherwise modern frame: "},{"t":"いられない"},{"t":" is the potential negative of "},{"t":"いる"},{"t":", which the classical language did not form this way.\n\nSo the sentence says you cannot stay in the condition of not doing it. "},{"r":"わら","t":"笑"},{"t":"わずにはいられない"},{"t":" is not a decision to laugh but an inability to keep from it, which is why the pattern belongs to feelings that overtake the speaker rather than to choices."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '2874a9ba42f514480630c73d63102b87fd5570c8f591f556b0e911d712ef2519' AND l.code = 'ja'
  AND g.segments = '[{"t":"ず"},{"t":" is the Old Japanese negative, the same one in "},{"t":"ざるを"},{"r":"う","t":"得"},{"t":"ない"},{"t":" and "},{"t":"にかかわらず"},{"t":", carried inside an otherwise modern frame: "},{"t":"いられない"},{"t":" is the potential negative of "},{"t":"いる"},{"t":", which the classical language did not form this way.\n\nSo the sentence says you cannot stay in the condition of not doing it. "},{"r":"わら","t":"笑"},{"t":"わずにはいられない"},{"t":" is not a decision to laugh but an inability to keep from it, which is why the pattern belongs to feelings that overtake the speaker rather than to choices."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜なしには: 君の
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-19f6d262d1ab1a4e', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"なし is the Old Japanese adjective behind modern ない. なしに alone simply means without; adding は marks that absence as the topic and sets up a denial about it.\n\nSo なしには must be answered by a negative: 君の助けなしにはできなかった. The は has raised the without-ness as the thing being discussed, and the sentence exists to say what it ruled out.","point":"〜なしには","before":[{"t":"なし"},{"t":" is the Old Japanese adjective behind modern "},{"t":"ない"},{"t":". "},{"t":"なしに"},{"t":" alone simply means without; adding "},{"t":"は"},{"t":" marks that absence as the topic and sets up a denial about it.\n\nSo "},{"t":"なしには"},{"t":" must be answered by a negative: "},{"t":"君","r":"ぎみ"},{"t":"の"},{"t":"助","r":"たす"},{"t":"けなしにはできなかった"},{"t":". The "},{"t":"は"},{"t":" has raised the without-ness as the thing being discussed, and the sentence exists to say what it ruled out."}],"after":[{"t":"なし"},{"t":" is the Old Japanese adjective behind modern "},{"t":"ない"},{"t":". "},{"t":"なしに"},{"t":" alone simply means without; adding "},{"t":"は"},{"t":" marks that absence as the topic and sets up a denial about it.\n\nSo "},{"t":"なしには"},{"t":" must be answered by a negative: "},{"t":"君","r":"きみ"},{"t":"の"},{"t":"助","r":"たす"},{"t":"けなしにはできなかった"},{"t":". The "},{"t":"は"},{"t":" has raised the without-ness as the thing being discussed, and the sentence exists to say what it ruled out."}],"changes":[{"word":"君の","from":[{"t":"君","r":"ぎみ"},{"t":"の"}],"to":[{"t":"君","r":"きみ"},{"t":"の"}],"why":"You is きみ. / 君 is きみ."}]}'::jsonb, '{"furigana":[{"t":"なし"},{"t":" is the Old Japanese adjective behind modern "},{"t":"ない"},{"t":". "},{"t":"なしに"},{"t":" alone simply means without; adding "},{"t":"は"},{"t":" marks that absence as the topic and sets up a denial about it.\n\nSo "},{"t":"なしには"},{"t":" must be answered by a negative: "},{"r":"ぎみ","t":"君"},{"t":"の"},{"r":"たす","t":"助"},{"t":"けなしにはできなかった"},{"t":". The "},{"t":"は"},{"t":" has raised the without-ness as the thing being discussed, and the sentence exists to say what it ruled out."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '19f6d262d1ab1a4e31231aba6c9ad4373b10a37ae4236cb20cd3e7836359dd8e' AND l.code = 'ja'
  AND g.segments = '[{"t":"なし"},{"t":" is the Old Japanese adjective behind modern "},{"t":"ない"},{"t":". "},{"t":"なしに"},{"t":" alone simply means without; adding "},{"t":"は"},{"t":" marks that absence as the topic and sets up a denial about it.\n\nSo "},{"t":"なしには"},{"t":" must be answered by a negative: "},{"r":"ぎみ","t":"君"},{"t":"の"},{"r":"たす","t":"助"},{"t":"けなしにはできなかった"},{"t":". The "},{"t":"は"},{"t":" has raised the without-ness as the thing being discussed, and the sentence exists to say what it ruled out."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜ゆえに: 故 is the kanji, 病気, 故に
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-3fb3d03d008ce576', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"故 is the kanji assigned to it; the こ of 事故 is that character''s unrelated Chinese reading. It is an ordinary noun, which is why it takes の after another noun: 病気ゆえに, 貧しさの故に.\n\nIt is the most formal of the reason words, above ため and から, because it survives mainly in classical and written registers. Descartes in Japanese is 我思う、ゆえに我あり, and the register is exactly right for it.","point":"〜ゆえに","before":[{"t":"故","r":"こ"},{"t":" is the kanji assigned to it; the "},{"t":"こ"},{"t":" of "},{"t":"事故","r":"じこ"},{"t":" is that character''s unrelated Chinese reading. It is an ordinary noun, which is why it takes "},{"t":"の"},{"t":" after another noun: "},{"t":"病気","r":"やまいけ"},{"t":"ゆえに"},{"t":", "},{"t":"貧","r":"まず"},{"t":"しさの"},{"t":"故","r":"こ"},{"t":"に"},{"t":".\n\nIt is the most formal of the reason words, above "},{"t":"ため"},{"t":" and "},{"t":"から"},{"t":", because it survives mainly in classical and written registers. Descartes in Japanese is "},{"t":"我","r":"われ"},{"t":"思","r":"おも"},{"t":"う"},{"t":"、"},{"t":"ゆえに"},{"t":"我","r":"われ"},{"t":"あり"},{"t":", and the register is exactly right for it."}],"after":[{"t":"故","r":"ゆえ"},{"t":" is the kanji"},{"t":" assigned to it; the "},{"t":"こ"},{"t":" of "},{"t":"事故","r":"じこ"},{"t":" is that character''s unrelated Chinese reading. It is an ordinary noun, which is why it takes "},{"t":"の"},{"t":" after another noun: "},{"t":"病気","r":"びょうき"},{"t":"ゆえに"},{"t":", "},{"t":"貧","r":"まず"},{"t":"しさの"},{"t":"故","r":"ゆえ"},{"t":"に"},{"t":".\n\nIt is the most formal of the reason words, above "},{"t":"ため"},{"t":" and "},{"t":"から"},{"t":", because it survives mainly in classical and written registers. Descartes in Japanese is "},{"t":"我","r":"われ"},{"t":"思","r":"おも"},{"t":"う"},{"t":"、"},{"t":"ゆえに"},{"t":"我","r":"われ"},{"t":"あり"},{"t":", and the register is exactly right for it."}],"changes":[{"word":"故 is the kanji","from":[{"t":"故","r":"こ"},{"t":" is the kanji"}],"to":[{"t":"故","r":"ゆえ"},{"t":" is the kanji"}],"why":"故 is ゆえ."},{"word":"病気","from":[{"t":"病気","r":"やまいけ"}],"to":[{"t":"病気","r":"びょうき"}],"why":"Illness is びょうき. / 病気 is びょうき."},{"word":"故に","from":[{"t":"故","r":"こ"},{"t":"に"}],"to":[{"t":"故","r":"ゆえ"},{"t":"に"}],"why":"故 is ゆえ."}]}'::jsonb, '{"furigana":[{"r":"こ","t":"故"},{"t":" is the kanji assigned to it; the "},{"t":"こ"},{"t":" of "},{"r":"じこ","t":"事故"},{"t":" is that character''s unrelated Chinese reading. It is an ordinary noun, which is why it takes "},{"t":"の"},{"t":" after another noun: "},{"r":"やまいけ","t":"病気"},{"t":"ゆえに"},{"t":", "},{"r":"まず","t":"貧"},{"t":"しさの"},{"r":"こ","t":"故"},{"t":"に"},{"t":".\n\nIt is the most formal of the reason words, above "},{"t":"ため"},{"t":" and "},{"t":"から"},{"t":", because it survives mainly in classical and written registers. Descartes in Japanese is "},{"r":"われ","t":"我"},{"r":"おも","t":"思"},{"t":"う"},{"t":"、"},{"t":"ゆえに"},{"r":"われ","t":"我"},{"t":"あり"},{"t":", and the register is exactly right for it."}]}'::jsonb, 'ai', 900, 'pending'
