-- そうですか / そうですね: from 様 or
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-ca75c19afb41f8c1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same そ as それ and そこ, in an adverbial form: そう means \"like that\". そうです is \"it is that way\", and そうですか asks whether it is.\n\nWorth keeping apart from the そう of そうだ, which is a different word: the dictionaries derive that one from 様 or from the character 相, not from the demonstrative. The shared spelling 然 covers several morphemes and is not evidence of kinship.","point":"そうですか / そうですね","before":[{"t":"The same "},{"t":"そ"},{"t":" as "},{"t":"それ"},{"t":" and "},{"t":"そこ"},{"t":", in an adverbial form: "},{"t":"そう"},{"t":" means \"like that\". "},{"t":"そうです"},{"t":" is \"it is that way\", and "},{"t":"そうですか"},{"t":" asks whether it is.\n\nWorth keeping apart from the "},{"t":"そう"},{"t":" of "},{"t":"そうだ"},{"t":", which is a different word: the dictionaries derive that one from "},{"t":"様","r":"さま"},{"t":" or from the character "},{"t":"相","r":"あい"},{"t":", not from the demonstrative. The shared spelling "},{"t":"然"},{"t":" covers several morphemes and is not evidence of kinship."}],"after":[{"t":"The same "},{"t":"そ"},{"t":" as "},{"t":"それ"},{"t":" and "},{"t":"そこ"},{"t":", in an adverbial form: "},{"t":"そう"},{"t":" means \"like that\". "},{"t":"そうです"},{"t":" is \"it is that way\", and "},{"t":"そうですか"},{"t":" asks whether it is.\n\nWorth keeping apart from the "},{"t":"そう"},{"t":" of "},{"t":"そうだ"},{"t":", which is a different word: the dictionaries derive that one "},{"t":"from 様","r":"よう"},{"t":" or"},{"t":" from the character "},{"t":"相","r":"あい"},{"t":", not from the demonstrative. The shared spelling "},{"t":"然"},{"t":" covers several morphemes and is not evidence of kinship."}],"changes":[{"word":"from 様 or","from":[{"t":"from "},{"t":"様","r":"さま"},{"t":" or"}],"to":[{"t":"from 様","r":"よう"},{"t":" or"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"}]}'::jsonb, '{"furigana":[{"t":"The same "},{"t":"そ"},{"t":" as "},{"t":"それ"},{"t":" and "},{"t":"そこ"},{"t":", in an adverbial form: "},{"t":"そう"},{"t":" means \"like that\". "},{"t":"そうです"},{"t":" is \"it is that way\", and "},{"t":"そうですか"},{"t":" asks whether it is.\n\nWorth keeping apart from the "},{"t":"そう"},{"t":" of "},{"t":"そうだ"},{"t":", which is a different word: the dictionaries derive that one from "},{"r":"さま","t":"様"},{"t":" or from the character "},{"r":"あい","t":"相"},{"t":", not from the demonstrative. The shared spelling "},{"t":"然"},{"t":" covers several morphemes and is not evidence of kinship."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'ca75c19afb41f8c1364499a2c45ea179b72a9492780738697c771571ac96d3b7' AND l.code = 'ja'
  AND g.segments = '[{"t":"The same "},{"t":"そ"},{"t":" as "},{"t":"それ"},{"t":" and "},{"t":"そこ"},{"t":", in an adverbial form: "},{"t":"そう"},{"t":" means \"like that\". "},{"t":"そうです"},{"t":" is \"it is that way\", and "},{"t":"そうですか"},{"t":" asks whether it is.\n\nWorth keeping apart from the "},{"t":"そう"},{"t":" of "},{"t":"そうだ"},{"t":", which is a different word: the dictionaries derive that one from "},{"r":"さま","t":"様"},{"t":" or from the character "},{"r":"あい","t":"相"},{"t":", not from the demonstrative. The shared spelling "},{"t":"然"},{"t":" covers several morphemes and is not evidence of kinship."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜ずつ: 日国
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-af1b0987df086aa4', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"日国 offers that account with a hedge, and the word has been in use since the Heian period. The older kana was づつ, still seen; the change to ずつ is orthographic rather than a change in the word.\n\nWhat it does is distribute: 一つずつ hands out one apiece, 少しずつ a little at a time. It always follows a quantity, because there has to be something to share out.","point":"〜ずつ","before":[{"t":"日","r":"にち"},{"t":"国","r":"くに"},{"t":" offers that account with a hedge, and the word has been in use since the Heian period. The older kana was "},{"t":"づつ"},{"t":", still seen; the change to "},{"t":"ずつ"},{"t":" is orthographic rather than a change in the word.\n\nWhat it does is distribute: "},{"t":"一","r":"ひと"},{"t":"つずつ"},{"t":" hands out one apiece, "},{"t":"少","r":"すこ"},{"t":"しずつ"},{"t":" a little at a time. It always follows a quantity, because there has to be something to share out."}],"after":[{"t":"日国","r":"にっこく"},{"t":" offers that account with a hedge, and the word has been in use since the Heian period. The older kana was "},{"t":"づつ"},{"t":", still seen; the change to "},{"t":"ずつ"},{"t":" is orthographic rather than a change in the word.\n\nWhat it does is distribute: "},{"t":"一","r":"ひと"},{"t":"つずつ"},{"t":" hands out one apiece, "},{"t":"少","r":"すこ"},{"t":"しずつ"},{"t":" a little at a time. It always follows a quantity, because there has to be something to share out."}],"changes":[{"word":"日国","from":[{"t":"日","r":"にち"},{"t":"国","r":"くに"}],"to":[{"t":"日国","r":"にっこく"}],"why":"Abbreviation read にっこく. / 日国 is にっこく."}]}'::jsonb, '{"furigana":[{"r":"にち","t":"日"},{"r":"くに","t":"国"},{"t":" offers that account with a hedge, and the word has been in use since the Heian period. The older kana was "},{"t":"づつ"},{"t":", still seen; the change to "},{"t":"ずつ"},{"t":" is orthographic rather than a change in the word.\n\nWhat it does is distribute: "},{"r":"ひと","t":"一"},{"t":"つずつ"},{"t":" hands out one apiece, "},{"r":"すこ","t":"少"},{"t":"しずつ"},{"t":" a little at a time. It always follows a quantity, because there has to be something to share out."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'af1b0987df086aa45c184f7b64ac108bce2e2a33747a353ab7ea64590c56ebc6' AND l.code = 'ja'
  AND g.segments = '[{"r":"にち","t":"日"},{"r":"くに","t":"国"},{"t":" offers that account with a hedge, and the word has been in use since the Heian period. The older kana was "},{"t":"づつ"},{"t":", still seen; the change to "},{"t":"ずつ"},{"t":" is orthographic rather than a change in the word.\n\nWhat it does is distribute: "},{"r":"ひと","t":"一"},{"t":"つずつ"},{"t":" hands out one apiece, "},{"r":"すこ","t":"少"},{"t":"しずつ"},{"t":" a little at a time. It always follows a quantity, because there has to be something to share out."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

