-- 〜前に / 〜後で: 寝る前, 前に
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-df25857bef02ed9d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"寝る前に takes the plain form because the sleeping has not happened at the point named; 寝た後で takes the past because it has. Neither is agreeing with the main clause.\n\nThe particles differ for the same reason. 前に names a point before, so に; 後で names the circumstances after, so で. Both are ordinary nouns behaving ordinarily.","point":"〜前に / 〜後で","before":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" takes the plain form because the sleeping has not happened at the point named; "},{"t":"寝","r":"ね"},{"t":"た"},{"t":"後","r":"あと"},{"t":"で"},{"t":" takes the past because it has. Neither is agreeing with the main clause.\n\nThe particles differ for the same reason. "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" names a point before, so "},{"t":"に"},{"t":"; "},{"t":"後","r":"あと"},{"t":"で"},{"t":" names the circumstances after, so "},{"t":"で"},{"t":". Both are ordinary nouns behaving ordinarily."}],"after":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"まえ"},{"t":"に"},{"t":" takes the plain form because the sleeping has not happened at the point named; "},{"t":"寝","r":"ね"},{"t":"た"},{"t":"後","r":"あと"},{"t":"で"},{"t":" takes the past because it has. Neither is agreeing with the main clause.\n\nThe particles differ for the same reason. "},{"t":"前","r":"まえ"},{"t":"に"},{"t":" names a point before, so "},{"t":"に"},{"t":"; "},{"t":"後","r":"あと"},{"t":"で"},{"t":" names the circumstances after, so "},{"t":"で"},{"t":". Both are ordinary nouns behaving ordinarily."}],"changes":[{"word":"寝る前","from":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"ぜん"}],"to":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"まえ"}],"why":"前 here is まえ."},{"word":"前に","from":[{"t":"前","r":"ぜん"},{"t":"に"}],"to":[{"t":"前","r":"まえ"},{"t":"に"}],"why":"前に is まえに."}]}'::jsonb, '{"furigana":[{"r":"ね","t":"寝"},{"t":"る"},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" takes the plain form because the sleeping has not happened at the point named; "},{"r":"ね","t":"寝"},{"t":"た"},{"r":"あと","t":"後"},{"t":"で"},{"t":" takes the past because it has. Neither is agreeing with the main clause.\n\nThe particles differ for the same reason. "},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" names a point before, so "},{"t":"に"},{"t":"; "},{"r":"あと","t":"後"},{"t":"で"},{"t":" names the circumstances after, so "},{"t":"で"},{"t":". Both are ordinary nouns behaving ordinarily."}]}'::jsonb, 'ai', 900, 'pending'
