-- 〜まで / 〜までに: 五時, 五時
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-c54e9ee7786213f9', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"まで marks a limit and everything up to it: 五時まで働く is working the whole stretch. Adding に names a single point inside that limit: 五時までに終わる is finishing by then, at some moment of your choosing.\n\nThat is why までに takes a one-off completion and まで takes something continuous, and why swapping them changes what you promised.","point":"〜まで / 〜までに","before":[{"t":"まで"},{"t":" marks a limit and everything up to it: "},{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"まで"},{"t":"働","r":"はたら"},{"t":"く"},{"t":" is working the whole stretch. Adding "},{"t":"に"},{"t":" names a single point inside that limit: "},{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"までに"},{"t":"終","r":"お"},{"t":"わる"},{"t":" is finishing by then, at some moment of your choosing.\n\nThat is why "},{"t":"までに"},{"t":" takes a one-off completion and "},{"t":"まで"},{"t":" takes something continuous, and why swapping them changes what you promised."}],"after":[{"t":"まで"},{"t":" marks a limit and everything up to it: "},{"t":"五時","r":"ごじ"},{"t":"まで"},{"t":"働","r":"はたら"},{"t":"く"},{"t":" is working the whole stretch. Adding "},{"t":"に"},{"t":" names a single point inside that limit: "},{"t":"五時","r":"ごじ"},{"t":"までに"},{"t":"終","r":"お"},{"t":"わる"},{"t":" is finishing by then, at some moment of your choosing.\n\nThat is why "},{"t":"までに"},{"t":" takes a one-off completion and "},{"t":"まで"},{"t":" takes something continuous, and why swapping them changes what you promised."}],"changes":[{"word":"五時","from":[{"t":"五","r":"うー"},{"t":"時","r":"とき"}],"to":[{"t":"五時","r":"ごじ"}],"why":"Five o''clock is ごじ."},{"word":"五時","from":[{"t":"五","r":"うー"},{"t":"時","r":"とき"}],"to":[{"t":"五時","r":"ごじ"}],"why":"Five o''clock is ごじ."}]}'::jsonb, '{"furigana":[{"t":"まで"},{"t":" marks a limit and everything up to it: "},{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"まで"},{"r":"はたら","t":"働"},{"t":"く"},{"t":" is working the whole stretch. Adding "},{"t":"に"},{"t":" names a single point inside that limit: "},{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"までに"},{"r":"お","t":"終"},{"t":"わる"},{"t":" is finishing by then, at some moment of your choosing.\n\nThat is why "},{"t":"までに"},{"t":" takes a one-off completion and "},{"t":"まで"},{"t":" takes something continuous, and why swapping them changes what you promised."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'c54e9ee7786213f9d4cd6c2c167ccdeeca0a3a95767076933cafc1839b3fcc9f' AND l.code = 'ja'
  AND g.segments = '[{"t":"まで"},{"t":" marks a limit and everything up to it: "},{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"まで"},{"r":"はたら","t":"働"},{"t":"く"},{"t":" is working the whole stretch. Adding "},{"t":"に"},{"t":" names a single point inside that limit: "},{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"までに"},{"r":"お","t":"終"},{"t":"わる"},{"t":" is finishing by then, at some moment of your choosing.\n\nThat is why "},{"t":"までに"},{"t":" takes a one-off completion and "},{"t":"まで"},{"t":" takes something continuous, and why swapping them changes what you promised."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- に (place of existence): 三時, 東京
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-7e9b0708f3b75348', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"机の上にあります names the point where the thing is, exactly as 三時に names the point in time and 東京に the point arrived at.\n\nWhat distinguishes it from で is not the particle but the verb. で goes with actions, which happen in a circumstance; に goes with ある and いる, which are about being at a point. 公園で遊ぶ against 公園にいる.","point":"に (place of existence)","before":[{"t":"机","r":"つくえ"},{"t":"の"},{"t":"上","r":"うえ"},{"t":"にあります"},{"t":" names the point where the thing is, exactly as "},{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"に"},{"t":" names the point in time and "},{"t":"東","r":"とん"},{"t":"京に"},{"t":" the point arrived at.\n\nWhat distinguishes it from "},{"t":"で"},{"t":" is not the particle but the verb. "},{"t":"で"},{"t":" goes with actions, which happen in a circumstance; "},{"t":"に"},{"t":" goes with "},{"t":"ある"},{"t":" and "},{"t":"いる"},{"t":", which are about being at a point. "},{"t":"公園","r":"こうえん"},{"t":"で"},{"t":"遊","r":"あそ"},{"t":"ぶ"},{"t":" against "},{"t":"公園","r":"こうえん"},{"t":"にいる"},{"t":"."}],"after":[{"t":"机","r":"つくえ"},{"t":"の"},{"t":"上","r":"うえ"},{"t":"にあります"},{"t":" names the point where the thing is, exactly as "},{"t":"三時","r":"さんじ"},{"t":"に"},{"t":" names the point in time and "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":" the point arrived at.\n\nWhat distinguishes it from "},{"t":"で"},{"t":" is not the particle but the verb. "},{"t":"で"},{"t":" goes with actions, which happen in a circumstance; "},{"t":"に"},{"t":" goes with "},{"t":"ある"},{"t":" and "},{"t":"いる"},{"t":", which are about being at a point. "},{"t":"公園","r":"こうえん"},{"t":"で"},{"t":"遊","r":"あそ"},{"t":"ぶ"},{"t":" against "},{"t":"公園","r":"こうえん"},{"t":"にいる"},{"t":"."}],"changes":[{"word":"三時","from":[{"t":"三","r":"さん"},{"t":"時","r":"とき"}],"to":[{"t":"三時","r":"さんじ"}],"why":"Three o''clock is さんじ. / 三時 is さんじ."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."}]}'::jsonb, '{"furigana":[{"r":"つくえ","t":"机"},{"t":"の"},{"r":"うえ","t":"上"},{"t":"にあります"},{"t":" names the point where the thing is, exactly as "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"に"},{"t":" names the point in time and "},{"r":"とん","t":"東"},{"t":"京に"},{"t":" the point arrived at.\n\nWhat distinguishes it from "},{"t":"で"},{"t":" is not the particle but the verb. "},{"t":"で"},{"t":" goes with actions, which happen in a circumstance; "},{"t":"に"},{"t":" goes with "},{"t":"ある"},{"t":" and "},{"t":"いる"},{"t":", which are about being at a point. "},{"r":"こうえん","t":"公園"},{"t":"で"},{"r":"あそ","t":"遊"},{"t":"ぶ"},{"t":" against "},{"r":"こうえん","t":"公園"},{"t":"にいる"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '7e9b0708f3b75348e83c49613c09607590d3fa9e21197c6a7f383f9bbf5b0e9b' AND l.code = 'ja'
  AND g.segments = '[{"r":"つくえ","t":"机"},{"t":"の"},{"r":"うえ","t":"上"},{"t":"にあります"},{"t":" names the point where the thing is, exactly as "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"に"},{"t":" names the point in time and "},{"r":"とん","t":"東"},{"t":"京に"},{"t":" the point arrived at.\n\nWhat distinguishes it from "},{"t":"で"},{"t":" is not the particle but the verb. "},{"t":"で"},{"t":" goes with actions, which happen in a circumstance; "},{"t":"に"},{"t":" goes with "},{"t":"ある"},{"t":" and "},{"t":"いる"},{"t":", which are about being at a point. "},{"r":"こうえん","t":"公園"},{"t":"で"},{"r":"あそ","t":"遊"},{"t":"ぶ"},{"t":" against "},{"r":"こうえん","t":"公園"},{"t":"にいる"},{"t":"."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜から〜まで: 一から十まで, 大阪, 五時, 九時, 東京
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-73407ffef268d96c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"から marks an origin, the same particle that gives reasons, and まで a limit reached and not passed. Put them together and you have a span with both ends named.\n\nThe pair works for time, place and quantity alike because neither particle was ever specialised: 九時から五時まで, 東京から大阪まで, 一から十まで.","point":"〜から〜まで","before":[{"t":"から"},{"t":" marks an origin, the same particle that gives reasons, and "},{"t":"まで"},{"t":" a limit reached and not passed. Put them together and you have a span with both ends named.\n\nThe pair works for time, place and quantity alike because neither particle was ever specialised: "},{"t":"九","r":"きゅう"},{"t":"時","r":"とき"},{"t":"から"},{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"まで"},{"t":", "},{"t":"東","r":"とん"},{"t":"京から"},{"t":"大","r":"たい"},{"t":"阪まで"},{"t":", "},{"t":"一","r":"いっち"},{"t":"から"},{"t":"十","r":"しー"},{"t":"まで"},{"t":"."}],"after":[{"t":"から"},{"t":" marks an origin, the same particle that gives reasons, and "},{"t":"まで"},{"t":" a limit reached and not passed. Put them together and you have a span with both ends named.\n\nThe pair works for time, place and quantity alike because neither particle was ever specialised: "},{"t":"九時","r":"くじ"},{"t":"から"},{"t":"五時","r":"ごじ"},{"t":"まで"},{"t":", "},{"t":"東京","r":"とうきょう"},{"t":"から"},{"t":"大阪","r":"おおさか"},{"t":"まで"},{"t":", "},{"t":"一","r":"いち"},{"t":"から"},{"t":"十","r":"じゅう"},{"t":"まで"},{"t":"."}],"changes":[{"word":"一から十まで","from":[{"t":"一","r":"いっち"},{"t":"から"},{"t":"十","r":"しー"},{"t":"まで"}],"to":[{"t":"一","r":"いち"},{"t":"から"},{"t":"十","r":"じゅう"},{"t":"まで"}],"why":"One to ten is いち and じゅう."},{"word":"大阪","from":[{"t":"大","r":"たい"},{"t":"阪"}],"to":[{"t":"大阪","r":"おおさか"}],"why":"Osaka is おおさか. / 大阪 is おおさか."},{"word":"五時","from":[{"t":"五","r":"うー"},{"t":"時","r":"とき"}],"to":[{"t":"五時","r":"ごじ"}],"why":"Five o''clock is ごじ."},{"word":"九時","from":[{"t":"九","r":"きゅう"},{"t":"時","r":"とき"}],"to":[{"t":"九時","r":"くじ"}],"why":"Nine o''clock is くじ."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."}]}'::jsonb, '{"furigana":[{"t":"から"},{"t":" marks an origin, the same particle that gives reasons, and "},{"t":"まで"},{"t":" a limit reached and not passed. Put them together and you have a span with both ends named.\n\nThe pair works for time, place and quantity alike because neither particle was ever specialised: "},{"r":"きゅう","t":"九"},{"r":"とき","t":"時"},{"t":"から"},{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"まで"},{"t":", "},{"r":"とん","t":"東"},{"t":"京から"},{"r":"たい","t":"大"},{"t":"阪まで"},{"t":", "},{"r":"いっち","t":"一"},{"t":"から"},{"r":"しー","t":"十"},{"t":"まで"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
