-- 〜も〜も: 好き
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-2a2789af9485c1f8', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"One も adds a thing; two add both. 肉も魚も好きです takes them together rather than listing them.\n\nWith a negative it sweeps the other way into \"neither\", for the same reason 誰も does: adding to nothing still leaves nothing. That symmetry is why the pattern needs no separate word for either \"both\" or \"neither\".","point":"〜も〜も","before":[{"t":"One "},{"t":"も"},{"t":" adds a thing; two add both. "},{"t":"肉","r":"にく"},{"t":"も"},{"t":"魚","r":"さかな"},{"t":"も"},{"t":"好","r":"ず"},{"t":"きです"},{"t":" takes them together rather than listing them.\n\nWith a negative it sweeps the other way into \"neither\", for the same reason "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":" does: adding to nothing still leaves nothing. That symmetry is why the pattern needs no separate word for either \"both\" or \"neither\"."}],"after":[{"t":"One "},{"t":"も"},{"t":" adds a thing; two add both. "},{"t":"肉","r":"にく"},{"t":"も"},{"t":"魚","r":"さかな"},{"t":"も"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":" takes them together rather than listing them.\n\nWith a negative it sweeps the other way into \"neither\", for the same reason "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":" does: adding to nothing still leaves nothing. That symmetry is why the pattern needs no separate word for either \"both\" or \"neither\"."}],"changes":[{"word":"好き","from":[{"t":"好","r":"ず"},{"t":"き"}],"to":[{"t":"好","r":"す"},{"t":"き"}],"why":"Like is すき. / 好き is すき."}]}'::jsonb, '{"furigana":[{"t":"One "},{"t":"も"},{"t":" adds a thing; two add both. "},{"r":"にく","t":"肉"},{"t":"も"},{"r":"さかな","t":"魚"},{"t":"も"},{"r":"ず","t":"好"},{"t":"きです"},{"t":" takes them together rather than listing them.\n\nWith a negative it sweeps the other way into \"neither\", for the same reason "},{"r":"だれ","t":"誰"},{"t":"も"},{"t":" does: adding to nothing still leaves nothing. That symmetry is why the pattern needs no separate word for either \"both\" or \"neither\"."}]}'::jsonb, 'ai', 900, 'pending'
