  AND g.segments = '[{"t":"One "},{"t":"も"},{"t":" adds a thing; two add both. "},{"r":"にく","t":"肉"},{"t":"も"},{"r":"さかな","t":"魚"},{"t":"も"},{"r":"ず","t":"好"},{"t":"きです"},{"t":" takes them together rather than listing them.\n\nWith a negative it sweeps the other way into \"neither\", for the same reason "},{"r":"だれ","t":"誰"},{"t":"も"},{"t":" does: adding to nothing still leaves nothing. That symmetry is why the pattern needs no separate word for either \"both\" or \"neither\"."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜そうだ (appearance): 美味しそう, 降りそう
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-ce0ce2514512e9f2', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"美味しそう cuts the い off and leaves the stem, and 降りそう uses the ます stem. There is no room in the form for tense or negation, and there does not need to be: you are reporting a look, and a look has no tense.\n\nHence the two exceptions that are otherwise pure memorisation. いい becomes よさそう and ない becomes なさそう, both taking a さ, because a one-syllable stem is too little to hang the ending on.","point":"〜そうだ (appearance)","before":[{"t":"美","r":"び"},{"t":"味","r":"あじ"},{"t":"しそう"},{"t":" cuts the "},{"t":"い"},{"t":" off and leaves the stem, and "},{"t":"降","r":"お"},{"t":"りそう"},{"t":" uses the "},{"t":"ます"},{"t":" stem. There is no room in the form for tense or negation, and there does not need to be: you are reporting a look, and a look has no tense.\n\nHence the two exceptions that are otherwise pure memorisation. "},{"t":"いい"},{"t":" becomes "},{"t":"よさそう"},{"t":" and "},{"t":"ない"},{"t":" becomes "},{"t":"なさそう"},{"t":", both taking a "},{"t":"さ"},{"t":", because a one-syllable stem is too little to hang the ending on."}],"after":[{"t":"美味","r":"おい"},{"t":"しそう"},{"t":" cuts the "},{"t":"い"},{"t":" off and leaves the stem, and "},{"t":"降","r":"ふ"},{"t":"りそう"},{"t":" uses the "},{"t":"ます"},{"t":" stem. There is no room in the form for tense or negation, and there does not need to be: you are reporting a look, and a look has no tense.\n\nHence the two exceptions that are otherwise pure memorisation. "},{"t":"いい"},{"t":" becomes "},{"t":"よさそう"},{"t":" and "},{"t":"ない"},{"t":" becomes "},{"t":"なさそう"},{"t":", both taking a "},{"t":"さ"},{"t":", because a one-syllable stem is too little to hang the ending on."}],"changes":[{"word":"美味しそう","from":[{"t":"美","r":"び"},{"t":"味","r":"あじ"},{"t":"しそう"}],"to":[{"t":"美味","r":"おい"},{"t":"しそう"}],"why":"美味しい is おいしい."},{"word":"降りそう","from":[{"t":"降","r":"お"},{"t":"りそう"}],"to":[{"t":"降","r":"ふ"},{"t":"りそう"}],"why":"雨が降る is ふる."}]}'::jsonb, '{"furigana":[{"r":"び","t":"美"},{"r":"あじ","t":"味"},{"t":"しそう"},{"t":" cuts the "},{"t":"い"},{"t":" off and leaves the stem, and "},{"r":"お","t":"降"},{"t":"りそう"},{"t":" uses the "},{"t":"ます"},{"t":" stem. There is no room in the form for tense or negation, and there does not need to be: you are reporting a look, and a look has no tense.\n\nHence the two exceptions that are otherwise pure memorisation. "},{"t":"いい"},{"t":" becomes "},{"t":"よさそう"},{"t":" and "},{"t":"ない"},{"t":" becomes "},{"t":"なさそう"},{"t":", both taking a "},{"t":"さ"},{"t":", because a one-syllable stem is too little to hang the ending on."}]}'::jsonb, 'ai', 900, 'pending'
