-- 〜ざるを得ない: 連体形, 得ない, 得ない, 得ない
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-975ed1f0897a848d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ざる is the 連体形 of ず, the Old Japanese negative, and 得ない is the negative potential of 得る, \"to obtain\". 行かざるを得ない says the not-going cannot be had.\n\nKnowing ざる is the old ず explains the attachment, which otherwise has to be memorised: it goes on the ない stem, 行か-, because that is the stem ず always took. And する is the exception せざるを得ない because classical する was す.","point":"〜ざるを得ない","before":[{"t":"ざる"},{"t":" is the "},{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"},{"t":" of "},{"t":"ず"},{"t":", the Old Japanese negative, and "},{"t":"得","r":"う"},{"t":"ない"},{"t":" is the negative potential of "},{"t":"得","r":"う"},{"t":"る"},{"t":", \"to obtain\". "},{"t":"行","r":"い"},{"t":"かざるを"},{"t":"得","r":"う"},{"t":"ない"},{"t":" says the not-going cannot be had.\n\nKnowing "},{"t":"ざる"},{"t":" is the old "},{"t":"ず"},{"t":" explains the attachment, which otherwise has to be memorised: it goes on the "},{"t":"ない"},{"t":" stem, "},{"t":"行","r":"い"},{"t":"か"},{"t":"-, because that is the stem "},{"t":"ず"},{"t":" always took. And "},{"t":"する"},{"t":" is the exception "},{"t":"せざるを"},{"t":"得","r":"う"},{"t":"ない"},{"t":" because classical "},{"t":"する"},{"t":" was "},{"t":"す"},{"t":"."}],"after":[{"t":"ざる"},{"t":" is the "},{"t":"連体形","r":"れんたいけい"},{"t":" of "},{"t":"ず"},{"t":", the Old Japanese negative, and "},{"t":"得","r":"え"},{"t":"ない"},{"t":" is the negative potential of "},{"t":"得","r":"う"},{"t":"る"},{"t":", \"to obtain\". "},{"t":"行","r":"い"},{"t":"かざるを"},{"t":"得","r":"え"},{"t":"ない"},{"t":" says the not-going cannot be had.\n\nKnowing "},{"t":"ざる"},{"t":" is the old "},{"t":"ず"},{"t":" explains the attachment, which otherwise has to be memorised: it goes on the "},{"t":"ない"},{"t":" stem, "},{"t":"行","r":"い"},{"t":"か"},{"t":"-, because that is the stem "},{"t":"ず"},{"t":" always took. And "},{"t":"する"},{"t":" is the exception "},{"t":"せざるを"},{"t":"得","r":"え"},{"t":"ない"},{"t":" because classical "},{"t":"する"},{"t":" was "},{"t":"す"},{"t":"."}],"changes":[{"word":"連体形","from":[{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"}],"to":[{"t":"連体形","r":"れんたいけい"}],"why":"Grammar term 連体形 is れんたいけい."},{"word":"得ない","from":[{"t":"得","r":"う"},{"t":"ない"}],"to":[{"t":"得","r":"え"},{"t":"ない"}],"why":"得ない is えない."},{"word":"得ない","from":[{"t":"得","r":"う"},{"t":"ない"}],"to":[{"t":"得","r":"え"},{"t":"ない"}],"why":"得ない is えない."},{"word":"得ない","from":[{"t":"得","r":"う"},{"t":"ない"}],"to":[{"t":"得","r":"え"},{"t":"ない"}],"why":"得ない is えない."}]}'::jsonb, '{"furigana":[{"t":"ざる"},{"t":" is the "},{"r":"つ","t":"連"},{"r":"たい","t":"体"},{"r":"なり","t":"形"},{"t":" of "},{"t":"ず"},{"t":", the Old Japanese negative, and "},{"r":"う","t":"得"},{"t":"ない"},{"t":" is the negative potential of "},{"r":"う","t":"得"},{"t":"る"},{"t":", \"to obtain\". "},{"r":"い","t":"行"},{"t":"かざるを"},{"r":"う","t":"得"},{"t":"ない"},{"t":" says the not-going cannot be had.\n\nKnowing "},{"t":"ざる"},{"t":" is the old "},{"t":"ず"},{"t":" explains the attachment, which otherwise has to be memorised: it goes on the "},{"t":"ない"},{"t":" stem, "},{"r":"い","t":"行"},{"t":"か"},{"t":"-, because that is the stem "},{"t":"ず"},{"t":" always took. And "},{"t":"する"},{"t":" is the exception "},{"t":"せざるを"},{"r":"う","t":"得"},{"t":"ない"},{"t":" because classical "},{"t":"する"},{"t":" was "},{"t":"す"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
