-- 〜きらいがある: 嫌いがある, 早合点
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-959a753225038b92', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"嫌いがある names a tendency as something disliked, and that judgement is built into the pattern before any adjective is added.\n\nWhich is why it never takes a good habit. 早合点するきらいがある works; a tendency to be kind does not, and would have to be 傾向 instead. The word for distaste is doing the evaluating.","point":"〜きらいがある","before":[{"t":"嫌","r":"ぎら"},{"t":"いがある"},{"t":" names a tendency as something disliked, and that judgement is built into the pattern before any adjective is added.\n\nWhich is why it never takes a good habit. "},{"t":"早","r":"はや"},{"t":"合","r":"あ"},{"t":"点","r":"ちょぼ"},{"t":"するきらいがある"},{"t":" works; a tendency to be kind does not, and would have to be "},{"t":"傾向","r":"けいこう"},{"t":" instead. The word for distaste is doing the evaluating."}],"after":[{"t":"嫌","r":"きら"},{"t":"いがある"},{"t":" names a tendency as something disliked, and that judgement is built into the pattern before any adjective is added.\n\nWhich is why it never takes a good habit. "},{"t":"早合点","r":"はやがてん"},{"t":"するきらいがある"},{"t":" works; a tendency to be kind does not, and would have to be "},{"t":"傾向","r":"けいこう"},{"t":" instead. The word for distaste is doing the evaluating."}],"changes":[{"word":"嫌いがある","from":[{"t":"嫌","r":"ぎら"},{"t":"いがある"}],"to":[{"t":"嫌","r":"きら"},{"t":"いがある"}],"why":"嫌い is きらい."},{"word":"早合点","from":[{"t":"早","r":"はや"},{"t":"合","r":"あ"},{"t":"点","r":"ちょぼ"}],"to":[{"t":"早合点","r":"はやがてん"}],"why":"早合点 is はやがてん."}]}'::jsonb, '{"furigana":[{"r":"ぎら","t":"嫌"},{"t":"いがある"},{"t":" names a tendency as something disliked, and that judgement is built into the pattern before any adjective is added.\n\nWhich is why it never takes a good habit. "},{"r":"はや","t":"早"},{"r":"あ","t":"合"},{"r":"ちょぼ","t":"点"},{"t":"するきらいがある"},{"t":" works; a tendency to be kind does not, and would have to be "},{"r":"けいこう","t":"傾向"},{"t":" instead. The word for distaste is doing the evaluating."}]}'::jsonb, 'ai', 900, 'pending'
