-- 〜まで: 五時, 五時
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-071fde811e9f7607', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"五時まで is up to five and not beyond; 駅まで is as far as the station. One particle, distance or duration alike.\n\nAdding に changes it entirely: 五時までに is a deadline, because に names a single point and まで the span before it. That one syllable is the whole difference between working until five and finishing by five.","point":"〜まで","before":[{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"まで"},{"t":" is up to five and not beyond; "},{"t":"駅","r":"えき"},{"t":"まで"},{"t":" is as far as the station. One particle, distance or duration alike.\n\nAdding "},{"t":"に"},{"t":" changes it entirely: "},{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"までに"},{"t":" is a deadline, because "},{"t":"に"},{"t":" names a single point and "},{"t":"まで"},{"t":" the span before it. That one syllable is the whole difference between working until five and finishing by five."}],"after":[{"t":"五時","r":"ごじ"},{"t":"まで"},{"t":" is up to five and not beyond; "},{"t":"駅","r":"えき"},{"t":"まで"},{"t":" is as far as the station. One particle, distance or duration alike.\n\nAdding "},{"t":"に"},{"t":" changes it entirely: "},{"t":"五時","r":"ごじ"},{"t":"までに"},{"t":" is a deadline, because "},{"t":"に"},{"t":" names a single point and "},{"t":"まで"},{"t":" the span before it. That one syllable is the whole difference between working until five and finishing by five."}],"changes":[{"word":"五時","from":[{"t":"五","r":"うー"},{"t":"時","r":"とき"}],"to":[{"t":"五時","r":"ごじ"}],"why":"Five o''clock is ごじ."},{"word":"五時","from":[{"t":"五","r":"うー"},{"t":"時","r":"とき"}],"to":[{"t":"五時","r":"ごじ"}],"why":"Five o''clock is ごじ."}]}'::jsonb, '{"furigana":[{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"まで"},{"t":" is up to five and not beyond; "},{"r":"えき","t":"駅"},{"t":"まで"},{"t":" is as far as the station. One particle, distance or duration alike.\n\nAdding "},{"t":"に"},{"t":" changes it entirely: "},{"r":"うー","t":"五"},{"r":"とき","t":"時"},{"t":"までに"},{"t":" is a deadline, because "},{"t":"に"},{"t":" names a single point and "},{"t":"まで"},{"t":" the span before it. That one syllable is the whole difference between working until five and finishing by five."}]}'::jsonb, 'ai', 900, 'pending'
