-- が with feelings: 嫌い, 好き, 下手
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-c7789220a0b65530', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"好き, 嫌い, 上手, 下手 and ほしい are adjectives; 分かる, できる and いる are intransitive verbs. Not one of them can take an object, so not one of them can take を.\n\nWhat が marks is simply the subject: in 日本語が分かる, the Japanese is the thing that is understood. Read that way the \"rule about feelings\" disappears and leaves ordinary grammar behind.","point":"が with feelings","before":[{"t":"好","r":"ず"},{"t":"き"},{"t":", "},{"t":"嫌","r":"ぎら"},{"t":"い"},{"t":", "},{"t":"上手","r":"じょうず"},{"t":", "},{"t":"下手","r":"したて"},{"t":" and "},{"t":"ほしい"},{"t":" are adjectives; "},{"t":"分","r":"わ"},{"t":"かる"},{"t":", "},{"t":"できる"},{"t":" and "},{"t":"いる"},{"t":" are intransitive verbs. Not one of them can take an object, so not one of them can take "},{"t":"を"},{"t":".\n\nWhat "},{"t":"が"},{"t":" marks is simply the subject: in "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"分","r":"わ"},{"t":"かる"},{"t":", the Japanese is the thing that is understood. Read that way the \"rule about feelings\" disappears and leaves ordinary grammar behind."}],"after":[{"t":"好","r":"す"},{"t":"き"},{"t":", "},{"t":"嫌","r":"きら"},{"t":"い"},{"t":", "},{"t":"上手","r":"じょうず"},{"t":", "},{"t":"下手","r":"へた"},{"t":" and "},{"t":"ほしい"},{"t":" are adjectives; "},{"t":"分","r":"わ"},{"t":"かる"},{"t":", "},{"t":"できる"},{"t":" and "},{"t":"いる"},{"t":" are intransitive verbs. Not one of them can take an object, so not one of them can take "},{"t":"を"},{"t":".\n\nWhat "},{"t":"が"},{"t":" marks is simply the subject: in "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"分","r":"わ"},{"t":"かる"},{"t":", the Japanese is the thing that is understood. Read that way the \"rule about feelings\" disappears and leaves ordinary grammar behind."}],"changes":[{"word":"嫌い","from":[{"t":"嫌","r":"ぎら"},{"t":"い"}],"to":[{"t":"嫌","r":"きら"},{"t":"い"}],"why":"Dislike is きらい. / 嫌い is きらい."},{"word":"好き","from":[{"t":"好","r":"ず"},{"t":"き"}],"to":[{"t":"好","r":"す"},{"t":"き"}],"why":"Like is すき. / 好き is すき."},{"word":"下手","from":[{"t":"下手","r":"したて"}],"to":[{"t":"下手","r":"へた"}],"why":"Unskilled is へた."}]}'::jsonb, '{"furigana":[{"r":"ず","t":"好"},{"t":"き"},{"t":", "},{"r":"ぎら","t":"嫌"},{"t":"い"},{"t":", "},{"r":"じょうず","t":"上手"},{"t":", "},{"r":"したて","t":"下手"},{"t":" and "},{"t":"ほしい"},{"t":" are adjectives; "},{"r":"わ","t":"分"},{"t":"かる"},{"t":", "},{"t":"できる"},{"t":" and "},{"t":"いる"},{"t":" are intransitive verbs. Not one of them can take an object, so not one of them can take "},{"t":"を"},{"t":".\n\nWhat "},{"t":"が"},{"t":" marks is simply the subject: in "},{"r":"にほんご","t":"日本語"},{"t":"が"},{"r":"わ","t":"分"},{"t":"かる"},{"t":", the Japanese is the thing that is understood. Read that way the \"rule about feelings\" disappears and leaves ordinary grammar behind."}]}'::jsonb, 'ai', 900, 'pending'
