WHERE g.text_hash = 'c7789220a0b655307d4af892c4d5a170f78acd418014e8e2ac1d6da6cc6b0af9' AND l.code = 'ja'
  AND g.segments = '[{"r":"ず","t":"好"},{"t":"き"},{"t":", "},{"r":"ぎら","t":"嫌"},{"t":"い"},{"t":", "},{"r":"じょうず","t":"上手"},{"t":", "},{"r":"したて","t":"下手"},{"t":" and "},{"t":"ほしい"},{"t":" are adjectives; "},{"r":"わ","t":"分"},{"t":"かる"},{"t":", "},{"t":"できる"},{"t":" and "},{"t":"いる"},{"t":" are intransitive verbs. Not one of them can take an object, so not one of them can take "},{"t":"を"},{"t":".\n\nWhat "},{"t":"が"},{"t":" marks is simply the subject: in "},{"r":"にほんご","t":"日本語"},{"t":"が"},{"r":"わ","t":"分"},{"t":"かる"},{"t":", the Japanese is the thing that is understood. Read that way the \"rule about feelings\" disappears and leaves ordinary grammar behind."}]'::jsonb
