-- の (one): 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-3be71ba9c78151f3', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"赤いのをください is \"give me the red one\", where の is the thing itself. It is the same の that turns clauses into nouns in んです and ので.\n\nWhich is why it cannot be used where こと would be needed, and why 私の alone means \"mine\". One particle: it makes whatever precedes it into a noun, and sometimes that noun is all you needed.","point":"の (one)","before":[{"t":"赤","r":"あか"},{"t":"いのをください"},{"t":" is \"give me the red one\", where "},{"t":"の"},{"t":" is the thing itself. It is the same "},{"t":"の"},{"t":" that turns clauses into nouns in "},{"t":"んです"},{"t":" and "},{"t":"ので"},{"t":".\n\nWhich is why it cannot be used where "},{"t":"こと"},{"t":" would be needed, and why "},{"t":"私","r":"わちき"},{"t":"の"},{"t":" alone means \"mine\". One particle: it makes whatever precedes it into a noun, and sometimes that noun is all you needed."}],"after":[{"t":"赤","r":"あか"},{"t":"いのをください"},{"t":" is \"give me the red one\", where "},{"t":"の"},{"t":" is the thing itself. It is the same "},{"t":"の"},{"t":" that turns clauses into nouns in "},{"t":"んです"},{"t":" and "},{"t":"ので"},{"t":".\n\nWhich is why it cannot be used where "},{"t":"こと"},{"t":" would be needed, and why "},{"t":"私","r":"わたし"},{"t":"の"},{"t":" alone means \"mine\". One particle: it makes whatever precedes it into a noun, and sometimes that noun is all you needed."}],"changes":[{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"r":"あか","t":"赤"},{"t":"いのをください"},{"t":" is \"give me the red one\", where "},{"t":"の"},{"t":" is the thing itself. It is the same "},{"t":"の"},{"t":" that turns clauses into nouns in "},{"t":"んです"},{"t":" and "},{"t":"ので"},{"t":".\n\nWhich is why it cannot be used where "},{"t":"こと"},{"t":" would be needed, and why "},{"r":"わちき","t":"私"},{"t":"の"},{"t":" alone means \"mine\". One particle: it makes whatever precedes it into a noun, and sometimes that noun is all you needed."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '3be71ba9c78151f343d41a6c011a531d5467c1659b1bb79a4297a27f26090d57' AND l.code = 'ja'
  AND g.segments = '[{"r":"あか","t":"赤"},{"t":"いのをください"},{"t":" is \"give me the red one\", where "},{"t":"の"},{"t":" is the thing itself. It is the same "},{"t":"の"},{"t":" that turns clauses into nouns in "},{"t":"んです"},{"t":" and "},{"t":"ので"},{"t":".\n\nWhich is why it cannot be used where "},{"t":"こと"},{"t":" would be needed, and why "},{"r":"わちき","t":"私"},{"t":"の"},{"t":" alone means \"mine\". One particle: it makes whatever precedes it into a noun, and sometimes that noun is all you needed."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

