INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d5768835457279c4', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"だけ comes from the noun 丈, a height or limit. でなく denies that the limit falls there, which opens the sentence up for whatever follows.\n\nThat is why a second clause is obligatory and usually carries も: the construction has denied a boundary and something has to come through the gap.","point":"〜だけでなく","before":[{"t":"だけ"},{"t":" comes from the noun "},{"t":"丈","r":"だけ"},{"t":", a height or limit. "},{"t":"でなく"},{"t":" denies that the limit falls there, which opens the sentence up for whatever follows.\n\nThat is why a second clause is obligatory and usually carries "},{"t":"も"},{"t":": the construction has denied a boundary and something has to come through the gap."}],"after":[{"t":"だけ"},{"t":" comes from the "},{"t":"noun 丈","r":"たけ"},{"t":", a height or limit. "},{"t":"でなく"},{"t":" denies that the limit falls there, which opens the sentence up for whatever follows.\n\nThat is why a second clause is obligatory and usually carries "},{"t":"も"},{"t":": the construction has denied a boundary and something has to come through the gap."}],"changes":[{"word":"noun 丈","from":[{"t":"noun "},{"t":"丈","r":"だけ"}],"to":[{"t":"noun 丈","r":"たけ"}],"why":"丈 is たけ."}]}'::jsonb, '{"furigana":[{"t":"だけ"},{"t":" comes from the noun "},{"r":"だけ","t":"丈"},{"t":", a height or limit. "},{"t":"でなく"},{"t":" denies that the limit falls there, which opens the sentence up for whatever follows.\n\nThat is why a second clause is obligatory and usually carries "},{"t":"も"},{"t":": the construction has denied a boundary and something has to come through the gap."}]}'::jsonb, 'ai', 900, 'pending'
