-- も (also): 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-0c061cf60e354684', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"私も is me in addition. With a negative it becomes \"not either\", because adding to nothing leaves nothing.\n\nThe same particle is doing the work far beyond this lesson. 誰も sweeps a question word into \"anyone at all\"; 〜ても is \"even if\"; にもかかわらず is \"even that did not come into it\". One particle, always adding.","point":"も (also)","before":[{"t":"私","r":"わちき"},{"t":"も"},{"t":" is me in addition. With a negative it becomes \"not either\", because adding to nothing leaves nothing.\n\nThe same particle is doing the work far beyond this lesson. "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":" sweeps a question word into \"anyone at all\"; 〜"},{"t":"ても"},{"t":" is \"even if\"; "},{"t":"にもかかわらず"},{"t":" is \"even that did not come into it\". One particle, always adding."}],"after":[{"t":"私","r":"わたし"},{"t":"も"},{"t":" is me in addition. With a negative it becomes \"not either\", because adding to nothing leaves nothing.\n\nThe same particle is doing the work far beyond this lesson. "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":" sweeps a question word into \"anyone at all\"; 〜"},{"t":"ても"},{"t":" is \"even if\"; "},{"t":"にもかかわらず"},{"t":" is \"even that did not come into it\". One particle, always adding."}],"changes":[{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"r":"わちき","t":"私"},{"t":"も"},{"t":" is me in addition. With a negative it becomes \"not either\", because adding to nothing leaves nothing.\n\nThe same particle is doing the work far beyond this lesson. "},{"r":"だれ","t":"誰"},{"t":"も"},{"t":" sweeps a question word into \"anyone at all\"; 〜"},{"t":"ても"},{"t":" is \"even if\"; "},{"t":"にもかかわらず"},{"t":" is \"even that did not come into it\". One particle, always adding."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '0c061cf60e354684e41ade66b3558f05f2317e4a6cf5508c767bd77c9e0dc7b8' AND l.code = 'ja'
