-- 〜ために: written 為 in
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b5a831913236d543', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A plain noun, still written 為 in careful prose. 家族のために働く is \"work for the family''s sake\" with no idiom in it anywhere.\n\nOne noun covers both textbook meanings, purpose and benefit, because they were never separate. It also explains the cause reading, 雨のために中止, which is the same noun pointed backwards: on account of.","point":"〜ために","before":[{"t":"A plain noun, still written "},{"t":"為","r":"す"},{"t":" in careful prose. "},{"t":"家族","r":"かぞく"},{"t":"のために"},{"t":"働","r":"はたら"},{"t":"く"},{"t":" is \"work for the family''s sake\" with no idiom in it anywhere.\n\nOne noun covers both textbook meanings, purpose and benefit, because they were never separate. It also explains the cause reading, "},{"t":"雨","r":"あめ"},{"t":"のために"},{"t":"中止","r":"ちゅうし"},{"t":", which is the same noun pointed backwards: on account of."}],"after":[{"t":"A plain noun, still "},{"t":"written 為","r":"ため"},{"t":" in"},{"t":" careful prose. "},{"t":"家族","r":"かぞく"},{"t":"のために"},{"t":"働","r":"はたら"},{"t":"く"},{"t":" is \"work for the family''s sake\" with no idiom in it anywhere.\n\nOne noun covers both textbook meanings, purpose and benefit, because they were never separate. It also explains the cause reading, "},{"t":"雨","r":"あめ"},{"t":"のために"},{"t":"中止","r":"ちゅうし"},{"t":", which is the same noun pointed backwards: on account of."}],"changes":[{"word":"written 為 in","from":[{"t":"written "},{"t":"為","r":"す"},{"t":" in"}],"to":[{"t":"written 為","r":"ため"},{"t":" in"}],"why":"為 is ため."}]}'::jsonb, '{"furigana":[{"t":"A plain noun, still written "},{"r":"す","t":"為"},{"t":" in careful prose. "},{"r":"かぞく","t":"家族"},{"t":"のために"},{"r":"はたら","t":"働"},{"t":"く"},{"t":" is \"work for the family''s sake\" with no idiom in it anywhere.\n\nOne noun covers both textbook meanings, purpose and benefit, because they were never separate. It also explains the cause reading, "},{"r":"あめ","t":"雨"},{"t":"のために"},{"r":"ちゅうし","t":"中止"},{"t":", which is the same noun pointed backwards: on account of."}]}'::jsonb, 'ai', 900, 'pending'
