-- Dictionary form: 食べる人, 連体形, 連体形, 終止形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-a946e37aaeb00ce2', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Classical Japanese had a 終止形 to end a sentence and a 連体形 to stand before a noun, and for most verbs they differed. They collapsed together, and the surviving shape is the one dictionaries list.\n\nJapanese never needed a relative pronoun: even before the merger the 連体形 modified nouns directly. What the merger did was hand both jobs to one shape, so 食べる now ends a sentence and also sits straight in front of a noun: 食べる人.","point":"Dictionary form","before":[{"t":"Classical Japanese had a "},{"t":"終","r":"お"},{"t":"止","r":"と"},{"t":"形","r":"なり"},{"t":" to end a sentence and a "},{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"},{"t":" to stand before a noun, and for most verbs they differed. They collapsed together, and the surviving shape is the one dictionaries list.\n\nJapanese never needed a relative pronoun: even before the merger the "},{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"},{"t":" modified nouns directly. What the merger did was hand both jobs to one shape, so "},{"t":"食","r":"た"},{"t":"べる"},{"t":" now ends a sentence and also sits straight in front of a noun: "},{"t":"食","r":"た"},{"t":"べる"},{"t":"人","r":"と"},{"t":"."}],"after":[{"t":"Classical Japanese had a "},{"t":"終止形","r":"しゅうしけい"},{"t":" to end a sentence and a "},{"t":"連体形","r":"れんたいけい"},{"t":" to stand before a noun, and for most verbs they differed. They collapsed together, and the surviving shape is the one dictionaries list.\n\nJapanese never needed a relative pronoun: even before the merger the "},{"t":"連体形","r":"れんたいけい"},{"t":" modified nouns directly. What the merger did was hand both jobs to one shape, so "},{"t":"食","r":"た"},{"t":"べる"},{"t":" now ends a sentence and also sits straight in front of a noun: "},{"t":"食","r":"た"},{"t":"べる"},{"t":"人","r":"ひと"},{"t":"."}],"changes":[{"word":"食べる人","from":[{"t":"食","r":"た"},{"t":"べる"},{"t":"人","r":"と"}],"to":[{"t":"食","r":"た"},{"t":"べる"},{"t":"人","r":"ひと"}],"why":"A person is ひと."},{"word":"連体形","from":[{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"}],"to":[{"t":"連体形","r":"れんたいけい"}],"why":"Grammar term 連体形 is れんたいけい."},{"word":"連体形","from":[{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"}],"to":[{"t":"連体形","r":"れんたいけい"}],"why":"Grammar term 連体形 is れんたいけい."},{"word":"終止形","from":[{"t":"終","r":"お"},{"t":"止","r":"と"},{"t":"形","r":"なり"}],"to":[{"t":"終止形","r":"しゅうしけい"}],"why":"Grammar term is しゅうしけい."}]}'::jsonb, '{"furigana":[{"t":"Classical Japanese had a "},{"r":"お","t":"終"},{"r":"と","t":"止"},{"r":"なり","t":"形"},{"t":" to end a sentence and a "},{"r":"つ","t":"連"},{"r":"たい","t":"体"},{"r":"なり","t":"形"},{"t":" to stand before a noun, and for most verbs they differed. They collapsed together, and the surviving shape is the one dictionaries list.\n\nJapanese never needed a relative pronoun: even before the merger the "},{"r":"つ","t":"連"},{"r":"たい","t":"体"},{"r":"なり","t":"形"},{"t":" modified nouns directly. What the merger did was hand both jobs to one shape, so "},{"r":"た","t":"食"},{"t":"べる"},{"t":" now ends a sentence and also sits straight in front of a noun: "},{"r":"た","t":"食"},{"t":"べる"},{"r":"と","t":"人"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
