-- 〜こそ: 係り結び, 今こそ, 已然形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-cd3ebdf39fa19444', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Classical Japanese had 係り結び: certain particles mid-sentence forced a particular ending on the final verb, and こそ demanded the 已然形. The agreement is gone; the particle stayed.\n\nWhat it does now is what it always did: single one element out as the one that counts. That is why こそ replaces は and が rather than joining them, and why 今こそ and あなたこそ need no other emphasis around them.","point":"〜こそ","before":[{"t":"Classical Japanese had "},{"t":"係","r":"がかり"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"},{"t":": certain particles mid-sentence forced a particular ending on the final verb, and "},{"t":"こそ"},{"t":" demanded the "},{"t":"已然"},{"t":"形","r":"なり"},{"t":". The agreement is gone; the particle stayed.\n\nWhat it does now is what it always did: single one element out as the one that counts. That is why "},{"t":"こそ"},{"t":" replaces "},{"t":"は"},{"t":" and "},{"t":"が"},{"t":" rather than joining them, and why "},{"t":"今","r":"こん"},{"t":"こそ"},{"t":" and "},{"t":"あなたこそ"},{"t":" need no other emphasis around them."}],"after":[{"t":"Classical Japanese had "},{"t":"係","r":"かか"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"},{"t":": certain particles mid-sentence forced a particular ending on the final verb, and "},{"t":"こそ"},{"t":" demanded the "},{"t":"已然形","r":"いぜんけい"},{"t":". The agreement is gone; the particle stayed.\n\nWhat it does now is what it always did: single one element out as the one that counts. That is why "},{"t":"こそ"},{"t":" replaces "},{"t":"は"},{"t":" and "},{"t":"が"},{"t":" rather than joining them, and why "},{"t":"今","r":"いま"},{"t":"こそ"},{"t":" and "},{"t":"あなたこそ"},{"t":" need no other emphasis around them."}],"changes":[{"word":"係り結び","from":[{"t":"係","r":"がかり"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"}],"to":[{"t":"係","r":"かか"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"}],"why":"係り結び is かかりむすび."},{"word":"今こそ","from":[{"t":"今","r":"こん"},{"t":"こそ"}],"to":[{"t":"今","r":"いま"},{"t":"こそ"}],"why":"今 is いま."},{"word":"已然形","from":[{"t":"已然"},{"t":"形","r":"なり"}],"to":[{"t":"已然形","r":"いぜんけい"}],"why":"Classical grammar term, いぜんけい."}]}'::jsonb, '{"furigana":[{"t":"Classical Japanese had "},{"r":"がかり","t":"係"},{"t":"り"},{"r":"むす","t":"結"},{"t":"び"},{"t":": certain particles mid-sentence forced a particular ending on the final verb, and "},{"t":"こそ"},{"t":" demanded the "},{"t":"已然"},{"r":"なり","t":"形"},{"t":". The agreement is gone; the particle stayed.\n\nWhat it does now is what it always did: single one element out as the one that counts. That is why "},{"t":"こそ"},{"t":" replaces "},{"t":"は"},{"t":" and "},{"t":"が"},{"t":" rather than joining them, and why "},{"r":"こん","t":"今"},{"t":"こそ"},{"t":" and "},{"t":"あなたこそ"},{"t":" need no other emphasis around them."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'cd3ebdf39fa19444ec481fc410997720b2cbac3eb240e87909e0e7a684fe4e57' AND l.code = 'ja'
  AND g.segments = '[{"t":"Classical Japanese had "},{"r":"がかり","t":"係"},{"t":"り"},{"r":"むす","t":"結"},{"t":"び"},{"t":": certain particles mid-sentence forced a particular ending on the final verb, and "},{"t":"こそ"},{"t":" demanded the "},{"t":"已然"},{"r":"なり","t":"形"},{"t":". The agreement is gone; the particle stayed.\n\nWhat it does now is what it always did: single one element out as the one that counts. That is why "},{"t":"こそ"},{"t":" replaces "},{"t":"は"},{"t":" and "},{"t":"が"},{"t":" rather than joining them, and why "},{"r":"こん","t":"今"},{"t":"こそ"},{"t":" and "},{"t":"あなたこそ"},{"t":" need no other emphasis around them."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜によって: によって違う, 人によって
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-dfdd0e63008e35f3', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Four textbook meanings (means, cause, agent, variation) and one verb behind all of them. Whatever the sentence is doing, によって names the thing the outcome hangs on.\n\nThe agent use in a passive is the same idea: この本は彼によって書かれた says the writing depended on him. And 人によって違う is variation because what differs is exactly what it depends on. The English translations diverge; the Japanese never did.","point":"〜によって","before":[{"t":"Four textbook meanings (means, cause, agent, variation) and one verb behind all of them. Whatever the sentence is doing, "},{"t":"によって"},{"t":" names the thing the outcome hangs on.\n\nThe agent use in a passive is the same idea: "},{"t":"この"},{"t":"本","r":"ほん"},{"t":"は"},{"t":"彼","r":"かれ"},{"t":"によって"},{"t":"書","r":"か"},{"t":"かれた"},{"t":" says the writing depended on him. And "},{"t":"人","r":"と"},{"t":"によって"},{"t":"違","r":"たが"},{"t":"う"},{"t":" is variation because what differs is exactly what it depends on. The English translations diverge; the Japanese never did."}],"after":[{"t":"Four textbook meanings (means, cause, agent, variation) and one verb behind all of them. Whatever the sentence is doing, "},{"t":"によって"},{"t":" names the thing the outcome hangs on.\n\nThe agent use in a passive is the same idea: "},{"t":"この"},{"t":"本","r":"ほん"},{"t":"は"},{"t":"彼","r":"かれ"},{"t":"によって"},{"t":"書","r":"か"},{"t":"かれた"},{"t":" says the writing depended on him. And "},{"t":"人","r":"ひと"},{"t":"によって"},{"t":"違","r":"ちが"},{"t":"う"},{"t":" is variation because what differs is exactly what it depends on. The English translations diverge; the Japanese never did."}],"changes":[{"word":"によって違う","from":[{"t":"によって"},{"t":"違","r":"たが"},{"t":"う"}],"to":[{"t":"によって"},{"t":"違","r":"ちが"},{"t":"う"}],"why":"間違う line would get a bare 違[ちが]う inside まちがう; #113 covers 間違う"},{"word":"人によって","from":[{"t":"人","r":"と"},{"t":"によって"}],"to":[{"t":"人","r":"ひと"},{"t":"によって"}],"why":"人 is ひと."}]}'::jsonb, '{"furigana":[{"t":"Four textbook meanings (means, cause, agent, variation) and one verb behind all of them. Whatever the sentence is doing, "},{"t":"によって"},{"t":" names the thing the outcome hangs on.\n\nThe agent use in a passive is the same idea: "},{"t":"この"},{"r":"ほん","t":"本"},{"t":"は"},{"r":"かれ","t":"彼"},{"t":"によって"},{"r":"か","t":"書"},{"t":"かれた"},{"t":" says the writing depended on him. And "},{"r":"と","t":"人"},{"t":"によって"},{"r":"たが","t":"違"},{"t":"う"},{"t":" is variation because what differs is exactly what it depends on. The English translations diverge; the Japanese never did."}]}'::jsonb, 'ai', 900, 'pending'
