-- が (subject): わが家
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-fcefeb585237f44f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"In Old Japanese が marked possession, much as の does now. The fossil survives in fixed expressions: わが国 \"my/our country\", わが家 \"my home\".\n\nIt shifted to marking subjects inside subordinate clauses, then generalised. Knowing this makes the modern split-up of が and の feel less arbitrary; they were once doing the same job, and in some relative clauses either still works.","point":"が (subject)","before":[{"t":"In Old Japanese "},{"t":"が"},{"t":" marked possession, much as "},{"t":"の"},{"t":" does now. The fossil survives in fixed expressions: "},{"t":"わが"},{"t":"国","r":"くに"},{"t":" \"my/our country\", "},{"t":"わが"},{"t":"家","r":"け"},{"t":" \"my home\".\n\nIt shifted to marking subjects inside subordinate clauses, then generalised. Knowing this makes the modern split-up of "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" feel less arbitrary; they were once doing the same job, and in some relative clauses either still works."}],"after":[{"t":"In Old Japanese "},{"t":"が"},{"t":" marked possession, much as "},{"t":"の"},{"t":" does now. The fossil survives in fixed expressions: "},{"t":"わが"},{"t":"国","r":"くに"},{"t":" \"my/our country\", "},{"t":"わが"},{"t":"家","r":"や"},{"t":" \"my home\".\n\nIt shifted to marking subjects inside subordinate clauses, then generalised. Knowing this makes the modern split-up of "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" feel less arbitrary; they were once doing the same job, and in some relative clauses either still works."}],"changes":[{"word":"わが家","from":[{"t":"わが"},{"t":"家","r":"け"}],"to":[{"t":"わが"},{"t":"家","r":"や"}],"why":"わが家 is read わがや"}]}'::jsonb, '{"furigana":[{"t":"In Old Japanese "},{"t":"が"},{"t":" marked possession, much as "},{"t":"の"},{"t":" does now. The fossil survives in fixed expressions: "},{"t":"わが"},{"r":"くに","t":"国"},{"t":" \"my/our country\", "},{"t":"わが"},{"r":"け","t":"家"},{"t":" \"my home\".\n\nIt shifted to marking subjects inside subordinate clauses, then generalised. Knowing this makes the modern split-up of "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" feel less arbitrary; they were once doing the same job, and in some relative clauses either still works."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'fcefeb585237f44f9fa6d2c684e93f4df1b2733084124c83b6d2b5f65fc6ea99' AND l.code = 'ja'
  AND g.segments = '[{"t":"In Old Japanese "},{"t":"が"},{"t":" marked possession, much as "},{"t":"の"},{"t":" does now. The fossil survives in fixed expressions: "},{"t":"わが"},{"r":"くに","t":"国"},{"t":" \"my/our country\", "},{"t":"わが"},{"r":"け","t":"家"},{"t":" \"my home\".\n\nIt shifted to marking subjects inside subordinate clauses, then generalised. Knowing this makes the modern split-up of "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" feel less arbitrary; they were once doing the same job, and in some relative clauses either still works."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜つつ: 連用形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-4e6b1a056112258c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It attached to the 連用形, exactly as ながら does, and the two are near-synonyms because they were built the same way. つつ simply stayed in the written language while ながら moved into speech.\n\nThe repetition sense survives in つつある, which is not \"while\" at all but a change still under way: 増えつつある, going on increasing. That is the older meaning, preserved in the one place ながら never took over.","point":"〜つつ","before":[{"t":"It attached to the "},{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"},{"t":", exactly as "},{"t":"ながら"},{"t":" does, and the two are near-synonyms because they were built the same way. "},{"t":"つつ"},{"t":" simply stayed in the written language while "},{"t":"ながら"},{"t":" moved into speech.\n\nThe repetition sense survives in "},{"t":"つつある"},{"t":", which is not \"while\" at all but a change still under way: "},{"t":"増","r":"ふ"},{"t":"えつつある"},{"t":", going on increasing. That is the older meaning, preserved in the one place "},{"t":"ながら"},{"t":" never took over."}],"after":[{"t":"It attached to the "},{"t":"連用形","r":"れんようけい"},{"t":", exactly as "},{"t":"ながら"},{"t":" does, and the two are near-synonyms because they were built the same way. "},{"t":"つつ"},{"t":" simply stayed in the written language while "},{"t":"ながら"},{"t":" moved into speech.\n\nThe repetition sense survives in "},{"t":"つつある"},{"t":", which is not \"while\" at all but a change still under way: "},{"t":"増","r":"ふ"},{"t":"えつつある"},{"t":", going on increasing. That is the older meaning, preserved in the one place "},{"t":"ながら"},{"t":" never took over."}],"changes":[{"word":"連用形","from":[{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"}],"to":[{"t":"連用形","r":"れんようけい"}],"why":"Grammar term 連用形 is れんようけい."}]}'::jsonb, '{"furigana":[{"t":"It attached to the "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":", exactly as "},{"t":"ながら"},{"t":" does, and the two are near-synonyms because they were built the same way. "},{"t":"つつ"},{"t":" simply stayed in the written language while "},{"t":"ながら"},{"t":" moved into speech.\n\nThe repetition sense survives in "},{"t":"つつある"},{"t":", which is not \"while\" at all but a change still under way: "},{"r":"ふ","t":"増"},{"t":"えつつある"},{"t":", going on increasing. That is the older meaning, preserved in the one place "},{"t":"ながら"},{"t":" never took over."}]}'::jsonb, 'ai', 900, 'pending'
