-- 〜に関して: 関して, 係わる, 付く
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-4959efdcb81fddd1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It enters through kanbun, and に関して is the written register''s について, the difference being only that 関する is Sino-Japanese and 付く is native, so the first belongs to reports and the second to speech.\n\nThe 関 also used to write native かかわる is spelling, not kinship: かかわる is its own word, written 係わる and 拘わる just as readily. And neither carries the settled dispute of をめぐって.","point":"〜に関して","before":[{"t":"It enters through kanbun, and "},{"t":"に"},{"t":"関","r":"かか"},{"t":"して"},{"t":" is the written register''s "},{"t":"について"},{"t":", the difference being only that "},{"t":"関","r":"かん"},{"t":"する"},{"t":" is Sino-Japanese and "},{"t":"付","r":"づ"},{"t":"く"},{"t":" is native, so the first belongs to reports and the second to speech.\n\nThe "},{"t":"関","r":"かか"},{"t":" also used to write native "},{"t":"かかわる"},{"t":" is spelling, not kinship: "},{"t":"かかわる"},{"t":" is its own word, written "},{"t":"係","r":"がかり"},{"t":"わる"},{"t":" and "},{"t":"拘わる"},{"t":" just as readily. And neither carries the settled dispute of "},{"t":"をめぐって"},{"t":"."}],"after":[{"t":"It enters through kanbun, and "},{"t":"に"},{"t":"関","r":"かん"},{"t":"して"},{"t":" is the written register''s "},{"t":"について"},{"t":", the difference being only that "},{"t":"関","r":"かん"},{"t":"する"},{"t":" is Sino-Japanese and "},{"t":"付","r":"つ"},{"t":"く"},{"t":" is native, so the first belongs to reports and the second to speech.\n\nThe "},{"t":"関","r":"かか"},{"t":" also used to write native "},{"t":"かかわる"},{"t":" is spelling, not kinship: "},{"t":"かかわる"},{"t":" is its own word, written "},{"t":"係","r":"かか"},{"t":"わる"},{"t":" and "},{"t":"拘わる"},{"t":" just as readily. And neither carries the settled dispute of "},{"t":"をめぐって"},{"t":"."}],"changes":[{"word":"関して","from":[{"t":"関","r":"かか"},{"t":"して"}],"to":[{"t":"関","r":"かん"},{"t":"して"}],"why":"関する is かんする."},{"word":"係わる","from":[{"t":"係","r":"がかり"},{"t":"わる"}],"to":[{"t":"係","r":"かか"},{"t":"わる"}],"why":"係わる is かかわる."},{"word":"付く","from":[{"t":"付","r":"づ"},{"t":"く"}],"to":[{"t":"付","r":"つ"},{"t":"く"}],"why":"付く is つく."}]}'::jsonb, '{"furigana":[{"t":"It enters through kanbun, and "},{"t":"に"},{"r":"かか","t":"関"},{"t":"して"},{"t":" is the written register''s "},{"t":"について"},{"t":", the difference being only that "},{"r":"かん","t":"関"},{"t":"する"},{"t":" is Sino-Japanese and "},{"r":"づ","t":"付"},{"t":"く"},{"t":" is native, so the first belongs to reports and the second to speech.\n\nThe "},{"r":"かか","t":"関"},{"t":" also used to write native "},{"t":"かかわる"},{"t":" is spelling, not kinship: "},{"t":"かかわる"},{"t":" is its own word, written "},{"r":"がかり","t":"係"},{"t":"わる"},{"t":" and "},{"t":"拘わる"},{"t":" just as readily. And neither carries the settled dispute of "},{"t":"をめぐって"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
