-- 〜ごとき / 〜ごとく: 光陰矢のごとし, 私ごとき
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d7b8c9267c328db2', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It inflects like an adjective: ごとく connects onward, ごとき stands before a noun, ごとし ends a sentence. 光陰矢のごとし, time flies like an arrow, is the phrase everybody knows.\n\nModern ようだ replaced it entirely, which is why ごとき now sounds either literary or contemptuous. 私ごとき is self-deprecation precisely because reaching for the archaic form makes a show of the comparison.","point":"〜ごとき / 〜ごとく","before":[{"t":"It inflects like an adjective: "},{"t":"ごとく"},{"t":" connects onward, "},{"t":"ごとき"},{"t":" stands before a noun, "},{"t":"ごとし"},{"t":" ends a sentence. "},{"t":"光","r":"ひかり"},{"t":"陰","r":"いん"},{"t":"矢","r":"や"},{"t":"のごとし"},{"t":", time flies like an arrow, is the phrase everybody knows.\n\nModern "},{"t":"ようだ"},{"t":" replaced it entirely, which is why "},{"t":"ごとき"},{"t":" now sounds either literary or contemptuous. "},{"t":"私","r":"わちき"},{"t":"ごとき"},{"t":" is self-deprecation precisely because reaching for the archaic form makes a show of the comparison."}],"after":[{"t":"It inflects like an adjective: "},{"t":"ごとく"},{"t":" connects onward, "},{"t":"ごとき"},{"t":" stands before a noun, "},{"t":"ごとし"},{"t":" ends a sentence. "},{"t":"光","r":"こう"},{"t":"陰","r":"いん"},{"t":"矢","r":"や"},{"t":"のごとし"},{"t":", time flies like an arrow, is the phrase everybody knows.\n\nModern "},{"t":"ようだ"},{"t":" replaced it entirely, which is why "},{"t":"ごとき"},{"t":" now sounds either literary or contemptuous. "},{"t":"私","r":"わたし"},{"t":"ごとき"},{"t":" is self-deprecation precisely because reaching for the archaic form makes a show of the comparison."}],"changes":[{"word":"光陰矢のごとし","from":[{"t":"光","r":"ひかり"},{"t":"陰","r":"いん"},{"t":"矢","r":"や"},{"t":"のごとし"}],"to":[{"t":"光","r":"こう"},{"t":"陰","r":"いん"},{"t":"矢","r":"や"},{"t":"のごとし"}],"why":"光陰 is こういん."},{"word":"私ごとき","from":[{"t":"私","r":"わちき"},{"t":"ごとき"}],"to":[{"t":"私","r":"わたし"},{"t":"ごとき"}],"why":"私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"It inflects like an adjective: "},{"t":"ごとく"},{"t":" connects onward, "},{"t":"ごとき"},{"t":" stands before a noun, "},{"t":"ごとし"},{"t":" ends a sentence. "},{"r":"ひかり","t":"光"},{"r":"いん","t":"陰"},{"r":"や","t":"矢"},{"t":"のごとし"},{"t":", time flies like an arrow, is the phrase everybody knows.\n\nModern "},{"t":"ようだ"},{"t":" replaced it entirely, which is why "},{"t":"ごとき"},{"t":" now sounds either literary or contemptuous. "},{"r":"わちき","t":"私"},{"t":"ごとき"},{"t":" is self-deprecation precisely because reaching for the archaic form makes a show of the comparison."}]}'::jsonb, 'ai', 900, 'pending'
