  AND g.segments = '[{"t":"It inflects like an adjective: "},{"t":"ごとく"},{"t":" connects onward, "},{"t":"ごとき"},{"t":" stands before a noun, "},{"t":"ごとし"},{"t":" ends a sentence. "},{"r":"ひかり","t":"光"},{"r":"いん","t":"陰"},{"r":"や","t":"矢"},{"t":"のごとし"},{"t":", time flies like an arrow, is the phrase everybody knows.\n\nModern "},{"t":"ようだ"},{"t":" replaced it entirely, which is why "},{"t":"ごとき"},{"t":" now sounds either literary or contemptuous. "},{"r":"わちき","t":"私"},{"t":"ごとき"},{"t":" is self-deprecation precisely because reaching for the archaic form makes a show of the comparison."}]'::jsonb
