-- 〜間に: 間に applies, 寝ている間 is, 寝ている間に
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-4871f1121d7b18ce', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It is written 間, the same character read かん in 時間 and 人間, but that is a Sino-Japanese morpheme and あいだ is the older native word underneath the shared spelling. 間に applies it to time: the stretch between one point and another.\n\nThe に is what makes it a window rather than a duration. 寝ている間 is the whole time; 寝ている間に is some moment inside it, which is why the second takes a one-off event and the first takes something lasting.","point":"〜間に","before":[{"t":"It is written "},{"t":"間","r":"かん"},{"t":", the same character read "},{"t":"かん"},{"t":" in "},{"t":"時間","r":"じかん"},{"t":" and "},{"t":"人間","r":"にんげん"},{"t":", but that is a Sino-Japanese morpheme and "},{"t":"あいだ"},{"t":" is the older native word underneath the shared spelling. "},{"t":"間","r":"ま"},{"t":"に"},{"t":" applies it to time: the stretch between one point and another.\n\nThe "},{"t":"に"},{"t":" is what makes it a window rather than a duration. "},{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"かん"},{"t":" is the whole time; "},{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"ま"},{"t":"に"},{"t":" is some moment inside it, which is why the second takes a one-off event and the first takes something lasting."}],"after":[{"t":"It is written "},{"t":"間","r":"かん"},{"t":", the same character read "},{"t":"かん"},{"t":" in "},{"t":"時間","r":"じかん"},{"t":" and "},{"t":"人間","r":"にんげん"},{"t":", but that is a Sino-Japanese morpheme and "},{"t":"あいだ"},{"t":" is the older native word underneath the shared spelling. "},{"t":"間","r":"あいだ"},{"t":"に applies"},{"t":" it to time: the stretch between one point and another.\n\nThe "},{"t":"に"},{"t":" is what makes it a window rather than a duration. "},{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"あいだ"},{"t":" is"},{"t":" the whole time; "},{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"あいだ"},{"t":"に"},{"t":" is some moment inside it, which is why the second takes a one-off event and the first takes something lasting."}],"changes":[{"word":"間に applies","from":[{"t":"間","r":"ま"},{"t":"に"},{"t":" applies"}],"to":[{"t":"間","r":"あいだ"},{"t":"に applies"}],"why":"間に合わない is まにあわない and 一週間に is かん; narrowed to the あいだ uses"},{"word":"寝ている間 is","from":[{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"かん"},{"t":" is"}],"to":[{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"あいだ"},{"t":" is"}],"why":"間 is あいだ."},{"word":"寝ている間に","from":[{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"ま"},{"t":"に"}],"to":[{"t":"寝","r":"ね"},{"t":"ている"},{"t":"間","r":"あいだ"},{"t":"に"}],"why":"間に合わない is まにあわない and 一週間に is かん; narrowed to the あいだ uses"}]}'::jsonb, '{"furigana":[{"t":"It is written "},{"r":"かん","t":"間"},{"t":", the same character read "},{"t":"かん"},{"t":" in "},{"r":"じかん","t":"時間"},{"t":" and "},{"r":"にんげん","t":"人間"},{"t":", but that is a Sino-Japanese morpheme and "},{"t":"あいだ"},{"t":" is the older native word underneath the shared spelling. "},{"r":"ま","t":"間"},{"t":"に"},{"t":" applies it to time: the stretch between one point and another.\n\nThe "},{"t":"に"},{"t":" is what makes it a window rather than a duration. "},{"r":"ね","t":"寝"},{"t":"ている"},{"r":"かん","t":"間"},{"t":" is the whole time; "},{"r":"ね","t":"寝"},{"t":"ている"},{"r":"ま","t":"間"},{"t":"に"},{"t":" is some moment inside it, which is why the second takes a one-off event and the first takes something lasting."}]}'::jsonb, 'ai', 900, 'pending'
