WHERE g.text_hash = '4871f1121d7b18ce0e3a72cfe57226648b13ba0a946ea6259537cc7e7633ace9' AND l.code = 'ja'
  AND g.segments = '[{"t":"It is written "},{"r":"かん","t":"間"},{"t":", the same character read "},{"t":"かん"},{"t":" in "},{"r":"じかん","t":"時間"},{"t":" and "},{"r":"にんげん","t":"人間"},{"t":", but that is a Sino-Japanese morpheme and "},{"t":"あいだ"},{"t":" is the older native word underneath the shared spelling. "},{"r":"ま","t":"間"},{"t":"に"},{"t":" applies it to time: the stretch between one point and another.\n\nThe "},{"t":"に"},{"t":" is what makes it a window rather than a duration. "},{"r":"ね","t":"寝"},{"t":"ている"},{"r":"かん","t":"間"},{"t":" is the whole time; "},{"r":"ね","t":"寝"},{"t":"ている"},{"r":"ま","t":"間"},{"t":"に"},{"t":" is some moment inside it, which is why the second takes a one-off event and the first takes something lasting."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 使役形 (causative): 未然形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-fdb8a610c05c071f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It looks like する and is not. す／さす attached to the 未然形 and meant to make or let happen; it survives as modern せる／させる.\n\nMake and let are one form because the auxiliary never separated them. With an intransitive verb the particle can tilt it (子供を行かせる leans toward compelling, 子供に行かせる toward permitting), but with a transitive verb the causee takes に either way (子供にご飯を食べさせる), and context decides.","point":"使役形 (causative)","before":[{"t":"It looks like "},{"t":"する"},{"t":" and is not. "},{"t":"す"},{"t":"／"},{"t":"さす"},{"t":" attached to the "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":" and meant to make or let happen; it survives as modern "},{"t":"せる"},{"t":"／"},{"t":"させる"},{"t":".\n\nMake and let are one form because the auxiliary never separated them. With an intransitive verb the particle can tilt it ("},{"t":"子供","r":"こども"},{"t":"を"},{"t":"行","r":"い"},{"t":"かせる"},{"t":" leans toward compelling, "},{"t":"子供","r":"こども"},{"t":"に"},{"t":"行","r":"い"},{"t":"かせる"},{"t":" toward permitting), but with a transitive verb the causee takes "},{"t":"に"},{"t":" either way ("},{"t":"子供","r":"こども"},{"t":"にご"},{"t":"飯","r":"はん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べさせる"},{"t":"), and context decides."}],"after":[{"t":"It looks like "},{"t":"する"},{"t":" and is not. "},{"t":"す"},{"t":"／"},{"t":"さす"},{"t":" attached to the "},{"t":"未然形","r":"みぜんけい"},{"t":" and meant to make or let happen; it survives as modern "},{"t":"せる"},{"t":"／"},{"t":"させる"},{"t":".\n\nMake and let are one form because the auxiliary never separated them. With an intransitive verb the particle can tilt it ("},{"t":"子供","r":"こども"},{"t":"を"},{"t":"行","r":"い"},{"t":"かせる"},{"t":" leans toward compelling, "},{"t":"子供","r":"こども"},{"t":"に"},{"t":"行","r":"い"},{"t":"かせる"},{"t":" toward permitting), but with a transitive verb the causee takes "},{"t":"に"},{"t":" either way ("},{"t":"子供","r":"こども"},{"t":"にご"},{"t":"飯","r":"はん"},{"t":"を"},{"t":"食","r":"た"},{"t":"べさせる"},{"t":"), and context decides."}],"changes":[{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."}]}'::jsonb, '{"furigana":[{"t":"It looks like "},{"t":"する"},{"t":" and is not. "},{"t":"す"},{"t":"／"},{"t":"さす"},{"t":" attached to the "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" and meant to make or let happen; it survives as modern "},{"t":"せる"},{"t":"／"},{"t":"させる"},{"t":".\n\nMake and let are one form because the auxiliary never separated them. With an intransitive verb the particle can tilt it ("},{"r":"こども","t":"子供"},{"t":"を"},{"r":"い","t":"行"},{"t":"かせる"},{"t":" leans toward compelling, "},{"r":"こども","t":"子供"},{"t":"に"},{"r":"い","t":"行"},{"t":"かせる"},{"t":" toward permitting), but with a transitive verb the causee takes "},{"t":"に"},{"t":" either way ("},{"r":"こども","t":"子供"},{"t":"にご"},{"r":"はん","t":"飯"},{"t":"を"},{"r":"た","t":"食"},{"t":"べさせる"},{"t":"), and context decides."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'fdb8a610c05c071f5dab0de0c6b827eb53fe5a2c67ab1b1a27a38fec303c5f7e' AND l.code = 'ja'
  AND g.segments = '[{"t":"It looks like "},{"t":"する"},{"t":" and is not. "},{"t":"す"},{"t":"／"},{"t":"さす"},{"t":" attached to the "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" and meant to make or let happen; it survives as modern "},{"t":"せる"},{"t":"／"},{"t":"させる"},{"t":".\n\nMake and let are one form because the auxiliary never separated them. With an intransitive verb the particle can tilt it ("},{"r":"こども","t":"子供"},{"t":"を"},{"r":"い","t":"行"},{"t":"かせる"},{"t":" leans toward compelling, "},{"r":"こども","t":"子供"},{"t":"に"},{"r":"い","t":"行"},{"t":"かせる"},{"t":" toward permitting), but with a transitive verb the causee takes "},{"t":"に"},{"t":" either way ("},{"r":"こども","t":"子供"},{"t":"にご"},{"r":"はん","t":"飯"},{"t":"を"},{"r":"た","t":"食"},{"t":"べさせる"},{"t":"), and context decides."}]'::jsonb
