-- よ (telling): 三時ですよ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b71d5f8796d1f77d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It marks the sentence as new information being given, which is why it can sound helpful (落ちましたよ), and equally why it can sound like being told off.\n\nThe risk is telling somebody what they already know. 会議は三時ですよ to the person who scheduled it is grammatical and rude, because よ has claimed they needed telling.","point":"よ (telling)","before":[{"t":"It marks the sentence as new information being given, which is why it can sound helpful ("},{"t":"落","r":"お"},{"t":"ちましたよ"},{"t":"), and equally why it can sound like being told off.\n\nThe risk is telling somebody what they already know. "},{"t":"会議","r":"かいぎ"},{"t":"は"},{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"ですよ"},{"t":" to the person who scheduled it is grammatical and rude, because "},{"t":"よ"},{"t":" has claimed they needed telling."}],"after":[{"t":"It marks the sentence as new information being given, which is why it can sound helpful ("},{"t":"落","r":"お"},{"t":"ちましたよ"},{"t":"), and equally why it can sound like being told off.\n\nThe risk is telling somebody what they already know. "},{"t":"会議","r":"かいぎ"},{"t":"は"},{"t":"三時","r":"さんじ"},{"t":"ですよ"},{"t":" to the person who scheduled it is grammatical and rude, because "},{"t":"よ"},{"t":" has claimed they needed telling."}],"changes":[{"word":"三時ですよ","from":[{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"ですよ"}],"to":[{"t":"三時","r":"さんじ"},{"t":"ですよ"}],"why":"Three o''clock is さんじ."}]}'::jsonb, '{"furigana":[{"t":"It marks the sentence as new information being given, which is why it can sound helpful ("},{"r":"お","t":"落"},{"t":"ちましたよ"},{"t":"), and equally why it can sound like being told off.\n\nThe risk is telling somebody what they already know. "},{"r":"かいぎ","t":"会議"},{"t":"は"},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"ですよ"},{"t":" to the person who scheduled it is grammatical and rude, because "},{"t":"よ"},{"t":" has claimed they needed telling."}]}'::jsonb, 'ai', 900, 'pending'
