-- 同じ: 連体詞
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-6935cc01cc18764c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It modifies a noun bare, 同じ本, where a な-adjective would need な and an i-adjective would end in い. Grammars class it as a 連体詞 for that reason.\n\nBut it takes だ and です like a な-adjective, and 同じで links like one. It is a word caught between two classes, and the irregularity is worth learning as a fact rather than a rule.","point":"同じ","before":[{"t":"It modifies a noun bare, "},{"t":"同","r":"おな"},{"t":"じ"},{"t":"本","r":"ほん"},{"t":", where a "},{"t":"な"},{"t":"-adjective would need "},{"t":"な"},{"t":" and an i-adjective would end in "},{"t":"い"},{"t":". Grammars class it as a "},{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"詞"},{"t":" for that reason.\n\nBut it takes "},{"t":"だ"},{"t":" and "},{"t":"です"},{"t":" like a "},{"t":"な"},{"t":"-adjective, and "},{"t":"同","r":"おな"},{"t":"じで"},{"t":" links like one. It is a word caught between two classes, and the irregularity is worth learning as a fact rather than a rule."}],"after":[{"t":"It modifies a noun bare, "},{"t":"同","r":"おな"},{"t":"じ"},{"t":"本","r":"ほん"},{"t":", where a "},{"t":"な"},{"t":"-adjective would need "},{"t":"な"},{"t":" and an i-adjective would end in "},{"t":"い"},{"t":". Grammars class it as a "},{"t":"連体詞","r":"れんたいし"},{"t":" for that reason.\n\nBut it takes "},{"t":"だ"},{"t":" and "},{"t":"です"},{"t":" like a "},{"t":"な"},{"t":"-adjective, and "},{"t":"同","r":"おな"},{"t":"じで"},{"t":" links like one. It is a word caught between two classes, and the irregularity is worth learning as a fact rather than a rule."}],"changes":[{"word":"連体詞","from":[{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"詞"}],"to":[{"t":"連体詞","r":"れんたいし"}],"why":"Grammar term is れんたいし."}]}'::jsonb, '{"furigana":[{"t":"It modifies a noun bare, "},{"r":"おな","t":"同"},{"t":"じ"},{"r":"ほん","t":"本"},{"t":", where a "},{"t":"な"},{"t":"-adjective would need "},{"t":"な"},{"t":" and an i-adjective would end in "},{"t":"い"},{"t":". Grammars class it as a "},{"r":"つ","t":"連"},{"r":"たい","t":"体"},{"t":"詞"},{"t":" for that reason.\n\nBut it takes "},{"t":"だ"},{"t":" and "},{"t":"です"},{"t":" like a "},{"t":"な"},{"t":"-adjective, and "},{"r":"おな","t":"同"},{"t":"じで"},{"t":" links like one. It is a word caught between two classes, and the irregularity is worth learning as a fact rather than a rule."}]}'::jsonb, 'ai', 900, 'pending'
