-- 〜ば (conditional): 来てください, 未然形, 未然形, 仮定形, 已然形, 已然形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-9998e370173af18b', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Old Japanese had both: ば on the 未然形 was hypothetical, ば on the 已然形 meant \"when\" or \"because\": something taken as actually so. The 未然形 construction died out, and the surviving 已然形 one took over the hypothetical meaning. Modern grammar renames that stem 仮定形, \"hypothetical form\", which quietly records the swap.\n\nThe old realis sense has not entirely gone. It is why ば sits so comfortably in general truths (春になれば暖かくなる), and why a command after an action-verb ば-clause sounds wrong where たら is fine. After a stative or adjectival condition it is unremarkable: 時間があれば来てください.","point":"〜ば (conditional)","before":[{"t":"Old Japanese had both: "},{"t":"ば"},{"t":" on the "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":" was hypothetical, "},{"t":"ば"},{"t":" on the "},{"t":"已然"},{"t":"形","r":"なり"},{"t":" meant \"when\" or \"because\": something taken as actually so. The "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":" construction died out, and the surviving "},{"t":"已然"},{"t":"形","r":"なり"},{"t":" one took over the hypothetical meaning. Modern grammar renames that stem "},{"t":"仮定","r":"かてい"},{"t":"形","r":"なり"},{"t":", \"hypothetical form\", which quietly records the swap.\n\nThe old realis sense has not entirely gone. It is why "},{"t":"ば"},{"t":" sits so comfortably in general truths ("},{"t":"春","r":"はる"},{"t":"になれば"},{"t":"暖","r":"あたた"},{"t":"かくなる"},{"t":"), and why a command after an action-verb "},{"t":"ば"},{"t":"-clause sounds wrong where "},{"t":"たら"},{"t":" is fine. After a stative or adjectival condition it is unremarkable: "},{"t":"時間","r":"じかん"},{"t":"があれば"},{"t":"来","r":"らい"},{"t":"てください"},{"t":"."}],"after":[{"t":"Old Japanese had both: "},{"t":"ば"},{"t":" on the "},{"t":"未然形","r":"みぜんけい"},{"t":" was hypothetical, "},{"t":"ば"},{"t":" on the "},{"t":"已然形","r":"いぜんけい"},{"t":" meant \"when\" or \"because\": something taken as actually so. The "},{"t":"未然形","r":"みぜんけい"},{"t":" construction died out, and the surviving "},{"t":"已然形","r":"いぜんけい"},{"t":" one took over the hypothetical meaning. Modern grammar renames that stem "},{"t":"仮定形","r":"かていけい"},{"t":", \"hypothetical form\", which quietly records the swap.\n\nThe old realis sense has not entirely gone. It is why "},{"t":"ば"},{"t":" sits so comfortably in general truths ("},{"t":"春","r":"はる"},{"t":"になれば"},{"t":"暖","r":"あたた"},{"t":"かくなる"},{"t":"), and why a command after an action-verb "},{"t":"ば"},{"t":"-clause sounds wrong where "},{"t":"たら"},{"t":" is fine. After a stative or adjectival condition it is unremarkable: "},{"t":"時間","r":"じかん"},{"t":"があれば"},{"t":"来","r":"き"},{"t":"てください"},{"t":"."}],"changes":[{"word":"来てください","from":[{"t":"来","r":"らい"},{"t":"てください"}],"to":[{"t":"来","r":"き"},{"t":"てください"}],"why":"The te-form of 来る is きて."},{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."},{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."},{"word":"仮定形","from":[{"t":"仮定","r":"かてい"},{"t":"形","r":"なり"}],"to":[{"t":"仮定形","r":"かていけい"}],"why":"Grammar term is かていけい."},{"word":"已然形","from":[{"t":"已然"},{"t":"形","r":"なり"}],"to":[{"t":"已然形","r":"いぜんけい"}],"why":"Classical grammar term, いぜんけい."},{"word":"已然形","from":[{"t":"已然"},{"t":"形","r":"なり"}],"to":[{"t":"已然形","r":"いぜんけい"}],"why":"Classical grammar term, いぜんけい."}]}'::jsonb, '{"furigana":[{"t":"Old Japanese had both: "},{"t":"ば"},{"t":" on the "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" was hypothetical, "},{"t":"ば"},{"t":" on the "},{"t":"已然"},{"r":"なり","t":"形"},{"t":" meant \"when\" or \"because\": something taken as actually so. The "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" construction died out, and the surviving "},{"t":"已然"},{"r":"なり","t":"形"},{"t":" one took over the hypothetical meaning. Modern grammar renames that stem "},{"r":"かてい","t":"仮定"},{"r":"なり","t":"形"},{"t":", \"hypothetical form\", which quietly records the swap.\n\nThe old realis sense has not entirely gone. It is why "},{"t":"ば"},{"t":" sits so comfortably in general truths ("},{"r":"はる","t":"春"},{"t":"になれば"},{"r":"あたた","t":"暖"},{"t":"かくなる"},{"t":"), and why a command after an action-verb "},{"t":"ば"},{"t":"-clause sounds wrong where "},{"t":"たら"},{"t":" is fine. After a stative or adjectival condition it is unremarkable: "},{"r":"じかん","t":"時間"},{"t":"があれば"},{"r":"らい","t":"来"},{"t":"てください"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
