-- 命令形 (imperative): 命令形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-141d45b079f68780', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Old Japanese verbs had a 命令形 among their six forms, and modern 行け and 食べろ come straight down from it. It is a conjugation, not something added to a verb.\n\nThere is nowhere in it to put politeness: that is what ください and なさい are for, and both are built from other verbs entirely. It is also why the imperative survives where bluntness is the point: signs, coaching, and 頑張れ.","point":"命令形 (imperative)","before":[{"t":"Old Japanese verbs had a "},{"t":"命令","r":"めいれい"},{"t":"形","r":"なり"},{"t":" among their six forms, and modern "},{"t":"行","r":"い"},{"t":"け"},{"t":" and "},{"t":"食","r":"た"},{"t":"べろ"},{"t":" come straight down from it. It is a conjugation, not something added to a verb.\n\nThere is nowhere in it to put politeness: that is what "},{"t":"ください"},{"t":" and "},{"t":"なさい"},{"t":" are for, and both are built from other verbs entirely. It is also why the imperative survives where bluntness is the point: signs, coaching, and "},{"t":"頑"},{"t":"張","r":"は"},{"t":"れ"},{"t":"."}],"after":[{"t":"Old Japanese verbs had a "},{"t":"命令形","r":"めいれいけい"},{"t":" among their six forms, and modern "},{"t":"行","r":"い"},{"t":"け"},{"t":" and "},{"t":"食","r":"た"},{"t":"べろ"},{"t":" come straight down from it. It is a conjugation, not something added to a verb.\n\nThere is nowhere in it to put politeness: that is what "},{"t":"ください"},{"t":" and "},{"t":"なさい"},{"t":" are for, and both are built from other verbs entirely. It is also why the imperative survives where bluntness is the point: signs, coaching, and "},{"t":"頑"},{"t":"張","r":"は"},{"t":"れ"},{"t":"."}],"changes":[{"word":"命令形","from":[{"t":"命令","r":"めいれい"},{"t":"形","r":"なり"}],"to":[{"t":"命令形","r":"めいれいけい"}],"why":"Grammar term is めいれいけい."}]}'::jsonb, '{"furigana":[{"t":"Old Japanese verbs had a "},{"r":"めいれい","t":"命令"},{"r":"なり","t":"形"},{"t":" among their six forms, and modern "},{"r":"い","t":"行"},{"t":"け"},{"t":" and "},{"r":"た","t":"食"},{"t":"べろ"},{"t":" come straight down from it. It is a conjugation, not something added to a verb.\n\nThere is nowhere in it to put politeness: that is what "},{"t":"ください"},{"t":" and "},{"t":"なさい"},{"t":" are for, and both are built from other verbs entirely. It is also why the imperative survives where bluntness is the point: signs, coaching, and "},{"t":"頑"},{"r":"は","t":"張"},{"t":"れ"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '141d45b079f687807ff2d28c6cefead2a7f99ffb2bb36bc6aeeafaa2c66ffcd7' AND l.code = 'ja'
  AND g.segments = '[{"t":"Old Japanese verbs had a "},{"r":"めいれい","t":"命令"},{"r":"なり","t":"形"},{"t":" among their six forms, and modern "},{"r":"い","t":"行"},{"t":"け"},{"t":" and "},{"r":"た","t":"食"},{"t":"べろ"},{"t":" come straight down from it. It is a conjugation, not something added to a verb.\n\nThere is nowhere in it to put politeness: that is what "},{"t":"ください"},{"t":" and "},{"t":"なさい"},{"t":" are for, and both are built from other verbs entirely. It is also why the imperative survives where bluntness is the point: signs, coaching, and "},{"t":"頑"},{"r":"は","t":"張"},{"t":"れ"},{"t":"."}]'::jsonb
