-- Word order: 私, 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-adbe1562d9c0c82c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Old Japanese was verb-final and so is the modern language; nothing in twelve hundred years moved it. What comes before the verb is comparatively free, because the particles say what each phrase is doing rather than the position.\n\nThat is the trade: English fixes the order and drops the case marking, Japanese fixes the verb and marks everything else. It is why 私はパンを食べます and パンを私は食べます are both grammatical. In writing the particles are what cannot be spared; speech drops は and を freely (これ食べる？), because the context is doing their work.","point":"Word order","before":[{"t":"Old Japanese was verb-final and so is the modern language; nothing in twelve hundred years moved it. What comes before the verb is comparatively free, because the particles say what each phrase is doing rather than the position.\n\nThat is the trade: English fixes the order and drops the case marking, Japanese fixes the verb and marks everything else. It is why "},{"t":"私","r":"わちき"},{"t":"はパンを"},{"t":"食","r":"た"},{"t":"べます"},{"t":" and "},{"t":"パンを"},{"t":"私","r":"わちき"},{"t":"は"},{"t":"食","r":"た"},{"t":"べます"},{"t":" are both grammatical. In writing the particles are what cannot be spared; speech drops "},{"t":"は"},{"t":" and "},{"t":"を"},{"t":" freely ("},{"t":"これ"},{"t":"食","r":"た"},{"t":"べる"},{"t":"？), because the context is doing their work."}],"after":[{"t":"Old Japanese was verb-final and so is the modern language; nothing in twelve hundred years moved it. What comes before the verb is comparatively free, because the particles say what each phrase is doing rather than the position.\n\nThat is the trade: English fixes the order and drops the case marking, Japanese fixes the verb and marks everything else. It is why "},{"t":"私","r":"わたし"},{"t":"はパンを"},{"t":"食","r":"た"},{"t":"べます"},{"t":" and "},{"t":"パンを"},{"t":"私","r":"わたし"},{"t":"は"},{"t":"食","r":"た"},{"t":"べます"},{"t":" are both grammatical. In writing the particles are what cannot be spared; speech drops "},{"t":"は"},{"t":" and "},{"t":"を"},{"t":" freely ("},{"t":"これ"},{"t":"食","r":"た"},{"t":"べる"},{"t":"？), because the context is doing their work."}],"changes":[{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"Old Japanese was verb-final and so is the modern language; nothing in twelve hundred years moved it. What comes before the verb is comparatively free, because the particles say what each phrase is doing rather than the position.\n\nThat is the trade: English fixes the order and drops the case marking, Japanese fixes the verb and marks everything else. It is why "},{"r":"わちき","t":"私"},{"t":"はパンを"},{"r":"た","t":"食"},{"t":"べます"},{"t":" and "},{"t":"パンを"},{"r":"わちき","t":"私"},{"t":"は"},{"r":"た","t":"食"},{"t":"べます"},{"t":" are both grammatical. In writing the particles are what cannot be spared; speech drops "},{"t":"は"},{"t":" and "},{"t":"を"},{"t":" freely ("},{"t":"これ"},{"r":"た","t":"食"},{"t":"べる"},{"t":"？), because the context is doing their work."}]}'::jsonb, 'ai', 900, 'pending'
