-- 〜さえ: 来さえ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-a7df1a2204c8015f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Old Japanese さへ added something on top of what was already there. The modern sense is that addition narrowed to its most surprising case: the one you would not have added.\n\nThe \"if only\" use came from elsewhere. In classical Japanese that job belonged to a different particle (だに, 命だに〜ば), and さえ took over だに''s territory in the medieval period, which is how one particle ended up carrying both \"even\" and \"if only\". Reading 来さえすればいい as \"if only the coming is added\" is a serviceable mnemonic but not the history.","point":"〜さえ","before":[{"t":"Old Japanese "},{"t":"さへ"},{"t":" added something on top of what was already there. The modern sense is that addition narrowed to its most surprising case: the one you would not have added.\n\nThe \"if only\" use came from elsewhere. In classical Japanese that job belonged to a different particle ("},{"t":"だに"},{"t":", "},{"t":"命","r":"いのち"},{"t":"だに"},{"t":"〜"},{"t":"ば"},{"t":"), and "},{"t":"さえ"},{"t":" took over "},{"t":"だに"},{"t":"''s territory in the medieval period, which is how one particle ended up carrying both \"even\" and \"if only\". Reading "},{"t":"来","r":"らい"},{"t":"さえすればいい"},{"t":" as \"if only the coming is added\" is a serviceable mnemonic but not the history."}],"after":[{"t":"Old Japanese "},{"t":"さへ"},{"t":" added something on top of what was already there. The modern sense is that addition narrowed to its most surprising case: the one you would not have added.\n\nThe \"if only\" use came from elsewhere. In classical Japanese that job belonged to a different particle ("},{"t":"だに"},{"t":", "},{"t":"命","r":"いのち"},{"t":"だに"},{"t":"〜"},{"t":"ば"},{"t":"), and "},{"t":"さえ"},{"t":" took over "},{"t":"だに"},{"t":"''s territory in the medieval period, which is how one particle ended up carrying both \"even\" and \"if only\". Reading "},{"t":"来","r":"き"},{"t":"さえ"},{"t":"すればいい"},{"t":" as \"if only the coming is added\" is a serviceable mnemonic but not the history."}],"changes":[{"word":"来さえ","from":[{"t":"来","r":"らい"},{"t":"さえ"}],"to":[{"t":"来","r":"き"},{"t":"さえ"}],"why":"来 is き before さえ."}]}'::jsonb, '{"furigana":[{"t":"Old Japanese "},{"t":"さへ"},{"t":" added something on top of what was already there. The modern sense is that addition narrowed to its most surprising case: the one you would not have added.\n\nThe \"if only\" use came from elsewhere. In classical Japanese that job belonged to a different particle ("},{"t":"だに"},{"t":", "},{"r":"いのち","t":"命"},{"t":"だに"},{"t":"〜"},{"t":"ば"},{"t":"), and "},{"t":"さえ"},{"t":" took over "},{"t":"だに"},{"t":"''s territory in the medieval period, which is how one particle ended up carrying both \"even\" and \"if only\". Reading "},{"r":"らい","t":"来"},{"t":"さえすればいい"},{"t":" as \"if only the coming is added\" is a serviceable mnemonic but not the history."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'a7df1a2204c8015fa374bf2c7d1f0570335f7b167af68dd3aa68c522bf611794' AND l.code = 'ja'
  AND g.segments = '[{"t":"Old Japanese "},{"t":"さへ"},{"t":" added something on top of what was already there. The modern sense is that addition narrowed to its most surprising case: the one you would not have added.\n\nThe \"if only\" use came from elsewhere. In classical Japanese that job belonged to a different particle ("},{"t":"だに"},{"t":", "},{"r":"いのち","t":"命"},{"t":"だに"},{"t":"〜"},{"t":"ば"},{"t":"), and "},{"t":"さえ"},{"t":" took over "},{"t":"だに"},{"t":"''s territory in the medieval period, which is how one particle ended up carrying both \"even\" and \"if only\". Reading "},{"r":"らい","t":"来"},{"t":"さえすればいい"},{"t":" as \"if only the coming is added\" is a serviceable mnemonic but not the history."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

