-- 〜ように言う: 様 of ようだ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-0aa29a31a98c66cc', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The 様 of ようだ with に and a verb of saying. What is quoted is not the sentence spoken but the way things were to be, which is why the verb in front stays plain and no quotation marks are implied.\n\nIt is how Japanese gives indirect commands without the imperative: 静かにするように言った reports that quiet was asked for, without repeating however bluntly it was put.","point":"〜ように言う","before":[{"t":"The "},{"t":"様","r":"さま"},{"t":" of "},{"t":"ようだ"},{"t":" with "},{"t":"に"},{"t":" and a verb of saying. What is quoted is not the sentence spoken but the way things were to be, which is why the verb in front stays plain and no quotation marks are implied.\n\nIt is how Japanese gives indirect commands without the imperative: "},{"t":"静","r":"しず"},{"t":"かにするように"},{"t":"言","r":"い"},{"t":"った"},{"t":" reports that quiet was asked for, without repeating however bluntly it was put."}],"after":[{"t":"The "},{"t":"様","r":"よう"},{"t":" of ようだ"},{"t":" with "},{"t":"に"},{"t":" and a verb of saying. What is quoted is not the sentence spoken but the way things were to be, which is why the verb in front stays plain and no quotation marks are implied.\n\nIt is how Japanese gives indirect commands without the imperative: "},{"t":"静","r":"しず"},{"t":"かにするように"},{"t":"言","r":"い"},{"t":"った"},{"t":" reports that quiet was asked for, without repeating however bluntly it was put."}],"changes":[{"word":"様 of ようだ","from":[{"t":"様","r":"さま"},{"t":" of "},{"t":"ようだ"}],"to":[{"t":"様","r":"よう"},{"t":" of ようだ"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"}]}'::jsonb, '{"furigana":[{"t":"The "},{"r":"さま","t":"様"},{"t":" of "},{"t":"ようだ"},{"t":" with "},{"t":"に"},{"t":" and a verb of saying. What is quoted is not the sentence spoken but the way things were to be, which is why the verb in front stays plain and no quotation marks are implied.\n\nIt is how Japanese gives indirect commands without the imperative: "},{"r":"しず","t":"静"},{"t":"かにするように"},{"r":"い","t":"言"},{"t":"った"},{"t":" reports that quiet was asked for, without repeating however bluntly it was put."}]}'::jsonb, 'ai', 900, 'pending'
