-- 〜らしい: 男らしい
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d8605139442daacf', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Old Japanese らし did mark inference from evidence, but it fell out of the spoken language by mid-Heian and was gone by Kamakura. Modern conjectural らしい arose in the Edo period out of the Late Middle Japanese SUFFIX らしい, the one in 男らしい and 学生らしい, \"as one would expect of\", echoing the remembered classical auxiliary rather than continuing it.\n\nThe suffix is therefore the source and the conjecture the offshoot, which is the reverse of how the two are usually presented. Both are still one idea: judging something by the evidence of what it appears to be. That is the difference from ようだ, which rests on what the speaker makes of it.","point":"〜らしい","before":[{"t":"Old Japanese "},{"t":"らし"},{"t":" did mark inference from evidence, but it fell out of the spoken language by mid-Heian and was gone by Kamakura. Modern conjectural "},{"t":"らしい"},{"t":" arose in the Edo period out of the Late Middle Japanese SUFFIX "},{"t":"らしい"},{"t":", the one in "},{"t":"男","r":"だん"},{"t":"らしい"},{"t":" and "},{"t":"学生","r":"がくせい"},{"t":"らしい"},{"t":", \"as one would expect of\", echoing the remembered classical auxiliary rather than continuing it.\n\nThe suffix is therefore the source and the conjecture the offshoot, which is the reverse of how the two are usually presented. Both are still one idea: judging something by the evidence of what it appears to be. That is the difference from "},{"t":"ようだ"},{"t":", which rests on what the speaker makes of it."}],"after":[{"t":"Old Japanese "},{"t":"らし"},{"t":" did mark inference from evidence, but it fell out of the spoken language by mid-Heian and was gone by Kamakura. Modern conjectural "},{"t":"らしい"},{"t":" arose in the Edo period out of the Late Middle Japanese SUFFIX "},{"t":"らしい"},{"t":", the one in "},{"t":"男","r":"おとこ"},{"t":"らしい"},{"t":" and "},{"t":"学生","r":"がくせい"},{"t":"らしい"},{"t":", \"as one would expect of\", echoing the remembered classical auxiliary rather than continuing it.\n\nThe suffix is therefore the source and the conjecture the offshoot, which is the reverse of how the two are usually presented. Both are still one idea: judging something by the evidence of what it appears to be. That is the difference from "},{"t":"ようだ"},{"t":", which rests on what the speaker makes of it."}],"changes":[{"word":"男らしい","from":[{"t":"男","r":"だん"},{"t":"らしい"}],"to":[{"t":"男","r":"おとこ"},{"t":"らしい"}],"why":"男 here is おとこ."}]}'::jsonb, '{"furigana":[{"t":"Old Japanese "},{"t":"らし"},{"t":" did mark inference from evidence, but it fell out of the spoken language by mid-Heian and was gone by Kamakura. Modern conjectural "},{"t":"らしい"},{"t":" arose in the Edo period out of the Late Middle Japanese SUFFIX "},{"t":"らしい"},{"t":", the one in "},{"r":"だん","t":"男"},{"t":"らしい"},{"t":" and "},{"r":"がくせい","t":"学生"},{"t":"らしい"},{"t":", \"as one would expect of\", echoing the remembered classical auxiliary rather than continuing it.\n\nThe suffix is therefore the source and the conjecture the offshoot, which is the reverse of how the two are usually presented. Both are still one idea: judging something by the evidence of what it appears to be. That is the difference from "},{"t":"ようだ"},{"t":", which rests on what the speaker makes of it."}]}'::jsonb, 'ai', 900, 'pending'
