-- 受身形 (passive): 来られる, 降られた, 先生
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-3811335d99227834', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"One auxiliary, four senses, none of them lost. It is why 先生が来られる can mean the teacher was come to, can come, or, most likely, simply comes, spoken respectfully.\n\nOne influential account ties the suffering passive to the spontaneous sense rather than the passive one: 雨に降られた would then be the older idea of something happening of itself, to someone, which explains the grievance and the fact that an intransitive verb can be passivised at all. Others read it as a later stretch of the plain passive with an affected party added. The construction is certain; its route is not.","point":"受身形 (passive)","before":[{"t":"One auxiliary, four senses, none of them lost. It is why "},{"t":"先生","r":"せんじょう"},{"t":"が"},{"t":"来","r":"らい"},{"t":"られる"},{"t":" can mean the teacher was come to, can come, or, most likely, simply comes, spoken respectfully.\n\nOne influential account ties the suffering passive to the spontaneous sense rather than the passive one: "},{"t":"雨","r":"あめ"},{"t":"に"},{"t":"降","r":"お"},{"t":"られた"},{"t":" would then be the older idea of something happening of itself, to someone, which explains the grievance and the fact that an intransitive verb can be passivised at all. Others read it as a later stretch of the plain passive with an affected party added. The construction is certain; its route is not."}],"after":[{"t":"One auxiliary, four senses, none of them lost. It is why "},{"t":"先生","r":"せんせい"},{"t":"が"},{"t":"来","r":"こ"},{"t":"られる"},{"t":" can mean the teacher was come to, can come, or, most likely, simply comes, spoken respectfully.\n\nOne influential account ties the suffering passive to the spontaneous sense rather than the passive one: "},{"t":"雨","r":"あめ"},{"t":"に"},{"t":"降","r":"ふ"},{"t":"られた"},{"t":" would then be the older idea of something happening of itself, to someone, which explains the grievance and the fact that an intransitive verb can be passivised at all. Others read it as a later stretch of the plain passive with an affected party added. The construction is certain; its route is not."}],"changes":[{"word":"来られる","from":[{"t":"来","r":"らい"},{"t":"られる"}],"to":[{"t":"来","r":"こ"},{"t":"られる"}],"why":"Potential of 来る is こられる."},{"word":"降られた","from":[{"t":"降","r":"お"},{"t":"られた"}],"to":[{"t":"降","r":"ふ"},{"t":"られた"}],"why":"Rain falls is ふる."},{"word":"先生","from":[{"t":"先生","r":"せんじょう"}],"to":[{"t":"先生","r":"せんせい"}],"why":"Teacher is せんせい. / Typo reading; correct is せんせい. / 先生 is せんせい."}]}'::jsonb, '{"furigana":[{"t":"One auxiliary, four senses, none of them lost. It is why "},{"r":"せんじょう","t":"先生"},{"t":"が"},{"r":"らい","t":"来"},{"t":"られる"},{"t":" can mean the teacher was come to, can come, or, most likely, simply comes, spoken respectfully.\n\nOne influential account ties the suffering passive to the spontaneous sense rather than the passive one: "},{"r":"あめ","t":"雨"},{"t":"に"},{"r":"お","t":"降"},{"t":"られた"},{"t":" would then be the older idea of something happening of itself, to someone, which explains the grievance and the fact that an intransitive verb can be passivised at all. Others read it as a later stretch of the plain passive with an affected party added. The construction is certain; its route is not."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '3811335d99227834a3f42a7a5539af10c360a77b02245299729df1d09041a041' AND l.code = 'ja'
  AND g.segments = '[{"t":"One auxiliary, four senses, none of them lost. It is why "},{"r":"せんじょう","t":"先生"},{"t":"が"},{"r":"らい","t":"来"},{"t":"られる"},{"t":" can mean the teacher was come to, can come, or, most likely, simply comes, spoken respectfully.\n\nOne influential account ties the suffering passive to the spontaneous sense rather than the passive one: "},{"r":"あめ","t":"雨"},{"t":"に"},{"r":"お","t":"降"},{"t":"られた"},{"t":" would then be the older idea of something happening of itself, to someone, which explains the grievance and the fact that an intransitive verb can be passivised at all. Others read it as a later stretch of the plain passive with an affected party added. The construction is certain; its route is not."}]'::jsonb
