-- 〜中: 一日中, 世界中, 授業中, 一年中
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-dc60f8232889bb16', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"One character, two on-readings, and they do not mean the same thing. 授業中 is during the lesson; 一日中 is all day long.\n\nThe split is not predictable from the character, so the reading has to be learned with each word. Roughly, ちゅう takes an activity you are in the middle of and じゅう a span or space filled completely: 世界中, 一年中.","point":"〜中","before":[{"t":"One character, two on-readings, and they do not mean the same thing. "},{"t":"授業","r":"じゅぎょう"},{"t":"中","r":"なか"},{"t":" is during the lesson; "},{"t":"一日","r":"いちにち"},{"t":"中","r":"なか"},{"t":" is all day long.\n\nThe split is not predictable from the character, so the reading has to be learned with each word. Roughly, "},{"t":"ちゅう"},{"t":" takes an activity you are in the middle of and "},{"t":"じゅう"},{"t":" a span or space filled completely: "},{"t":"世界","r":"せかい"},{"t":"中","r":"なか"},{"t":", "},{"t":"一年","r":"いちねん"},{"t":"中","r":"なか"},{"t":"."}],"after":[{"t":"One character, two on-readings, and they do not mean the same thing. "},{"t":"授業中","r":"じゅぎょうちゅう"},{"t":" is during the lesson; "},{"t":"一日中","r":"いちにちじゅう"},{"t":" is all day long.\n\nThe split is not predictable from the character, so the reading has to be learned with each word. Roughly, "},{"t":"ちゅう"},{"t":" takes an activity you are in the middle of and "},{"t":"じゅう"},{"t":" a span or space filled completely: "},{"t":"世界中","r":"せかいじゅう"},{"t":", "},{"t":"一年中","r":"いちねんじゅう"},{"t":"."}],"changes":[{"word":"一日中","from":[{"t":"一日","r":"いちにち"},{"t":"中","r":"なか"}],"to":[{"t":"一日中","r":"いちにちじゅう"}],"why":"一日中 is いちにちじゅう."},{"word":"世界中","from":[{"t":"世界","r":"せかい"},{"t":"中","r":"なか"}],"to":[{"t":"世界中","r":"せかいじゅう"}],"why":"All over the world is せかいじゅう. / 世界中 is せかいじゅう."},{"word":"授業中","from":[{"t":"授業","r":"じゅぎょう"},{"t":"中","r":"なか"}],"to":[{"t":"授業中","r":"じゅぎょうちゅう"}],"why":"授業中 is じゅぎょうちゅう."},{"word":"一年中","from":[{"t":"一年","r":"いちねん"},{"t":"中","r":"なか"}],"to":[{"t":"一年中","r":"いちねんじゅう"}],"why":"一年中 is いちねんじゅう."}]}'::jsonb, '{"furigana":[{"t":"One character, two on-readings, and they do not mean the same thing. "},{"r":"じゅぎょう","t":"授業"},{"r":"なか","t":"中"},{"t":" is during the lesson; "},{"r":"いちにち","t":"一日"},{"r":"なか","t":"中"},{"t":" is all day long.\n\nThe split is not predictable from the character, so the reading has to be learned with each word. Roughly, "},{"t":"ちゅう"},{"t":" takes an activity you are in the middle of and "},{"t":"じゅう"},{"t":" a span or space filled completely: "},{"r":"せかい","t":"世界"},{"r":"なか","t":"中"},{"t":", "},{"r":"いちねん","t":"一年"},{"r":"なか","t":"中"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'dc60f8232889bb16508589d902ef8f1a541da21f92fe78827e670a6acdfd1870' AND l.code = 'ja'
  AND g.segments = '[{"t":"One character, two on-readings, and they do not mean the same thing. "},{"r":"じゅぎょう","t":"授業"},{"r":"なか","t":"中"},{"t":" is during the lesson; "},{"r":"いちにち","t":"一日"},{"r":"なか","t":"中"},{"t":" is all day long.\n\nThe split is not predictable from the character, so the reading has to be learned with each word. Roughly, "},{"t":"ちゅう"},{"t":" takes an activity you are in the middle of and "},{"t":"じゅう"},{"t":" a span or space filled completely: "},{"r":"せかい","t":"世界"},{"r":"なか","t":"中"},{"t":", "},{"r":"いちねん","t":"一年"},{"r":"なか","t":"中"},{"t":"."}]'::jsonb
