-- 〜上: セキュリティ上, 法律上, 健康上
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-144c0bd257758521', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"One kanji across three patterns at this level. As a Sino-Japanese suffix it means \"on the plane of\": 法律上 is on the legal plane, 健康上 on the health one.\n\nIt favours compact, compound-ready nouns, overwhelmingly Sino-Japanese, though modern loans join freely enough, as セキュリティ上の理由 and ルール上 show.","point":"〜上","before":[{"t":"One kanji across three patterns at this level. As a Sino-Japanese suffix it means \"on the plane of\": "},{"t":"法律","r":"ほうりつ"},{"t":"上","r":"うえ"},{"t":" is on the legal plane, "},{"t":"健康","r":"けんこう"},{"t":"上","r":"うえ"},{"t":" on the health one.\n\nIt favours compact, compound-ready nouns, overwhelmingly Sino-Japanese, though modern loans join freely enough, as "},{"t":"セキュリティ"},{"t":"上","r":"うえ"},{"t":"の"},{"t":"理由","r":"りゆう"},{"t":" and "},{"t":"ルール"},{"t":"上","r":"うえ"},{"t":" show."}],"after":[{"t":"One kanji across three patterns at this level. As a Sino-Japanese suffix it means \"on the plane of\": "},{"t":"法律上","r":"ほうりつじょう"},{"t":" is on the legal plane, "},{"t":"健康上","r":"けんこうじょう"},{"t":" on the health one.\n\nIt favours compact, compound-ready nouns, overwhelmingly Sino-Japanese, though modern loans join freely enough, as "},{"t":"セキュリティ"},{"t":"上","r":"じょう"},{"t":"の"},{"t":"理由","r":"りゆう"},{"t":" and "},{"t":"ルール"},{"t":"上","r":"うえ"},{"t":" show."}],"changes":[{"word":"セキュリティ上","from":[{"t":"セキュリティ"},{"t":"上","r":"うえ"}],"to":[{"t":"セキュリティ"},{"t":"上","r":"じょう"}],"why":"Suffix 上 is じょう."},{"word":"法律上","from":[{"t":"法律","r":"ほうりつ"},{"t":"上","r":"うえ"}],"to":[{"t":"法律上","r":"ほうりつじょう"}],"why":"Suffix 上 is じょう."},{"word":"健康上","from":[{"t":"健康","r":"けんこう"},{"t":"上","r":"うえ"}],"to":[{"t":"健康上","r":"けんこうじょう"}],"why":"Suffix 上 is じょう."}]}'::jsonb, '{"furigana":[{"t":"One kanji across three patterns at this level. As a Sino-Japanese suffix it means \"on the plane of\": "},{"r":"ほうりつ","t":"法律"},{"r":"うえ","t":"上"},{"t":" is on the legal plane, "},{"r":"けんこう","t":"健康"},{"r":"うえ","t":"上"},{"t":" on the health one.\n\nIt favours compact, compound-ready nouns, overwhelmingly Sino-Japanese, though modern loans join freely enough, as "},{"t":"セキュリティ"},{"r":"うえ","t":"上"},{"t":"の"},{"r":"りゆう","t":"理由"},{"t":" and "},{"t":"ルール"},{"r":"うえ","t":"上"},{"t":" show."}]}'::jsonb, 'ai', 900, 'pending'
