-- 〜から (from): 家柄
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-85b61c22be310f9b', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The dictionaries offer several accounts: an old noun of reason or interval, a formal noun, or the から of 人柄 and 家柄, a nature or stock. None has settled it.\n\nWhat is not in doubt is that the two uses are one word. A journey from Tokyo and a decision from a reason are the same idea: the thing it started out of. That is why Japanese needs no separate word for \"because\" here, and why から sits after a noun or a whole clause without changing shape.","point":"〜から (from)","before":[{"t":"The dictionaries offer several accounts: an old noun of reason or interval, a formal noun, or the "},{"t":"から"},{"t":" of "},{"t":"人柄","r":"ひとがら"},{"t":" and "},{"t":"家","r":"け"},{"t":"柄","r":"え"},{"t":", a nature or stock. None has settled it.\n\nWhat is not in doubt is that the two uses are one word. A journey from Tokyo and a decision from a reason are the same idea: the thing it started out of. That is why Japanese needs no separate word for \"because\" here, and why "},{"t":"から"},{"t":" sits after a noun or a whole clause without changing shape."}],"after":[{"t":"The dictionaries offer several accounts: an old noun of reason or interval, a formal noun, or the "},{"t":"から"},{"t":" of "},{"t":"人柄","r":"ひとがら"},{"t":" and "},{"t":"家柄","r":"いえがら"},{"t":", a nature or stock. None has settled it.\n\nWhat is not in doubt is that the two uses are one word. A journey from Tokyo and a decision from a reason are the same idea: the thing it started out of. That is why Japanese needs no separate word for \"because\" here, and why "},{"t":"から"},{"t":" sits after a noun or a whole clause without changing shape."}],"changes":[{"word":"家柄","from":[{"t":"家","r":"け"},{"t":"柄","r":"え"}],"to":[{"t":"家柄","r":"いえがら"}],"why":"Family stock is いえがら."}]}'::jsonb, '{"furigana":[{"t":"The dictionaries offer several accounts: an old noun of reason or interval, a formal noun, or the "},{"t":"から"},{"t":" of "},{"r":"ひとがら","t":"人柄"},{"t":" and "},{"r":"け","t":"家"},{"r":"え","t":"柄"},{"t":", a nature or stock. None has settled it.\n\nWhat is not in doubt is that the two uses are one word. A journey from Tokyo and a decision from a reason are the same idea: the thing it started out of. That is why Japanese needs no separate word for \"because\" here, and why "},{"t":"から"},{"t":" sits after a noun or a whole clause without changing shape."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '85b61c22be310f9be58725d7254352818f7c7db953645ec90ab1ed13750d7ea8' AND l.code = 'ja'
  AND g.segments = '[{"t":"The dictionaries offer several accounts: an old noun of reason or interval, a formal noun, or the "},{"t":"から"},{"t":" of "},{"r":"ひとがら","t":"人柄"},{"t":" and "},{"r":"け","t":"家"},{"r":"え","t":"柄"},{"t":", a nature or stock. None has settled it.\n\nWhat is not in doubt is that the two uses are one word. A journey from Tokyo and a decision from a reason are the same idea: the thing it started out of. That is why Japanese needs no separate word for \"because\" here, and why "},{"t":"から"},{"t":" sits after a noun or a whole clause without changing shape."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- とても / あまり: 新流行, 訛語
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-879e69209300ba84', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The full phrase means \"whether thus or otherwise\": in any case, no matter what. Worn down to とても it kept that shrug, and とても行けない, \"there is no way I can go\", is the original construction and still current.\n\nThe positive とても寒い spread in Taishō and Shōwa. Akutagawa called it a 新流行 and said it was not Tokyo language; Tsubouchi called it 訛語. They lost, but the negative use never went anywhere, which is why とても〜ない reads as idiomatic rather than as a contradiction.","point":"とても / あまり","before":[{"t":"The full phrase means \"whether thus or otherwise\": in any case, no matter what. Worn down to "},{"t":"とても"},{"t":" it kept that shrug, and "},{"t":"とても"},{"t":"行","r":"い"},{"t":"けない"},{"t":", \"there is no way I can go\", is the original construction and still current.\n\nThe positive "},{"t":"とても"},{"t":"寒","r":"さむ"},{"t":"い"},{"t":" spread in Taishō and Shōwa. Akutagawa called it a "},{"t":"新","r":"あら"},{"t":"流行","r":"りゅうこう"},{"t":" and said it was not Tokyo language; Tsubouchi called it "},{"t":"訛"},{"t":"語","r":"かた"},{"t":". They lost, but the negative use never went anywhere, which is why "},{"t":"とても"},{"t":"〜"},{"t":"ない"},{"t":" reads as idiomatic rather than as a contradiction."}],"after":[{"t":"The full phrase means \"whether thus or otherwise\": in any case, no matter what. Worn down to "},{"t":"とても"},{"t":" it kept that shrug, and "},{"t":"とても"},{"t":"行","r":"い"},{"t":"けない"},{"t":", \"there is no way I can go\", is the original construction and still current.\n\nThe positive "},{"t":"とても"},{"t":"寒","r":"さむ"},{"t":"い"},{"t":" spread in Taishō and Shōwa. Akutagawa called it a "},{"t":"新流行","r":"しんりゅうこう"},{"t":" and said it was not Tokyo language; Tsubouchi called it "},{"t":"訛語","r":"かご"},{"t":". They lost, but the negative use never went anywhere, which is why "},{"t":"とても"},{"t":"〜"},{"t":"ない"},{"t":" reads as idiomatic rather than as a contradiction."}],"changes":[{"word":"新流行","from":[{"t":"新","r":"あら"},{"t":"流行","r":"りゅうこう"}],"to":[{"t":"新流行","r":"しんりゅうこう"}],"why":"新 is しん."},{"word":"訛語","from":[{"t":"訛"},{"t":"語","r":"かた"}],"to":[{"t":"訛語","r":"かご"}],"why":"訛語 is かご."}]}'::jsonb, '{"furigana":[{"t":"The full phrase means \"whether thus or otherwise\": in any case, no matter what. Worn down to "},{"t":"とても"},{"t":" it kept that shrug, and "},{"t":"とても"},{"r":"い","t":"行"},{"t":"けない"},{"t":", \"there is no way I can go\", is the original construction and still current.\n\nThe positive "},{"t":"とても"},{"r":"さむ","t":"寒"},{"t":"い"},{"t":" spread in Taishō and Shōwa. Akutagawa called it a "},{"r":"あら","t":"新"},{"r":"りゅうこう","t":"流行"},{"t":" and said it was not Tokyo language; Tsubouchi called it "},{"t":"訛"},{"r":"かた","t":"語"},{"t":". They lost, but the negative use never went anywhere, which is why "},{"t":"とても"},{"t":"〜"},{"t":"ない"},{"t":" reads as idiomatic rather than as a contradiction."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '879e69209300ba84c5e6275d5464001f9219226be171234ae512e452a1b9d547' AND l.code = 'ja'
  AND g.segments = '[{"t":"The full phrase means \"whether thus or otherwise\": in any case, no matter what. Worn down to "},{"t":"とても"},{"t":" it kept that shrug, and "},{"t":"とても"},{"r":"い","t":"行"},{"t":"けない"},{"t":", \"there is no way I can go\", is the original construction and still current.\n\nThe positive "},{"t":"とても"},{"r":"さむ","t":"寒"},{"t":"い"},{"t":" spread in Taishō and Shōwa. Akutagawa called it a "},{"r":"あら","t":"新"},{"r":"りゅうこう","t":"流行"},{"t":" and said it was not Tokyo language; Tsubouchi called it "},{"t":"訛"},{"r":"かた","t":"語"},{"t":". They lost, but the negative use never went anywhere, which is why "},{"t":"とても"},{"t":"〜"},{"t":"ない"},{"t":" reads as idiomatic rather than as a contradiction."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜ても: 降っても, 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-c9f32ea89e2265dc', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The particle is the same one in 私も and 一度も. It adds the sense of even, and nothing else has been added anywhere.\n\n雨が降っても行く is therefore \"even with it raining, I go\"; the te-form supplies the linking, も supplies the concession. It also explains the question-word pattern 何を食べても, where も keeps its sweeping sense and takes the whole range at once.","point":"〜ても","before":[{"t":"The particle is the same one in "},{"t":"私","r":"わちき"},{"t":"も"},{"t":" and "},{"t":"一度","r":"いちど"},{"t":"も"},{"t":". It adds the sense of even, and nothing else has been added anywhere.\n\n"},{"t":"雨","r":"あめ"},{"t":"が"},{"t":"降","r":"お"},{"t":"っても"},{"t":"行","r":"い"},{"t":"く"},{"t":" is therefore \"even with it raining, I go\"; the te-form supplies the linking, "},{"t":"も"},{"t":" supplies the concession. It also explains the question-word pattern "},{"t":"何","r":"なに"},{"t":"を"},{"t":"食","r":"た"},{"t":"べても"},{"t":", where "},{"t":"も"},{"t":" keeps its sweeping sense and takes the whole range at once."}],"after":[{"t":"The particle is the same one in "},{"t":"私","r":"わたし"},{"t":"も"},{"t":" and "},{"t":"一度","r":"いちど"},{"t":"も"},{"t":". It adds the sense of even, and nothing else has been added anywhere.\n\n"},{"t":"雨","r":"あめ"},{"t":"が"},{"t":"降","r":"ふ"},{"t":"っても"},{"t":"行","r":"い"},{"t":"く"},{"t":" is therefore \"even with it raining, I go\"; the te-form supplies the linking, "},{"t":"も"},{"t":" supplies the concession. It also explains the question-word pattern "},{"t":"何","r":"なに"},{"t":"を"},{"t":"食","r":"た"},{"t":"べても"},{"t":", where "},{"t":"も"},{"t":" keeps its sweeping sense and takes the whole range at once."}],"changes":[{"word":"降っても","from":[{"t":"降","r":"お"},{"t":"っても"}],"to":[{"t":"降","r":"ふ"},{"t":"っても"}],"why":"雨が降る is ふる."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"The particle is the same one in "},{"r":"わちき","t":"私"},{"t":"も"},{"t":" and "},{"r":"いちど","t":"一度"},{"t":"も"},{"t":". It adds the sense of even, and nothing else has been added anywhere.\n\n"},{"r":"あめ","t":"雨"},{"t":"が"},{"r":"お","t":"降"},{"t":"っても"},{"r":"い","t":"行"},{"t":"く"},{"t":" is therefore \"even with it raining, I go\"; the te-form supplies the linking, "},{"t":"も"},{"t":" supplies the concession. It also explains the question-word pattern "},{"r":"なに","t":"何"},{"t":"を"},{"r":"た","t":"食"},{"t":"べても"},{"t":", where "},{"t":"も"},{"t":" keeps its sweeping sense and takes the whole range at once."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'c9f32ea89e2265dc8133fd9e6f917b36d41e40c98b26c752b387aa7187e82113' AND l.code = 'ja'
  AND g.segments = '[{"t":"The particle is the same one in "},{"r":"わちき","t":"私"},{"t":"も"},{"t":" and "},{"r":"いちど","t":"一度"},{"t":"も"},{"t":". It adds the sense of even, and nothing else has been added anywhere.\n\n"},{"r":"あめ","t":"雨"},{"t":"が"},{"r":"お","t":"降"},{"t":"っても"},{"r":"い","t":"行"},{"t":"く"},{"t":" is therefore \"even with it raining, I go\"; the te-form supplies the linking, "},{"t":"も"},{"t":" supplies the concession. It also explains the question-word pattern "},{"r":"なに","t":"何"},{"t":"を"},{"r":"た","t":"食"},{"t":"べても"},{"t":", where "},{"t":"も"},{"t":" keeps its sweeping sense and takes the whole range at once."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
