-- 〜に限り: 夏はビール
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-57706ae57b0ee5d2', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same 限る. 本日に限り says today is the edge and nothing outside it counts.\n\nThat is why it belongs to notices and offers (学生に限り半額), where the point is exactly where the line falls. 〜に限る, the other form, means something else entirely: 夏はビールに限る, \"nothing beats\", which is the limit read as the only thing worth having.","point":"〜に限り","before":[{"t":"The same "},{"t":"限","r":"かぎ"},{"t":"る"},{"t":". "},{"t":"本日","r":"ほんじつ"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"り"},{"t":" says today is the edge and nothing outside it counts.\n\nThat is why it belongs to notices and offers ("},{"t":"学生","r":"がくせい"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"り"},{"t":"半","r":"はん"},{"t":"額","r":"がく"},{"t":"), where the point is exactly where the line falls. 〜"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"る"},{"t":", the other form, means something else entirely: "},{"t":"夏","r":"か"},{"t":"はビールに"},{"t":"限","r":"かぎ"},{"t":"る"},{"t":", \"nothing beats\", which is the limit read as the only thing worth having."}],"after":[{"t":"The same "},{"t":"限","r":"かぎ"},{"t":"る"},{"t":". "},{"t":"本日","r":"ほんじつ"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"り"},{"t":" says today is the edge and nothing outside it counts.\n\nThat is why it belongs to notices and offers ("},{"t":"学生","r":"がくせい"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"り"},{"t":"半","r":"はん"},{"t":"額","r":"がく"},{"t":"), where the point is exactly where the line falls. 〜"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"る"},{"t":", the other form, means something else entirely: "},{"t":"夏","r":"なつ"},{"t":"はビール"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"る"},{"t":", \"nothing beats\", which is the limit read as the only thing worth having."}],"changes":[{"word":"夏はビール","from":[{"t":"夏","r":"か"},{"t":"はビール"}],"to":[{"t":"夏","r":"なつ"},{"t":"はビール"}],"why":"Summer is なつ."}]}'::jsonb, '{"furigana":[{"t":"The same "},{"r":"かぎ","t":"限"},{"t":"る"},{"t":". "},{"r":"ほんじつ","t":"本日"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"り"},{"t":" says today is the edge and nothing outside it counts.\n\nThat is why it belongs to notices and offers ("},{"r":"がくせい","t":"学生"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"り"},{"r":"はん","t":"半"},{"r":"がく","t":"額"},{"t":"), where the point is exactly where the line falls. 〜"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"る"},{"t":", the other form, means something else entirely: "},{"r":"か","t":"夏"},{"t":"はビールに"},{"r":"かぎ","t":"限"},{"t":"る"},{"t":", \"nothing beats\", which is the limit read as the only thing worth having."}]}'::jsonb, 'ai', 900, 'pending'
