  AND g.segments = '[{"t":"The same "},{"r":"かぎ","t":"限"},{"t":"る"},{"t":". "},{"r":"ほんじつ","t":"本日"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"り"},{"t":" says today is the edge and nothing outside it counts.\n\nThat is why it belongs to notices and offers ("},{"r":"がくせい","t":"学生"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"り"},{"r":"はん","t":"半"},{"r":"がく","t":"額"},{"t":"), where the point is exactly where the line falls. 〜"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"る"},{"t":", the other form, means something else entirely: "},{"r":"か","t":"夏"},{"t":"はビールに"},{"r":"かぎ","t":"限"},{"t":"る"},{"t":", \"nothing beats\", which is the limit read as the only thing worth having."}]'::jsonb
