-- 〜がたい: みにくい字
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-e472026122fb67dd', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The shared kanji 難 is spelling, not shared origin. がたし meant difficult; the suffix にくい comes from 憎い, \"disagreeable\", extended to \"hard to\"; dictionaries gloss it 《難い・悪い》 and trace it to 憎む.\n\nThe division of labour follows: にくい is physical awkwardness (読みにくい字), がたい is difficulty in bringing yourself to it (信じがたい, 忘れがたい), and がたい keeps to written and emotional contexts because 難し is the older, stiffer word. 難い in ありがたい (hard to exist, therefore precious) is where ありがとう comes from.","point":"〜がたい","before":[{"t":"The shared kanji "},{"t":"難","r":"なん"},{"t":" is spelling, not shared origin. "},{"t":"がたし"},{"t":" meant difficult; the suffix "},{"t":"にくい"},{"t":" comes from "},{"t":"憎","r":"にく"},{"t":"い"},{"t":", \"disagreeable\", extended to \"hard to\"; dictionaries gloss it 《"},{"t":"難","r":"にく"},{"t":"い・"},{"t":"悪","r":"わる"},{"t":"い"},{"t":"》 and trace it to "},{"t":"憎","r":"にく"},{"t":"む"},{"t":".\n\nThe division of labour follows: "},{"t":"にくい"},{"t":" is physical awkwardness ("},{"t":"読","r":"よ"},{"t":"みにくい"},{"t":"字","r":"あざな"},{"t":"), "},{"t":"がたい"},{"t":" is difficulty in bringing yourself to it ("},{"t":"信","r":"しん"},{"t":"じがたい"},{"t":", "},{"t":"忘","r":"わす"},{"t":"れがたい"},{"t":"), and "},{"t":"がたい"},{"t":" keeps to written and emotional contexts because "},{"t":"難","r":"むずか"},{"t":"し"},{"t":" is the older, stiffer word. "},{"t":"難","r":"にく"},{"t":"い"},{"t":" in "},{"t":"ありがたい"},{"t":" (hard to exist, therefore precious) is where "},{"t":"ありがとう"},{"t":" comes from."}],"after":[{"t":"The shared kanji "},{"t":"難","r":"なん"},{"t":" is spelling, not shared origin. "},{"t":"がたし"},{"t":" meant difficult; the suffix "},{"t":"にくい"},{"t":" comes from "},{"t":"憎","r":"にく"},{"t":"い"},{"t":", \"disagreeable\", extended to \"hard to\"; dictionaries gloss it 《"},{"t":"難","r":"にく"},{"t":"い・"},{"t":"悪","r":"わる"},{"t":"い"},{"t":"》 and trace it to "},{"t":"憎","r":"にく"},{"t":"む"},{"t":".\n\nThe division of labour follows: "},{"t":"にくい"},{"t":" is physical awkwardness ("},{"t":"読","r":"よ"},{"t":"みにくい"},{"t":"字","r":"じ"},{"t":"), "},{"t":"がたい"},{"t":" is difficulty in bringing yourself to it ("},{"t":"信","r":"しん"},{"t":"じがたい"},{"t":", "},{"t":"忘","r":"わす"},{"t":"れがたい"},{"t":"), and "},{"t":"がたい"},{"t":" keeps to written and emotional contexts because "},{"t":"難","r":"むずか"},{"t":"し"},{"t":" is the older, stiffer word. "},{"t":"難","r":"にく"},{"t":"い"},{"t":" in "},{"t":"ありがたい"},{"t":" (hard to exist, therefore precious) is where "},{"t":"ありがとう"},{"t":" comes from."}],"changes":[{"word":"みにくい字","from":[{"t":"みにくい"},{"t":"字","r":"あざな"}],"to":[{"t":"みにくい"},{"t":"字","r":"じ"}],"why":"Character is じ."}]}'::jsonb, '{"furigana":[{"t":"The shared kanji "},{"r":"なん","t":"難"},{"t":" is spelling, not shared origin. "},{"t":"がたし"},{"t":" meant difficult; the suffix "},{"t":"にくい"},{"t":" comes from "},{"r":"にく","t":"憎"},{"t":"い"},{"t":", \"disagreeable\", extended to \"hard to\"; dictionaries gloss it 《"},{"r":"にく","t":"難"},{"t":"い・"},{"r":"わる","t":"悪"},{"t":"い"},{"t":"》 and trace it to "},{"r":"にく","t":"憎"},{"t":"む"},{"t":".\n\nThe division of labour follows: "},{"t":"にくい"},{"t":" is physical awkwardness ("},{"r":"よ","t":"読"},{"t":"みにくい"},{"r":"あざな","t":"字"},{"t":"), "},{"t":"がたい"},{"t":" is difficulty in bringing yourself to it ("},{"r":"しん","t":"信"},{"t":"じがたい"},{"t":", "},{"r":"わす","t":"忘"},{"t":"れがたい"},{"t":"), and "},{"t":"がたい"},{"t":" keeps to written and emotional contexts because "},{"r":"むずか","t":"難"},{"t":"し"},{"t":" is the older, stiffer word. "},{"r":"にく","t":"難"},{"t":"い"},{"t":" in "},{"t":"ありがたい"},{"t":" (hard to exist, therefore precious) is where "},{"t":"ありがとう"},{"t":" comes from."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'e472026122fb67dd9ecdeafe3ccfd2b26af51a4d0867a993858f861c855a45ba' AND l.code = 'ja'
  AND g.segments = '[{"t":"The shared kanji "},{"r":"なん","t":"難"},{"t":" is spelling, not shared origin. "},{"t":"がたし"},{"t":" meant difficult; the suffix "},{"t":"にくい"},{"t":" comes from "},{"r":"にく","t":"憎"},{"t":"い"},{"t":", \"disagreeable\", extended to \"hard to\"; dictionaries gloss it 《"},{"r":"にく","t":"難"},{"t":"い・"},{"r":"わる","t":"悪"},{"t":"い"},{"t":"》 and trace it to "},{"r":"にく","t":"憎"},{"t":"む"},{"t":".\n\nThe division of labour follows: "},{"t":"にくい"},{"t":" is physical awkwardness ("},{"r":"よ","t":"読"},{"t":"みにくい"},{"r":"あざな","t":"字"},{"t":"), "},{"t":"がたい"},{"t":" is difficulty in bringing yourself to it ("},{"r":"しん","t":"信"},{"t":"じがたい"},{"t":", "},{"r":"わす","t":"忘"},{"t":"れがたい"},{"t":"), and "},{"t":"がたい"},{"t":" keeps to written and emotional contexts because "},{"r":"むずか","t":"難"},{"t":"し"},{"t":" is the older, stiffer word. "},{"r":"にく","t":"難"},{"t":"い"},{"t":" in "},{"t":"ありがたい"},{"t":" (hard to exist, therefore precious) is where "},{"t":"ありがとう"},{"t":" comes from."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

