-- 〜くらい / 〜ぐらい: 一位
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-74cbec3535d493bd', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The 位 of 一位 and 位置: a place on a scale. Put after a quantity it gives the approximate reading, because naming a grade is vaguer than naming a number.\n\nThe belittling use is the same scale pointed downward. 掃除くらいしなさい says cleaning ranks that low, so there is no excuse: the dismissiveness is the noun doing its ordinary job.","point":"〜くらい / 〜ぐらい","before":[{"t":"The "},{"t":"位","r":"くらい"},{"t":" of "},{"t":"一","r":"いっち"},{"t":"位","r":"くらい"},{"t":" and "},{"t":"位置","r":"いち"},{"t":": a place on a scale. Put after a quantity it gives the approximate reading, because naming a grade is vaguer than naming a number.\n\nThe belittling use is the same scale pointed downward. "},{"t":"掃除","r":"そうじ"},{"t":"くらいしなさい"},{"t":" says cleaning ranks that low, so there is no excuse: the dismissiveness is the noun doing its ordinary job."}],"after":[{"t":"The "},{"t":"位","r":"くらい"},{"t":" of "},{"t":"一位","r":"いちい"},{"t":" and "},{"t":"位置","r":"いち"},{"t":": a place on a scale. Put after a quantity it gives the approximate reading, because naming a grade is vaguer than naming a number.\n\nThe belittling use is the same scale pointed downward. "},{"t":"掃除","r":"そうじ"},{"t":"くらいしなさい"},{"t":" says cleaning ranks that low, so there is no excuse: the dismissiveness is the noun doing its ordinary job."}],"changes":[{"word":"一位","from":[{"t":"一","r":"いっち"},{"t":"位","r":"くらい"}],"to":[{"t":"一位","r":"いちい"}],"why":"First place is いちい."}]}'::jsonb, '{"furigana":[{"t":"The "},{"r":"くらい","t":"位"},{"t":" of "},{"r":"いっち","t":"一"},{"r":"くらい","t":"位"},{"t":" and "},{"r":"いち","t":"位置"},{"t":": a place on a scale. Put after a quantity it gives the approximate reading, because naming a grade is vaguer than naming a number.\n\nThe belittling use is the same scale pointed downward. "},{"r":"そうじ","t":"掃除"},{"t":"くらいしなさい"},{"t":" says cleaning ranks that low, so there is no excuse: the dismissiveness is the noun doing its ordinary job."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '74cbec3535d493bd38e5d5cf2db1fd61e90f3747d38c94d54dc45d0d62a29d7d' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"r":"くらい","t":"位"},{"t":" of "},{"r":"いっち","t":"一"},{"r":"くらい","t":"位"},{"t":" and "},{"r":"いち","t":"位置"},{"t":": a place on a scale. Put after a quantity it gives the approximate reading, because naming a grade is vaguer than naming a number.\n\nThe belittling use is the same scale pointed downward. "},{"r":"そうじ","t":"掃除"},{"t":"くらいしなさい"},{"t":" says cleaning ranks that low, so there is no excuse: the dismissiveness is the noun doing its ordinary job."}]'::jsonb
