ON CONFLICT DO NOTHING;

-- Relative clause: 連体形, 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-eb823f53495de8c5', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The 連体形 was the classical form for standing before a noun, and when it merged with the sentence-ending form the modifying ability came along. 昨日買った本 is \"yesterday-bought book\" with no \"that\" or \"which\" anywhere.\n\nThe clause comes before the noun because every modifier in Japanese does, the same order as 赤い本 and 私の本. And が rather than は marks the subject inside it: は belongs to the sentence as a whole, and a modifying clause is not one.","point":"Relative clause","before":[{"t":"The "},{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"},{"t":" was the classical form for standing before a noun, and when it merged with the sentence-ending form the modifying ability came along. "},{"t":"昨日","r":"きのう"},{"t":"買","r":"か"},{"t":"った"},{"t":"本","r":"ほん"},{"t":" is \"yesterday-bought book\" with no \"that\" or \"which\" anywhere.\n\nThe clause comes before the noun because every modifier in Japanese does, the same order as "},{"t":"赤","r":"あか"},{"t":"い"},{"t":"本","r":"ほん"},{"t":" and "},{"t":"私","r":"わちき"},{"t":"の"},{"t":"本","r":"ほん"},{"t":". And "},{"t":"が"},{"t":" rather than "},{"t":"は"},{"t":" marks the subject inside it: "},{"t":"は"},{"t":" belongs to the sentence as a whole, and a modifying clause is not one."}],"after":[{"t":"The "},{"t":"連体形","r":"れんたいけい"},{"t":" was the classical form for standing before a noun, and when it merged with the sentence-ending form the modifying ability came along. "},{"t":"昨日","r":"きのう"},{"t":"買","r":"か"},{"t":"った"},{"t":"本","r":"ほん"},{"t":" is \"yesterday-bought book\" with no \"that\" or \"which\" anywhere.\n\nThe clause comes before the noun because every modifier in Japanese does, the same order as "},{"t":"赤","r":"あか"},{"t":"い"},{"t":"本","r":"ほん"},{"t":" and "},{"t":"私","r":"わたし"},{"t":"の"},{"t":"本","r":"ほん"},{"t":". And "},{"t":"が"},{"t":" rather than "},{"t":"は"},{"t":" marks the subject inside it: "},{"t":"は"},{"t":" belongs to the sentence as a whole, and a modifying clause is not one."}],"changes":[{"word":"連体形","from":[{"t":"連","r":"つ"},{"t":"体","r":"たい"},{"t":"形","r":"なり"}],"to":[{"t":"連体形","r":"れんたいけい"}],"why":"Grammar term 連体形 is れんたいけい."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"The "},{"r":"つ","t":"連"},{"r":"たい","t":"体"},{"r":"なり","t":"形"},{"t":" was the classical form for standing before a noun, and when it merged with the sentence-ending form the modifying ability came along. "},{"r":"きのう","t":"昨日"},{"r":"か","t":"買"},{"t":"った"},{"r":"ほん","t":"本"},{"t":" is \"yesterday-bought book\" with no \"that\" or \"which\" anywhere.\n\nThe clause comes before the noun because every modifier in Japanese does, the same order as "},{"r":"あか","t":"赤"},{"t":"い"},{"r":"ほん","t":"本"},{"t":" and "},{"r":"わちき","t":"私"},{"t":"の"},{"r":"ほん","t":"本"},{"t":". And "},{"t":"が"},{"t":" rather than "},{"t":"は"},{"t":" marks the subject inside it: "},{"t":"は"},{"t":" belongs to the sentence as a whole, and a modifying clause is not one."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'eb823f53495de8c5bdcbacd06091de5258cb116b28fdc15fec2d6dee6aea6b91' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"r":"つ","t":"連"},{"r":"たい","t":"体"},{"r":"なり","t":"形"},{"t":" was the classical form for standing before a noun, and when it merged with the sentence-ending form the modifying ability came along. "},{"r":"きのう","t":"昨日"},{"r":"か","t":"買"},{"t":"った"},{"r":"ほん","t":"本"},{"t":" is \"yesterday-bought book\" with no \"that\" or \"which\" anywhere.\n\nThe clause comes before the noun because every modifier in Japanese does, the same order as "},{"r":"あか","t":"赤"},{"t":"い"},{"r":"ほん","t":"本"},{"t":" and "},{"r":"わちき","t":"私"},{"t":"の"},{"r":"ほん","t":"本"},{"t":". And "},{"t":"が"},{"t":" rather than "},{"t":"は"},{"t":" marks the subject inside it: "},{"t":"は"},{"t":" belongs to the sentence as a whole, and a modifying clause is not one."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜なんか / 〜なんて: 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-fd0d0fc7f3423d03', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Two different routes to the same shrug. なんか reaches for \"what\" instead of naming the thing; なんて comes from など plus と, so it reaches for \"or some such\": the belittling in it is the など of N5, not the question word.\n\nEither way the tone is built in rather than added, which is why neither can be used politely about a listener''s things. 私なんか, turned on yourself, is self-deprecation for exactly the same reason.","point":"〜なんか / 〜なんて","before":[{"t":"Two different routes to the same shrug. "},{"t":"なんか"},{"t":" reaches for \"what\" instead of naming the thing; "},{"t":"なんて"},{"t":" comes from "},{"t":"など"},{"t":" plus "},{"t":"と"},{"t":", so it reaches for \"or some such\": the belittling in it is the "},{"t":"など"},{"t":" of N5, not the question word.\n\nEither way the tone is built in rather than added, which is why neither can be used politely about a listener''s things. "},{"t":"私","r":"わちき"},{"t":"なんか"},{"t":", turned on yourself, is self-deprecation for exactly the same reason."}],"after":[{"t":"Two different routes to the same shrug. "},{"t":"なんか"},{"t":" reaches for \"what\" instead of naming the thing; "},{"t":"なんて"},{"t":" comes from "},{"t":"など"},{"t":" plus "},{"t":"と"},{"t":", so it reaches for \"or some such\": the belittling in it is the "},{"t":"など"},{"t":" of N5, not the question word.\n\nEither way the tone is built in rather than added, which is why neither can be used politely about a listener''s things. "},{"t":"私","r":"わたし"},{"t":"なんか"},{"t":", turned on yourself, is self-deprecation for exactly the same reason."}],"changes":[{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"Two different routes to the same shrug. "},{"t":"なんか"},{"t":" reaches for \"what\" instead of naming the thing; "},{"t":"なんて"},{"t":" comes from "},{"t":"など"},{"t":" plus "},{"t":"と"},{"t":", so it reaches for \"or some such\": the belittling in it is the "},{"t":"など"},{"t":" of N5, not the question word.\n\nEither way the tone is built in rather than added, which is why neither can be used politely about a listener''s things. "},{"r":"わちき","t":"私"},{"t":"なんか"},{"t":", turned on yourself, is self-deprecation for exactly the same reason."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'fd0d0fc7f3423d0383d61caccf1d7fba9729d46529e59933fd9e15bb68d04d84' AND l.code = 'ja'
  AND g.segments = '[{"t":"Two different routes to the same shrug. "},{"t":"なんか"},{"t":" reaches for \"what\" instead of naming the thing; "},{"t":"なんて"},{"t":" comes from "},{"t":"など"},{"t":" plus "},{"t":"と"},{"t":", so it reaches for \"or some such\": the belittling in it is the "},{"t":"など"},{"t":" of N5, not the question word.\n\nEither way the tone is built in rather than added, which is why neither can be used politely about a listener''s things. "},{"r":"わちき","t":"私"},{"t":"なんか"},{"t":", turned on yourself, is self-deprecation for exactly the same reason."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

