-- 〜どころではない: 所
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-f256c00ab4ca2194', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Where どころか rejects a description, どころではない rejects the occasion. 勉強どころではない says circumstances leave no space for studying.\n\nBoth are the noun 所 doing what it does at N4, locating a moment as a place, and the negation lands differently only because of what is being denied a location.","point":"〜どころではない","before":[{"t":"Where "},{"t":"どころか"},{"t":" rejects a description, "},{"t":"どころではない"},{"t":" rejects the occasion. "},{"t":"勉強","r":"べんきょう"},{"t":"どころではない"},{"t":" says circumstances leave no space for studying.\n\nBoth are the noun "},{"t":"所","r":"しょ"},{"t":" doing what it does at N4, locating a moment as a place, and the negation lands differently only because of what is being denied a location."}],"after":[{"t":"Where "},{"t":"どころか"},{"t":" rejects a description, "},{"t":"どころではない"},{"t":" rejects the occasion. "},{"t":"勉強","r":"べんきょう"},{"t":"どころではない"},{"t":" says circumstances leave no space for studying.\n\nBoth are the noun "},{"t":"所","r":"ところ"},{"t":" doing what it does at N4, locating a moment as a place, and the negation lands differently only because of what is being denied a location."}],"changes":[{"word":"所","from":[{"t":"所","r":"しょ"}],"to":[{"t":"所","r":"ところ"}],"why":"The noun meaning place is ところ here."}]}'::jsonb, '{"furigana":[{"t":"Where "},{"t":"どころか"},{"t":" rejects a description, "},{"t":"どころではない"},{"t":" rejects the occasion. "},{"r":"べんきょう","t":"勉強"},{"t":"どころではない"},{"t":" says circumstances leave no space for studying.\n\nBoth are the noun "},{"r":"しょ","t":"所"},{"t":" doing what it does at N4, locating a moment as a place, and the negation lands differently only because of what is being denied a location."}]}'::jsonb, 'ai', 900, 'pending'
