-- 〜って (quotation): さんって人
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-250db6c919b48344', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"「行く」と言っていた compressed to 行くって. Which route it took is disputed: a gemination of classical とて, or a contraction of と言って, or of という, which is the account usually given for the topic use.\n\nThat is why って can stand where と cannot (田中さんって人, 明日って本当？), and why it needs no verb after it. The saying is already implied by the particle that used to mark it.","point":"〜って (quotation)","before":[{"t":"「"},{"t":"行","r":"い"},{"t":"く"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"っていた"},{"t":" compressed to "},{"t":"行","r":"い"},{"t":"くって"},{"t":". Which route it took is disputed: a gemination of classical "},{"t":"とて"},{"t":", or a contraction of "},{"t":"と"},{"t":"言","r":"い"},{"t":"って"},{"t":", or of "},{"t":"という"},{"t":", which is the account usually given for the topic use.\n\nThat is why "},{"t":"って"},{"t":" can stand where "},{"t":"と"},{"t":" cannot ("},{"t":"田","r":"た"},{"t":"中","r":"なか"},{"t":"さんって"},{"t":"人","r":"と"},{"t":", "},{"t":"明日","r":"あした"},{"t":"って"},{"t":"本当","r":"ほんとう"},{"t":"？), and why it needs no verb after it. The saying is already implied by the particle that used to mark it."}],"after":[{"t":"「"},{"t":"行","r":"い"},{"t":"く"},{"t":"」"},{"t":"と"},{"t":"言","r":"い"},{"t":"っていた"},{"t":" compressed to "},{"t":"行","r":"い"},{"t":"くって"},{"t":". Which route it took is disputed: a gemination of classical "},{"t":"とて"},{"t":", or a contraction of "},{"t":"と"},{"t":"言","r":"い"},{"t":"って"},{"t":", or of "},{"t":"という"},{"t":", which is the account usually given for the topic use.\n\nThat is why "},{"t":"って"},{"t":" can stand where "},{"t":"と"},{"t":" cannot ("},{"t":"田","r":"た"},{"t":"中","r":"なか"},{"t":"さんって"},{"t":"人","r":"ひと"},{"t":", "},{"t":"明日","r":"あした"},{"t":"って"},{"t":"本当","r":"ほんとう"},{"t":"？), and why it needs no verb after it. The saying is already implied by the particle that used to mark it."}],"changes":[{"word":"さんって人","from":[{"t":"さんって"},{"t":"人","r":"と"}],"to":[{"t":"さんって"},{"t":"人","r":"ひと"}],"why":"Person is ひと."}]}'::jsonb, '{"furigana":[{"t":"「"},{"r":"い","t":"行"},{"t":"く"},{"t":"」"},{"t":"と"},{"r":"い","t":"言"},{"t":"っていた"},{"t":" compressed to "},{"r":"い","t":"行"},{"t":"くって"},{"t":". Which route it took is disputed: a gemination of classical "},{"t":"とて"},{"t":", or a contraction of "},{"t":"と"},{"r":"い","t":"言"},{"t":"って"},{"t":", or of "},{"t":"という"},{"t":", which is the account usually given for the topic use.\n\nThat is why "},{"t":"って"},{"t":" can stand where "},{"t":"と"},{"t":" cannot ("},{"r":"た","t":"田"},{"r":"なか","t":"中"},{"t":"さんって"},{"r":"と","t":"人"},{"t":", "},{"r":"あした","t":"明日"},{"t":"って"},{"r":"ほんとう","t":"本当"},{"t":"？), and why it needs no verb after it. The saying is already implied by the particle that used to mark it."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '250db6c919b483446f365798bb489ce61b8ca3bf55333f40682a73e793b7e7ac' AND l.code = 'ja'
  AND g.segments = '[{"t":"「"},{"r":"い","t":"行"},{"t":"く"},{"t":"」"},{"t":"と"},{"r":"い","t":"言"},{"t":"っていた"},{"t":" compressed to "},{"r":"い","t":"行"},{"t":"くって"},{"t":". Which route it took is disputed: a gemination of classical "},{"t":"とて"},{"t":", or a contraction of "},{"t":"と"},{"r":"い","t":"言"},{"t":"って"},{"t":", or of "},{"t":"という"},{"t":", which is the account usually given for the topic use.\n\nThat is why "},{"t":"って"},{"t":" can stand where "},{"t":"と"},{"t":" cannot ("},{"r":"た","t":"田"},{"r":"なか","t":"中"},{"t":"さんって"},{"r":"と","t":"人"},{"t":", "},{"r":"あした","t":"明日"},{"t":"って"},{"r":"ほんとう","t":"本当"},{"t":"？), and why it needs no verb after it. The saying is already implied by the particle that used to mark it."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- あります / います: 男ありけり
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b3b61ca0517f587c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ある is for what does not: objects, buildings, plans. いる is for what does: people and animals. The division is animacy, not size or importance. And it is younger than it looks. Classical Japanese used あり of people freely: 昔、男ありけり.\n\nIt reaches much further than this lesson. ている is built on いる and describes something in progress; てある is built on ある and describes a thing left in a state. The split you learn here is the one those two patterns rest on.","point":"あります / います","before":[{"t":"ある"},{"t":" is for what does not: objects, buildings, plans. "},{"t":"いる"},{"t":" is for what does: people and animals. The division is animacy, not size or importance. And it is younger than it looks. Classical Japanese used "},{"t":"あり"},{"t":" of people freely: "},{"t":"昔","r":"むかし"},{"t":"、"},{"t":"男","r":"だん"},{"t":"ありけり"},{"t":".\n\nIt reaches much further than this lesson. "},{"t":"ている"},{"t":" is built on "},{"t":"いる"},{"t":" and describes something in progress; "},{"t":"てある"},{"t":" is built on "},{"t":"ある"},{"t":" and describes a thing left in a state. The split you learn here is the one those two patterns rest on."}],"after":[{"t":"ある"},{"t":" is for what does not: objects, buildings, plans. "},{"t":"いる"},{"t":" is for what does: people and animals. The division is animacy, not size or importance. And it is younger than it looks. Classical Japanese used "},{"t":"あり"},{"t":" of people freely: "},{"t":"昔","r":"むかし"},{"t":"、"},{"t":"男","r":"おとこ"},{"t":"ありけり"},{"t":".\n\nIt reaches much further than this lesson. "},{"t":"ている"},{"t":" is built on "},{"t":"いる"},{"t":" and describes something in progress; "},{"t":"てある"},{"t":" is built on "},{"t":"ある"},{"t":" and describes a thing left in a state. The split you learn here is the one those two patterns rest on."}],"changes":[{"word":"男ありけり","from":[{"t":"男","r":"だん"},{"t":"ありけり"}],"to":[{"t":"男","r":"おとこ"},{"t":"ありけり"}],"why":"男 is おとこ."}]}'::jsonb, '{"furigana":[{"t":"ある"},{"t":" is for what does not: objects, buildings, plans. "},{"t":"いる"},{"t":" is for what does: people and animals. The division is animacy, not size or importance. And it is younger than it looks. Classical Japanese used "},{"t":"あり"},{"t":" of people freely: "},{"r":"むかし","t":"昔"},{"t":"、"},{"r":"だん","t":"男"},{"t":"ありけり"},{"t":".\n\nIt reaches much further than this lesson. "},{"t":"ている"},{"t":" is built on "},{"t":"いる"},{"t":" and describes something in progress; "},{"t":"てある"},{"t":" is built on "},{"t":"ある"},{"t":" and describes a thing left in a state. The split you learn here is the one those two patterns rest on."}]}'::jsonb, 'ai', 900, 'pending'
