SELECT 'crq-grammar-93edfb3495e2c7a7', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"いえ is the 已然形 of 言う; ども is Old Japanese for \"even though\". The whole is \"even though one says\".\n\nAnd it is the identical ども taught at N5 inside けれども, the ancestor of けれど and けど. One particle, one meaning, at the two ends of the syllabus: the casual けど and the lofty といえども are the same word wearing different amounts of its original self.","point":"〜といえども","before":[{"t":"いえ"},{"t":" is the "},{"t":"已然"},{"t":"形","r":"なり"},{"t":" of "},{"t":"言","r":"い"},{"t":"う"},{"t":"; "},{"t":"ども"},{"t":" is Old Japanese for \"even though\". The whole is \"even though one says\".\n\nAnd it is the identical "},{"t":"ども"},{"t":" taught at N5 inside "},{"t":"けれども"},{"t":", the ancestor of "},{"t":"けれど"},{"t":" and "},{"t":"けど"},{"t":". One particle, one meaning, at the two ends of the syllabus: the casual "},{"t":"けど"},{"t":" and the lofty "},{"t":"といえども"},{"t":" are the same word wearing different amounts of its original self."}],"after":[{"t":"いえ"},{"t":" is the "},{"t":"已然形","r":"いぜんけい"},{"t":" of "},{"t":"言","r":"い"},{"t":"う"},{"t":"; "},{"t":"ども"},{"t":" is Old Japanese for \"even though\". The whole is \"even though one says\".\n\nAnd it is the identical "},{"t":"ども"},{"t":" taught at N5 inside "},{"t":"けれども"},{"t":", the ancestor of "},{"t":"けれど"},{"t":" and "},{"t":"けど"},{"t":". One particle, one meaning, at the two ends of the syllabus: the casual "},{"t":"けど"},{"t":" and the lofty "},{"t":"といえども"},{"t":" are the same word wearing different amounts of its original self."}],"changes":[{"word":"已然形","from":[{"t":"已然"},{"t":"形","r":"なり"}],"to":[{"t":"已然形","r":"いぜんけい"}],"why":"Classical grammar term, いぜんけい."}]}'::jsonb, '{"furigana":[{"t":"いえ"},{"t":" is the "},{"t":"已然"},{"r":"なり","t":"形"},{"t":" of "},{"r":"い","t":"言"},{"t":"う"},{"t":"; "},{"t":"ども"},{"t":" is Old Japanese for \"even though\". The whole is \"even though one says\".\n\nAnd it is the identical "},{"t":"ども"},{"t":" taught at N5 inside "},{"t":"けれども"},{"t":", the ancestor of "},{"t":"けれど"},{"t":" and "},{"t":"けど"},{"t":". One particle, one meaning, at the two ends of the syllabus: the casual "},{"t":"けど"},{"t":" and the lofty "},{"t":"といえども"},{"t":" are the same word wearing different amounts of its original self."}]}'::jsonb, 'ai', 900, 'pending'
