-- 〜ばこそ: 係り結び
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-c6023800820137ac', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"こso singles one thing out as the one that counts, and in classical Japanese it forced a particular ending on the sentence: 係り結び. Attached to a condition, it insists that this and no other is the reason.\n\n愛すればこそ叱る: precisely because there is love. The ば supplies the cause, こそ refuses every competing one, and neither part means \"precisely\" on its own.","point":"〜ばこそ","before":[{"t":"こ"},{"t":"so singles one thing out as the one that counts, and in classical Japanese it forced a particular ending on the sentence: "},{"t":"係","r":"がかり"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"},{"t":". Attached to a condition, it insists that this and no other is the reason.\n\n"},{"t":"愛","r":"あい"},{"t":"すればこそ"},{"t":"叱","r":"しか"},{"t":"る"},{"t":": precisely because there is love. The "},{"t":"ば"},{"t":" supplies the cause, "},{"t":"こそ"},{"t":" refuses every competing one, and neither part means \"precisely\" on its own."}],"after":[{"t":"こ"},{"t":"so singles one thing out as the one that counts, and in classical Japanese it forced a particular ending on the sentence: "},{"t":"係","r":"かか"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"},{"t":". Attached to a condition, it insists that this and no other is the reason.\n\n"},{"t":"愛","r":"あい"},{"t":"すればこそ"},{"t":"叱","r":"しか"},{"t":"る"},{"t":": precisely because there is love. The "},{"t":"ば"},{"t":" supplies the cause, "},{"t":"こそ"},{"t":" refuses every competing one, and neither part means \"precisely\" on its own."}],"changes":[{"word":"係り結び","from":[{"t":"係","r":"がかり"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"}],"to":[{"t":"係","r":"かか"},{"t":"り"},{"t":"結","r":"むす"},{"t":"び"}],"why":"係り結び is かかりむすび."}]}'::jsonb, '{"furigana":[{"t":"こ"},{"t":"so singles one thing out as the one that counts, and in classical Japanese it forced a particular ending on the sentence: "},{"r":"がかり","t":"係"},{"t":"り"},{"r":"むす","t":"結"},{"t":"び"},{"t":". Attached to a condition, it insists that this and no other is the reason.\n\n"},{"r":"あい","t":"愛"},{"t":"すればこそ"},{"r":"しか","t":"叱"},{"t":"る"},{"t":": precisely because there is love. The "},{"t":"ば"},{"t":" supplies the cause, "},{"t":"こそ"},{"t":" refuses every competing one, and neither part means \"precisely\" on its own."}]}'::jsonb, 'ai', 900, 'pending'
