-- 〜が上手 / 〜が下手: most likely 端, 下手
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-aa2e87bee235189a', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"じょうず is a genuine Sino-Japanese compound, the upper hand. へた is not its mirror: it is a native word, most likely 端 (はた), the shallow edge rather than the deep part, and 下手 was written onto it later to make the pair look symmetrical.\n\nBoth behave as な-adjectives, which is why the thing you are good at takes が. 日本語が上手です has no verb of ability in it, so there is nothing for を to mark, and 得意 and 苦手 take が for the same reason.","point":"〜が上手 / 〜が下手","before":[{"t":"じょうず"},{"t":" is a genuine Sino-Japanese compound, the upper hand. "},{"t":"へた"},{"t":" is not its mirror: it is a native word, most likely "},{"t":"端","r":"たん"},{"t":" ("},{"t":"はた"},{"t":"), the shallow edge rather than the deep part, and "},{"t":"下手","r":"したて"},{"t":" was written onto it later to make the pair look symmetrical.\n\nBoth behave as "},{"t":"な"},{"t":"-adjectives, which is why the thing you are good at takes "},{"t":"が"},{"t":". "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"上手","r":"じょうず"},{"t":"です"},{"t":" has no verb of ability in it, so there is nothing for "},{"t":"を"},{"t":" to mark, and "},{"t":"得意","r":"とくい"},{"t":" and "},{"t":"苦手","r":"にがて"},{"t":" take "},{"t":"が"},{"t":" for the same reason."}],"after":[{"t":"じょうず"},{"t":" is a genuine Sino-Japanese compound, the upper hand. "},{"t":"へた"},{"t":" is not its mirror: it is a native word, "},{"t":"most likely 端","r":"はた"},{"t":" ("},{"t":"はた"},{"t":"), the shallow edge rather than the deep part, and "},{"t":"下手","r":"へた"},{"t":" was written onto it later to make the pair look symmetrical.\n\nBoth behave as "},{"t":"な"},{"t":"-adjectives, which is why the thing you are good at takes "},{"t":"が"},{"t":". "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"上手","r":"じょうず"},{"t":"です"},{"t":" has no verb of ability in it, so there is nothing for "},{"t":"を"},{"t":" to mark, and "},{"t":"得意","r":"とくい"},{"t":" and "},{"t":"苦手","r":"にがて"},{"t":" take "},{"t":"が"},{"t":" for the same reason."}],"changes":[{"word":"most likely 端","from":[{"t":"most likely "},{"t":"端","r":"たん"}],"to":[{"t":"most likely 端","r":"はた"}],"why":"The native word is はた."},{"word":"下手","from":[{"t":"下手","r":"したて"}],"to":[{"t":"下手","r":"へた"}],"why":"Unskilled is へた."}]}'::jsonb, '{"furigana":[{"t":"じょうず"},{"t":" is a genuine Sino-Japanese compound, the upper hand. "},{"t":"へた"},{"t":" is not its mirror: it is a native word, most likely "},{"r":"たん","t":"端"},{"t":" ("},{"t":"はた"},{"t":"), the shallow edge rather than the deep part, and "},{"r":"したて","t":"下手"},{"t":" was written onto it later to make the pair look symmetrical.\n\nBoth behave as "},{"t":"な"},{"t":"-adjectives, which is why the thing you are good at takes "},{"t":"が"},{"t":". "},{"r":"にほんご","t":"日本語"},{"t":"が"},{"r":"じょうず","t":"上手"},{"t":"です"},{"t":" has no verb of ability in it, so there is nothing for "},{"t":"を"},{"t":" to mark, and "},{"r":"とくい","t":"得意"},{"t":" and "},{"r":"にがて","t":"苦手"},{"t":" take "},{"t":"が"},{"t":" for the same reason."}]}'::jsonb, 'ai', 900, 'pending'
