-- 〜たら: 未然形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-aef256fa928d6d85', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"たり, itself て + あり, had a full set of forms, and たら is its 未然形. So 〜たら is not the past tense plus a conditional; both た and たら descend from the one auxiliary.\n\nThis explains why たら feels like \"once X has happened\" rather than a bare hypothetical: the completive sense of たり is still inside it. It is also why たら, alone among the conditionals, comfortably takes a request or a command afterwards.","point":"〜たら","before":[{"t":"たり"},{"t":", itself "},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":", had a full set of forms, and "},{"t":"たら"},{"t":" is its "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":". So 〜"},{"t":"たら"},{"t":" is not the past tense plus a conditional; both "},{"t":"た"},{"t":" and "},{"t":"たら"},{"t":" descend from the one auxiliary.\n\nThis explains why "},{"t":"たら"},{"t":" feels like \"once X has happened\" rather than a bare hypothetical: the completive sense of "},{"t":"たり"},{"t":" is still inside it. It is also why "},{"t":"たら"},{"t":", alone among the conditionals, comfortably takes a request or a command afterwards."}],"after":[{"t":"たり"},{"t":", itself "},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":", had a full set of forms, and "},{"t":"たら"},{"t":" is its "},{"t":"未然形","r":"みぜんけい"},{"t":". So 〜"},{"t":"たら"},{"t":" is not the past tense plus a conditional; both "},{"t":"た"},{"t":" and "},{"t":"たら"},{"t":" descend from the one auxiliary.\n\nThis explains why "},{"t":"たら"},{"t":" feels like \"once X has happened\" rather than a bare hypothetical: the completive sense of "},{"t":"たり"},{"t":" is still inside it. It is also why "},{"t":"たら"},{"t":", alone among the conditionals, comfortably takes a request or a command afterwards."}],"changes":[{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."}]}'::jsonb, '{"furigana":[{"t":"たり"},{"t":", itself "},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":", had a full set of forms, and "},{"t":"たら"},{"t":" is its "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":". So 〜"},{"t":"たら"},{"t":" is not the past tense plus a conditional; both "},{"t":"た"},{"t":" and "},{"t":"たら"},{"t":" descend from the one auxiliary.\n\nThis explains why "},{"t":"たら"},{"t":" feels like \"once X has happened\" rather than a bare hypothetical: the completive sense of "},{"t":"たり"},{"t":" is still inside it. It is also why "},{"t":"たら"},{"t":", alone among the conditionals, comfortably takes a request or a command afterwards."}]}'::jsonb, 'ai', 900, 'pending'
