-- 〜つもり: 連用形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-a2e80733102bef55', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"つもり is 積もり, the 連用形 of 積もる, the verb used for snow accumulating. An intention is something that has piled up in the mind.\n\nThis is why つもり means a settled plan rather than a passing wish. Something that has accumulated took time to get there. たい, which is a desire, carries no such weight.","point":"〜つもり","before":[{"t":"つもり"},{"t":" is "},{"t":"積","r":"つ"},{"t":"もり"},{"t":", the "},{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"},{"t":" of "},{"t":"積","r":"つ"},{"t":"もる"},{"t":", the verb used for snow accumulating. An intention is something that has piled up in the mind.\n\nThis is why "},{"t":"つもり"},{"t":" means a settled plan rather than a passing wish. Something that has accumulated took time to get there. "},{"t":"たい"},{"t":", which is a desire, carries no such weight."}],"after":[{"t":"つもり"},{"t":" is "},{"t":"積","r":"つ"},{"t":"もり"},{"t":", the "},{"t":"連用形","r":"れんようけい"},{"t":" of "},{"t":"積","r":"つ"},{"t":"もる"},{"t":", the verb used for snow accumulating. An intention is something that has piled up in the mind.\n\nThis is why "},{"t":"つもり"},{"t":" means a settled plan rather than a passing wish. Something that has accumulated took time to get there. "},{"t":"たい"},{"t":", which is a desire, carries no such weight."}],"changes":[{"word":"連用形","from":[{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"}],"to":[{"t":"連用形","r":"れんようけい"}],"why":"Grammar term 連用形 is れんようけい."}]}'::jsonb, '{"furigana":[{"t":"つもり"},{"t":" is "},{"r":"つ","t":"積"},{"t":"もり"},{"t":", the "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" of "},{"r":"つ","t":"積"},{"t":"もる"},{"t":", the verb used for snow accumulating. An intention is something that has piled up in the mind.\n\nThis is why "},{"t":"つもり"},{"t":" means a settled plan rather than a passing wish. Something that has accumulated took time to get there. "},{"t":"たい"},{"t":", which is a desire, carries no such weight."}]}'::jsonb, 'ai', 900, 'pending'
