-- 〜て form: 連用形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-9c4e14e8a9fa8172', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"て is the 連用形 of the perfective auxiliary つ. So the te-form is literally a stem plus a completion marker: \"having done X\".\n\nThat original sense of completion is still doing work in the modern language. It is why て naturally means \"and then\" rather than plain \"and\", why 〜てから means \"after doing\", and why the past tense た is built from the same material (て + あり → たり → た). One morpheme, and it explains a whole family of forms.","point":"〜て form","before":[{"t":"て"},{"t":" is the "},{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"},{"t":" of the perfective auxiliary "},{"t":"つ"},{"t":". So the te-form is literally a stem plus a completion marker: \"having done X\".\n\nThat original sense of completion is still doing work in the modern language. It is why "},{"t":"て"},{"t":" naturally means \"and then\" rather than plain \"and\", why 〜"},{"t":"てから"},{"t":" means \"after doing\", and why the past tense "},{"t":"た"},{"t":" is built from the same material ("},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":" → "},{"t":"たり"},{"t":" → "},{"t":"た"},{"t":"). One morpheme, and it explains a whole family of forms."}],"after":[{"t":"て"},{"t":" is the "},{"t":"連用形","r":"れんようけい"},{"t":" of the perfective auxiliary "},{"t":"つ"},{"t":". So the te-form is literally a stem plus a completion marker: \"having done X\".\n\nThat original sense of completion is still doing work in the modern language. It is why "},{"t":"て"},{"t":" naturally means \"and then\" rather than plain \"and\", why 〜"},{"t":"てから"},{"t":" means \"after doing\", and why the past tense "},{"t":"た"},{"t":" is built from the same material ("},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":" → "},{"t":"たり"},{"t":" → "},{"t":"た"},{"t":"). One morpheme, and it explains a whole family of forms."}],"changes":[{"word":"連用形","from":[{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"}],"to":[{"t":"連用形","r":"れんようけい"}],"why":"Grammar term 連用形 is れんようけい."}]}'::jsonb, '{"furigana":[{"t":"て"},{"t":" is the "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" of the perfective auxiliary "},{"t":"つ"},{"t":". So the te-form is literally a stem plus a completion marker: \"having done X\".\n\nThat original sense of completion is still doing work in the modern language. It is why "},{"t":"て"},{"t":" naturally means \"and then\" rather than plain \"and\", why 〜"},{"t":"てから"},{"t":" means \"after doing\", and why the past tense "},{"t":"た"},{"t":" is built from the same material ("},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":" → "},{"t":"たり"},{"t":" → "},{"t":"た"},{"t":"). One morpheme, and it explains a whole family of forms."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '9c4e14e8a9fa8172d41ba79757709258c2291652474d7068f249a7ed28d44f0c' AND l.code = 'ja'
  AND g.segments = '[{"t":"て"},{"t":" is the "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" of the perfective auxiliary "},{"t":"つ"},{"t":". So the te-form is literally a stem plus a completion marker: \"having done X\".\n\nThat original sense of completion is still doing work in the modern language. It is why "},{"t":"て"},{"t":" naturally means \"and then\" rather than plain \"and\", why 〜"},{"t":"てから"},{"t":" means \"after doing\", and why the past tense "},{"t":"た"},{"t":" is built from the same material ("},{"t":"て"},{"t":" + "},{"t":"あり"},{"t":" → "},{"t":"たり"},{"t":" → "},{"t":"た"},{"t":"). One morpheme, and it explains a whole family of forms."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
