-- 〜ないで: 連用形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-5cae2b90c8431bab', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ないで is the negative with で: 傘を持たないで出かけた, going out in the circumstance of not having one. なくて is the adjective negative ない in its て-form, which links a cause: 分からなくて困った.\n\nWhich で this is has no settled account: it is read as a particle by some and as the 連用形 of だ by others, and the particle itself is traced back either to にて or to ずて, the classical negative plus て. What is not in doubt is the division of labour: ないで attaches to how something was done, なくて to why.","point":"〜ないで","before":[{"t":"ないで"},{"t":" is the negative with "},{"t":"で"},{"t":": "},{"t":"傘","r":"かさ"},{"t":"を"},{"t":"持","r":"も"},{"t":"たないで"},{"t":"出","r":"で"},{"t":"かけた"},{"t":", going out in the circumstance of not having one. "},{"t":"なくて"},{"t":" is the adjective negative "},{"t":"ない"},{"t":" in its "},{"t":"て"},{"t":"-form, which links a cause: "},{"t":"分","r":"わ"},{"t":"からなくて"},{"t":"困","r":"こま"},{"t":"った"},{"t":".\n\nWhich "},{"t":"で"},{"t":" this is has no settled account: it is read as a particle by some and as the "},{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"},{"t":" of "},{"t":"だ"},{"t":" by others, and the particle itself is traced back either to "},{"t":"にて"},{"t":" or to "},{"t":"ずて"},{"t":", the classical negative plus "},{"t":"て"},{"t":". What is not in doubt is the division of labour: "},{"t":"ないで"},{"t":" attaches to how something was done, "},{"t":"なくて"},{"t":" to why."}],"after":[{"t":"ないで"},{"t":" is the negative with "},{"t":"で"},{"t":": "},{"t":"傘","r":"かさ"},{"t":"を"},{"t":"持","r":"も"},{"t":"たないで"},{"t":"出","r":"で"},{"t":"かけた"},{"t":", going out in the circumstance of not having one. "},{"t":"なくて"},{"t":" is the adjective negative "},{"t":"ない"},{"t":" in its "},{"t":"て"},{"t":"-form, which links a cause: "},{"t":"分","r":"わ"},{"t":"からなくて"},{"t":"困","r":"こま"},{"t":"った"},{"t":".\n\nWhich "},{"t":"で"},{"t":" this is has no settled account: it is read as a particle by some and as the "},{"t":"連用形","r":"れんようけい"},{"t":" of "},{"t":"だ"},{"t":" by others, and the particle itself is traced back either to "},{"t":"にて"},{"t":" or to "},{"t":"ずて"},{"t":", the classical negative plus "},{"t":"て"},{"t":". What is not in doubt is the division of labour: "},{"t":"ないで"},{"t":" attaches to how something was done, "},{"t":"なくて"},{"t":" to why."}],"changes":[{"word":"連用形","from":[{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"}],"to":[{"t":"連用形","r":"れんようけい"}],"why":"Grammar term 連用形 is れんようけい."}]}'::jsonb, '{"furigana":[{"t":"ないで"},{"t":" is the negative with "},{"t":"で"},{"t":": "},{"r":"かさ","t":"傘"},{"t":"を"},{"r":"も","t":"持"},{"t":"たないで"},{"r":"で","t":"出"},{"t":"かけた"},{"t":", going out in the circumstance of not having one. "},{"t":"なくて"},{"t":" is the adjective negative "},{"t":"ない"},{"t":" in its "},{"t":"て"},{"t":"-form, which links a cause: "},{"r":"わ","t":"分"},{"t":"からなくて"},{"r":"こま","t":"困"},{"t":"った"},{"t":".\n\nWhich "},{"t":"で"},{"t":" this is has no settled account: it is read as a particle by some and as the "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" of "},{"t":"だ"},{"t":" by others, and the particle itself is traced back either to "},{"t":"にて"},{"t":" or to "},{"t":"ずて"},{"t":", the classical negative plus "},{"t":"て"},{"t":". What is not in doubt is the division of labour: "},{"t":"ないで"},{"t":" attaches to how something was done, "},{"t":"なくて"},{"t":" to why."}]}'::jsonb, 'ai', 900, 'pending'
