-- 〜なら (conditional): 未然形, 京都
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b315029ed0abe26a', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"なり asserted that something was so, and its 未然形 なら took ば, later dropped, to give a plain hypothetical: \"if it be so\".\n\nModern なら has specialised away from that, toward picking up something already in play: 京都なら電車が早い answers a Kyoto somebody has put on the table rather than raising one. The copula''s asserting nature made that natural, though the history alone does not dictate it. It is also why なら, alone among the four, attaches straight to a bare noun.","point":"〜なら (conditional)","before":[{"t":"なり"},{"t":" asserted that something was so, and its "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":" "},{"t":"なら"},{"t":" took "},{"t":"ば"},{"t":", later dropped, to give a plain hypothetical: \"if it be so\".\n\nModern "},{"t":"なら"},{"t":" has specialised away from that, toward picking up something already in play: "},{"t":"京"},{"t":"都","r":"みやこ"},{"t":"なら"},{"t":"電車","r":"でんしゃ"},{"t":"が"},{"t":"早","r":"はや"},{"t":"い"},{"t":" answers a Kyoto somebody has put on the table rather than raising one. The copula''s asserting nature made that natural, though the history alone does not dictate it. It is also why "},{"t":"なら"},{"t":", alone among the four, attaches straight to a bare noun."}],"after":[{"t":"なり"},{"t":" asserted that something was so, and its "},{"t":"未然形","r":"みぜんけい"},{"t":" "},{"t":"なら"},{"t":" took "},{"t":"ば"},{"t":", later dropped, to give a plain hypothetical: \"if it be so\".\n\nModern "},{"t":"なら"},{"t":" has specialised away from that, toward picking up something already in play: "},{"t":"京都","r":"きょうと"},{"t":"なら"},{"t":"電車","r":"でんしゃ"},{"t":"が"},{"t":"早","r":"はや"},{"t":"い"},{"t":" answers a Kyoto somebody has put on the table rather than raising one. The copula''s asserting nature made that natural, though the history alone does not dictate it. It is also why "},{"t":"なら"},{"t":", alone among the four, attaches straight to a bare noun."}],"changes":[{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."},{"word":"京都","from":[{"t":"京"},{"t":"都","r":"みやこ"}],"to":[{"t":"京都","r":"きょうと"}],"why":"Kyoto is きょうと. / The city is きょうと."}]}'::jsonb, '{"furigana":[{"t":"なり"},{"t":" asserted that something was so, and its "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" "},{"t":"なら"},{"t":" took "},{"t":"ば"},{"t":", later dropped, to give a plain hypothetical: \"if it be so\".\n\nModern "},{"t":"なら"},{"t":" has specialised away from that, toward picking up something already in play: "},{"t":"京"},{"r":"みやこ","t":"都"},{"t":"なら"},{"r":"でんしゃ","t":"電車"},{"t":"が"},{"r":"はや","t":"早"},{"t":"い"},{"t":" answers a Kyoto somebody has put on the table rather than raising one. The copula''s asserting nature made that natural, though the history alone does not dictate it. It is also why "},{"t":"なら"},{"t":", alone among the four, attaches straight to a bare noun."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'b315029ed0abe26a6bcb488594e3334d3fb71c7f5582f0b8ecbe2c634e895c2a' AND l.code = 'ja'
  AND g.segments = '[{"t":"なり"},{"t":" asserted that something was so, and its "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" "},{"t":"なら"},{"t":" took "},{"t":"ば"},{"t":", later dropped, to give a plain hypothetical: \"if it be so\".\n\nModern "},{"t":"なら"},{"t":" has specialised away from that, toward picking up something already in play: "},{"t":"京"},{"r":"みやこ","t":"都"},{"t":"なら"},{"r":"でんしゃ","t":"電車"},{"t":"が"},{"r":"はや","t":"早"},{"t":"い"},{"t":" answers a Kyoto somebody has put on the table rather than raising one. The copula''s asserting nature made that natural, though the history alone does not dictate it. It is also why "},{"t":"なら"},{"t":", alone among the four, attaches straight to a bare noun."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

