INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-18fbdf8af433fef9', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"にかかわらず and にもかかわらず share every other syllable. も means \"even\", and adding it says that even this (which plainly should have been concerned in the matter) was not.\n\nThat is why にかかわらず takes neutral alternatives (晴雨にかかわらず) and にもかかわらず takes a real obstacle (努力したにもかかわらず). One is indifference, the other is a complaint, and も is doing all of it.","point":"〜にもかかわらず","before":[{"t":"にかかわらず"},{"t":" and "},{"t":"にもかかわらず"},{"t":" share every other syllable. "},{"t":"も"},{"t":" means \"even\", and adding it says that even this (which plainly should have been concerned in the matter) was not.\n\nThat is why "},{"t":"にかかわらず"},{"t":" takes neutral alternatives ("},{"t":"晴","r":"は"},{"t":"雨","r":"あめ"},{"t":"にかかわらず"},{"t":") and "},{"t":"にもかかわらず"},{"t":" takes a real obstacle ("},{"t":"努力","r":"どりょく"},{"t":"したにもかかわらず"},{"t":"). One is indifference, the other is a complaint, and "},{"t":"も"},{"t":" is doing all of it."}],"after":[{"t":"にかかわらず"},{"t":" and "},{"t":"にもかかわらず"},{"t":" share every other syllable. "},{"t":"も"},{"t":" means \"even\", and adding it says that even this (which plainly should have been concerned in the matter) was not.\n\nThat is why "},{"t":"にかかわらず"},{"t":" takes neutral alternatives ("},{"t":"晴雨","r":"せいう"},{"t":"にかかわらず"},{"t":") and "},{"t":"にもかかわらず"},{"t":" takes a real obstacle ("},{"t":"努力","r":"どりょく"},{"t":"したにもかかわらず"},{"t":"). One is indifference, the other is a complaint, and "},{"t":"も"},{"t":" is doing all of it."}],"changes":[{"word":"晴雨","from":[{"t":"晴","r":"は"},{"t":"雨","r":"あめ"}],"to":[{"t":"晴雨","r":"せいう"}],"why":"Compound is せいう."}]}'::jsonb, '{"furigana":[{"t":"にかかわらず"},{"t":" and "},{"t":"にもかかわらず"},{"t":" share every other syllable. "},{"t":"も"},{"t":" means \"even\", and adding it says that even this (which plainly should have been concerned in the matter) was not.\n\nThat is why "},{"t":"にかかわらず"},{"t":" takes neutral alternatives ("},{"r":"は","t":"晴"},{"r":"あめ","t":"雨"},{"t":"にかかわらず"},{"t":") and "},{"t":"にもかかわらず"},{"t":" takes a real obstacle ("},{"r":"どりょく","t":"努力"},{"t":"したにもかかわらず"},{"t":"). One is indifference, the other is a complaint, and "},{"t":"も"},{"t":" is doing all of it."}]}'::jsonb, 'ai', 900, 'pending'
