-- が inside a clause: 私が, 私, 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-39616bdfba695769', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"は marks the topic of a whole sentence, and a clause describing a noun is not a whole sentence. So 私が買った本 uses が, and 私は buys nothing inside a clause.\n\nThe older genitive が is still visible in the alternative 私の買った本, which is equally correct and slightly more formal, the same が-and-の overlap preserved in 我が国.","point":"が inside a clause","before":[{"t":"は"},{"t":" marks the topic of a whole sentence, and a clause describing a noun is not a whole sentence. So "},{"t":"私","r":"わちき"},{"t":"が"},{"t":"買","r":"か"},{"t":"った"},{"t":"本","r":"ほん"},{"t":" uses "},{"t":"が"},{"t":", and "},{"t":"私","r":"わちき"},{"t":"は"},{"t":" buys nothing inside a clause.\n\nThe older genitive "},{"t":"が"},{"t":" is still visible in the alternative "},{"t":"私","r":"わちき"},{"t":"の"},{"t":"買","r":"か"},{"t":"った"},{"t":"本","r":"ほん"},{"t":", which is equally correct and slightly more formal, the same "},{"t":"が"},{"t":"-and-"},{"t":"の"},{"t":" overlap preserved in "},{"t":"我","r":"わ"},{"t":"が"},{"t":"国","r":"くに"},{"t":"."}],"after":[{"t":"は"},{"t":" marks the topic of a whole sentence, and a clause describing a noun is not a whole sentence. So "},{"t":"私","r":"わたし"},{"t":"が"},{"t":"買","r":"か"},{"t":"った"},{"t":"本","r":"ほん"},{"t":" uses "},{"t":"が"},{"t":", and "},{"t":"私","r":"わたし"},{"t":"は"},{"t":" buys nothing inside a clause.\n\nThe older genitive "},{"t":"が"},{"t":" is still visible in the alternative "},{"t":"私","r":"わたし"},{"t":"の"},{"t":"買","r":"か"},{"t":"った"},{"t":"本","r":"ほん"},{"t":", which is equally correct and slightly more formal, the same "},{"t":"が"},{"t":"-and-"},{"t":"の"},{"t":" overlap preserved in "},{"t":"我","r":"わ"},{"t":"が"},{"t":"国","r":"くに"},{"t":"."}],"changes":[{"word":"私が","from":[{"t":"私","r":"わちき"},{"t":"が"}],"to":[{"t":"私","r":"わたし"},{"t":"が"}],"why":"私 is わたし."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"は"},{"t":" marks the topic of a whole sentence, and a clause describing a noun is not a whole sentence. So "},{"r":"わちき","t":"私"},{"t":"が"},{"r":"か","t":"買"},{"t":"った"},{"r":"ほん","t":"本"},{"t":" uses "},{"t":"が"},{"t":", and "},{"r":"わちき","t":"私"},{"t":"は"},{"t":" buys nothing inside a clause.\n\nThe older genitive "},{"t":"が"},{"t":" is still visible in the alternative "},{"r":"わちき","t":"私"},{"t":"の"},{"r":"か","t":"買"},{"t":"った"},{"r":"ほん","t":"本"},{"t":", which is equally correct and slightly more formal, the same "},{"t":"が"},{"t":"-and-"},{"t":"の"},{"t":" overlap preserved in "},{"r":"わ","t":"我"},{"t":"が"},{"r":"くに","t":"国"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
