  AND g.segments = '[{"t":"は"},{"t":" marks the topic of a whole sentence, and a clause describing a noun is not a whole sentence. So "},{"r":"わちき","t":"私"},{"t":"が"},{"r":"か","t":"買"},{"t":"った"},{"r":"ほん","t":"本"},{"t":" uses "},{"t":"が"},{"t":", and "},{"r":"わちき","t":"私"},{"t":"は"},{"t":" buys nothing inside a clause.\n\nThe older genitive "},{"t":"が"},{"t":" is still visible in the alternative "},{"r":"わちき","t":"私"},{"t":"の"},{"r":"か","t":"買"},{"t":"った"},{"r":"ほん","t":"本"},{"t":", which is equally correct and slightly more formal, the same "},{"t":"が"},{"t":"-and-"},{"t":"の"},{"t":" overlap preserved in "},{"r":"わ","t":"我"},{"t":"が"},{"r":"くに","t":"国"},{"t":"."}]'::jsonb
