SELECT 'crq-grammar-d47fccfc99be1e82', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ひとつ, ふたつ, みっつ: one, two, three in the words Japanese used before it borrowed いち, に, さん from Chinese. The native series survives only up to nine, and ten is とお.\n\nThat is why つ is the counter you fall back on when no other fits: it is older than the borrowed system that produced the specialised counters. ひとり and ふたり are the same native numbers, which is why they break the pattern that 三人 follows.","point":"〜つ (counter)","before":[{"t":"ひとつ"},{"t":", "},{"t":"ふたつ"},{"t":", "},{"t":"みっつ"},{"t":": one, two, three in the words Japanese used before it borrowed "},{"t":"いち"},{"t":", "},{"t":"に"},{"t":", "},{"t":"さん"},{"t":" from Chinese. The native series survives only up to nine, and ten is "},{"t":"とお"},{"t":".\n\nThat is why "},{"t":"つ"},{"t":" is the counter you fall back on when no other fits: it is older than the borrowed system that produced the specialised counters. "},{"t":"ひとり"},{"t":" and "},{"t":"ふたり"},{"t":" are the same native numbers, which is why they break the pattern that "},{"t":"三","r":"さん"},{"t":"人","r":"と"},{"t":" follows."}],"after":[{"t":"ひとつ"},{"t":", "},{"t":"ふたつ"},{"t":", "},{"t":"みっつ"},{"t":": one, two, three in the words Japanese used before it borrowed "},{"t":"いち"},{"t":", "},{"t":"に"},{"t":", "},{"t":"さん"},{"t":" from Chinese. The native series survives only up to nine, and ten is "},{"t":"とお"},{"t":".\n\nThat is why "},{"t":"つ"},{"t":" is the counter you fall back on when no other fits: it is older than the borrowed system that produced the specialised counters. "},{"t":"ひとり"},{"t":" and "},{"t":"ふたり"},{"t":" are the same native numbers, which is why they break the pattern that "},{"t":"三人","r":"さんにん"},{"t":" follows."}],"changes":[{"word":"三人","from":[{"t":"三","r":"さん"},{"t":"人","r":"と"}],"to":[{"t":"三人","r":"さんにん"}],"why":"Three people is さんにん."}]}'::jsonb, '{"furigana":[{"t":"ひとつ"},{"t":", "},{"t":"ふたつ"},{"t":", "},{"t":"みっつ"},{"t":": one, two, three in the words Japanese used before it borrowed "},{"t":"いち"},{"t":", "},{"t":"に"},{"t":", "},{"t":"さん"},{"t":" from Chinese. The native series survives only up to nine, and ten is "},{"t":"とお"},{"t":".\n\nThat is why "},{"t":"つ"},{"t":" is the counter you fall back on when no other fits: it is older than the borrowed system that produced the specialised counters. "},{"t":"ひとり"},{"t":" and "},{"t":"ふたり"},{"t":" are the same native numbers, which is why they break the pattern that "},{"r":"さん","t":"三"},{"r":"と","t":"人"},{"t":" follows."}]}'::jsonb, 'ai', 900, 'pending'
