-- に (direction / time): 三時, 東京, 東京
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-e4569058e1788c10', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"へ came from 辺, a vicinity, historically a heading rather than a point. The two overlap for destinations in modern Japanese, and 東京へ着く is perfectly ordinary; what に keeps to itself is every other kind of point.\n\nOne idea covers every use the textbook lists separately. 三時に is a point in time; 東京に着く is a point in space; 友達に渡す is the point the thing lands on. If the sentence has a target, it is に.","point":"に (direction / time)","before":[{"t":"へ"},{"t":" came from "},{"t":"辺","r":"へ"},{"t":", a vicinity, historically a heading rather than a point. The two overlap for destinations in modern Japanese, and "},{"t":"東","r":"とん"},{"t":"京へ"},{"t":"着","r":"つ"},{"t":"く"},{"t":" is perfectly ordinary; what "},{"t":"に"},{"t":" keeps to itself is every other kind of point.\n\nOne idea covers every use the textbook lists separately. "},{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"に"},{"t":" is a point in time; "},{"t":"東","r":"とん"},{"t":"京に"},{"t":"着","r":"つ"},{"t":"く"},{"t":" is a point in space; "},{"t":"友達","r":"ともだち"},{"t":"に"},{"t":"渡","r":"わた"},{"t":"す"},{"t":" is the point the thing lands on. If the sentence has a target, it is "},{"t":"に"},{"t":"."}],"after":[{"t":"へ"},{"t":" came from "},{"t":"辺","r":"へ"},{"t":", a vicinity, historically a heading rather than a point. The two overlap for destinations in modern Japanese, and "},{"t":"東京","r":"とうきょう"},{"t":"へ"},{"t":"着","r":"つ"},{"t":"く"},{"t":" is perfectly ordinary; what "},{"t":"に"},{"t":" keeps to itself is every other kind of point.\n\nOne idea covers every use the textbook lists separately. "},{"t":"三時","r":"さんじ"},{"t":"に"},{"t":" is a point in time; "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":"着","r":"つ"},{"t":"く"},{"t":" is a point in space; "},{"t":"友達","r":"ともだち"},{"t":"に"},{"t":"渡","r":"わた"},{"t":"す"},{"t":" is the point the thing lands on. If the sentence has a target, it is "},{"t":"に"},{"t":"."}],"changes":[{"word":"三時","from":[{"t":"三","r":"さん"},{"t":"時","r":"とき"}],"to":[{"t":"三時","r":"さんじ"}],"why":"Three o''clock is さんじ. / 三時 is さんじ."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."}]}'::jsonb, '{"furigana":[{"t":"へ"},{"t":" came from "},{"r":"へ","t":"辺"},{"t":", a vicinity, historically a heading rather than a point. The two overlap for destinations in modern Japanese, and "},{"r":"とん","t":"東"},{"t":"京へ"},{"r":"つ","t":"着"},{"t":"く"},{"t":" is perfectly ordinary; what "},{"t":"に"},{"t":" keeps to itself is every other kind of point.\n\nOne idea covers every use the textbook lists separately. "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"に"},{"t":" is a point in time; "},{"r":"とん","t":"東"},{"t":"京に"},{"r":"つ","t":"着"},{"t":"く"},{"t":" is a point in space; "},{"r":"ともだち","t":"友達"},{"t":"に"},{"r":"わた","t":"渡"},{"t":"す"},{"t":" is the point the thing lands on. If the sentence has a target, it is "},{"t":"に"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
