-- と (together with): 先生, 先生
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-97c4aca7a7fcaa63', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"友達と行く pairs you with a companion exactly as 本と鉛筆 pairs two things. Nothing distinguishes them but what is on either side.\n\nIt is why と cannot be used for a one-sided action: 先生と話す is a conversation, 先生に話す is telling, since pairing implies both parties are in it.","point":"と (together with)","before":[{"t":"友達","r":"ともだち"},{"t":"と"},{"t":"行","r":"い"},{"t":"く"},{"t":" pairs you with a companion exactly as "},{"t":"本","r":"ほん"},{"t":"と"},{"t":"鉛筆","r":"えんぴつ"},{"t":" pairs two things. Nothing distinguishes them but what is on either side.\n\nIt is why "},{"t":"と"},{"t":" cannot be used for a one-sided action: "},{"t":"先生","r":"せんじょう"},{"t":"と"},{"t":"話","r":"はな"},{"t":"す"},{"t":" is a conversation, "},{"t":"先生","r":"せんじょう"},{"t":"に"},{"t":"話","r":"はな"},{"t":"す"},{"t":" is telling, since pairing implies both parties are in it."}],"after":[{"t":"友達","r":"ともだち"},{"t":"と"},{"t":"行","r":"い"},{"t":"く"},{"t":" pairs you with a companion exactly as "},{"t":"本","r":"ほん"},{"t":"と"},{"t":"鉛筆","r":"えんぴつ"},{"t":" pairs two things. Nothing distinguishes them but what is on either side.\n\nIt is why "},{"t":"と"},{"t":" cannot be used for a one-sided action: "},{"t":"先生","r":"せんせい"},{"t":"と"},{"t":"話","r":"はな"},{"t":"す"},{"t":" is a conversation, "},{"t":"先生","r":"せんせい"},{"t":"に"},{"t":"話","r":"はな"},{"t":"す"},{"t":" is telling, since pairing implies both parties are in it."}],"changes":[{"word":"先生","from":[{"t":"先生","r":"せんじょう"}],"to":[{"t":"先生","r":"せんせい"}],"why":"Teacher is せんせい. / Typo reading; correct is せんせい. / 先生 is せんせい."},{"word":"先生","from":[{"t":"先生","r":"せんじょう"}],"to":[{"t":"先生","r":"せんせい"}],"why":"Teacher is せんせい. / Typo reading; correct is せんせい. / 先生 is せんせい."}]}'::jsonb, '{"furigana":[{"r":"ともだち","t":"友達"},{"t":"と"},{"r":"い","t":"行"},{"t":"く"},{"t":" pairs you with a companion exactly as "},{"r":"ほん","t":"本"},{"t":"と"},{"r":"えんぴつ","t":"鉛筆"},{"t":" pairs two things. Nothing distinguishes them but what is on either side.\n\nIt is why "},{"t":"と"},{"t":" cannot be used for a one-sided action: "},{"r":"せんじょう","t":"先生"},{"t":"と"},{"r":"はな","t":"話"},{"t":"す"},{"t":" is a conversation, "},{"r":"せんじょう","t":"先生"},{"t":"に"},{"r":"はな","t":"話"},{"t":"す"},{"t":" is telling, since pairing implies both parties are in it."}]}'::jsonb, 'ai', 900, 'pending'
