-- 〜まい: 私はもう, 二度
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-53de3e7566b762fa', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"まじ negated べし. Where べし said something should or would be, まじ said it should not or would not, and まい is what survives of it.\n\nIt kept both of べし''s senses. 雨は降るまい is conjecture (surely not); 二度と行くまい is resolve (I will not). The two readings textbooks list separately are the one auxiliary. Which you get depends on the subject and on whether the verb names something one can will: 私はもう長くは生きられまい is first person and still pure conjecture.","point":"〜まい","before":[{"t":"まじ"},{"t":" negated "},{"t":"べし"},{"t":". Where "},{"t":"べし"},{"t":" said something should or would be, "},{"t":"まじ"},{"t":" said it should not or would not, and "},{"t":"まい"},{"t":" is what survives of it.\n\nIt kept both of "},{"t":"べし"},{"t":"''s senses. "},{"t":"雨","r":"あめ"},{"t":"は"},{"t":"降","r":"ふ"},{"t":"るまい"},{"t":" is conjecture (surely not); "},{"t":"二","r":"りゃん"},{"t":"度","r":"たび"},{"t":"と"},{"t":"行","r":"い"},{"t":"くまい"},{"t":" is resolve (I will not). The two readings textbooks list separately are the one auxiliary. Which you get depends on the subject and on whether the verb names something one can will: "},{"t":"私","r":"わちき"},{"t":"はもう"},{"t":"長","r":"なが"},{"t":"くは"},{"t":"生","r":"い"},{"t":"きられまい"},{"t":" is first person and still pure conjecture."}],"after":[{"t":"まじ"},{"t":" negated "},{"t":"べし"},{"t":". Where "},{"t":"べし"},{"t":" said something should or would be, "},{"t":"まじ"},{"t":" said it should not or would not, and "},{"t":"まい"},{"t":" is what survives of it.\n\nIt kept both of "},{"t":"べし"},{"t":"''s senses. "},{"t":"雨","r":"あめ"},{"t":"は"},{"t":"降","r":"ふ"},{"t":"るまい"},{"t":" is conjecture (surely not); "},{"t":"二度","r":"にど"},{"t":"と"},{"t":"行","r":"い"},{"t":"くまい"},{"t":" is resolve (I will not). The two readings textbooks list separately are the one auxiliary. Which you get depends on the subject and on whether the verb names something one can will: "},{"t":"私","r":"わたし"},{"t":"はもう"},{"t":"長","r":"なが"},{"t":"くは"},{"t":"生","r":"い"},{"t":"きられまい"},{"t":" is first person and still pure conjecture."}],"changes":[{"word":"私はもう","from":[{"t":"私","r":"わちき"},{"t":"はもう"}],"to":[{"t":"私","r":"わたし"},{"t":"はもう"}],"why":"私 is わたし."},{"word":"二度","from":[{"t":"二","r":"りゃん"},{"t":"度","r":"たび"}],"to":[{"t":"二度","r":"にど"}],"why":"Counter reading, two times is にど."}]}'::jsonb, '{"furigana":[{"t":"まじ"},{"t":" negated "},{"t":"べし"},{"t":". Where "},{"t":"べし"},{"t":" said something should or would be, "},{"t":"まじ"},{"t":" said it should not or would not, and "},{"t":"まい"},{"t":" is what survives of it.\n\nIt kept both of "},{"t":"べし"},{"t":"''s senses. "},{"r":"あめ","t":"雨"},{"t":"は"},{"r":"ふ","t":"降"},{"t":"るまい"},{"t":" is conjecture (surely not); "},{"r":"りゃん","t":"二"},{"r":"たび","t":"度"},{"t":"と"},{"r":"い","t":"行"},{"t":"くまい"},{"t":" is resolve (I will not). The two readings textbooks list separately are the one auxiliary. Which you get depends on the subject and on whether the verb names something one can will: "},{"r":"わちき","t":"私"},{"t":"はもう"},{"r":"なが","t":"長"},{"t":"くは"},{"r":"い","t":"生"},{"t":"きられまい"},{"t":" is first person and still pure conjecture."}]}'::jsonb, 'ai', 900, 'pending'
