-- 〜ませんでした: 幕末
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-e46527a366baf10e', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ません ends in the fossilised negative ん, which does not inflect. So the polite negative past cannot be built the way ました is; it borrows でした, the past of です, and puts it after.\n\nThat is why this form is two words long where every other polite ending is one, though it was settled by competition rather than by logic: Edo speech said ませなんだ, and 幕末 had ませんかった and ませんだった before ませんでした won in the Meiji years. The plain equivalent なかった has no such trouble, because ない is an adjective and can simply become かった.","point":"〜ませんでした","before":[{"t":"ません"},{"t":" ends in the fossilised negative "},{"t":"ん"},{"t":", which does not inflect. So the polite negative past cannot be built the way "},{"t":"ました"},{"t":" is; it borrows "},{"t":"でした"},{"t":", the past of "},{"t":"です"},{"t":", and puts it after.\n\nThat is why this form is two words long where every other polite ending is one, though it was settled by competition rather than by logic: Edo speech said "},{"t":"ませなんだ"},{"t":", and "},{"t":"幕","r":"まく"},{"t":"末","r":"うれ"},{"t":" had "},{"t":"ませんかった"},{"t":" and "},{"t":"ませんだった"},{"t":" before "},{"t":"ませんでした"},{"t":" won in the Meiji years. The plain equivalent "},{"t":"なかった"},{"t":" has no such trouble, because "},{"t":"ない"},{"t":" is an adjective and can simply become "},{"t":"かった"},{"t":"."}],"after":[{"t":"ません"},{"t":" ends in the fossilised negative "},{"t":"ん"},{"t":", which does not inflect. So the polite negative past cannot be built the way "},{"t":"ました"},{"t":" is; it borrows "},{"t":"でした"},{"t":", the past of "},{"t":"です"},{"t":", and puts it after.\n\nThat is why this form is two words long where every other polite ending is one, though it was settled by competition rather than by logic: Edo speech said "},{"t":"ませなんだ"},{"t":", and "},{"t":"幕末","r":"ばくまつ"},{"t":" had "},{"t":"ませんかった"},{"t":" and "},{"t":"ませんだった"},{"t":" before "},{"t":"ませんでした"},{"t":" won in the Meiji years. The plain equivalent "},{"t":"なかった"},{"t":" has no such trouble, because "},{"t":"ない"},{"t":" is an adjective and can simply become "},{"t":"かった"},{"t":"."}],"changes":[{"word":"幕末","from":[{"t":"幕","r":"まく"},{"t":"末","r":"うれ"}],"to":[{"t":"幕末","r":"ばくまつ"}],"why":"Compound is ばくまつ. / 幕末 is ばくまつ."}]}'::jsonb, '{"furigana":[{"t":"ません"},{"t":" ends in the fossilised negative "},{"t":"ん"},{"t":", which does not inflect. So the polite negative past cannot be built the way "},{"t":"ました"},{"t":" is; it borrows "},{"t":"でした"},{"t":", the past of "},{"t":"です"},{"t":", and puts it after.\n\nThat is why this form is two words long where every other polite ending is one, though it was settled by competition rather than by logic: Edo speech said "},{"t":"ませなんだ"},{"t":", and "},{"r":"まく","t":"幕"},{"r":"うれ","t":"末"},{"t":" had "},{"t":"ませんかった"},{"t":" and "},{"t":"ませんだった"},{"t":" before "},{"t":"ませんでした"},{"t":" won in the Meiji years. The plain equivalent "},{"t":"なかった"},{"t":" has no such trouble, because "},{"t":"ない"},{"t":" is an adjective and can simply become "},{"t":"かった"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'e46527a366baf10e2722561f4869319c7cb5355b91080cbbad94aaf792638aaf' AND l.code = 'ja'
  AND g.segments = '[{"t":"ません"},{"t":" ends in the fossilised negative "},{"t":"ん"},{"t":", which does not inflect. So the polite negative past cannot be built the way "},{"t":"ました"},{"t":" is; it borrows "},{"t":"でした"},{"t":", the past of "},{"t":"です"},{"t":", and puts it after.\n\nThat is why this form is two words long where every other polite ending is one, though it was settled by competition rather than by logic: Edo speech said "},{"t":"ませなんだ"},{"t":", and "},{"r":"まく","t":"幕"},{"r":"うれ","t":"末"},{"t":" had "},{"t":"ませんかった"},{"t":" and "},{"t":"ませんだった"},{"t":" before "},{"t":"ませんでした"},{"t":" won in the Meiji years. The plain equivalent "},{"t":"なかった"},{"t":" has no such trouble, because "},{"t":"ない"},{"t":" is an adjective and can simply become "},{"t":"かった"},{"t":"."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
