-- 〜わけではない: 嫌い
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-e2803ad5698ba302', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"わけがない flatly denies that any reason exists. わけではない uses では (the topic-marked negative), and topic-marking is what makes it partial: it denies this particular account while leaving others standing.\n\nSo 嫌いなわけではない says not that liking is untrue but that dislike is not the explanation. The same では does the same softening everywhere else in the language, which is why the pattern feels hedged without anything hedging having been added.","point":"〜わけではない","before":[{"t":"わけがない"},{"t":" flatly denies that any reason exists. "},{"t":"わけではない"},{"t":" uses "},{"t":"では"},{"t":" (the topic-marked negative), and topic-marking is what makes it partial: it denies this particular account while leaving others standing.\n\nSo "},{"t":"嫌","r":"ぎら"},{"t":"いなわけではない"},{"t":" says not that liking is untrue but that dislike is not the explanation. The same "},{"t":"では"},{"t":" does the same softening everywhere else in the language, which is why the pattern feels hedged without anything hedging having been added."}],"after":[{"t":"わけがない"},{"t":" flatly denies that any reason exists. "},{"t":"わけではない"},{"t":" uses "},{"t":"では"},{"t":" (the topic-marked negative), and topic-marking is what makes it partial: it denies this particular account while leaving others standing.\n\nSo "},{"t":"嫌","r":"きら"},{"t":"い"},{"t":"なわけではない"},{"t":" says not that liking is untrue but that dislike is not the explanation. The same "},{"t":"では"},{"t":" does the same softening everywhere else in the language, which is why the pattern feels hedged without anything hedging having been added."}],"changes":[{"word":"嫌い","from":[{"t":"嫌","r":"ぎら"},{"t":"い"}],"to":[{"t":"嫌","r":"きら"},{"t":"い"}],"why":"Dislike is きらい. / 嫌い is きらい."}]}'::jsonb, '{"furigana":[{"t":"わけがない"},{"t":" flatly denies that any reason exists. "},{"t":"わけではない"},{"t":" uses "},{"t":"では"},{"t":" (the topic-marked negative), and topic-marking is what makes it partial: it denies this particular account while leaving others standing.\n\nSo "},{"r":"ぎら","t":"嫌"},{"t":"いなわけではない"},{"t":" says not that liking is untrue but that dislike is not the explanation. The same "},{"t":"では"},{"t":" does the same softening everywhere else in the language, which is why the pattern feels hedged without anything hedging having been added."}]}'::jsonb, 'ai', 900, 'pending'
