SELECT 'crq-grammar-11519696ec7f69c4', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"一分 is いっぷん, 二分 is にふん, 三分 is さんぷん: three consonants across three consecutive numbers. 時 is steadier but still gives よじ and くじ rather than しじ and きゅうじ.\n\nThese are ordinary sound changes at a boundary, the same ones that give いっぽん and さんぼん. They are not learnable by rule in any form shorter than the list, which is why the list is what to learn.","point":"〜時 / 〜分 (time)","before":[{"t":"一","r":"いっち"},{"t":"分","r":"ふん"},{"t":" is "},{"t":"いっぷん"},{"t":", "},{"t":"二","r":"りゃん"},{"t":"分","r":"ふん"},{"t":" is "},{"t":"にふん"},{"t":", "},{"t":"三","r":"さん"},{"t":"分","r":"ふん"},{"t":" is "},{"t":"さんぷん"},{"t":": three consonants across three consecutive numbers. "},{"t":"時","r":"とき"},{"t":" is steadier but still gives "},{"t":"よじ"},{"t":" and "},{"t":"くじ"},{"t":" rather than "},{"t":"しじ"},{"t":" and "},{"t":"きゅうじ"},{"t":".\n\nThese are ordinary sound changes at a boundary, the same ones that give "},{"t":"いっぽん"},{"t":" and "},{"t":"さんぼん"},{"t":". They are not learnable by rule in any form shorter than the list, which is why the list is what to learn."}],"after":[{"t":"一分","r":"いっぷん"},{"t":" is "},{"t":"いっぷん"},{"t":", "},{"t":"二分","r":"にふん"},{"t":" is "},{"t":"にふん"},{"t":", "},{"t":"三分","r":"さんぷん"},{"t":" is "},{"t":"さんぷん"},{"t":": three consonants across three consecutive numbers. "},{"t":"時","r":"とき"},{"t":" is steadier but still gives "},{"t":"よじ"},{"t":" and "},{"t":"くじ"},{"t":" rather than "},{"t":"しじ"},{"t":" and "},{"t":"きゅうじ"},{"t":".\n\nThese are ordinary sound changes at a boundary, the same ones that give "},{"t":"いっぽん"},{"t":" and "},{"t":"さんぼん"},{"t":". They are not learnable by rule in any form shorter than the list, which is why the list is what to learn."}],"changes":[{"word":"一分","from":[{"t":"一","r":"いっち"},{"t":"分","r":"ふん"}],"to":[{"t":"一分","r":"いっぷん"}],"why":"One minute is いっぷん."},{"word":"二分","from":[{"t":"二","r":"りゃん"},{"t":"分","r":"ふん"}],"to":[{"t":"二分","r":"にふん"}],"why":"Two minutes is にふん."},{"word":"三分","from":[{"t":"三","r":"さん"},{"t":"分","r":"ふん"}],"to":[{"t":"三分","r":"さんぷん"}],"why":"Three minutes is さんぷん."}]}'::jsonb, '{"furigana":[{"r":"いっち","t":"一"},{"r":"ふん","t":"分"},{"t":" is "},{"t":"いっぷん"},{"t":", "},{"r":"りゃん","t":"二"},{"r":"ふん","t":"分"},{"t":" is "},{"t":"にふん"},{"t":", "},{"r":"さん","t":"三"},{"r":"ふん","t":"分"},{"t":" is "},{"t":"さんぷん"},{"t":": three consonants across three consecutive numbers. "},{"r":"とき","t":"時"},{"t":" is steadier but still gives "},{"t":"よじ"},{"t":" and "},{"t":"くじ"},{"t":" rather than "},{"t":"しじ"},{"t":" and "},{"t":"きゅうじ"},{"t":".\n\nThese are ordinary sound changes at a boundary, the same ones that give "},{"t":"いっぽん"},{"t":" and "},{"t":"さんぼん"},{"t":". They are not learnable by rule in any form shorter than the list, which is why the list is what to learn."}]}'::jsonb, 'ai', 900, 'pending'
