-- 〜人 (counter): 二日, 四日, 三日, 三人, 十日
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-e1ee71a4619c4b18', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"三人 is さんにん, borrowed Chinese number plus borrowed reading, entirely regular. 一人 and 二人 are ひと and ふた (the native numbers behind ひとつ and ふたつ), with a native ending.\n\nSo the exception is not an exception but a survival: the two commonest counts kept the old words while everything above three went over to the borrowed system. The same native numbers survive in the date series (二日, 三日, 四日), which stayed native all the way to 十日.","point":"〜人 (counter)","before":[{"t":"三","r":"さん"},{"t":"人","r":"と"},{"t":" is "},{"t":"さんにん"},{"t":", borrowed Chinese number plus borrowed reading, entirely regular. "},{"t":"一人","r":"ひとり"},{"t":" and "},{"t":"二人","r":"ふたり"},{"t":" are "},{"t":"ひと"},{"t":" and "},{"t":"ふた"},{"t":" (the native numbers behind "},{"t":"ひとつ"},{"t":" and "},{"t":"ふたつ"},{"t":"), with a native ending.\n\nSo the exception is not an exception but a survival: the two commonest counts kept the old words while everything above three went over to the borrowed system. The same native numbers survive in the date series ("},{"t":"二","r":"りゃん"},{"t":"日","r":"にち"},{"t":", "},{"t":"三","r":"さん"},{"t":"日","r":"にち"},{"t":", "},{"t":"四","r":"し"},{"t":"日","r":"にち"},{"t":"), which stayed native all the way to "},{"t":"十","r":"しー"},{"t":"日","r":"にち"},{"t":"."}],"after":[{"t":"三人","r":"さんにん"},{"t":" is "},{"t":"さんにん"},{"t":", borrowed Chinese number plus borrowed reading, entirely regular. "},{"t":"一人","r":"ひとり"},{"t":" and "},{"t":"二人","r":"ふたり"},{"t":" are "},{"t":"ひと"},{"t":" and "},{"t":"ふた"},{"t":" (the native numbers behind "},{"t":"ひとつ"},{"t":" and "},{"t":"ふたつ"},{"t":"), with a native ending.\n\nSo the exception is not an exception but a survival: the two commonest counts kept the old words while everything above three went over to the borrowed system. The same native numbers survive in the date series ("},{"t":"二日","r":"ふつか"},{"t":", "},{"t":"三日","r":"みっか"},{"t":", "},{"t":"四日","r":"よっか"},{"t":"), which stayed native all the way to "},{"t":"十日","r":"とおか"},{"t":"."}],"changes":[{"word":"二日","from":[{"t":"二","r":"りゃん"},{"t":"日","r":"にち"}],"to":[{"t":"二日","r":"ふつか"}],"why":"二日 is ふつか."},{"word":"四日","from":[{"t":"四","r":"し"},{"t":"日","r":"にち"}],"to":[{"t":"四日","r":"よっか"}],"why":"Fourth day is よっか."},{"word":"三日","from":[{"t":"三","r":"さん"},{"t":"日","r":"にち"}],"to":[{"t":"三日","r":"みっか"}],"why":"Three days is みっか."},{"word":"三人","from":[{"t":"三","r":"さん"},{"t":"人","r":"と"}],"to":[{"t":"三人","r":"さんにん"}],"why":"Three people is さんにん."},{"word":"十日","from":[{"t":"十","r":"しー"},{"t":"日","r":"にち"}],"to":[{"t":"十日","r":"とおか"}],"why":"The tenth day is とおか."}]}'::jsonb, '{"furigana":[{"r":"さん","t":"三"},{"r":"と","t":"人"},{"t":" is "},{"t":"さんにん"},{"t":", borrowed Chinese number plus borrowed reading, entirely regular. "},{"r":"ひとり","t":"一人"},{"t":" and "},{"r":"ふたり","t":"二人"},{"t":" are "},{"t":"ひと"},{"t":" and "},{"t":"ふた"},{"t":" (the native numbers behind "},{"t":"ひとつ"},{"t":" and "},{"t":"ふたつ"},{"t":"), with a native ending.\n\nSo the exception is not an exception but a survival: the two commonest counts kept the old words while everything above three went over to the borrowed system. The same native numbers survive in the date series ("},{"r":"りゃん","t":"二"},{"r":"にち","t":"日"},{"t":", "},{"r":"さん","t":"三"},{"r":"にち","t":"日"},{"t":", "},{"r":"し","t":"四"},{"r":"にち","t":"日"},{"t":"), which stayed native all the way to "},{"r":"しー","t":"十"},{"r":"にち","t":"日"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
