-- 〜しか〜ない: より外
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-97fa00fd9a9e3e3c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"千円しかない is \"apart from a thousand yen, there is not\". しか sets the thing aside and the negative rules out the rest.\n\nIt is a late arrival; it spread in the Edo period and is essentially absent from Heian prose, which used 〜より外…ず instead. The pieces are usually read as the particle し plus the particle か. That the negative is required is not a rule to remember but the other half of the sentence, and it is why しか carries a shortfall where だけ, which merely limits, does not.","point":"〜しか〜ない","before":[{"t":"千","r":"せん"},{"t":"円","r":"えん"},{"t":"しかない"},{"t":" is \"apart from a thousand yen, there is not\". "},{"t":"しか"},{"t":" sets the thing aside and the negative rules out the rest.\n\nIt is a late arrival; it spread in the Edo period and is essentially absent from Heian prose, which used 〜"},{"t":"より"},{"t":"外","r":"がい"},{"t":"…"},{"t":"ず"},{"t":" instead. The pieces are usually read as the particle "},{"t":"し"},{"t":" plus the particle "},{"t":"か"},{"t":". That the negative is required is not a rule to remember but the other half of the sentence, and it is why "},{"t":"しか"},{"t":" carries a shortfall where "},{"t":"だけ"},{"t":", which merely limits, does not."}],"after":[{"t":"千","r":"せん"},{"t":"円","r":"えん"},{"t":"しかない"},{"t":" is \"apart from a thousand yen, there is not\". "},{"t":"しか"},{"t":" sets the thing aside and the negative rules out the rest.\n\nIt is a late arrival; it spread in the Edo period and is essentially absent from Heian prose, which used 〜"},{"t":"より"},{"t":"外","r":"ほか"},{"t":"…"},{"t":"ず"},{"t":" instead. The pieces are usually read as the particle "},{"t":"し"},{"t":" plus the particle "},{"t":"か"},{"t":". That the negative is required is not a rule to remember but the other half of the sentence, and it is why "},{"t":"しか"},{"t":" carries a shortfall where "},{"t":"だけ"},{"t":", which merely limits, does not."}],"changes":[{"word":"より外","from":[{"t":"より"},{"t":"外","r":"がい"}],"to":[{"t":"より"},{"t":"外","r":"ほか"}],"why":"外 here is ほか."}]}'::jsonb, '{"furigana":[{"r":"せん","t":"千"},{"r":"えん","t":"円"},{"t":"しかない"},{"t":" is \"apart from a thousand yen, there is not\". "},{"t":"しか"},{"t":" sets the thing aside and the negative rules out the rest.\n\nIt is a late arrival; it spread in the Edo period and is essentially absent from Heian prose, which used 〜"},{"t":"より"},{"r":"がい","t":"外"},{"t":"…"},{"t":"ず"},{"t":" instead. The pieces are usually read as the particle "},{"t":"し"},{"t":" plus the particle "},{"t":"か"},{"t":". That the negative is required is not a rule to remember but the other half of the sentence, and it is why "},{"t":"しか"},{"t":" carries a shortfall where "},{"t":"だけ"},{"t":", which merely limits, does not."}]}'::jsonb, 'ai', 900, 'pending'
