INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-4d04bb0602df30af', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"塗 is a shared spelling, not shared ancestry: まみれる is not kin to 塗る. It is attested from the Heian period, in 大和物語 among others.\n\nWhat is まみれ has had something spread over it, typically things that genuinely coat: 血まみれ, 泥まみれ, 汗まみれ. The conventional extension is to clinging abstractions (借金まみれ), where だらけ, which can hold anything anywhere including mistakes, is the broader word.","point":"〜まみれ","before":[{"t":"塗","r":"ぬ"},{"t":" is a shared spelling, not shared ancestry: "},{"t":"まみれる"},{"t":" is not kin to "},{"t":"塗","r":"ぬ"},{"t":"る"},{"t":". It is attested from the Heian period, in "},{"t":"大","r":"たい"},{"t":"和","r":"にこ"},{"t":"物語","r":"ものがたり"},{"t":" among others.\n\nWhat is "},{"t":"まみれ"},{"t":" has had something spread over it, typically things that genuinely coat: "},{"t":"血","r":"ち"},{"t":"まみれ"},{"t":", "},{"t":"泥","r":"どろ"},{"t":"まみれ"},{"t":", "},{"t":"汗","r":"あせ"},{"t":"まみれ"},{"t":". The conventional extension is to clinging abstractions ("},{"t":"借金","r":"しゃっきん"},{"t":"まみれ"},{"t":"), where "},{"t":"だらけ"},{"t":", which can hold anything anywhere including mistakes, is the broader word."}],"after":[{"t":"塗","r":"ぬ"},{"t":" is a shared spelling, not shared ancestry: "},{"t":"まみれる"},{"t":" is not kin to "},{"t":"塗","r":"ぬ"},{"t":"る"},{"t":". It is attested from the Heian period, in "},{"t":"大和物語","r":"やまとものがたり"},{"t":" among others.\n\nWhat is "},{"t":"まみれ"},{"t":" has had something spread over it, typically things that genuinely coat: "},{"t":"血","r":"ち"},{"t":"まみれ"},{"t":", "},{"t":"泥","r":"どろ"},{"t":"まみれ"},{"t":", "},{"t":"汗","r":"あせ"},{"t":"まみれ"},{"t":". The conventional extension is to clinging abstractions ("},{"t":"借金","r":"しゃっきん"},{"t":"まみれ"},{"t":"), where "},{"t":"だらけ"},{"t":", which can hold anything anywhere including mistakes, is the broader word."}],"changes":[{"word":"大和物語","from":[{"t":"大","r":"たい"},{"t":"和","r":"にこ"},{"t":"物語","r":"ものがたり"}],"to":[{"t":"大和物語","r":"やまとものがたり"}],"why":"Title is やまとものがたり."}]}'::jsonb, '{"furigana":[{"r":"ぬ","t":"塗"},{"t":" is a shared spelling, not shared ancestry: "},{"t":"まみれる"},{"t":" is not kin to "},{"r":"ぬ","t":"塗"},{"t":"る"},{"t":". It is attested from the Heian period, in "},{"r":"たい","t":"大"},{"r":"にこ","t":"和"},{"r":"ものがたり","t":"物語"},{"t":" among others.\n\nWhat is "},{"t":"まみれ"},{"t":" has had something spread over it, typically things that genuinely coat: "},{"r":"ち","t":"血"},{"t":"まみれ"},{"t":", "},{"r":"どろ","t":"泥"},{"t":"まみれ"},{"t":", "},{"r":"あせ","t":"汗"},{"t":"まみれ"},{"t":". The conventional extension is to clinging abstractions ("},{"r":"しゃっきん","t":"借金"},{"t":"まみれ"},{"t":"), where "},{"t":"だらけ"},{"t":", which can hold anything anywhere including mistakes, is the broader word."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '4d04bb0602df30af74bafbcbbaaf13008702fb32ea8b6ae1195e138a44f2ffc9' AND l.code = 'ja'
  AND g.segments = '[{"r":"ぬ","t":"塗"},{"t":" is a shared spelling, not shared ancestry: "},{"t":"まみれる"},{"t":" is not kin to "},{"r":"ぬ","t":"塗"},{"t":"る"},{"t":". It is attested from the Heian period, in "},{"r":"たい","t":"大"},{"r":"にこ","t":"和"},{"r":"ものがたり","t":"物語"},{"t":" among others.\n\nWhat is "},{"t":"まみれ"},{"t":" has had something spread over it, typically things that genuinely coat: "},{"r":"ち","t":"血"},{"t":"まみれ"},{"t":", "},{"r":"どろ","t":"泥"},{"t":"まみれ"},{"t":", "},{"r":"あせ","t":"汗"},{"t":"まみれ"},{"t":". The conventional extension is to clinging abstractions ("},{"r":"しゃっきん","t":"借金"},{"t":"まみれ"},{"t":"), where "},{"t":"だらけ"},{"t":", which can hold anything anywhere including mistakes, is the broader word."}]'::jsonb
