SELECT 'crq-grammar-1db6c72c6df8c710', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"大言海 takes it that way: a mimetic for liquid running everywhere, plus the suffix that gives 塩気 and 嫌気. It is not certain, but it is a real account rather than a blank, and the word is attested from the Muromachi period for blood, sweat and mud.\n\nWhat separates it from まみれ and ずくめ is reach. まみれ needs something that could coat a surface, ずくめ a single quality filling a thing completely, while だらけ takes anything in unwelcome quantity: mud, mistakes, holes.","point":"〜だらけ","before":[{"t":"大","r":"たい"},{"t":"言","r":"い"},{"t":"海","r":"うみ"},{"t":" takes it that way: a mimetic for liquid running everywhere, plus the suffix that gives "},{"t":"塩","r":"しお"},{"t":"気","r":"げ"},{"t":" and "},{"t":"嫌","r":"いや"},{"t":"気","r":"げ"},{"t":". It is not certain, but it is a real account rather than a blank, and the word is attested from the Muromachi period for blood, sweat and mud.\n\nWhat separates it from "},{"t":"まみれ"},{"t":" and "},{"t":"ずくめ"},{"t":" is reach. "},{"t":"まみれ"},{"t":" needs something that could coat a surface, "},{"t":"ずくめ"},{"t":" a single quality filling a thing completely, while "},{"t":"だらけ"},{"t":" takes anything in unwelcome quantity: mud, mistakes, holes."}],"after":[{"t":"大言海","r":"だいげんかい"},{"t":" takes it that way: a mimetic for liquid running everywhere, plus the suffix that gives "},{"t":"塩気","r":"しおけ"},{"t":" and "},{"t":"嫌気","r":"いやけ"},{"t":". It is not certain, but it is a real account rather than a blank, and the word is attested from the Muromachi period for blood, sweat and mud.\n\nWhat separates it from "},{"t":"まみれ"},{"t":" and "},{"t":"ずくめ"},{"t":" is reach. "},{"t":"まみれ"},{"t":" needs something that could coat a surface, "},{"t":"ずくめ"},{"t":" a single quality filling a thing completely, while "},{"t":"だらけ"},{"t":" takes anything in unwelcome quantity: mud, mistakes, holes."}],"changes":[{"word":"大言海","from":[{"t":"大","r":"たい"},{"t":"言","r":"い"},{"t":"海","r":"うみ"}],"to":[{"t":"大言海","r":"だいげんかい"}],"why":"Dictionary title is だいげんかい."},{"word":"嫌気","from":[{"t":"嫌","r":"いや"},{"t":"気","r":"げ"}],"to":[{"t":"嫌気","r":"いやけ"}],"why":"Compound is いやけ. / 嫌気 is いやけ."},{"word":"塩気","from":[{"t":"塩","r":"しお"},{"t":"気","r":"げ"}],"to":[{"t":"塩気","r":"しおけ"}],"why":"Compound is しおけ."}]}'::jsonb, '{"furigana":[{"r":"たい","t":"大"},{"r":"い","t":"言"},{"r":"うみ","t":"海"},{"t":" takes it that way: a mimetic for liquid running everywhere, plus the suffix that gives "},{"r":"しお","t":"塩"},{"r":"げ","t":"気"},{"t":" and "},{"r":"いや","t":"嫌"},{"r":"げ","t":"気"},{"t":". It is not certain, but it is a real account rather than a blank, and the word is attested from the Muromachi period for blood, sweat and mud.\n\nWhat separates it from "},{"t":"まみれ"},{"t":" and "},{"t":"ずくめ"},{"t":" is reach. "},{"t":"まみれ"},{"t":" needs something that could coat a surface, "},{"t":"ずくめ"},{"t":" a single quality filling a thing completely, while "},{"t":"だらけ"},{"t":" takes anything in unwelcome quantity: mud, mistakes, holes."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '1db6c72c6df8c710a297baf9c2ee3467d9bcf12d42c938efd11b18e4d84a6ac7' AND l.code = 'ja'
  AND g.segments = '[{"r":"たい","t":"大"},{"r":"い","t":"言"},{"r":"うみ","t":"海"},{"t":" takes it that way: a mimetic for liquid running everywhere, plus the suffix that gives "},{"r":"しお","t":"塩"},{"r":"げ","t":"気"},{"t":" and "},{"r":"いや","t":"嫌"},{"r":"げ","t":"気"},{"t":". It is not certain, but it is a real account rather than a blank, and the word is attested from the Muromachi period for blood, sweat and mud.\n\nWhat separates it from "},{"t":"まみれ"},{"t":" and "},{"t":"ずくめ"},{"t":" is reach. "},{"t":"まみれ"},{"t":" needs something that could coat a surface, "},{"t":"ずくめ"},{"t":" a single quality filling a thing completely, while "},{"t":"だらけ"},{"t":" takes anything in unwelcome quantity: mud, mistakes, holes."}]'::jsonb
