-- 〜始める / 〜終わる / 〜続ける: 降り始, 降り始
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-a984f018721b3524', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"始める, 終わる and 続ける are full verbs. Attached to a stem they say when the action starts, stops or carries on, and nothing is idiomatic about the join.\n\n始める is the transitive member and 始まる never compounds this way, so it is 降り始める and never 降り始まる. 終わる does not follow that rule; it compounds as it stands, 読み終わる, with 読み終える alongside it. The pairing has to be learned verb by verb.","point":"〜始める / 〜終わる / 〜続ける","before":[{"t":"始","r":"はじ"},{"t":"める"},{"t":", "},{"t":"終","r":"お"},{"t":"わる"},{"t":" and "},{"t":"続","r":"つづ"},{"t":"ける"},{"t":" are full verbs. Attached to a stem they say when the action starts, stops or carries on, and nothing is idiomatic about the join.\n\n"},{"t":"始","r":"はじ"},{"t":"める"},{"t":" is the transitive member and "},{"t":"始","r":"はじ"},{"t":"まる"},{"t":" never compounds this way, so it is "},{"t":"降","r":"お"},{"t":"り"},{"t":"始","r":"はじ"},{"t":"める"},{"t":" and never "},{"t":"降","r":"お"},{"t":"り"},{"t":"始","r":"はじ"},{"t":"まる"},{"t":". "},{"t":"終","r":"お"},{"t":"わる"},{"t":" does not follow that rule; it compounds as it stands, "},{"t":"読","r":"よ"},{"t":"み"},{"t":"終","r":"お"},{"t":"わる"},{"t":", with "},{"t":"読","r":"よ"},{"t":"み"},{"t":"終","r":"お"},{"t":"える"},{"t":" alongside it. The pairing has to be learned verb by verb."}],"after":[{"t":"始","r":"はじ"},{"t":"める"},{"t":", "},{"t":"終","r":"お"},{"t":"わる"},{"t":" and "},{"t":"続","r":"つづ"},{"t":"ける"},{"t":" are full verbs. Attached to a stem they say when the action starts, stops or carries on, and nothing is idiomatic about the join.\n\n"},{"t":"始","r":"はじ"},{"t":"める"},{"t":" is the transitive member and "},{"t":"始","r":"はじ"},{"t":"まる"},{"t":" never compounds this way, so it is "},{"t":"降","r":"ふ"},{"t":"り"},{"t":"始","r":"はじ"},{"t":"める"},{"t":" and never "},{"t":"降","r":"ふ"},{"t":"り"},{"t":"始","r":"はじ"},{"t":"まる"},{"t":". "},{"t":"終","r":"お"},{"t":"わる"},{"t":" does not follow that rule; it compounds as it stands, "},{"t":"読","r":"よ"},{"t":"み"},{"t":"終","r":"お"},{"t":"わる"},{"t":", with "},{"t":"読","r":"よ"},{"t":"み"},{"t":"終","r":"お"},{"t":"える"},{"t":" alongside it. The pairing has to be learned verb by verb."}],"changes":[{"word":"降り始","from":[{"t":"降","r":"お"},{"t":"り"},{"t":"始","r":"はじ"}],"to":[{"t":"降","r":"ふ"},{"t":"り"},{"t":"始","r":"はじ"}],"why":"Rain falls is ふる."},{"word":"降り始","from":[{"t":"降","r":"お"},{"t":"り"},{"t":"始","r":"はじ"}],"to":[{"t":"降","r":"ふ"},{"t":"り"},{"t":"始","r":"はじ"}],"why":"Rain falls is ふる."}]}'::jsonb, '{"furigana":[{"r":"はじ","t":"始"},{"t":"める"},{"t":", "},{"r":"お","t":"終"},{"t":"わる"},{"t":" and "},{"r":"つづ","t":"続"},{"t":"ける"},{"t":" are full verbs. Attached to a stem they say when the action starts, stops or carries on, and nothing is idiomatic about the join.\n\n"},{"r":"はじ","t":"始"},{"t":"める"},{"t":" is the transitive member and "},{"r":"はじ","t":"始"},{"t":"まる"},{"t":" never compounds this way, so it is "},{"r":"お","t":"降"},{"t":"り"},{"r":"はじ","t":"始"},{"t":"める"},{"t":" and never "},{"r":"お","t":"降"},{"t":"り"},{"r":"はじ","t":"始"},{"t":"まる"},{"t":". "},{"r":"お","t":"終"},{"t":"わる"},{"t":" does not follow that rule; it compounds as it stands, "},{"r":"よ","t":"読"},{"t":"み"},{"r":"お","t":"終"},{"t":"わる"},{"t":", with "},{"r":"よ","t":"読"},{"t":"み"},{"r":"お","t":"終"},{"t":"える"},{"t":" alongside it. The pairing has to be learned verb by verb."}]}'::jsonb, 'ai', 900, 'pending'
