-- 〜につれて: 連れて
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b992ecb987f534f6', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"子供を連れて行く is taking a child along. につれて keeps that image exactly: one thing moves and drags the other after it.\n\nHence the constraint that catches people out: につれて needs gradual, continuous change on both sides. A single step cannot lead anything along, so 春になるにつれて works and 駅に着くにつれて does not.","point":"〜につれて","before":[{"t":"子供","r":"こども"},{"t":"を"},{"t":"連","r":"づ"},{"t":"れて"},{"t":"行","r":"い"},{"t":"く"},{"t":" is taking a child along. "},{"t":"につれて"},{"t":" keeps that image exactly: one thing moves and drags the other after it.\n\nHence the constraint that catches people out: "},{"t":"につれて"},{"t":" needs gradual, continuous change on both sides. A single step cannot lead anything along, so "},{"t":"春","r":"はる"},{"t":"になるにつれて"},{"t":" works and "},{"t":"駅","r":"えき"},{"t":"に"},{"t":"着","r":"つ"},{"t":"くにつれて"},{"t":" does not."}],"after":[{"t":"子供","r":"こども"},{"t":"を"},{"t":"連","r":"つ"},{"t":"れて"},{"t":"行","r":"い"},{"t":"く"},{"t":" is taking a child along. "},{"t":"につれて"},{"t":" keeps that image exactly: one thing moves and drags the other after it.\n\nHence the constraint that catches people out: "},{"t":"につれて"},{"t":" needs gradual, continuous change on both sides. A single step cannot lead anything along, so "},{"t":"春","r":"はる"},{"t":"になるにつれて"},{"t":" works and "},{"t":"駅","r":"えき"},{"t":"に"},{"t":"着","r":"つ"},{"t":"くにつれて"},{"t":" does not."}],"changes":[{"word":"連れて","from":[{"t":"連","r":"づ"},{"t":"れて"}],"to":[{"t":"連","r":"つ"},{"t":"れて"}],"why":"連れる is つれる."}]}'::jsonb, '{"furigana":[{"r":"こども","t":"子供"},{"t":"を"},{"r":"づ","t":"連"},{"t":"れて"},{"r":"い","t":"行"},{"t":"く"},{"t":" is taking a child along. "},{"t":"につれて"},{"t":" keeps that image exactly: one thing moves and drags the other after it.\n\nHence the constraint that catches people out: "},{"t":"につれて"},{"t":" needs gradual, continuous change on both sides. A single step cannot lead anything along, so "},{"r":"はる","t":"春"},{"t":"になるにつれて"},{"t":" works and "},{"r":"えき","t":"駅"},{"t":"に"},{"r":"つ","t":"着"},{"t":"くにつれて"},{"t":" does not."}]}'::jsonb, 'ai', 900, 'pending'
