SELECT 'crq-grammar-6f42e9d4b5da8343', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"寝る前に uses the dictionary form because the sleeping has not happened yet at the point being named. 寝た後で uses the past because it has.\n\nThe tense is not agreeing with the main clause; it is describing the state of affairs at the moment 前 or 後 picks out. Both are ordinary nouns of position (the same 前 as 駅の前), and they behave as position nouns should.","point":"〜前に","before":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" uses the dictionary form because the sleeping has not happened yet at the point being named. "},{"t":"寝","r":"ね"},{"t":"た"},{"t":"後","r":"あと"},{"t":"で"},{"t":" uses the past because it has.\n\nThe tense is not agreeing with the main clause; it is describing the state of affairs at the moment "},{"t":"前","r":"ぜん"},{"t":" or "},{"t":"後","r":"あと"},{"t":" picks out. Both are ordinary nouns of position (the same "},{"t":"前","r":"ぜん"},{"t":" as "},{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"ぜん"},{"t":"), and they behave as position nouns should."}],"after":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"まえ"},{"t":"に"},{"t":" uses the dictionary form because the sleeping has not happened yet at the point being named. "},{"t":"寝","r":"ね"},{"t":"た"},{"t":"後","r":"あと"},{"t":"で"},{"t":" uses the past because it has.\n\nThe tense is not agreeing with the main clause; it is describing the state of affairs at the moment "},{"t":"前","r":"まえ"},{"t":" or"},{"t":" "},{"t":"後","r":"あと"},{"t":" picks out. Both are ordinary nouns of position (the "},{"t":"same 前","r":"まえ"},{"t":" as"},{"t":" "},{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"まえ"},{"t":"), and they behave as position nouns should."}],"changes":[{"word":"same 前 as","from":[{"t":"same "},{"t":"前","r":"ぜん"},{"t":" as"}],"to":[{"t":"same 前","r":"まえ"},{"t":" as"}],"why":"The position noun 前 is まえ."},{"word":"前 or","from":[{"t":"前","r":"ぜん"},{"t":" or"}],"to":[{"t":"前","r":"まえ"},{"t":" or"}],"why":"The position noun 前 is まえ."},{"word":"寝る前","from":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"ぜん"}],"to":[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"まえ"}],"why":"前 here is まえ."},{"word":"駅の前","from":[{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"ぜん"}],"to":[{"t":"駅","r":"えき"},{"t":"の"},{"t":"前","r":"まえ"}],"why":"In front of the station is えきのまえ."}]}'::jsonb, '{"furigana":[{"r":"ね","t":"寝"},{"t":"る"},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" uses the dictionary form because the sleeping has not happened yet at the point being named. "},{"r":"ね","t":"寝"},{"t":"た"},{"r":"あと","t":"後"},{"t":"で"},{"t":" uses the past because it has.\n\nThe tense is not agreeing with the main clause; it is describing the state of affairs at the moment "},{"r":"ぜん","t":"前"},{"t":" or "},{"r":"あと","t":"後"},{"t":" picks out. Both are ordinary nouns of position (the same "},{"r":"ぜん","t":"前"},{"t":" as "},{"r":"えき","t":"駅"},{"t":"の"},{"r":"ぜん","t":"前"},{"t":"), and they behave as position nouns should."}]}'::jsonb, 'ai', 900, 'pending'
