-- 〜に対して: 私に対して, 兄に対, 弟は
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-bc3656be10381b3d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"対 is the 対 of 反対 and 対立: one thing set facing another. に対して puts the sentence in that posture.\n\nBoth senses follow from the picture. Facing someone is directing something at them (私に対して失礼だ); facing something is being set against it, which gives the contrastive reading (兄に対して弟は静かだ). Same stance, read forwards or sideways.","point":"〜に対して","before":[{"t":"対","r":"たい"},{"t":" is the "},{"t":"対","r":"たい"},{"t":" of "},{"t":"反対","r":"はんたい"},{"t":" and "},{"t":"対立","r":"たいりつ"},{"t":": one thing set facing another. "},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":" puts the sentence in that posture.\n\nBoth senses follow from the picture. Facing someone is directing something at them ("},{"t":"私","r":"わちき"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":"失礼","r":"しつれい"},{"t":"だ"},{"t":"); facing something is being set against it, which gives the contrastive reading ("},{"t":"兄","r":"にい"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":"弟","r":"おとと"},{"t":"は"},{"t":"静","r":"しず"},{"t":"かだ"},{"t":"). Same stance, read forwards or sideways."}],"after":[{"t":"対","r":"たい"},{"t":" is the "},{"t":"対","r":"たい"},{"t":" of "},{"t":"反対","r":"はんたい"},{"t":" and "},{"t":"対立","r":"たいりつ"},{"t":": one thing set facing another. "},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":" puts the sentence in that posture.\n\nBoth senses follow from the picture. Facing someone is directing something at them ("},{"t":"私","r":"わたし"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":"失礼","r":"しつれい"},{"t":"だ"},{"t":"); facing something is being set against it, which gives the contrastive reading ("},{"t":"兄","r":"あに"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"},{"t":"弟","r":"おとうと"},{"t":"は"},{"t":"静","r":"しず"},{"t":"かだ"},{"t":"). Same stance, read forwards or sideways."}],"changes":[{"word":"私に対して","from":[{"t":"私","r":"わちき"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"}],"to":[{"t":"私","r":"わたし"},{"t":"に"},{"t":"対","r":"たい"},{"t":"して"}],"why":"私 is わたし."},{"word":"兄に対","from":[{"t":"兄","r":"にい"},{"t":"に"},{"t":"対","r":"たい"}],"to":[{"t":"兄","r":"あに"},{"t":"に"},{"t":"対","r":"たい"}],"why":"Own elder brother is あに."},{"word":"弟は","from":[{"t":"弟","r":"おとと"},{"t":"は"}],"to":[{"t":"弟","r":"おとうと"},{"t":"は"}],"why":"弟 is おとうと."}]}'::jsonb, '{"furigana":[{"r":"たい","t":"対"},{"t":" is the "},{"r":"たい","t":"対"},{"t":" of "},{"r":"はんたい","t":"反対"},{"t":" and "},{"r":"たいりつ","t":"対立"},{"t":": one thing set facing another. "},{"t":"に"},{"r":"たい","t":"対"},{"t":"して"},{"t":" puts the sentence in that posture.\n\nBoth senses follow from the picture. Facing someone is directing something at them ("},{"r":"わちき","t":"私"},{"t":"に"},{"r":"たい","t":"対"},{"t":"して"},{"r":"しつれい","t":"失礼"},{"t":"だ"},{"t":"); facing something is being set against it, which gives the contrastive reading ("},{"r":"にい","t":"兄"},{"t":"に"},{"r":"たい","t":"対"},{"t":"して"},{"r":"おとと","t":"弟"},{"t":"は"},{"r":"しず","t":"静"},{"t":"かだ"},{"t":"). Same stance, read forwards or sideways."}]}'::jsonb, 'ai', 900, 'pending'
