-- 〜たところだ: 所
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-f9f522ec15aff7db', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"所 is an ordinary noun. 出かけるところ is the spot just before leaving, 出かけているところ the spot during, 出かけたところ the spot immediately after.\n\nWorth holding apart from たところで at N1, which looks almost identical and is not: たところで is hypothetical (even supposing you had), while たところだ reports something that genuinely just happened. The で and the だ carry the whole difference.","point":"〜たところだ","before":[{"t":"所","r":"しょ"},{"t":" is an ordinary noun. "},{"t":"出","r":"で"},{"t":"かけるところ"},{"t":" is the spot just before leaving, "},{"t":"出","r":"で"},{"t":"かけているところ"},{"t":" the spot during, "},{"t":"出","r":"で"},{"t":"かけたところ"},{"t":" the spot immediately after.\n\nWorth holding apart from "},{"t":"たところで"},{"t":" at N1, which looks almost identical and is not: "},{"t":"たところで"},{"t":" is hypothetical (even supposing you had), while "},{"t":"たところだ"},{"t":" reports something that genuinely just happened. The "},{"t":"で"},{"t":" and the "},{"t":"だ"},{"t":" carry the whole difference."}],"after":[{"t":"所","r":"ところ"},{"t":" is an ordinary noun. "},{"t":"出","r":"で"},{"t":"かけるところ"},{"t":" is the spot just before leaving, "},{"t":"出","r":"で"},{"t":"かけているところ"},{"t":" the spot during, "},{"t":"出","r":"で"},{"t":"かけたところ"},{"t":" the spot immediately after.\n\nWorth holding apart from "},{"t":"たところで"},{"t":" at N1, which looks almost identical and is not: "},{"t":"たところで"},{"t":" is hypothetical (even supposing you had), while "},{"t":"たところだ"},{"t":" reports something that genuinely just happened. The "},{"t":"で"},{"t":" and the "},{"t":"だ"},{"t":" carry the whole difference."}],"changes":[{"word":"所","from":[{"t":"所","r":"しょ"}],"to":[{"t":"所","r":"ところ"}],"why":"The noun meaning place is ところ here."}]}'::jsonb, '{"furigana":[{"r":"しょ","t":"所"},{"t":" is an ordinary noun. "},{"r":"で","t":"出"},{"t":"かけるところ"},{"t":" is the spot just before leaving, "},{"r":"で","t":"出"},{"t":"かけているところ"},{"t":" the spot during, "},{"r":"で","t":"出"},{"t":"かけたところ"},{"t":" the spot immediately after.\n\nWorth holding apart from "},{"t":"たところで"},{"t":" at N1, which looks almost identical and is not: "},{"t":"たところで"},{"t":" is hypothetical (even supposing you had), while "},{"t":"たところだ"},{"t":" reports something that genuinely just happened. The "},{"t":"で"},{"t":" and the "},{"t":"だ"},{"t":" carry the whole difference."}]}'::jsonb, 'ai', 900, 'pending'
