-- 〜ながらも: 敵ながら
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-68d712632a7f2302', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"敵ながらあっぱれ, 残念ながら, 知りながら黙っていた: none of these needs a も, and all of them concede. The concession is ながら''s own, inherited from its older sense of a state persisting unchanged, the one preserved in 昔ながら and 生まれながらに.\n\nSo も is not supplying the concession but sharpening it. 知っていながらも simply presses harder on a contrast ながら was already making.","point":"〜ながらも","before":[{"t":"敵","r":"かたき"},{"t":"ながらあっぱれ"},{"t":", "},{"t":"残念","r":"ざんねん"},{"t":"ながら"},{"t":", "},{"t":"知","r":"し"},{"t":"りながら"},{"t":"黙","r":"だま"},{"t":"っていた"},{"t":": none of these needs a "},{"t":"も"},{"t":", and all of them concede. The concession is "},{"t":"ながら"},{"t":"''s own, inherited from its older sense of a state persisting unchanged, the one preserved in "},{"t":"昔","r":"むかし"},{"t":"ながら"},{"t":" and "},{"t":"生","r":"う"},{"t":"まれながらに"},{"t":".\n\nSo "},{"t":"も"},{"t":" is not supplying the concession but sharpening it. "},{"t":"知","r":"し"},{"t":"っていながらも"},{"t":" simply presses harder on a contrast "},{"t":"ながら"},{"t":" was already making."}],"after":[{"t":"敵","r":"てき"},{"t":"ながら"},{"t":"あっぱれ"},{"t":", "},{"t":"残念","r":"ざんねん"},{"t":"ながら"},{"t":", "},{"t":"知","r":"し"},{"t":"りながら"},{"t":"黙","r":"だま"},{"t":"っていた"},{"t":": none of these needs a "},{"t":"も"},{"t":", and all of them concede. The concession is "},{"t":"ながら"},{"t":"''s own, inherited from its older sense of a state persisting unchanged, the one preserved in "},{"t":"昔","r":"むかし"},{"t":"ながら"},{"t":" and "},{"t":"生","r":"う"},{"t":"まれながらに"},{"t":".\n\nSo "},{"t":"も"},{"t":" is not supplying the concession but sharpening it. "},{"t":"知","r":"し"},{"t":"っていながらも"},{"t":" simply presses harder on a contrast "},{"t":"ながら"},{"t":" was already making."}],"changes":[{"word":"敵ながら","from":[{"t":"敵","r":"かたき"},{"t":"ながら"}],"to":[{"t":"敵","r":"てき"},{"t":"ながら"}],"why":"敵 here is てき."}]}'::jsonb, '{"furigana":[{"r":"かたき","t":"敵"},{"t":"ながらあっぱれ"},{"t":", "},{"r":"ざんねん","t":"残念"},{"t":"ながら"},{"t":", "},{"r":"し","t":"知"},{"t":"りながら"},{"r":"だま","t":"黙"},{"t":"っていた"},{"t":": none of these needs a "},{"t":"も"},{"t":", and all of them concede. The concession is "},{"t":"ながら"},{"t":"''s own, inherited from its older sense of a state persisting unchanged, the one preserved in "},{"r":"むかし","t":"昔"},{"t":"ながら"},{"t":" and "},{"r":"う","t":"生"},{"t":"まれながらに"},{"t":".\n\nSo "},{"t":"も"},{"t":" is not supplying the concession but sharpening it. "},{"r":"し","t":"知"},{"t":"っていながらも"},{"t":" simply presses harder on a contrast "},{"t":"ながら"},{"t":" was already making."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '68d712632a7f2302fec7ba457f948887bf36b494031cd6d8efc62d97cacfdf91' AND l.code = 'ja'
  AND g.segments = '[{"r":"かたき","t":"敵"},{"t":"ながらあっぱれ"},{"t":", "},{"r":"ざんねん","t":"残念"},{"t":"ながら"},{"t":", "},{"r":"し","t":"知"},{"t":"りながら"},{"r":"だま","t":"黙"},{"t":"っていた"},{"t":": none of these needs a "},{"t":"も"},{"t":", and all of them concede. The concession is "},{"t":"ながら"},{"t":"''s own, inherited from its older sense of a state persisting unchanged, the one preserved in "},{"r":"むかし","t":"昔"},{"t":"ながら"},{"t":" and "},{"r":"う","t":"生"},{"t":"まれながらに"},{"t":".\n\nSo "},{"t":"も"},{"t":" is not supplying the concession but sharpening it. "},{"r":"し","t":"知"},{"t":"っていながらも"},{"t":" simply presses harder on a contrast "},{"t":"ながら"},{"t":" was already making."}]'::jsonb
