SELECT 'crq-grammar-5c5ac7f3c64e9eb8', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The names 五段 and 一段 say exactly what the verbs do: move through five vowel rows, or stay on one.","point":"Verb classes","before":[{"t":"The names "},{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":" and "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":" say exactly what the verbs do: move through five vowel rows, or stay on one."}],"after":[{"t":"The names "},{"t":"五","r":"ご"},{"t":"段","r":"だん"},{"t":" and "},{"t":"一","r":"いち"},{"t":"段","r":"だん"},{"t":" say exactly what the verbs do: move through five vowel rows, or stay on one."}],"changes":[{"word":"五段","from":[{"t":"五","r":"うー"},{"t":"段","r":"だん"}],"to":[{"t":"五","r":"ご"},{"t":"段","r":"だん"}],"why":"五段 is ごだん."},{"word":"一段","from":[{"t":"一","r":"いっち"},{"t":"段","r":"だん"}],"to":[{"t":"一","r":"いち"},{"t":"段","r":"だん"}],"why":"一段 is いちだん."}]}'::jsonb, '{"furigana":[{"t":"The names "},{"r":"うー","t":"五"},{"r":"だん","t":"段"},{"t":" and "},{"r":"いっち","t":"一"},{"r":"だん","t":"段"},{"t":" say exactly what the verbs do: move through five vowel rows, or stay on one."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
