  AND g.segments = '[{"t":"The names "},{"r":"うー","t":"五"},{"r":"だん","t":"段"},{"t":" and "},{"r":"いっち","t":"一"},{"r":"だん","t":"段"},{"t":" say exactly what the verbs do: move through five vowel rows, or stay on one."}]'::jsonb
