-- Verb classes: 五段, 五段, 一段, 四段
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-7d9cd96f7f2f36e4', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"書く runs across か・き・く・け・こ: five steps, 五段. 食べる never leaves the え row: 食べない, 食べます, 食べる, 食べれば. One step, 一段. The fifth step is newer than it looks: the class was called 四段 until the 1946 kana reform respelled 書かう as 書こう and added the お row.\n\nSo the classification is not a list to memorise but a description of the stem you can watch happening. It also explains why only 五段 verbs have a て-form worth learning rules for: a stem that moves has consonants colliding with the ending, and a stem that stays put does not.","point":"Verb classes","before":[{"t":"書","r":"か"},{"t":"く"},{"t":" runs across "},{"t":"か・き・く・け・こ"},{"t":": five steps, "},{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":". "},{"t":"食","r":"た"},{"t":"べる"},{"t":" never leaves the "},{"t":"え"},{"t":" row: "},{"t":"食","r":"た"},{"t":"べない"},{"t":", "},{"t":"食","r":"た"},{"t":"べます"},{"t":", "},{"t":"食","r":"た"},{"t":"べる"},{"t":", "},{"t":"食","r":"た"},{"t":"べれば"},{"t":". One step, "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":". The fifth step is newer than it looks: the class was called "},{"t":"四","r":"し"},{"t":"段","r":"だん"},{"t":" until the 1946 kana reform respelled "},{"t":"書","r":"か"},{"t":"かう"},{"t":" as "},{"t":"書","r":"か"},{"t":"こう"},{"t":" and added the "},{"t":"お"},{"t":" row.\n\nSo the classification is not a list to memorise but a description of the stem you can watch happening. It also explains why only "},{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":" verbs have a "},{"t":"て"},{"t":"-form worth learning rules for: a stem that moves has consonants colliding with the ending, and a stem that stays put does not."}],"after":[{"t":"書","r":"か"},{"t":"く"},{"t":" runs across "},{"t":"か・き・く・け・こ"},{"t":": five steps, "},{"t":"五","r":"ご"},{"t":"段","r":"だん"},{"t":". "},{"t":"食","r":"た"},{"t":"べる"},{"t":" never leaves the "},{"t":"え"},{"t":" row: "},{"t":"食","r":"た"},{"t":"べない"},{"t":", "},{"t":"食","r":"た"},{"t":"べます"},{"t":", "},{"t":"食","r":"た"},{"t":"べる"},{"t":", "},{"t":"食","r":"た"},{"t":"べれば"},{"t":". One step, "},{"t":"一","r":"いち"},{"t":"段","r":"だん"},{"t":". The fifth step is newer than it looks: the class was called "},{"t":"四段","r":"よだん"},{"t":" until the 1946 kana reform respelled "},{"t":"書","r":"か"},{"t":"かう"},{"t":" as "},{"t":"書","r":"か"},{"t":"こう"},{"t":" and added the "},{"t":"お"},{"t":" row.\n\nSo the classification is not a list to memorise but a description of the stem you can watch happening. It also explains why only "},{"t":"五","r":"ご"},{"t":"段","r":"だん"},{"t":" verbs have a "},{"t":"て"},{"t":"-form worth learning rules for: a stem that moves has consonants colliding with the ending, and a stem that stays put does not."}],"changes":[{"word":"五段","from":[{"t":"五","r":"うー"},{"t":"段","r":"だん"}],"to":[{"t":"五","r":"ご"},{"t":"段","r":"だん"}],"why":"五段 is ごだん."},{"word":"五段","from":[{"t":"五","r":"うー"},{"t":"段","r":"だん"}],"to":[{"t":"五","r":"ご"},{"t":"段","r":"だん"}],"why":"五段 is ごだん."},{"word":"一段","from":[{"t":"一","r":"いっち"},{"t":"段","r":"だん"}],"to":[{"t":"一","r":"いち"},{"t":"段","r":"だん"}],"why":"一段 is いちだん."},{"word":"四段","from":[{"t":"四","r":"し"},{"t":"段","r":"だん"}],"to":[{"t":"四段","r":"よだん"}],"why":"Fourth grade is よだん."}]}'::jsonb, '{"furigana":[{"r":"か","t":"書"},{"t":"く"},{"t":" runs across "},{"t":"か・き・く・け・こ"},{"t":": five steps, "},{"r":"うー","t":"五"},{"r":"だん","t":"段"},{"t":". "},{"r":"た","t":"食"},{"t":"べる"},{"t":" never leaves the "},{"t":"え"},{"t":" row: "},{"r":"た","t":"食"},{"t":"べない"},{"t":", "},{"r":"た","t":"食"},{"t":"べます"},{"t":", "},{"r":"た","t":"食"},{"t":"べる"},{"t":", "},{"r":"た","t":"食"},{"t":"べれば"},{"t":". One step, "},{"r":"いっち","t":"一"},{"r":"だん","t":"段"},{"t":". The fifth step is newer than it looks: the class was called "},{"r":"し","t":"四"},{"r":"だん","t":"段"},{"t":" until the 1946 kana reform respelled "},{"r":"か","t":"書"},{"t":"かう"},{"t":" as "},{"r":"か","t":"書"},{"t":"こう"},{"t":" and added the "},{"t":"お"},{"t":" row.\n\nSo the classification is not a list to memorise but a description of the stem you can watch happening. It also explains why only "},{"r":"うー","t":"五"},{"r":"だん","t":"段"},{"t":" verbs have a "},{"t":"て"},{"t":"-form worth learning rules for: a stem that moves has consonants colliding with the ending, and a stem that stays put does not."}]}'::jsonb, 'ai', 900, 'pending'
