-- 〜ように見える: The 様 supplies, 見える, 見える
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-c71b017b6cacc8ce', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"見える is \"to be visible, to appear\": intransitive, so what appears takes が. The 様 supplies the manner, and the whole says something presents the appearance of being so.\n\nIt is more cautious than ようだ alone. ようだ is the speaker''s conclusion; ように見える reports only what is visible and leaves the conclusion unmade.","point":"〜ように見える","before":[{"t":"見","r":"まみ"},{"t":"える"},{"t":" is \"to be visible, to appear\": intransitive, so what appears takes "},{"t":"が"},{"t":". The "},{"t":"様","r":"さま"},{"t":" supplies the manner, and the whole says something presents the appearance of being so.\n\nIt is more cautious than "},{"t":"ようだ"},{"t":" alone. "},{"t":"ようだ"},{"t":" is the speaker''s conclusion; "},{"t":"ように"},{"t":"見","r":"まみ"},{"t":"える"},{"t":" reports only what is visible and leaves the conclusion unmade."}],"after":[{"t":"見","r":"み"},{"t":"える"},{"t":" is \"to be visible, to appear\": intransitive, so what appears takes "},{"t":"が"},{"t":". "},{"t":"The 様","r":"よう"},{"t":" supplies"},{"t":" the manner, and the whole says something presents the appearance of being so.\n\nIt is more cautious than "},{"t":"ようだ"},{"t":" alone. "},{"t":"ようだ"},{"t":" is the speaker''s conclusion; "},{"t":"ように"},{"t":"見","r":"み"},{"t":"える"},{"t":" reports only what is visible and leaves the conclusion unmade."}],"changes":[{"word":"The 様 supplies","from":[{"t":"The "},{"t":"様","r":"さま"},{"t":" supplies"}],"to":[{"t":"The 様","r":"よう"},{"t":" supplies"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"},{"word":"見える","from":[{"t":"見","r":"まみ"},{"t":"える"}],"to":[{"t":"見","r":"み"},{"t":"える"}],"why":"見える is みえる."},{"word":"見える","from":[{"t":"見","r":"まみ"},{"t":"える"}],"to":[{"t":"見","r":"み"},{"t":"える"}],"why":"見える is みえる."}]}'::jsonb, '{"furigana":[{"r":"まみ","t":"見"},{"t":"える"},{"t":" is \"to be visible, to appear\": intransitive, so what appears takes "},{"t":"が"},{"t":". The "},{"r":"さま","t":"様"},{"t":" supplies the manner, and the whole says something presents the appearance of being so.\n\nIt is more cautious than "},{"t":"ようだ"},{"t":" alone. "},{"t":"ようだ"},{"t":" is the speaker''s conclusion; "},{"t":"ように"},{"r":"まみ","t":"見"},{"t":"える"},{"t":" reports only what is visible and leaves the conclusion unmade."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'c71b017b6cacc8cecf328ff4302fc1be6c52ba0757a652bc91e9a703d655d4e2' AND l.code = 'ja'
  AND g.segments = '[{"r":"まみ","t":"見"},{"t":"える"},{"t":" is \"to be visible, to appear\": intransitive, so what appears takes "},{"t":"が"},{"t":". The "},{"r":"さま","t":"様"},{"t":" supplies the manner, and the whole says something presents the appearance of being so.\n\nIt is more cautious than "},{"t":"ようだ"},{"t":" alone. "},{"t":"ようだ"},{"t":" is the speaker''s conclusion; "},{"t":"ように"},{"r":"まみ","t":"見"},{"t":"える"},{"t":" reports only what is visible and leaves the conclusion unmade."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

