-- 〜ようだ: 様 is an ordinary, noun, the 様
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-5d76e16ce1b9c385', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"様 is an ordinary noun, the 様 of 様子 and of 皆様. 雨のようだ is literally \"it has the appearance of rain\".\n\nRecognising it as a noun explains an entire family at once. ように is that noun with に, \"in the manner that\"; ようになる is coming to be that way; ようにする is making it that way; みたい is the casual stand-in for the same thing. Five patterns, one word, and it is why よう takes の after a noun: 学生のよう, exactly as any other noun would. みたい, worn down further, attaches directly instead: 学生みたい.","point":"〜ようだ","before":[{"t":"様","r":"さま"},{"t":" is an ordinary noun, the "},{"t":"様","r":"さま"},{"t":" of "},{"t":"様子","r":"ようす"},{"t":" and of "},{"t":"皆様","r":"みなさま"},{"t":". "},{"t":"雨","r":"あめ"},{"t":"のようだ"},{"t":" is literally \"it has the appearance of rain\".\n\nRecognising it as a noun explains an entire family at once. "},{"t":"ように"},{"t":" is that noun with "},{"t":"に"},{"t":", \"in the manner that\"; "},{"t":"ようになる"},{"t":" is coming to be that way; "},{"t":"ようにする"},{"t":" is making it that way; "},{"t":"みたい"},{"t":" is the casual stand-in for the same thing. Five patterns, one word, and it is why "},{"t":"よう"},{"t":" takes "},{"t":"の"},{"t":" after a noun: "},{"t":"学生","r":"がくせい"},{"t":"のよう"},{"t":", exactly as any other noun would. "},{"t":"みたい"},{"t":", worn down further, attaches directly instead: "},{"t":"学生","r":"がくせい"},{"t":"みたい"},{"t":"."}],"after":[{"t":"様","r":"よう"},{"t":" is an ordinary"},{"t":" "},{"t":"noun, the 様","r":"よう"},{"t":" of "},{"t":"様子","r":"ようす"},{"t":" and of "},{"t":"皆様","r":"みなさま"},{"t":". "},{"t":"雨","r":"あめ"},{"t":"のようだ"},{"t":" is literally \"it has the appearance of rain\".\n\nRecognising it as a noun explains an entire family at once. "},{"t":"ように"},{"t":" is that noun with "},{"t":"に"},{"t":", \"in the manner that\"; "},{"t":"ようになる"},{"t":" is coming to be that way; "},{"t":"ようにする"},{"t":" is making it that way; "},{"t":"みたい"},{"t":" is the casual stand-in for the same thing. Five patterns, one word, and it is why "},{"t":"よう"},{"t":" takes "},{"t":"の"},{"t":" after a noun: "},{"t":"学生","r":"がくせい"},{"t":"のよう"},{"t":", exactly as any other noun would. "},{"t":"みたい"},{"t":", worn down further, attaches directly instead: "},{"t":"学生","r":"がくせい"},{"t":"みたい"},{"t":"."}],"changes":[{"word":"様 is an ordinary","from":[{"t":"様","r":"さま"},{"t":" is an ordinary"}],"to":[{"t":"様","r":"よう"},{"t":" is an ordinary"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"},{"word":"noun, the 様","from":[{"t":"noun, the "},{"t":"様","r":"さま"}],"to":[{"t":"noun, the 様","r":"よう"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"}]}'::jsonb, '{"furigana":[{"r":"さま","t":"様"},{"t":" is an ordinary noun, the "},{"r":"さま","t":"様"},{"t":" of "},{"r":"ようす","t":"様子"},{"t":" and of "},{"r":"みなさま","t":"皆様"},{"t":". "},{"r":"あめ","t":"雨"},{"t":"のようだ"},{"t":" is literally \"it has the appearance of rain\".\n\nRecognising it as a noun explains an entire family at once. "},{"t":"ように"},{"t":" is that noun with "},{"t":"に"},{"t":", \"in the manner that\"; "},{"t":"ようになる"},{"t":" is coming to be that way; "},{"t":"ようにする"},{"t":" is making it that way; "},{"t":"みたい"},{"t":" is the casual stand-in for the same thing. Five patterns, one word, and it is why "},{"t":"よう"},{"t":" takes "},{"t":"の"},{"t":" after a noun: "},{"r":"がくせい","t":"学生"},{"t":"のよう"},{"t":", exactly as any other noun would. "},{"t":"みたい"},{"t":", worn down further, attaches directly instead: "},{"r":"がくせい","t":"学生"},{"t":"みたい"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
