WHERE g.text_hash = '5d76e16ce1b9c385e7d1aa5d4c52a780dbd2175b86aa82ddbd6f766dd08df312' AND l.code = 'ja'
  AND g.segments = '[{"r":"さま","t":"様"},{"t":" is an ordinary noun, the "},{"r":"さま","t":"様"},{"t":" of "},{"r":"ようす","t":"様子"},{"t":" and of "},{"r":"みなさま","t":"皆様"},{"t":". "},{"r":"あめ","t":"雨"},{"t":"のようだ"},{"t":" is literally \"it has the appearance of rain\".\n\nRecognising it as a noun explains an entire family at once. "},{"t":"ように"},{"t":" is that noun with "},{"t":"に"},{"t":", \"in the manner that\"; "},{"t":"ようになる"},{"t":" is coming to be that way; "},{"t":"ようにする"},{"t":" is making it that way; "},{"t":"みたい"},{"t":" is the casual stand-in for the same thing. Five patterns, one word, and it is why "},{"t":"よう"},{"t":" takes "},{"t":"の"},{"t":" after a noun: "},{"r":"がくせい","t":"学生"},{"t":"のよう"},{"t":", exactly as any other noun would. "},{"t":"みたい"},{"t":", worn down further, attaches directly instead: "},{"r":"がくせい","t":"学生"},{"t":"みたい"},{"t":"."}]'::jsonb
