-- 〜させていただく: 閉店
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-06bac4a3418aa3f8', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"説明させていただきます parses as \"I receive your letting me explain\". Every piece is literal: させ is the causative, いただく the humble もらう.\n\nThat is why it implies permission was granted, and why it grates when nobody granted anything. Used for something entirely your own (閉店させていただきます), it asks the listener to supply a consent they were never asked for, which is the exact reason the form is criticised in Japanese as much as it is taught.","point":"〜させていただく","before":[{"t":"説明","r":"せつめい"},{"t":"させていただきます"},{"t":" parses as \"I receive your letting me explain\". Every piece is literal: "},{"t":"させ"},{"t":" is the causative, "},{"t":"いただく"},{"t":" the humble "},{"t":"もらう"},{"t":".\n\nThat is why it implies permission was granted, and why it grates when nobody granted anything. Used for something entirely your own ("},{"t":"閉","r":"し"},{"t":"店","r":"てん"},{"t":"させていただきます"},{"t":"), it asks the listener to supply a consent they were never asked for, which is the exact reason the form is criticised in Japanese as much as it is taught."}],"after":[{"t":"説明","r":"せつめい"},{"t":"させていただきます"},{"t":" parses as \"I receive your letting me explain\". Every piece is literal: "},{"t":"させ"},{"t":" is the causative, "},{"t":"いただく"},{"t":" the humble "},{"t":"もらう"},{"t":".\n\nThat is why it implies permission was granted, and why it grates when nobody granted anything. Used for something entirely your own ("},{"t":"閉店","r":"へいてん"},{"t":"させていただきます"},{"t":"), it asks the listener to supply a consent they were never asked for, which is the exact reason the form is criticised in Japanese as much as it is taught."}],"changes":[{"word":"閉店","from":[{"t":"閉","r":"し"},{"t":"店","r":"てん"}],"to":[{"t":"閉店","r":"へいてん"}],"why":"Compound is へいてん."}]}'::jsonb, '{"furigana":[{"r":"せつめい","t":"説明"},{"t":"させていただきます"},{"t":" parses as \"I receive your letting me explain\". Every piece is literal: "},{"t":"させ"},{"t":" is the causative, "},{"t":"いただく"},{"t":" the humble "},{"t":"もらう"},{"t":".\n\nThat is why it implies permission was granted, and why it grates when nobody granted anything. Used for something entirely your own ("},{"r":"し","t":"閉"},{"r":"てん","t":"店"},{"t":"させていただきます"},{"t":"), it asks the listener to supply a consent they were never asked for, which is the exact reason the form is criticised in Japanese as much as it is taught."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '06bac4a3418aa3f83d6fa78c351ac55fffdc905fc363db5ab1ebd758e5ff2ce8' AND l.code = 'ja'
  AND g.segments = '[{"r":"せつめい","t":"説明"},{"t":"させていただきます"},{"t":" parses as \"I receive your letting me explain\". Every piece is literal: "},{"t":"させ"},{"t":" is the causative, "},{"t":"いただく"},{"t":" the humble "},{"t":"もらう"},{"t":".\n\nThat is why it implies permission was granted, and why it grates when nobody granted anything. Used for something entirely your own ("},{"r":"し","t":"閉"},{"r":"てん","t":"店"},{"t":"させていただきます"},{"t":"), it asks the listener to supply a consent they were never asked for, which is the exact reason the form is criticised in Japanese as much as it is taught."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

