-- 〜すぎる: 過ぎる, 過ぎる
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-6849c2b8deb43112', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"過ぎる is a full verb: 時間が過ぎる, \"time passes\". Attached to a stem it keeps that meaning exactly: 食べすぎる is \"eating passes [the proper point]\".\n\nWhich explains the tone. すぎる is never neutral praise, because passing the proper point is a complaint in any language. It cannot be used for \"very\".","point":"〜すぎる","before":[{"t":"過","r":"よ"},{"t":"ぎる"},{"t":" is a full verb: "},{"t":"時間","r":"じかん"},{"t":"が"},{"t":"過","r":"よ"},{"t":"ぎる"},{"t":", \"time passes\". Attached to a stem it keeps that meaning exactly: "},{"t":"食","r":"た"},{"t":"べすぎる"},{"t":" is \"eating passes [the proper point]\".\n\nWhich explains the tone. "},{"t":"すぎる"},{"t":" is never neutral praise, because passing the proper point is a complaint in any language. It cannot be used for \"very\"."}],"after":[{"t":"過","r":"す"},{"t":"ぎる"},{"t":" is a full verb: "},{"t":"時間","r":"じかん"},{"t":"が"},{"t":"過","r":"す"},{"t":"ぎる"},{"t":", \"time passes\". Attached to a stem it keeps that meaning exactly: "},{"t":"食","r":"た"},{"t":"べすぎる"},{"t":" is \"eating passes [the proper point]\".\n\nWhich explains the tone. "},{"t":"すぎる"},{"t":" is never neutral praise, because passing the proper point is a complaint in any language. It cannot be used for \"very\"."}],"changes":[{"word":"過ぎる","from":[{"t":"過","r":"よ"},{"t":"ぎる"}],"to":[{"t":"過","r":"す"},{"t":"ぎる"}],"why":"過ぎる is すぎる."},{"word":"過ぎる","from":[{"t":"過","r":"よ"},{"t":"ぎる"}],"to":[{"t":"過","r":"す"},{"t":"ぎる"}],"why":"過ぎる is すぎる."}]}'::jsonb, '{"furigana":[{"r":"よ","t":"過"},{"t":"ぎる"},{"t":" is a full verb: "},{"r":"じかん","t":"時間"},{"t":"が"},{"r":"よ","t":"過"},{"t":"ぎる"},{"t":", \"time passes\". Attached to a stem it keeps that meaning exactly: "},{"r":"た","t":"食"},{"t":"べすぎる"},{"t":" is \"eating passes [the proper point]\".\n\nWhich explains the tone. "},{"t":"すぎる"},{"t":" is never neutral praise, because passing the proper point is a complaint in any language. It cannot be used for \"very\"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '6849c2b8deb43112c116400f109c1b005f82d6e093ba4d6eb7c6d7d89359545f' AND l.code = 'ja'
  AND g.segments = '[{"r":"よ","t":"過"},{"t":"ぎる"},{"t":" is a full verb: "},{"r":"じかん","t":"時間"},{"t":"が"},{"r":"よ","t":"過"},{"t":"ぎる"},{"t":", \"time passes\". Attached to a stem it keeps that meaning exactly: "},{"r":"た","t":"食"},{"t":"べすぎる"},{"t":" is \"eating passes [the proper point]\".\n\nWhich explains the tone. "},{"t":"すぎる"},{"t":" is never neutral praise, because passing the proper point is a complaint in any language. It cannot be used for \"very\"."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜にかかわらず: 得ない
