  AND g.segments = '[{"r":"かか","t":"関"},{"t":"わる"},{"t":" is an everyday verb: "},{"r":"じけん","t":"事件"},{"t":"に"},{"r":"かか","t":"関"},{"t":"わる"},{"t":", to be mixed up in something. "},{"t":"にかかわらず"},{"t":" says the outcome is not concerned with the thing named.\n\nThe "},{"t":"ず"},{"t":" is the Old Japanese negative, the same one in "},{"r":"し","t":"知"},{"t":"らず"},{"t":" and "},{"t":"ざるを"},{"r":"う","t":"得"},{"t":"ない"},{"t":", and it is why the attachment is to the "},{"t":"ない"},{"t":" stem rather than to a te-form. "},{"r":"てんこう","t":"天候"},{"t":"にかかわらず"},{"t":": the weather does not come into it."}]'::jsonb
