-- 〜そうだ (hearsay): 降りそう
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-2a8ad70f5f9e586b', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"降るそうだ takes the plain form whole (tense, negation and all), because what is being passed on is somebody else''s statement, and a statement needs all of it.\n\nThat single fact separates it from the そうだ of appearance, which takes a bare stem. 降りそうだ and 降るそうだ differ by one syllable and mean entirely different things: one is the sky, the other is the forecast. The attachment point is the whole distinction, and it is more reliable to lean on than the meaning.","point":"〜そうだ (hearsay)","before":[{"t":"降","r":"ふ"},{"t":"るそうだ"},{"t":" takes the plain form whole (tense, negation and all), because what is being passed on is somebody else''s statement, and a statement needs all of it.\n\nThat single fact separates it from the "},{"t":"そうだ"},{"t":" of appearance, which takes a bare stem. "},{"t":"降","r":"お"},{"t":"りそうだ"},{"t":" and "},{"t":"降","r":"ふ"},{"t":"るそうだ"},{"t":" differ by one syllable and mean entirely different things: one is the sky, the other is the forecast. The attachment point is the whole distinction, and it is more reliable to lean on than the meaning."}],"after":[{"t":"降","r":"ふ"},{"t":"るそうだ"},{"t":" takes the plain form whole (tense, negation and all), because what is being passed on is somebody else''s statement, and a statement needs all of it.\n\nThat single fact separates it from the "},{"t":"そうだ"},{"t":" of appearance, which takes a bare stem. "},{"t":"降","r":"ふ"},{"t":"りそう"},{"t":"だ"},{"t":" and "},{"t":"降","r":"ふ"},{"t":"るそうだ"},{"t":" differ by one syllable and mean entirely different things: one is the sky, the other is the forecast. The attachment point is the whole distinction, and it is more reliable to lean on than the meaning."}],"changes":[{"word":"降りそう","from":[{"t":"降","r":"お"},{"t":"りそう"}],"to":[{"t":"降","r":"ふ"},{"t":"りそう"}],"why":"雨が降る is ふる."}]}'::jsonb, '{"furigana":[{"r":"ふ","t":"降"},{"t":"るそうだ"},{"t":" takes the plain form whole (tense, negation and all), because what is being passed on is somebody else''s statement, and a statement needs all of it.\n\nThat single fact separates it from the "},{"t":"そうだ"},{"t":" of appearance, which takes a bare stem. "},{"r":"お","t":"降"},{"t":"りそうだ"},{"t":" and "},{"r":"ふ","t":"降"},{"t":"るそうだ"},{"t":" differ by one syllable and mean entirely different things: one is the sky, the other is the forecast. The attachment point is the whole distinction, and it is more reliable to lean on than the meaning."}]}'::jsonb, 'ai', 900, 'pending'
