INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-183e110b3e824d65', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"音楽が好きです says the music is likeable-to-me. There is no verb \"to like\" in the sentence, so there is no object, so を would have nothing to mark.\n\nThe same holds for 嫌い, 上手, 下手, ほしい and 分かる: every one of them an adjective or an intransitive verb, every one taking が. Learn the class and the particle stops being a rule about feelings and becomes ordinary grammar.","point":"〜が好き","before":[{"t":"音楽","r":"おんがく"},{"t":"が"},{"t":"好","r":"ず"},{"t":"きです"},{"t":" says the music is likeable-to-me. There is no verb \"to like\" in the sentence, so there is no object, so "},{"t":"を"},{"t":" would have nothing to mark.\n\nThe same holds for "},{"t":"嫌","r":"ぎら"},{"t":"い"},{"t":", "},{"t":"上手","r":"じょうず"},{"t":", "},{"t":"下手","r":"したて"},{"t":", "},{"t":"ほしい"},{"t":" and "},{"t":"分","r":"わ"},{"t":"かる"},{"t":": every one of them an adjective or an intransitive verb, every one taking "},{"t":"が"},{"t":". Learn the class and the particle stops being a rule about feelings and becomes ordinary grammar."}],"after":[{"t":"音楽","r":"おんがく"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":"です"},{"t":" says the music is likeable-to-me. There is no verb \"to like\" in the sentence, so there is no object, so "},{"t":"を"},{"t":" would have nothing to mark.\n\nThe same holds for "},{"t":"嫌","r":"きら"},{"t":"い"},{"t":", "},{"t":"上手","r":"じょうず"},{"t":", "},{"t":"下手","r":"へた"},{"t":", "},{"t":"ほしい"},{"t":" and "},{"t":"分","r":"わ"},{"t":"かる"},{"t":": every one of them an adjective or an intransitive verb, every one taking "},{"t":"が"},{"t":". Learn the class and the particle stops being a rule about feelings and becomes ordinary grammar."}],"changes":[{"word":"嫌い","from":[{"t":"嫌","r":"ぎら"},{"t":"い"}],"to":[{"t":"嫌","r":"きら"},{"t":"い"}],"why":"Dislike is きらい. / 嫌い is きらい."},{"word":"好き","from":[{"t":"好","r":"ず"},{"t":"き"}],"to":[{"t":"好","r":"す"},{"t":"き"}],"why":"Like is すき. / 好き is すき."},{"word":"下手","from":[{"t":"下手","r":"したて"}],"to":[{"t":"下手","r":"へた"}],"why":"Unskilled is へた."}]}'::jsonb, '{"furigana":[{"r":"おんがく","t":"音楽"},{"t":"が"},{"r":"ず","t":"好"},{"t":"きです"},{"t":" says the music is likeable-to-me. There is no verb \"to like\" in the sentence, so there is no object, so "},{"t":"を"},{"t":" would have nothing to mark.\n\nThe same holds for "},{"r":"ぎら","t":"嫌"},{"t":"い"},{"t":", "},{"r":"じょうず","t":"上手"},{"t":", "},{"r":"したて","t":"下手"},{"t":", "},{"t":"ほしい"},{"t":" and "},{"r":"わ","t":"分"},{"t":"かる"},{"t":": every one of them an adjective or an intransitive verb, every one taking "},{"t":"が"},{"t":". Learn the class and the particle stops being a rule about feelings and becomes ordinary grammar."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '183e110b3e824d650e8a1cb4cbd52fb4b47f572e9ada81445f8231aa0330fa43' AND l.code = 'ja'
  AND g.segments = '[{"r":"おんがく","t":"音楽"},{"t":"が"},{"r":"ず","t":"好"},{"t":"きです"},{"t":" says the music is likeable-to-me. There is no verb \"to like\" in the sentence, so there is no object, so "},{"t":"を"},{"t":" would have nothing to mark.\n\nThe same holds for "},{"r":"ぎら","t":"嫌"},{"t":"い"},{"t":", "},{"r":"じょうず","t":"上手"},{"t":", "},{"r":"したて","t":"下手"},{"t":", "},{"t":"ほしい"},{"t":" and "},{"r":"わ","t":"分"},{"t":"かる"},{"t":": every one of them an adjective or an intransitive verb, every one taking "},{"t":"が"},{"t":". Learn the class and the particle stops being a rule about feelings and becomes ordinary grammar."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜後で: 前に
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-cbe9d1dfc25902eb', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"駅の後ろ uses the same character for physical behind. 後で puts the sentence at a point after the thing named, a position noun with the で of circumstance.\n\nIt takes the past tense in front for the reason 前に takes the plain form: the verb describes the state of affairs at the moment being pointed at, and by then the act is done.","point":"〜後で","before":[{"t":"駅","r":"えき"},{"t":"の"},{"t":"後","r":"うし"},{"t":"ろ"},{"t":" uses the same character for physical behind. "},{"t":"後","r":"あと"},{"t":"で"},{"t":" puts the sentence at a point after the thing named, a position noun with the "},{"t":"で"},{"t":" of circumstance.\n\nIt takes the past tense in front for the reason "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" takes the plain form: the verb describes the state of affairs at the moment being pointed at, and by then the act is done."}],"after":[{"t":"駅","r":"えき"},{"t":"の"},{"t":"後","r":"うし"},{"t":"ろ"},{"t":" uses the same character for physical behind. "},{"t":"後","r":"あと"},{"t":"で"},{"t":" puts the sentence at a point after the thing named, a position noun with the "},{"t":"で"},{"t":" of circumstance.\n\nIt takes the past tense in front for the reason "},{"t":"前","r":"まえ"},{"t":"に"},{"t":" takes the plain form: the verb describes the state of affairs at the moment being pointed at, and by then the act is done."}],"changes":[{"word":"前に","from":[{"t":"前","r":"ぜん"},{"t":"に"}],"to":[{"t":"前","r":"まえ"},{"t":"に"}],"why":"前に is まえに."}]}'::jsonb, '{"furigana":[{"r":"えき","t":"駅"},{"t":"の"},{"r":"うし","t":"後"},{"t":"ろ"},{"t":" uses the same character for physical behind. "},{"r":"あと","t":"後"},{"t":"で"},{"t":" puts the sentence at a point after the thing named, a position noun with the "},{"t":"で"},{"t":" of circumstance.\n\nIt takes the past tense in front for the reason "},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" takes the plain form: the verb describes the state of affairs at the moment being pointed at, and by then the act is done."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'cbe9d1dfc25902eb3598ce5997b4fad4a66dee6ff1c2eee89fdab8a8a86ec809' AND l.code = 'ja'
  AND g.segments = '[{"r":"えき","t":"駅"},{"t":"の"},{"r":"うし","t":"後"},{"t":"ろ"},{"t":" uses the same character for physical behind. "},{"r":"あと","t":"後"},{"t":"で"},{"t":" puts the sentence at a point after the thing named, a position noun with the "},{"t":"で"},{"t":" of circumstance.\n\nIt takes the past tense in front for the reason "},{"r":"ぜん","t":"前"},{"t":"に"},{"t":" takes the plain form: the verb describes the state of affairs at the moment being pointed at, and by then the act is done."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- に (per): 三回
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-88090371fa9eb28b', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The に of 週に三回 is the same に that marks a point: it names the frame the count sits in.","point":"に (per)","before":[{"t":"The "},{"t":"に"},{"t":" of "},{"t":"週","r":"しゅう"},{"t":"に"},{"t":"三","r":"さん"},{"t":"回","r":"まわ"},{"t":" is the same "},{"t":"に"},{"t":" that marks a point: it names the frame the count sits in."}],"after":[{"t":"The "},{"t":"に"},{"t":" of "},{"t":"週","r":"しゅう"},{"t":"に"},{"t":"三回","r":"さんかい"},{"t":" is the same "},{"t":"に"},{"t":" that marks a point: it names the frame the count sits in."}],"changes":[{"word":"三回","from":[{"t":"三","r":"さん"},{"t":"回","r":"まわ"}],"to":[{"t":"三回","r":"さんかい"}],"why":"Three times is さんかい."}]}'::jsonb, '{"furigana":[{"t":"The "},{"t":"に"},{"t":" of "},{"r":"しゅう","t":"週"},{"t":"に"},{"r":"さん","t":"三"},{"r":"まわ","t":"回"},{"t":" is the same "},{"t":"に"},{"t":" that marks a point: it names the frame the count sits in."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '88090371fa9eb28bfa47ef82262360dc9c027b97d590cadf084a6989abe74e43' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"t":"に"},{"t":" of "},{"r":"しゅう","t":"週"},{"t":"に"},{"r":"さん","t":"三"},{"r":"まわ","t":"回"},{"t":" is the same "},{"t":"に"},{"t":" that marks a point: it names the frame the count sits in."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- に (per): 三時, 東京, 三回
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-28e5e789ae0a051c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"週に三回 sets \"week\" as the unit and puts three occurrences inside it. に is doing what it always does: naming the place something lands.\n\nSo there is no separate \"per\" particle to learn. It is the same に as 三時に and 東京に, and the English \"per\" is what has no counterpart, not the Japanese.","point":"に (per)","before":[{"t":"週","r":"しゅう"},{"t":"に"},{"t":"三","r":"さん"},{"t":"回","r":"まわ"},{"t":" sets \"week\" as the unit and puts three occurrences inside it. "},{"t":"に"},{"t":" is doing what it always does: naming the place something lands.\n\nSo there is no separate \"per\" particle to learn. It is the same "},{"t":"に"},{"t":" as "},{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"に"},{"t":" and "},{"t":"東","r":"とん"},{"t":"京に"},{"t":", and the English \"per\" is what has no counterpart, not the Japanese."}],"after":[{"t":"週","r":"しゅう"},{"t":"に"},{"t":"三回","r":"さんかい"},{"t":" sets \"week\" as the unit and puts three occurrences inside it. "},{"t":"に"},{"t":" is doing what it always does: naming the place something lands.\n\nSo there is no separate \"per\" particle to learn. It is the same "},{"t":"に"},{"t":" as "},{"t":"三時","r":"さんじ"},{"t":"に"},{"t":" and "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":", and the English \"per\" is what has no counterpart, not the Japanese."}],"changes":[{"word":"三時","from":[{"t":"三","r":"さん"},{"t":"時","r":"とき"}],"to":[{"t":"三時","r":"さんじ"}],"why":"Three o''clock is さんじ. / 三時 is さんじ."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."},{"word":"三回","from":[{"t":"三","r":"さん"},{"t":"回","r":"まわ"}],"to":[{"t":"三回","r":"さんかい"}],"why":"Three times is さんかい."}]}'::jsonb, '{"furigana":[{"r":"しゅう","t":"週"},{"t":"に"},{"r":"さん","t":"三"},{"r":"まわ","t":"回"},{"t":" sets \"week\" as the unit and puts three occurrences inside it. "},{"t":"に"},{"t":" is doing what it always does: naming the place something lands.\n\nSo there is no separate \"per\" particle to learn. It is the same "},{"t":"に"},{"t":" as "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"に"},{"t":" and "},{"r":"とん","t":"東"},{"t":"京に"},{"t":", and the English \"per\" is what has no counterpart, not the Japanese."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '28e5e789ae0a051c52a543df174376116bc4f60113a37635071bbda77b4cfe7d' AND l.code = 'ja'
  AND g.segments = '[{"r":"しゅう","t":"週"},{"t":"に"},{"r":"さん","t":"三"},{"r":"まわ","t":"回"},{"t":" sets \"week\" as the unit and puts three occurrences inside it. "},{"t":"に"},{"t":" is doing what it always does: naming the place something lands.\n\nSo there is no separate \"per\" particle to learn. It is the same "},{"t":"に"},{"t":" as "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"に"},{"t":" and "},{"r":"とん","t":"東"},{"t":"京に"},{"t":", and the English \"per\" is what has no counterpart, not the Japanese."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- Leaving things out: 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-535e8af7795db56f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The subject is not omitted from a full sentence so much as never obligatory in the first place. Old Japanese behaved the same way, and the language has no grammatical agreement that would need one.\n\nWhich is why supplying 私は every time sounds wrong rather than merely verbose: an overt topic marks a contrast or a change of subject, so using one where none is needed tells the listener something you did not mean.","point":"Leaving things out","before":[{"t":"The subject is not omitted from a full sentence so much as never obligatory in the first place. Old Japanese behaved the same way, and the language has no grammatical agreement that would need one.\n\nWhich is why supplying "},{"t":"私","r":"わちき"},{"t":"は"},{"t":" every time sounds wrong rather than merely verbose: an overt topic marks a contrast or a change of subject, so using one where none is needed tells the listener something you did not mean."}],"after":[{"t":"The subject is not omitted from a full sentence so much as never obligatory in the first place. Old Japanese behaved the same way, and the language has no grammatical agreement that would need one.\n\nWhich is why supplying "},{"t":"私","r":"わたし"},{"t":"は"},{"t":" every time sounds wrong rather than merely verbose: an overt topic marks a contrast or a change of subject, so using one where none is needed tells the listener something you did not mean."}],"changes":[{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"The subject is not omitted from a full sentence so much as never obligatory in the first place. Old Japanese behaved the same way, and the language has no grammatical agreement that would need one.\n\nWhich is why supplying "},{"r":"わちき","t":"私"},{"t":"は"},{"t":" every time sounds wrong rather than merely verbose: an overt topic marks a contrast or a change of subject, so using one where none is needed tells the listener something you did not mean."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '535e8af7795db56fac84d84749b5ac7154c26aacd837ccd2f5dbe10cddeb2c7e' AND l.code = 'ja'
  AND g.segments = '[{"t":"The subject is not omitted from a full sentence so much as never obligatory in the first place. Old Japanese behaved the same way, and the language has no grammatical agreement that would need one.\n\nWhich is why supplying "},{"r":"わちき","t":"私"},{"t":"は"},{"t":" every time sounds wrong rather than merely verbose: an overt topic marks a contrast or a change of subject, so using one where none is needed tells the listener something you did not mean."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

