-- 〜や否や: 否 is the classical, か否か, や否や
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-5a7ce889e47c4b68', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"否 is the classical word for no, the same one in か否か at N2. Asking whether a thing has happened or not, at the instant of asking, gives the sense of immediacy.\n\nThe three N1 immediacy patterns differ by nuance rather than by how tight the interval is: や否や belongs to written style and general statements, なり adds unexpectedness and holds the subject fixed, が早いか dramatises the onset.","point":"〜や否や","before":[{"t":"否","r":"ひ"},{"t":" is the classical word for no, the same one in "},{"t":"か"},{"t":"否","r":"ひ"},{"t":"か"},{"t":" at N2. Asking whether a thing has happened or not, at the instant of asking, gives the sense of immediacy.\n\nThe three N1 immediacy patterns differ by nuance rather than by how tight the interval is: "},{"t":"や"},{"t":"否","r":"ひ"},{"t":"や"},{"t":" belongs to written style and general statements, "},{"t":"なり"},{"t":" adds unexpectedness and holds the subject fixed, "},{"t":"が"},{"t":"早","r":"はや"},{"t":"いか"},{"t":" dramatises the onset."}],"after":[{"t":"否","r":"いな"},{"t":" is the classical"},{"t":" word for no, the same one in "},{"t":"か"},{"t":"否","r":"いな"},{"t":"か"},{"t":" at N2. Asking whether a thing has happened or not, at the instant of asking, gives the sense of immediacy.\n\nThe three N1 immediacy patterns differ by nuance rather than by how tight the interval is: "},{"t":"や"},{"t":"否","r":"いな"},{"t":"や"},{"t":" belongs to written style and general statements, "},{"t":"なり"},{"t":" adds unexpectedness and holds the subject fixed, "},{"t":"が"},{"t":"早","r":"はや"},{"t":"いか"},{"t":" dramatises the onset."}],"changes":[{"word":"否 is the classical","from":[{"t":"否","r":"ひ"},{"t":" is the classical"}],"to":[{"t":"否","r":"いな"},{"t":" is the classical"}],"why":"The classical no is いな."},{"word":"か否か","from":[{"t":"か"},{"t":"否","r":"ひ"},{"t":"か"}],"to":[{"t":"か"},{"t":"否","r":"いな"},{"t":"か"}],"why":"否 here is いな."},{"word":"や否や","from":[{"t":"や"},{"t":"否","r":"ひ"},{"t":"や"}],"to":[{"t":"や"},{"t":"否","r":"いな"},{"t":"や"}],"why":"bare 否 also hits the 否 of 安否/否定 in prose (ひ there); limit to や否や and the explicit いな mentions; か否か is covered by #73"}]}'::jsonb, '{"furigana":[{"r":"ひ","t":"否"},{"t":" is the classical word for no, the same one in "},{"t":"か"},{"r":"ひ","t":"否"},{"t":"か"},{"t":" at N2. Asking whether a thing has happened or not, at the instant of asking, gives the sense of immediacy.\n\nThe three N1 immediacy patterns differ by nuance rather than by how tight the interval is: "},{"t":"や"},{"r":"ひ","t":"否"},{"t":"や"},{"t":" belongs to written style and general statements, "},{"t":"なり"},{"t":" adds unexpectedness and holds the subject fixed, "},{"t":"が"},{"r":"はや","t":"早"},{"t":"いか"},{"t":" dramatises the onset."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '5a7ce889e47c4b68b3372122cebd4a4435730ea9f61fecfd8771e5ac66acda19' AND l.code = 'ja'
  AND g.segments = '[{"r":"ひ","t":"否"},{"t":" is the classical word for no, the same one in "},{"t":"か"},{"r":"ひ","t":"否"},{"t":"か"},{"t":" at N2. Asking whether a thing has happened or not, at the instant of asking, gives the sense of immediacy.\n\nThe three N1 immediacy patterns differ by nuance rather than by how tight the interval is: "},{"t":"や"},{"r":"ひ","t":"否"},{"t":"や"},{"t":" belongs to written style and general statements, "},{"t":"なり"},{"t":" adds unexpectedness and holds the subject fixed, "},{"t":"が"},{"r":"はや","t":"早"},{"t":"いか"},{"t":" dramatises the onset."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
