-- 〜いながらにして: 家にいながらにして, 世界中, 話せる
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-69956e0ee1be3748', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same ながら as 生まれながらに, meaning a state that persists rather than two things at once. いながら is staying put.\n\n家にいながらにして世界中と話せる says the whole thing without moving: the state of being at home is unbroken while the rest happens. The pattern is a small monument to what ながら used to mean.","point":"〜いながらにして","before":[{"t":"The same "},{"t":"ながら"},{"t":" as "},{"t":"生","r":"う"},{"t":"まれながらに"},{"t":", meaning a state that persists rather than two things at once. "},{"t":"いながら"},{"t":" is staying put.\n\n"},{"t":"家","r":"け"},{"t":"にいながらにして"},{"t":"世界","r":"せかい"},{"t":"中","r":"なか"},{"t":"と"},{"t":"話","r":"わ"},{"t":"せる"},{"t":" says the whole thing without moving: the state of being at home is unbroken while the rest happens. The pattern is a small monument to what "},{"t":"ながら"},{"t":" used to mean."}],"after":[{"t":"The same "},{"t":"ながら"},{"t":" as "},{"t":"生","r":"う"},{"t":"まれながらに"},{"t":", meaning a state that persists rather than two things at once. "},{"t":"いながら"},{"t":" is staying put.\n\n"},{"t":"家","r":"いえ"},{"t":"にいながらにして"},{"t":"世界中","r":"せかいじゅう"},{"t":"と"},{"t":"話","r":"はな"},{"t":"せる"},{"t":" says the whole thing without moving: the state of being at home is unbroken while the rest happens. The pattern is a small monument to what "},{"t":"ながら"},{"t":" used to mean."}],"changes":[{"word":"家にいながらにして","from":[{"t":"家","r":"け"},{"t":"にいながらにして"}],"to":[{"t":"家","r":"いえ"},{"t":"にいながらにして"}],"why":"Home is いえ here."},{"word":"世界中","from":[{"t":"世界","r":"せかい"},{"t":"中","r":"なか"}],"to":[{"t":"世界中","r":"せかいじゅう"}],"why":"All over the world is せかいじゅう. / 世界中 is せかいじゅう."},{"word":"話せる","from":[{"t":"話","r":"わ"},{"t":"せる"}],"to":[{"t":"話","r":"はな"},{"t":"せる"}],"why":"話せる is はなせる."}]}'::jsonb, '{"furigana":[{"t":"The same "},{"t":"ながら"},{"t":" as "},{"r":"う","t":"生"},{"t":"まれながらに"},{"t":", meaning a state that persists rather than two things at once. "},{"t":"いながら"},{"t":" is staying put.\n\n"},{"r":"け","t":"家"},{"t":"にいながらにして"},{"r":"せかい","t":"世界"},{"r":"なか","t":"中"},{"t":"と"},{"r":"わ","t":"話"},{"t":"せる"},{"t":" says the whole thing without moving: the state of being at home is unbroken while the rest happens. The pattern is a small monument to what "},{"t":"ながら"},{"t":" used to mean."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '69956e0ee1be3748a80e0e27d97c63888e3b1f1646bd6432d7b912b2df77afd8' AND l.code = 'ja'
  AND g.segments = '[{"t":"The same "},{"t":"ながら"},{"t":" as "},{"r":"う","t":"生"},{"t":"まれながらに"},{"t":", meaning a state that persists rather than two things at once. "},{"t":"いながら"},{"t":" is staying put.\n\n"},{"r":"け","t":"家"},{"t":"にいながらにして"},{"r":"せかい","t":"世界"},{"r":"なか","t":"中"},{"t":"と"},{"r":"わ","t":"話"},{"t":"せる"},{"t":" says the whole thing without moving: the state of being at home is unbroken while the rest happens. The pattern is a small monument to what "},{"t":"ながら"},{"t":" used to mean."}]'::jsonb
