-- Having something: 車があります, 好き, 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b9c558a3f7a161c5', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"車があります is \"a car exists\"; who it belongs to is supplied by は or に, not by a verb of having. 私には子供がいます is literally \"to me, children exist\".\n\nThat is why the possessed thing takes が rather than を: there is no transitive verb in the sentence at all. The same shape underlies 分かる and 好き, and it is the commonest reason a learner reaches for を and finds it wrong.","point":"Having something","before":[{"t":"車","r":"しゃ"},{"t":"があります"},{"t":" is \"a car exists\"; who it belongs to is supplied by "},{"t":"は"},{"t":" or "},{"t":"に"},{"t":", not by a verb of having. "},{"t":"私","r":"わちき"},{"t":"には"},{"t":"子供","r":"こども"},{"t":"がいます"},{"t":" is literally \"to me, children exist\".\n\nThat is why the possessed thing takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":": there is no transitive verb in the sentence at all. The same shape underlies "},{"t":"分","r":"わ"},{"t":"かる"},{"t":" and "},{"t":"好","r":"ず"},{"t":"き"},{"t":", and it is the commonest reason a learner reaches for "},{"t":"を"},{"t":" and finds it wrong."}],"after":[{"t":"車","r":"くるま"},{"t":"があります"},{"t":" is \"a car exists\"; who it belongs to is supplied by "},{"t":"は"},{"t":" or "},{"t":"に"},{"t":", not by a verb of having. "},{"t":"私","r":"わたし"},{"t":"には"},{"t":"子供","r":"こども"},{"t":"がいます"},{"t":" is literally \"to me, children exist\".\n\nThat is why the possessed thing takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":": there is no transitive verb in the sentence at all. The same shape underlies "},{"t":"分","r":"わ"},{"t":"かる"},{"t":" and "},{"t":"好","r":"す"},{"t":"き"},{"t":", and it is the commonest reason a learner reaches for "},{"t":"を"},{"t":" and finds it wrong."}],"changes":[{"word":"車があります","from":[{"t":"車","r":"しゃ"},{"t":"があります"}],"to":[{"t":"車","r":"くるま"},{"t":"があります"}],"why":"Car is くるま."},{"word":"好き","from":[{"t":"好","r":"ず"},{"t":"き"}],"to":[{"t":"好","r":"す"},{"t":"き"}],"why":"Like is すき. / 好き is すき."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"r":"しゃ","t":"車"},{"t":"があります"},{"t":" is \"a car exists\"; who it belongs to is supplied by "},{"t":"は"},{"t":" or "},{"t":"に"},{"t":", not by a verb of having. "},{"r":"わちき","t":"私"},{"t":"には"},{"r":"こども","t":"子供"},{"t":"がいます"},{"t":" is literally \"to me, children exist\".\n\nThat is why the possessed thing takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":": there is no transitive verb in the sentence at all. The same shape underlies "},{"r":"わ","t":"分"},{"t":"かる"},{"t":" and "},{"r":"ず","t":"好"},{"t":"き"},{"t":", and it is the commonest reason a learner reaches for "},{"t":"を"},{"t":" and finds it wrong."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'b9c558a3f7a161c50e8f834e8609737b58d2b22c59de15c0ee5fef5f5af2090c' AND l.code = 'ja'
  AND g.segments = '[{"r":"しゃ","t":"車"},{"t":"があります"},{"t":" is \"a car exists\"; who it belongs to is supplied by "},{"t":"は"},{"t":" or "},{"t":"に"},{"t":", not by a verb of having. "},{"r":"わちき","t":"私"},{"t":"には"},{"r":"こども","t":"子供"},{"t":"がいます"},{"t":" is literally \"to me, children exist\".\n\nThat is why the possessed thing takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":": there is no transitive verb in the sentence at all. The same shape underlies "},{"r":"わ","t":"分"},{"t":"かる"},{"t":" and "},{"r":"ず","t":"好"},{"t":"き"},{"t":", and it is the commonest reason a learner reaches for "},{"t":"を"},{"t":" and finds it wrong."}]'::jsonb
