-- で (tool, material): 酒を作
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-9f0a9bfce4d9d803', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"木で作る is building in the circumstance of wood. There is no separate material particle in Japanese.\n\nWhere で will not go is a change so complete the original is gone: 米から酒を作る takes から, because the rice is a starting point that has been left behind rather than a circumstance the making happened in.","point":"で (tool, material)","before":[{"t":"木","r":"き"},{"t":"で"},{"t":"作","r":"つく"},{"t":"る"},{"t":" is building in the circumstance of wood. There is no separate material particle in Japanese.\n\nWhere "},{"t":"で"},{"t":" will not go is a change so complete the original is gone: "},{"t":"米","r":"こめ"},{"t":"から"},{"t":"酒","r":"しゅ"},{"t":"を"},{"t":"作","r":"つく"},{"t":"る"},{"t":" takes "},{"t":"から"},{"t":", because the rice is a starting point that has been left behind rather than a circumstance the making happened in."}],"after":[{"t":"木","r":"き"},{"t":"で"},{"t":"作","r":"つく"},{"t":"る"},{"t":" is building in the circumstance of wood. There is no separate material particle in Japanese.\n\nWhere "},{"t":"で"},{"t":" will not go is a change so complete the original is gone: "},{"t":"米","r":"こめ"},{"t":"から"},{"t":"酒","r":"さけ"},{"t":"を"},{"t":"作","r":"つく"},{"t":"る"},{"t":" takes "},{"t":"から"},{"t":", because the rice is a starting point that has been left behind rather than a circumstance the making happened in."}],"changes":[{"word":"酒を作","from":[{"t":"酒","r":"しゅ"},{"t":"を"},{"t":"作","r":"つく"}],"to":[{"t":"酒","r":"さけ"},{"t":"を"},{"t":"作","r":"つく"}],"why":"FINAL dropped the reading on 作"}]}'::jsonb, '{"furigana":[{"r":"き","t":"木"},{"t":"で"},{"r":"つく","t":"作"},{"t":"る"},{"t":" is building in the circumstance of wood. There is no separate material particle in Japanese.\n\nWhere "},{"t":"で"},{"t":" will not go is a change so complete the original is gone: "},{"r":"こめ","t":"米"},{"t":"から"},{"r":"しゅ","t":"酒"},{"t":"を"},{"r":"つく","t":"作"},{"t":"る"},{"t":" takes "},{"t":"から"},{"t":", because the rice is a starting point that has been left behind rather than a circumstance the making happened in."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '9f0a9bfce4d9d803c4f6da881175b4311dde6d0e9b6fb3e97aefd2c2353815d5' AND l.code = 'ja'
  AND g.segments = '[{"r":"き","t":"木"},{"t":"で"},{"r":"つく","t":"作"},{"t":"る"},{"t":" is building in the circumstance of wood. There is no separate material particle in Japanese.\n\nWhere "},{"t":"で"},{"t":" will not go is a change so complete the original is gone: "},{"r":"こめ","t":"米"},{"t":"から"},{"r":"しゅ","t":"酒"},{"t":"を"},{"r":"つく","t":"作"},{"t":"る"},{"t":" takes "},{"t":"から"},{"t":", because the rice is a starting point that has been left behind rather than a circumstance the making happened in."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜ている (habit): 今走って
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-163829375de25b8c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ている is the te-form with いる, \"exists having done\". Whether that reads as in-progress, as a resulting state, or as a habit is decided by the verb''s own aspect and by adverbs like 毎日.\n\n毎日走っています is habit; 今走っています is progress; 結婚しています is a state that resulted. One form, three readings, and Japanese does not mark the difference because the context always does.","point":"〜ている (habit)","before":[{"t":"ている"},{"t":" is the te-form with "},{"t":"いる"},{"t":", \"exists having done\". Whether that reads as in-progress, as a resulting state, or as a habit is decided by the verb''s own aspect and by adverbs like "},{"t":"毎日","r":"まいにち"},{"t":".\n\n"},{"t":"毎日","r":"まいにち"},{"t":"走","r":"はし"},{"t":"っています"},{"t":" is habit; "},{"t":"今","r":"こん"},{"t":"走","r":"はし"},{"t":"っています"},{"t":" is progress; "},{"t":"結婚","r":"けっこん"},{"t":"しています"},{"t":" is a state that resulted. One form, three readings, and Japanese does not mark the difference because the context always does."}],"after":[{"t":"ている"},{"t":" is the te-form with "},{"t":"いる"},{"t":", \"exists having done\". Whether that reads as in-progress, as a resulting state, or as a habit is decided by the verb''s own aspect and by adverbs like "},{"t":"毎日","r":"まいにち"},{"t":".\n\n"},{"t":"毎日","r":"まいにち"},{"t":"走","r":"はし"},{"t":"っています"},{"t":" is habit; "},{"t":"今","r":"いま"},{"t":"走","r":"はし"},{"t":"って"},{"t":"います"},{"t":" is progress; "},{"t":"結婚","r":"けっこん"},{"t":"しています"},{"t":" is a state that resulted. One form, three readings, and Japanese does not mark the difference because the context always does."}],"changes":[{"word":"今走って","from":[{"t":"今","r":"こん"},{"t":"走","r":"はし"},{"t":"って"}],"to":[{"t":"今","r":"いま"},{"t":"走","r":"はし"},{"t":"って"}],"why":"今 is いま."}]}'::jsonb, '{"furigana":[{"t":"ている"},{"t":" is the te-form with "},{"t":"いる"},{"t":", \"exists having done\". Whether that reads as in-progress, as a resulting state, or as a habit is decided by the verb''s own aspect and by adverbs like "},{"r":"まいにち","t":"毎日"},{"t":".\n\n"},{"r":"まいにち","t":"毎日"},{"r":"はし","t":"走"},{"t":"っています"},{"t":" is habit; "},{"r":"こん","t":"今"},{"r":"はし","t":"走"},{"t":"っています"},{"t":" is progress; "},{"r":"けっこん","t":"結婚"},{"t":"しています"},{"t":" is a state that resulted. One form, three readings, and Japanese does not mark the difference because the context always does."}]}'::jsonb, 'ai', 900, 'pending'
