-- 〜がゆえに: 故に
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-07ff950892ed06f5', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Before が marked subjects it marked possession, which is why 我が国 still reads as \"my country\". がゆえに is \"by reason OF\", with が doing the joining.\n\nSo the difference from plain ゆえに is not emphasis but an older grammar preserved; classical の故に is equally good, and が and の differed by register rather than by force. The whole phrase is a fossil kept for formal writing.","point":"〜がゆえに","before":[{"t":"Before "},{"t":"が"},{"t":" marked subjects it marked possession, which is why "},{"t":"我","r":"わ"},{"t":"が"},{"t":"国","r":"くに"},{"t":" still reads as \"my country\". "},{"t":"がゆえに"},{"t":" is \"by reason OF\", with "},{"t":"が"},{"t":" doing the joining.\n\nSo the difference from plain "},{"t":"ゆえに"},{"t":" is not emphasis but an older grammar preserved; classical "},{"t":"の"},{"t":"故","r":"こ"},{"t":"に"},{"t":" is equally good, and "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" differed by register rather than by force. The whole phrase is a fossil kept for formal writing."}],"after":[{"t":"Before "},{"t":"が"},{"t":" marked subjects it marked possession, which is why "},{"t":"我","r":"わ"},{"t":"が"},{"t":"国","r":"くに"},{"t":" still reads as \"my country\". "},{"t":"がゆえに"},{"t":" is \"by reason OF\", with "},{"t":"が"},{"t":" doing the joining.\n\nSo the difference from plain "},{"t":"ゆえに"},{"t":" is not emphasis but an older grammar preserved; classical "},{"t":"の"},{"t":"故","r":"ゆえ"},{"t":"に"},{"t":" is equally good, and "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" differed by register rather than by force. The whole phrase is a fossil kept for formal writing."}],"changes":[{"word":"故に","from":[{"t":"故","r":"こ"},{"t":"に"}],"to":[{"t":"故","r":"ゆえ"},{"t":"に"}],"why":"故 is ゆえ."}]}'::jsonb, '{"furigana":[{"t":"Before "},{"t":"が"},{"t":" marked subjects it marked possession, which is why "},{"r":"わ","t":"我"},{"t":"が"},{"r":"くに","t":"国"},{"t":" still reads as \"my country\". "},{"t":"がゆえに"},{"t":" is \"by reason OF\", with "},{"t":"が"},{"t":" doing the joining.\n\nSo the difference from plain "},{"t":"ゆえに"},{"t":" is not emphasis but an older grammar preserved; classical "},{"t":"の"},{"r":"こ","t":"故"},{"t":"に"},{"t":" is equally good, and "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" differed by register rather than by force. The whole phrase is a fossil kept for formal writing."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '07ff950892ed06f557ead7f7899656444d3aa819cab7207301ca396e2b2a2ff9' AND l.code = 'ja'
  AND g.segments = '[{"t":"Before "},{"t":"が"},{"t":" marked subjects it marked possession, which is why "},{"r":"わ","t":"我"},{"t":"が"},{"r":"くに","t":"国"},{"t":" still reads as \"my country\". "},{"t":"がゆえに"},{"t":" is \"by reason OF\", with "},{"t":"が"},{"t":" doing the joining.\n\nSo the difference from plain "},{"t":"ゆえに"},{"t":" is not emphasis but an older grammar preserved; classical "},{"t":"の"},{"r":"こ","t":"故"},{"t":"に"},{"t":" is equally good, and "},{"t":"が"},{"t":" and "},{"t":"の"},{"t":" differed by register rather than by force. The whole phrase is a fossil kept for formal writing."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜がち: 病気
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-31b6eca0afc1f079', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The thing that tends to happen is the thing that wins out. 病気がち is illness prevailing more often than not.\n\nThe negative colouring follows from that: what prevails over you is not usually welcome, which is why 忘れがち and 遅れがち are natural and 元気がち is not. Compare 気味, which is a touch of something, and っぽい, which is a resemblance: three suffixes, three quite different pictures.","point":"〜がち","before":[{"t":"The thing that tends to happen is the thing that wins out. "},{"t":"病気","r":"やまいけ"},{"t":"がち"},{"t":" is illness prevailing more often than not.\n\nThe negative colouring follows from that: what prevails over you is not usually welcome, which is why "},{"t":"忘","r":"わす"},{"t":"れがち"},{"t":" and "},{"t":"遅","r":"おく"},{"t":"れがち"},{"t":" are natural and "},{"t":"元気","r":"げんき"},{"t":"がち"},{"t":" is not. Compare "},{"t":"気味","r":"ぎみ"},{"t":", which is a touch of something, and "},{"t":"っぽい"},{"t":", which is a resemblance: three suffixes, three quite different pictures."}],"after":[{"t":"The thing that tends to happen is the thing that wins out. "},{"t":"病気","r":"びょうき"},{"t":"がち"},{"t":" is illness prevailing more often than not.\n\nThe negative colouring follows from that: what prevails over you is not usually welcome, which is why "},{"t":"忘","r":"わす"},{"t":"れがち"},{"t":" and "},{"t":"遅","r":"おく"},{"t":"れがち"},{"t":" are natural and "},{"t":"元気","r":"げんき"},{"t":"がち"},{"t":" is not. Compare "},{"t":"気味","r":"ぎみ"},{"t":", which is a touch of something, and "},{"t":"っぽい"},{"t":", which is a resemblance: three suffixes, three quite different pictures."}],"changes":[{"word":"病気","from":[{"t":"病気","r":"やまいけ"}],"to":[{"t":"病気","r":"びょうき"}],"why":"Illness is びょうき. / 病気 is びょうき."}]}'::jsonb, '{"furigana":[{"t":"The thing that tends to happen is the thing that wins out. "},{"r":"やまいけ","t":"病気"},{"t":"がち"},{"t":" is illness prevailing more often than not.\n\nThe negative colouring follows from that: what prevails over you is not usually welcome, which is why "},{"r":"わす","t":"忘"},{"t":"れがち"},{"t":" and "},{"r":"おく","t":"遅"},{"t":"れがち"},{"t":" are natural and "},{"r":"げんき","t":"元気"},{"t":"がち"},{"t":" is not. Compare "},{"r":"ぎみ","t":"気味"},{"t":", which is a touch of something, and "},{"t":"っぽい"},{"t":", which is a resemblance: three suffixes, three quite different pictures."}]}'::jsonb, 'ai', 900, 'pending'
