  AND g.segments = '[{"t":"The thing that tends to happen is the thing that wins out. "},{"r":"やまいけ","t":"病気"},{"t":"がち"},{"t":" is illness prevailing more often than not.\n\nThe negative colouring follows from that: what prevails over you is not usually welcome, which is why "},{"r":"わす","t":"忘"},{"t":"れがち"},{"t":" and "},{"r":"おく","t":"遅"},{"t":"れがち"},{"t":" are natural and "},{"r":"げんき","t":"元気"},{"t":"がち"},{"t":" is not. Compare "},{"r":"ぎみ","t":"気味"},{"t":", which is a touch of something, and "},{"t":"っぽい"},{"t":", which is a resemblance: three suffixes, three quite different pictures."}]'::jsonb
