-- 〜ごろ: 三時ごろ, 三時ごろ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-bd85079fd675576d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"若い頃 is one''s youth; 三時ごろ is around three. What ごろ makes vague is where a moment falls.\n\nThat is exactly why the two cannot be swapped. 三時ごろ is around three o''clock, a point; 三時間ぐらい is about three hours, an amount. Ask whether the number is a place on the clock or a length, and the particle chooses itself.","point":"〜ごろ","before":[{"t":"若","r":"わか"},{"t":"い"},{"t":"頃","r":"ごろ"},{"t":" is one''s youth; "},{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"ごろ"},{"t":" is around three. What "},{"t":"ごろ"},{"t":" makes vague is where a moment falls.\n\nThat is exactly why the two cannot be swapped. "},{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"ごろ"},{"t":" is around three o''clock, a point; "},{"t":"三","r":"さん"},{"t":"時間","r":"じかん"},{"t":"ぐらい"},{"t":" is about three hours, an amount. Ask whether the number is a place on the clock or a length, and the particle chooses itself."}],"after":[{"t":"若","r":"わか"},{"t":"い"},{"t":"頃","r":"ごろ"},{"t":" is one''s youth; "},{"t":"三時","r":"さんじ"},{"t":"ごろ"},{"t":" is around three. What "},{"t":"ごろ"},{"t":" makes vague is where a moment falls.\n\nThat is exactly why the two cannot be swapped. "},{"t":"三時","r":"さんじ"},{"t":"ごろ"},{"t":" is around three o''clock, a point; "},{"t":"三","r":"さん"},{"t":"時間","r":"じかん"},{"t":"ぐらい"},{"t":" is about three hours, an amount. Ask whether the number is a place on the clock or a length, and the particle chooses itself."}],"changes":[{"word":"三時ごろ","from":[{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"ごろ"}],"to":[{"t":"三時","r":"さんじ"},{"t":"ごろ"}],"why":"Three o''clock is さんじ."},{"word":"三時ごろ","from":[{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"ごろ"}],"to":[{"t":"三時","r":"さんじ"},{"t":"ごろ"}],"why":"Three o''clock is さんじ."}]}'::jsonb, '{"furigana":[{"r":"わか","t":"若"},{"t":"い"},{"r":"ごろ","t":"頃"},{"t":" is one''s youth; "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"ごろ"},{"t":" is around three. What "},{"t":"ごろ"},{"t":" makes vague is where a moment falls.\n\nThat is exactly why the two cannot be swapped. "},{"r":"さん","t":"三"},{"r":"とき","t":"時"},{"t":"ごろ"},{"t":" is around three o''clock, a point; "},{"r":"さん","t":"三"},{"r":"じかん","t":"時間"},{"t":"ぐらい"},{"t":" is about three hours, an amount. Ask whether the number is a place on the clock or a length, and the particle chooses itself."}]}'::jsonb, 'ai', 900, 'pending'
