-- 〜あげく: 断られた, 挙句, 挙句, 連歌
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-714ab7b1fbe176c7', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"連歌 was composed in sequence by several poets, and the 挙句 was the last verse, the one everything before had been building toward. The phrase 挙句の果て still carries that finality.\n\nThe modern sense keeps the long build-up and adds a verdict on it. あげく always follows a drawn-out process and always ends badly (待たされたあげく断られた), which is why it cannot be used for a good outcome however long the wait.","point":"〜あげく","before":[{"t":"連","r":"つ"},{"t":"歌","r":"うた"},{"t":" was composed in sequence by several poets, and the "},{"t":"挙","r":"あ"},{"t":"句","r":"く"},{"t":" was the last verse, the one everything before had been building toward. The phrase "},{"t":"挙","r":"あ"},{"t":"句","r":"く"},{"t":"の"},{"t":"果","r":"は"},{"t":"て"},{"t":" still carries that finality.\n\nThe modern sense keeps the long build-up and adds a verdict on it. "},{"t":"あげく"},{"t":" always follows a drawn-out process and always ends badly ("},{"t":"待","r":"ま"},{"t":"たされたあげく"},{"t":"断","r":"た"},{"t":"られた"},{"t":"), which is why it cannot be used for a good outcome however long the wait."}],"after":[{"t":"連歌","r":"れんが"},{"t":" was composed in sequence by several poets, and the "},{"t":"挙句","r":"あげく"},{"t":" was the last verse, the one everything before had been building toward. The phrase "},{"t":"挙句","r":"あげく"},{"t":"の"},{"t":"果","r":"は"},{"t":"て"},{"t":" still carries that finality.\n\nThe modern sense keeps the long build-up and adds a verdict on it. "},{"t":"あげく"},{"t":" always follows a drawn-out process and always ends badly ("},{"t":"待","r":"ま"},{"t":"たされたあげく"},{"t":"断","r":"ことわ"},{"t":"られた"},{"t":"), which is why it cannot be used for a good outcome however long the wait."}],"changes":[{"word":"断られた","from":[{"t":"断","r":"た"},{"t":"られた"}],"to":[{"t":"断","r":"ことわ"},{"t":"られた"}],"why":"Refuse is ことわる."},{"word":"挙句","from":[{"t":"挙","r":"あ"},{"t":"句","r":"く"}],"to":[{"t":"挙句","r":"あげく"}],"why":"Compound is あげく."},{"word":"挙句","from":[{"t":"挙","r":"あ"},{"t":"句","r":"く"}],"to":[{"t":"挙句","r":"あげく"}],"why":"Compound is あげく."},{"word":"連歌","from":[{"t":"連","r":"つ"},{"t":"歌","r":"うた"}],"to":[{"t":"連歌","r":"れんが"}],"why":"Compound is れんが."}]}'::jsonb, '{"furigana":[{"r":"つ","t":"連"},{"r":"うた","t":"歌"},{"t":" was composed in sequence by several poets, and the "},{"r":"あ","t":"挙"},{"r":"く","t":"句"},{"t":" was the last verse, the one everything before had been building toward. The phrase "},{"r":"あ","t":"挙"},{"r":"く","t":"句"},{"t":"の"},{"r":"は","t":"果"},{"t":"て"},{"t":" still carries that finality.\n\nThe modern sense keeps the long build-up and adds a verdict on it. "},{"t":"あげく"},{"t":" always follows a drawn-out process and always ends badly ("},{"r":"ま","t":"待"},{"t":"たされたあげく"},{"r":"た","t":"断"},{"t":"られた"},{"t":"), which is why it cannot be used for a good outcome however long the wait."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
