-- 〜にあらず: 人にあらず
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-5083be93a550fd05', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"あり was the Old Japanese existence verb, ancestor of ある. にあらず is the classical way of denying identity.\n\nIt survives in mottoes and set phrases (人にあらず) for the same reason べからず survives on signs. The modern ではない descends from the very same construction: its で is にて worn down, so the に never actually left.","point":"〜にあらず","before":[{"t":"あり"},{"t":" was the Old Japanese existence verb, ancestor of "},{"t":"ある"},{"t":". "},{"t":"にあらず"},{"t":" is the classical way of denying identity.\n\nIt survives in mottoes and set phrases ("},{"t":"人","r":"と"},{"t":"にあらず"},{"t":") for the same reason "},{"t":"べからず"},{"t":" survives on signs. The modern "},{"t":"ではない"},{"t":" descends from the very same construction: its "},{"t":"で"},{"t":" is "},{"t":"にて"},{"t":" worn down, so the "},{"t":"に"},{"t":" never actually left."}],"after":[{"t":"あり"},{"t":" was the Old Japanese existence verb, ancestor of "},{"t":"ある"},{"t":". "},{"t":"にあらず"},{"t":" is the classical way of denying identity.\n\nIt survives in mottoes and set phrases ("},{"t":"人","r":"ひと"},{"t":"にあらず"},{"t":") for the same reason "},{"t":"べからず"},{"t":" survives on signs. The modern "},{"t":"ではない"},{"t":" descends from the very same construction: its "},{"t":"で"},{"t":" is "},{"t":"にて"},{"t":" worn down, so the "},{"t":"に"},{"t":" never actually left."}],"changes":[{"word":"人にあらず","from":[{"t":"人","r":"と"},{"t":"にあらず"}],"to":[{"t":"人","r":"ひと"},{"t":"にあらず"}],"why":"Person is ひと."}]}'::jsonb, '{"furigana":[{"t":"あり"},{"t":" was the Old Japanese existence verb, ancestor of "},{"t":"ある"},{"t":". "},{"t":"にあらず"},{"t":" is the classical way of denying identity.\n\nIt survives in mottoes and set phrases ("},{"r":"と","t":"人"},{"t":"にあらず"},{"t":") for the same reason "},{"t":"べからず"},{"t":" survives on signs. The modern "},{"t":"ではない"},{"t":" descends from the very same construction: its "},{"t":"で"},{"t":" is "},{"t":"にて"},{"t":" worn down, so the "},{"t":"に"},{"t":" never actually left."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '5083be93a550fd05f27ec124a2f49f6eeaf5f24cce5b7210fab4672be1caa836' AND l.code = 'ja'
  AND g.segments = '[{"t":"あり"},{"t":" was the Old Japanese existence verb, ancestor of "},{"t":"ある"},{"t":". "},{"t":"にあらず"},{"t":" is the classical way of denying identity.\n\nIt survives in mottoes and set phrases ("},{"r":"と","t":"人"},{"t":"にあらず"},{"t":") for the same reason "},{"t":"べからず"},{"t":" survives on signs. The modern "},{"t":"ではない"},{"t":" descends from the very same construction: its "},{"t":"で"},{"t":" is "},{"t":"にて"},{"t":" worn down, so the "},{"t":"に"},{"t":" never actually left."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- いつも / よく / ときどき / たまに: 偶 is a character
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-40c26575f5c1c0c8', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"いつも is the question word いつ swept by も into \"always\", the same も that makes 誰も into \"nobody\"; 何時 is only how it is spelled. たま is a native noun for something rare (dictionaries connect it to 玉) and 偶 is a character laid on it afterwards. 時々 is the repetition mark doing what it looks like.\n\nよく is the odd one out and the only transparent one: it is the adverbial form of 良い. That an adverb meaning \"well\" also means \"often\" is simply a sense the dictionaries list, not a route anyone can trace.","point":"いつも / よく / ときどき / たまに","before":[{"t":"いつも"},{"t":" is the question word "},{"t":"いつ"},{"t":" swept by "},{"t":"も"},{"t":" into \"always\", the same "},{"t":"も"},{"t":" that makes "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":" into \"nobody\"; "},{"t":"何","r":"なに"},{"t":"時","r":"とき"},{"t":" is only how it is spelled. "},{"t":"たま"},{"t":" is a native noun for something rare (dictionaries connect it to "},{"t":"玉","r":"たま"},{"t":") and "},{"t":"偶","r":"ぐう"},{"t":" is a character laid on it afterwards. "},{"t":"時々","r":"ときどき"},{"t":" is the repetition mark doing what it looks like.\n\n"},{"t":"よく"},{"t":" is the odd one out and the only transparent one: it is the adverbial form of "},{"t":"良","r":"よ"},{"t":"い"},{"t":". That an adverb meaning \"well\" also means \"often\" is simply a sense the dictionaries list, not a route anyone can trace."}],"after":[{"t":"いつも"},{"t":" is the question word "},{"t":"いつ"},{"t":" swept by "},{"t":"も"},{"t":" into \"always\", the same "},{"t":"も"},{"t":" that makes "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":" into \"nobody\"; "},{"t":"何","r":"なに"},{"t":"時","r":"とき"},{"t":" is only how it is spelled. "},{"t":"たま"},{"t":" is a native noun for something rare (dictionaries connect it to "},{"t":"玉","r":"たま"},{"t":") and "},{"t":"偶","r":"たま"},{"t":" is a character"},{"t":" laid on it afterwards. "},{"t":"時々","r":"ときどき"},{"t":" is the repetition mark doing what it looks like.\n\n"},{"t":"よく"},{"t":" is the odd one out and the only transparent one: it is the adverbial form of "},{"t":"良","r":"よ"},{"t":"い"},{"t":". That an adverb meaning \"well\" also means \"often\" is simply a sense the dictionaries list, not a route anyone can trace."}],"changes":[{"word":"偶 is a character","from":[{"t":"偶","r":"ぐう"},{"t":" is a character"}],"to":[{"t":"偶","r":"たま"},{"t":" is a character"}],"why":"Native reading discussed is たま."}]}'::jsonb, '{"furigana":[{"t":"いつも"},{"t":" is the question word "},{"t":"いつ"},{"t":" swept by "},{"t":"も"},{"t":" into \"always\", the same "},{"t":"も"},{"t":" that makes "},{"r":"だれ","t":"誰"},{"t":"も"},{"t":" into \"nobody\"; "},{"r":"なに","t":"何"},{"r":"とき","t":"時"},{"t":" is only how it is spelled. "},{"t":"たま"},{"t":" is a native noun for something rare (dictionaries connect it to "},{"r":"たま","t":"玉"},{"t":") and "},{"r":"ぐう","t":"偶"},{"t":" is a character laid on it afterwards. "},{"r":"ときどき","t":"時々"},{"t":" is the repetition mark doing what it looks like.\n\n"},{"t":"よく"},{"t":" is the odd one out and the only transparent one: it is the adverbial form of "},{"r":"よ","t":"良"},{"t":"い"},{"t":". That an adverb meaning \"well\" also means \"often\" is simply a sense the dictionaries list, not a route anyone can trace."}]}'::jsonb, 'ai', 900, 'pending'
