-- 〜うちに: 間に is neutral, and 間に are
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-3eeb129ff6016721', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The plain noun for an interior. 若いうちに is literally within the young part, and the sense of a window that will shut comes from the walls the noun implies.\n\nIt is why うちに and 間に are not interchangeable. 間に is neutral about the window ending; うちに says get it done before the inside runs out, and that urgency is the noun, not an idiom laid over it.","point":"〜うちに","before":[{"t":"The plain noun for an interior. "},{"t":"若","r":"わか"},{"t":"いうちに"},{"t":" is literally within the young part, and the sense of a window that will shut comes from the walls the noun implies.\n\nIt is why "},{"t":"うちに"},{"t":" and "},{"t":"間","r":"ま"},{"t":"に"},{"t":" are not interchangeable. "},{"t":"間","r":"ま"},{"t":"に"},{"t":" is neutral about the window ending; "},{"t":"うちに"},{"t":" says get it done before the inside runs out, and that urgency is the noun, not an idiom laid over it."}],"after":[{"t":"The plain noun for an interior. "},{"t":"若","r":"わか"},{"t":"いうちに"},{"t":" is literally within the young part, and the sense of a window that will shut comes from the walls the noun implies.\n\nIt is why "},{"t":"うちに"},{"t":" "},{"t":"and 間","r":"あいだ"},{"t":"に are"},{"t":" not interchangeable. "},{"t":"間","r":"あいだ"},{"t":"に is neutral"},{"t":" about the window ending; "},{"t":"うちに"},{"t":" says get it done before the inside runs out, and that urgency is the noun, not an idiom laid over it."}],"changes":[{"word":"間に is neutral","from":[{"t":"間","r":"ま"},{"t":"に"},{"t":" is neutral"}],"to":[{"t":"間","r":"あいだ"},{"t":"に is neutral"}],"why":"間に合わない is まにあわない and 一週間に is かん; narrowed to the あいだ uses"},{"word":"and 間に are","from":[{"t":"and "},{"t":"間","r":"ま"},{"t":"に"},{"t":" are"}],"to":[{"t":"and 間","r":"あいだ"},{"t":"に are"}],"why":"間に合わない is まにあわない and 一週間に is かん; narrowed to the あいだ uses"}]}'::jsonb, '{"furigana":[{"t":"The plain noun for an interior. "},{"r":"わか","t":"若"},{"t":"いうちに"},{"t":" is literally within the young part, and the sense of a window that will shut comes from the walls the noun implies.\n\nIt is why "},{"t":"うちに"},{"t":" and "},{"r":"ま","t":"間"},{"t":"に"},{"t":" are not interchangeable. "},{"r":"ま","t":"間"},{"t":"に"},{"t":" is neutral about the window ending; "},{"t":"うちに"},{"t":" says get it done before the inside runs out, and that urgency is the noun, not an idiom laid over it."}]}'::jsonb, 'ai', 900, 'pending'
