-- 〜おそれがある: 危険性
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-4e24cc7f2228a31f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A plain noun for something feared. 恐れがある is \"there exists a fear of it\", which is why the pattern only ever attaches to bad outcomes.\n\nIt is the stiff, official register (weather warnings, notices, reports), because naming a fear as a thing that exists is how documents talk. 危険性がある is its Sino-Japanese equivalent and behaves the same way.","point":"〜おそれがある","before":[{"t":"A plain noun for something feared. "},{"t":"恐","r":"おそ"},{"t":"れがある"},{"t":" is \"there exists a fear of it\", which is why the pattern only ever attaches to bad outcomes.\n\nIt is the stiff, official register (weather warnings, notices, reports), because naming a fear as a thing that exists is how documents talk. "},{"t":"危険","r":"きけん"},{"t":"性","r":"なりくせ"},{"t":"がある"},{"t":" is its Sino-Japanese equivalent and behaves the same way."}],"after":[{"t":"A plain noun for something feared. "},{"t":"恐","r":"おそ"},{"t":"れがある"},{"t":" is \"there exists a fear of it\", which is why the pattern only ever attaches to bad outcomes.\n\nIt is the stiff, official register (weather warnings, notices, reports), because naming a fear as a thing that exists is how documents talk. "},{"t":"危険性","r":"きけんせい"},{"t":"がある"},{"t":" is its Sino-Japanese equivalent and behaves the same way."}],"changes":[{"word":"危険性","from":[{"t":"危険","r":"きけん"},{"t":"性","r":"なりくせ"}],"to":[{"t":"危険性","r":"きけんせい"}],"why":"Compound is きけんせい. / 性 here is せい."}]}'::jsonb, '{"furigana":[{"t":"A plain noun for something feared. "},{"r":"おそ","t":"恐"},{"t":"れがある"},{"t":" is \"there exists a fear of it\", which is why the pattern only ever attaches to bad outcomes.\n\nIt is the stiff, official register (weather warnings, notices, reports), because naming a fear as a thing that exists is how documents talk. "},{"r":"きけん","t":"危険"},{"r":"なりくせ","t":"性"},{"t":"がある"},{"t":" is its Sino-Japanese equivalent and behaves the same way."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '4e24cc7f2228a31f2af152d77e6910d4fd22dfea33ae1ce99c78852c4af29866' AND l.code = 'ja'
  AND g.segments = '[{"t":"A plain noun for something feared. "},{"r":"おそ","t":"恐"},{"t":"れがある"},{"t":" is \"there exists a fear of it\", which is why the pattern only ever attaches to bad outcomes.\n\nIt is the stiff, official register (weather warnings, notices, reports), because naming a fear as a thing that exists is how documents talk. "},{"r":"きけん","t":"危険"},{"r":"なりくせ","t":"性"},{"t":"がある"},{"t":" is its Sino-Japanese equivalent and behaves the same way."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

