  AND g.segments = '[{"t":"かぎり"},{"t":" is "},{"r":"かぎ","t":"限"},{"t":"り"},{"t":", the "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" of "},{"r":"かぎ","t":"限"},{"t":"る"},{"t":": \"to set a boundary\"."}]'::jsonb
