-- 〜かぎり: 私が
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-da97698ab08d55b0', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A noun meaning the limit of something. 私が知るかぎり draws a line around what I know and speaks only inside it.\n\nThe pattern that looks like a different meaning is the same line seen from the other side: 生きているかぎり is for as long as the boundary holds. Extent and duration are one limit, measured in space or in time.","point":"〜かぎり","before":[{"t":"A noun meaning the limit of something. "},{"t":"私","r":"わちき"},{"t":"が"},{"t":"知","r":"し"},{"t":"るかぎり"},{"t":" draws a line around what I know and speaks only inside it.\n\nThe pattern that looks like a different meaning is the same line seen from the other side: "},{"t":"生","r":"い"},{"t":"きているかぎり"},{"t":" is for as long as the boundary holds. Extent and duration are one limit, measured in space or in time."}],"after":[{"t":"A noun meaning the limit of something. "},{"t":"私","r":"わたし"},{"t":"が"},{"t":"知","r":"し"},{"t":"るかぎり"},{"t":" draws a line around what I know and speaks only inside it.\n\nThe pattern that looks like a different meaning is the same line seen from the other side: "},{"t":"生","r":"い"},{"t":"きているかぎり"},{"t":" is for as long as the boundary holds. Extent and duration are one limit, measured in space or in time."}],"changes":[{"word":"私が","from":[{"t":"私","r":"わちき"},{"t":"が"}],"to":[{"t":"私","r":"わたし"},{"t":"が"}],"why":"私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"A noun meaning the limit of something. "},{"r":"わちき","t":"私"},{"t":"が"},{"r":"し","t":"知"},{"t":"るかぎり"},{"t":" draws a line around what I know and speaks only inside it.\n\nThe pattern that looks like a different meaning is the same line seen from the other side: "},{"r":"い","t":"生"},{"t":"きているかぎり"},{"t":" is for as long as the boundary holds. Extent and duration are one limit, measured in space or in time."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'da97698ab08d55b0d7177ffb97f8c7d791ee881ae2110313dedd1ab98bb3d6fb' AND l.code = 'ja'
  AND g.segments = '[{"t":"A noun meaning the limit of something. "},{"r":"わちき","t":"私"},{"t":"が"},{"r":"し","t":"知"},{"t":"るかぎり"},{"t":" draws a line around what I know and speaks only inside it.\n\nThe pattern that looks like a different meaning is the same line seen from the other side: "},{"r":"い","t":"生"},{"t":"きているかぎり"},{"t":" is for as long as the boundary holds. Extent and duration are one limit, measured in space or in time."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

