SELECT 'crq-grammar-08720404ad56c17f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A substitution. 代わりに puts one thing into the slot another would have filled.\n\nBoth textbook meanings are that one act. Replacement is 私の代わりに行く; exchange is 手伝う代わりに昼を奢って, where each side stands in for the other. Compensation is just substitution with something owed going the other way.","point":"〜かわりに","before":[{"t":"A substitution. "},{"t":"代","r":"か"},{"t":"わりに"},{"t":" puts one thing into the slot another would have filled.\n\nBoth textbook meanings are that one act. Replacement is "},{"t":"私","r":"わちき"},{"t":"の"},{"t":"代","r":"か"},{"t":"わりに"},{"t":"行","r":"い"},{"t":"く"},{"t":"; exchange is "},{"t":"手伝","r":"てつだ"},{"t":"う"},{"t":"代","r":"か"},{"t":"わりに"},{"t":"昼","r":"ひる"},{"t":"を奢って"},{"t":", where each side stands in for the other. Compensation is just substitution with something owed going the other way."}],"after":[{"t":"A substitution. "},{"t":"代","r":"か"},{"t":"わりに"},{"t":" puts one thing into the slot another would have filled.\n\nBoth textbook meanings are that one act. Replacement is "},{"t":"私","r":"わたし"},{"t":"の"},{"t":"代","r":"か"},{"t":"わりに"},{"t":"行","r":"い"},{"t":"く"},{"t":"; exchange is "},{"t":"手伝","r":"てつだ"},{"t":"う"},{"t":"代","r":"か"},{"t":"わりに"},{"t":"昼","r":"ひる"},{"t":"を奢って"},{"t":", where each side stands in for the other. Compensation is just substitution with something owed going the other way."}],"changes":[{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"t":"A substitution. "},{"r":"か","t":"代"},{"t":"わりに"},{"t":" puts one thing into the slot another would have filled.\n\nBoth textbook meanings are that one act. Replacement is "},{"r":"わちき","t":"私"},{"t":"の"},{"r":"か","t":"代"},{"t":"わりに"},{"r":"い","t":"行"},{"t":"く"},{"t":"; exchange is "},{"r":"てつだ","t":"手伝"},{"t":"う"},{"r":"か","t":"代"},{"t":"わりに"},{"r":"ひる","t":"昼"},{"t":"を奢って"},{"t":", where each side stands in for the other. Compensation is just substitution with something owed going the other way."}]}'::jsonb, 'ai', 900, 'pending'
