-- 〜きり: 縁を切る
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-9ff3e812027f270c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"一度きり is once and the line drawn there. The verb is the everyday one in 切符 and 縁を切る.\n\nBoth readings are that cut. 二人きり is only two because everyone else has been cut away; 出かけたきり帰らない is left after the cut with nothing following. The emphatic っきり is the same word.","point":"〜きり","before":[{"t":"一度","r":"いちど"},{"t":"きり"},{"t":" is once and the line drawn there. The verb is the everyday one in "},{"t":"切符","r":"きっぷ"},{"t":" and "},{"t":"縁","r":"ふち"},{"t":"を"},{"t":"切","r":"き"},{"t":"る"},{"t":".\n\nBoth readings are that cut. "},{"t":"二人","r":"ふたり"},{"t":"きり"},{"t":" is only two because everyone else has been cut away; "},{"t":"出","r":"で"},{"t":"かけたきり"},{"t":"帰","r":"かえ"},{"t":"らない"},{"t":" is left after the cut with nothing following. The emphatic "},{"t":"っきり"},{"t":" is the same word."}],"after":[{"t":"一度","r":"いちど"},{"t":"きり"},{"t":" is once and the line drawn there. The verb is the everyday one in "},{"t":"切符","r":"きっぷ"},{"t":" and "},{"t":"縁","r":"えん"},{"t":"を"},{"t":"切","r":"き"},{"t":"る"},{"t":".\n\nBoth readings are that cut. "},{"t":"二人","r":"ふたり"},{"t":"きり"},{"t":" is only two because everyone else has been cut away; "},{"t":"出","r":"で"},{"t":"かけたきり"},{"t":"帰","r":"かえ"},{"t":"らない"},{"t":" is left after the cut with nothing following. The emphatic "},{"t":"っきり"},{"t":" is the same word."}],"changes":[{"word":"縁を切る","from":[{"t":"縁","r":"ふち"},{"t":"を"},{"t":"切","r":"き"},{"t":"る"}],"to":[{"t":"縁","r":"えん"},{"t":"を"},{"t":"切","r":"き"},{"t":"る"}],"why":"縁を切る is えんをきる."}]}'::jsonb, '{"furigana":[{"r":"いちど","t":"一度"},{"t":"きり"},{"t":" is once and the line drawn there. The verb is the everyday one in "},{"r":"きっぷ","t":"切符"},{"t":" and "},{"r":"ふち","t":"縁"},{"t":"を"},{"r":"き","t":"切"},{"t":"る"},{"t":".\n\nBoth readings are that cut. "},{"r":"ふたり","t":"二人"},{"t":"きり"},{"t":" is only two because everyone else has been cut away; "},{"r":"で","t":"出"},{"t":"かけたきり"},{"r":"かえ","t":"帰"},{"t":"らない"},{"t":" is left after the cut with nothing following. The emphatic "},{"t":"っきり"},{"t":" is the same word."}]}'::jsonb, 'ai', 900, 'pending'
