WHERE g.text_hash = '9ff3e812027f270c29abb4f4311251c46d0c5946ce1006b0e09484152ecb7c6f' AND l.code = 'ja'
  AND g.segments = '[{"r":"いちど","t":"一度"},{"t":"きり"},{"t":" is once and the line drawn there. The verb is the everyday one in "},{"r":"きっぷ","t":"切符"},{"t":" and "},{"r":"ふち","t":"縁"},{"t":"を"},{"r":"き","t":"切"},{"t":"る"},{"t":".\n\nBoth readings are that cut. "},{"r":"ふたり","t":"二人"},{"t":"きり"},{"t":" is only two because everyone else has been cut away; "},{"r":"で","t":"出"},{"t":"かけたきり"},{"r":"かえ","t":"帰"},{"t":"らない"},{"t":" is left after the cut with nothing following. The emphatic "},{"t":"っきり"},{"t":" is the same word."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
