SELECT 'crq-grammar-079a3af3c0581a71', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The 位 of 一位 and 位置. Naming a grade rather than a figure is what makes 三時間ぐらい approximate.\n\nIt is the same word that grows into the belittling くらい at N3: 掃除くらいしなさい, ranking the chore that low. And it differs from ごろ, which is 頃, a point in time: ぐらい measures a quantity, ごろ locates a moment.","point":"〜ぐらい / 〜くらい","before":[{"t":"The "},{"t":"位","r":"くらい"},{"t":" of "},{"t":"一","r":"いっち"},{"t":"位","r":"くらい"},{"t":" and "},{"t":"位置","r":"いち"},{"t":". Naming a grade rather than a figure is what makes "},{"t":"三","r":"さん"},{"t":"時間","r":"じかん"},{"t":"ぐらい"},{"t":" approximate.\n\nIt is the same word that grows into the belittling "},{"t":"くらい"},{"t":" at N3: "},{"t":"掃除","r":"そうじ"},{"t":"くらいしなさい"},{"t":", ranking the chore that low. And it differs from "},{"t":"ごろ"},{"t":", which is "},{"t":"頃","r":"ごろ"},{"t":", a point in time: "},{"t":"ぐらい"},{"t":" measures a quantity, "},{"t":"ごろ"},{"t":" locates a moment."}],"after":[{"t":"The "},{"t":"位","r":"くらい"},{"t":" of "},{"t":"一位","r":"いちい"},{"t":" and "},{"t":"位置","r":"いち"},{"t":". Naming a grade rather than a figure is what makes "},{"t":"三","r":"さん"},{"t":"時間","r":"じかん"},{"t":"ぐらい"},{"t":" approximate.\n\nIt is the same word that grows into the belittling "},{"t":"くらい"},{"t":" at N3: "},{"t":"掃除","r":"そうじ"},{"t":"くらいしなさい"},{"t":", ranking the chore that low. And it differs from "},{"t":"ごろ"},{"t":", which is "},{"t":"頃","r":"ごろ"},{"t":", a point in time: "},{"t":"ぐらい"},{"t":" measures a quantity, "},{"t":"ごろ"},{"t":" locates a moment."}],"changes":[{"word":"一位","from":[{"t":"一","r":"いっち"},{"t":"位","r":"くらい"}],"to":[{"t":"一位","r":"いちい"}],"why":"First place is いちい."}]}'::jsonb, '{"furigana":[{"t":"The "},{"r":"くらい","t":"位"},{"t":" of "},{"r":"いっち","t":"一"},{"r":"くらい","t":"位"},{"t":" and "},{"r":"いち","t":"位置"},{"t":". Naming a grade rather than a figure is what makes "},{"r":"さん","t":"三"},{"r":"じかん","t":"時間"},{"t":"ぐらい"},{"t":" approximate.\n\nIt is the same word that grows into the belittling "},{"t":"くらい"},{"t":" at N3: "},{"r":"そうじ","t":"掃除"},{"t":"くらいしなさい"},{"t":", ranking the chore that low. And it differs from "},{"t":"ごろ"},{"t":", which is "},{"r":"ごろ","t":"頃"},{"t":", a point in time: "},{"t":"ぐらい"},{"t":" measures a quantity, "},{"t":"ごろ"},{"t":" locates a moment."}]}'::jsonb, 'ai', 900, 'pending'
