-- 〜けど (but): 已然形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-1799c2df2f334b97', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The chain is けれども → けれど → けど. けれ is the old 已然形 ending of adjectives, the one in 寒けれ, and ども is an Old Japanese concessive meaning \"even though\"; the pair formed at the end of the Muromachi period and spread to other predicates, with けれど and けど following in Edo.\n\nThe length of the form tracks its formality precisely: けれども is the whole thing, けど is what survives casual speech. That is not an arbitrary register scale; it is literally how much of the original phrase you bothered to say.","point":"〜けど (but)","before":[{"t":"The chain is "},{"t":"けれども"},{"t":" → "},{"t":"けれど"},{"t":" → "},{"t":"けど"},{"t":". "},{"t":"けれ"},{"t":" is the old "},{"t":"已然"},{"t":"形","r":"なり"},{"t":" ending of adjectives, the one in "},{"t":"寒","r":"さむ"},{"t":"けれ"},{"t":", and "},{"t":"ども"},{"t":" is an Old Japanese concessive meaning \"even though\"; the pair formed at the end of the Muromachi period and spread to other predicates, with "},{"t":"けれど"},{"t":" and "},{"t":"けど"},{"t":" following in Edo.\n\nThe length of the form tracks its formality precisely: "},{"t":"けれども"},{"t":" is the whole thing, "},{"t":"けど"},{"t":" is what survives casual speech. That is not an arbitrary register scale; it is literally how much of the original phrase you bothered to say."}],"after":[{"t":"The chain is "},{"t":"けれども"},{"t":" → "},{"t":"けれど"},{"t":" → "},{"t":"けど"},{"t":". "},{"t":"けれ"},{"t":" is the old "},{"t":"已然形","r":"いぜんけい"},{"t":" ending of adjectives, the one in "},{"t":"寒","r":"さむ"},{"t":"けれ"},{"t":", and "},{"t":"ども"},{"t":" is an Old Japanese concessive meaning \"even though\"; the pair formed at the end of the Muromachi period and spread to other predicates, with "},{"t":"けれど"},{"t":" and "},{"t":"けど"},{"t":" following in Edo.\n\nThe length of the form tracks its formality precisely: "},{"t":"けれども"},{"t":" is the whole thing, "},{"t":"けど"},{"t":" is what survives casual speech. That is not an arbitrary register scale; it is literally how much of the original phrase you bothered to say."}],"changes":[{"word":"已然形","from":[{"t":"已然"},{"t":"形","r":"なり"}],"to":[{"t":"已然形","r":"いぜんけい"}],"why":"Classical grammar term, いぜんけい."}]}'::jsonb, '{"furigana":[{"t":"The chain is "},{"t":"けれども"},{"t":" → "},{"t":"けれど"},{"t":" → "},{"t":"けど"},{"t":". "},{"t":"けれ"},{"t":" is the old "},{"t":"已然"},{"r":"なり","t":"形"},{"t":" ending of adjectives, the one in "},{"r":"さむ","t":"寒"},{"t":"けれ"},{"t":", and "},{"t":"ども"},{"t":" is an Old Japanese concessive meaning \"even though\"; the pair formed at the end of the Muromachi period and spread to other predicates, with "},{"t":"けれど"},{"t":" and "},{"t":"けど"},{"t":" following in Edo.\n\nThe length of the form tracks its formality precisely: "},{"t":"けれども"},{"t":" is the whole thing, "},{"t":"けど"},{"t":" is what survives casual speech. That is not an arbitrary register scale; it is literally how much of the original phrase you bothered to say."}]}'::jsonb, 'ai', 900, 'pending'
