-- 〜げ: 心細げ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d84e1e0d8d075185', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Whether that け is the Chinese loan 気 or a native noun the character was fitted to is not settled. What it does is not in doubt: it reports an appearance, and 悲しげ is a sad air about someone. The げ-adjectives are characteristic of Heian prose: うつくしげ, 心細げ.\n\nSo げ, 気味 and そう all describe outward signs, differing in register and reach. げ is literary and works on emotions; 気味 is a trace, usually unwelcome; そう is the plain spoken one. All three exist because Japanese will not let you assert another person''s feelings flatly.","point":"〜げ","before":[{"t":"Whether that "},{"t":"け"},{"t":" is the Chinese loan "},{"t":"気","r":"げ"},{"t":" or a native noun the character was fitted to is not settled. What it does is not in doubt: it reports an appearance, and "},{"t":"悲","r":"かな"},{"t":"しげ"},{"t":" is a sad air about someone. The "},{"t":"げ"},{"t":"-adjectives are characteristic of Heian prose: "},{"t":"うつくしげ"},{"t":", "},{"t":"心","r":"しん"},{"t":"細","r":"ささ"},{"t":"げ"},{"t":".\n\nSo "},{"t":"げ"},{"t":", "},{"t":"気味","r":"ぎみ"},{"t":" and "},{"t":"そう"},{"t":" all describe outward signs, differing in register and reach. "},{"t":"げ"},{"t":" is literary and works on emotions; "},{"t":"気味","r":"ぎみ"},{"t":" is a trace, usually unwelcome; "},{"t":"そう"},{"t":" is the plain spoken one. All three exist because Japanese will not let you assert another person''s feelings flatly."}],"after":[{"t":"Whether that "},{"t":"け"},{"t":" is the Chinese loan "},{"t":"気","r":"げ"},{"t":" or a native noun the character was fitted to is not settled. What it does is not in doubt: it reports an appearance, and "},{"t":"悲","r":"かな"},{"t":"しげ"},{"t":" is a sad air about someone. The "},{"t":"げ"},{"t":"-adjectives are characteristic of Heian prose: "},{"t":"うつくしげ"},{"t":", "},{"t":"心細","r":"こころぼそ"},{"t":"げ"},{"t":".\n\nSo "},{"t":"げ"},{"t":", "},{"t":"気味","r":"ぎみ"},{"t":" and "},{"t":"そう"},{"t":" all describe outward signs, differing in register and reach. "},{"t":"げ"},{"t":" is literary and works on emotions; "},{"t":"気味","r":"ぎみ"},{"t":" is a trace, usually unwelcome; "},{"t":"そう"},{"t":" is the plain spoken one. All three exist because Japanese will not let you assert another person''s feelings flatly."}],"changes":[{"word":"心細げ","from":[{"t":"心","r":"しん"},{"t":"細","r":"ささ"},{"t":"げ"}],"to":[{"t":"心細","r":"こころぼそ"},{"t":"げ"}],"why":"心細い is こころぼそい."}]}'::jsonb, '{"furigana":[{"t":"Whether that "},{"t":"け"},{"t":" is the Chinese loan "},{"r":"げ","t":"気"},{"t":" or a native noun the character was fitted to is not settled. What it does is not in doubt: it reports an appearance, and "},{"r":"かな","t":"悲"},{"t":"しげ"},{"t":" is a sad air about someone. The "},{"t":"げ"},{"t":"-adjectives are characteristic of Heian prose: "},{"t":"うつくしげ"},{"t":", "},{"r":"しん","t":"心"},{"r":"ささ","t":"細"},{"t":"げ"},{"t":".\n\nSo "},{"t":"げ"},{"t":", "},{"r":"ぎみ","t":"気味"},{"t":" and "},{"t":"そう"},{"t":" all describe outward signs, differing in register and reach. "},{"t":"げ"},{"t":" is literary and works on emotions; "},{"r":"ぎみ","t":"気味"},{"t":" is a trace, usually unwelcome; "},{"t":"そう"},{"t":" is the plain spoken one. All three exist because Japanese will not let you assert another person''s feelings flatly."}]}'::jsonb, 'ai', 900, 'pending'
