-- 〜てしまう: 仕舞う
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b816e8efa8b0f087', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The literal verb is still in use: 片付けて仕舞う, to tidy things away. It carries finishing and shutting in one action.\n\nBoth senses of the compound come straight out of that, and they are not two meanings but one. 食べてしまった is finished off completely; 忘れてしまった is regrettable, because a thing that has been put away and the shutters brought down is a thing you cannot get back at. The casual 〜ちゃう is a contraction of 〜てしまう, and 〜じゃう of 〜でしまう.","point":"〜てしまう","before":[{"t":"The literal verb is still in use: "},{"t":"片付","r":"かたづ"},{"t":"けて"},{"t":"仕","r":"つか"},{"t":"舞","r":"ま"},{"t":"う"},{"t":", to tidy things away. It carries finishing and shutting in one action.\n\nBoth senses of the compound come straight out of that, and they are not two meanings but one. "},{"t":"食","r":"た"},{"t":"べてしまった"},{"t":" is finished off completely; "},{"t":"忘","r":"わす"},{"t":"れてしまった"},{"t":" is regrettable, because a thing that has been put away and the shutters brought down is a thing you cannot get back at. The casual 〜"},{"t":"ちゃう"},{"t":" is a contraction of 〜"},{"t":"てしまう"},{"t":", and 〜"},{"t":"じゃう"},{"t":" of 〜"},{"t":"でしまう"},{"t":"."}],"after":[{"t":"The literal verb is still in use: "},{"t":"片付","r":"かたづ"},{"t":"けて"},{"t":"仕舞","r":"しま"},{"t":"う"},{"t":", to tidy things away. It carries finishing and shutting in one action.\n\nBoth senses of the compound come straight out of that, and they are not two meanings but one. "},{"t":"食","r":"た"},{"t":"べてしまった"},{"t":" is finished off completely; "},{"t":"忘","r":"わす"},{"t":"れてしまった"},{"t":" is regrettable, because a thing that has been put away and the shutters brought down is a thing you cannot get back at. The casual 〜"},{"t":"ちゃう"},{"t":" is a contraction of 〜"},{"t":"てしまう"},{"t":", and 〜"},{"t":"じゃう"},{"t":" of 〜"},{"t":"でしまう"},{"t":"."}],"changes":[{"word":"仕舞う","from":[{"t":"仕","r":"つか"},{"t":"舞","r":"ま"},{"t":"う"}],"to":[{"t":"仕舞","r":"しま"},{"t":"う"}],"why":"Compound verb is しまう."}]}'::jsonb, '{"furigana":[{"t":"The literal verb is still in use: "},{"r":"かたづ","t":"片付"},{"t":"けて"},{"r":"つか","t":"仕"},{"r":"ま","t":"舞"},{"t":"う"},{"t":", to tidy things away. It carries finishing and shutting in one action.\n\nBoth senses of the compound come straight out of that, and they are not two meanings but one. "},{"r":"た","t":"食"},{"t":"べてしまった"},{"t":" is finished off completely; "},{"r":"わす","t":"忘"},{"t":"れてしまった"},{"t":" is regrettable, because a thing that has been put away and the shutters brought down is a thing you cannot get back at. The casual 〜"},{"t":"ちゃう"},{"t":" is a contraction of 〜"},{"t":"てしまう"},{"t":", and 〜"},{"t":"じゃう"},{"t":" of 〜"},{"t":"でしまう"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
