-- 〜にすぎない: 過ぎる
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-2951248bee83dbcd', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same 過ぎる taught at N5 in 食べすぎる, where passing the proper point is a complaint. Negated it becomes a limit: this does not pass that point.\n\nSo にすぎない always belittles. 学生にすぎない is \"no more than a student\", and the dismissiveness is the verb refusing to let the thing exceed its bound.","point":"〜にすぎない","before":[{"t":"The same "},{"t":"過","r":"よ"},{"t":"ぎる"},{"t":" taught at N5 in "},{"t":"食","r":"た"},{"t":"べすぎる"},{"t":", where passing the proper point is a complaint. Negated it becomes a limit: this does not pass that point.\n\nSo "},{"t":"にすぎない"},{"t":" always belittles. "},{"t":"学生","r":"がくせい"},{"t":"にすぎない"},{"t":" is \"no more than a student\", and the dismissiveness is the verb refusing to let the thing exceed its bound."}],"after":[{"t":"The same "},{"t":"過","r":"す"},{"t":"ぎる"},{"t":" taught at N5 in "},{"t":"食","r":"た"},{"t":"べすぎる"},{"t":", where passing the proper point is a complaint. Negated it becomes a limit: this does not pass that point.\n\nSo "},{"t":"にすぎない"},{"t":" always belittles. "},{"t":"学生","r":"がくせい"},{"t":"にすぎない"},{"t":" is \"no more than a student\", and the dismissiveness is the verb refusing to let the thing exceed its bound."}],"changes":[{"word":"過ぎる","from":[{"t":"過","r":"よ"},{"t":"ぎる"}],"to":[{"t":"過","r":"す"},{"t":"ぎる"}],"why":"過ぎる is すぎる."}]}'::jsonb, '{"furigana":[{"t":"The same "},{"r":"よ","t":"過"},{"t":"ぎる"},{"t":" taught at N5 in "},{"r":"た","t":"食"},{"t":"べすぎる"},{"t":", where passing the proper point is a complaint. Negated it becomes a limit: this does not pass that point.\n\nSo "},{"t":"にすぎない"},{"t":" always belittles. "},{"r":"がくせい","t":"学生"},{"t":"にすぎない"},{"t":" is \"no more than a student\", and the dismissiveness is the verb refusing to let the thing exceed its bound."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '2951248bee83dbcd4821d5b6267b277a8c6078e5de87173c6aaedf8f629e6923' AND l.code = 'ja'
  AND g.segments = '[{"t":"The same "},{"r":"よ","t":"過"},{"t":"ぎる"},{"t":" taught at N5 in "},{"r":"た","t":"食"},{"t":"べすぎる"},{"t":", where passing the proper point is a complaint. Negated it becomes a limit: this does not pass that point.\n\nSo "},{"t":"にすぎない"},{"t":" always belittles. "},{"r":"がくせい","t":"学生"},{"t":"にすぎない"},{"t":" is \"no more than a student\", and the dismissiveness is the verb refusing to let the thing exceed its bound."}]'::jsonb
