-- 〜ずくめ: 三省堂
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-ba8149c3717bd906', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The kana is the clue. It is written ずくめ and not づくめ, which is itself a sign that lexicographers do not read it as a transparent 尽く; 三省堂国語辞典 derives it instead from 竦める, \"to bind tight\". Either way the sense is a thing filled out with one quality and no remainder.\n\nWhich is why it takes only a small set of nouns and describes a totality rather than a mess: 黒ずくめ, いいことずくめ, and 規則ずくめ (that last one showing the totality can oppress rather than please). だらけ is a scattering of something; ずくめ leaves no room for anything else.","point":"〜ずくめ","before":[{"t":"The kana is the clue. It is written "},{"t":"ずくめ"},{"t":" and not "},{"t":"づくめ"},{"t":", which is itself a sign that lexicographers do not read it as a transparent "},{"t":"尽","r":"つ"},{"t":"く"},{"t":"; "},{"t":"三","r":"さん"},{"t":"省","r":"はぶ"},{"t":"堂"},{"t":"国語","r":"こくご"},{"t":"辞典","r":"じてん"},{"t":" derives it instead from "},{"t":"竦める"},{"t":", \"to bind tight\". Either way the sense is a thing filled out with one quality and no remainder.\n\nWhich is why it takes only a small set of nouns and describes a totality rather than a mess: "},{"t":"黒","r":"くろ"},{"t":"ずくめ"},{"t":", "},{"t":"いいことずくめ"},{"t":", and "},{"t":"規則","r":"きそく"},{"t":"ずくめ"},{"t":" (that last one showing the totality can oppress rather than please). "},{"t":"だらけ"},{"t":" is a scattering of something; "},{"t":"ずくめ"},{"t":" leaves no room for anything else."}],"after":[{"t":"The kana is the clue. It is written "},{"t":"ずくめ"},{"t":" and not "},{"t":"づくめ"},{"t":", which is itself a sign that lexicographers do not read it as a transparent "},{"t":"尽","r":"つ"},{"t":"く"},{"t":"; "},{"t":"三省堂","r":"さんせいどう"},{"t":"国語","r":"こくご"},{"t":"辞典","r":"じてん"},{"t":" derives it instead from "},{"t":"竦める"},{"t":", \"to bind tight\". Either way the sense is a thing filled out with one quality and no remainder.\n\nWhich is why it takes only a small set of nouns and describes a totality rather than a mess: "},{"t":"黒","r":"くろ"},{"t":"ずくめ"},{"t":", "},{"t":"いいことずくめ"},{"t":", and "},{"t":"規則","r":"きそく"},{"t":"ずくめ"},{"t":" (that last one showing the totality can oppress rather than please). "},{"t":"だらけ"},{"t":" is a scattering of something; "},{"t":"ずくめ"},{"t":" leaves no room for anything else."}],"changes":[{"word":"三省堂","from":[{"t":"三","r":"さん"},{"t":"省","r":"はぶ"},{"t":"堂"}],"to":[{"t":"三省堂","r":"さんせいどう"}],"why":"Publisher is さんせいどう."}]}'::jsonb, '{"furigana":[{"t":"The kana is the clue. It is written "},{"t":"ずくめ"},{"t":" and not "},{"t":"づくめ"},{"t":", which is itself a sign that lexicographers do not read it as a transparent "},{"r":"つ","t":"尽"},{"t":"く"},{"t":"; "},{"r":"さん","t":"三"},{"r":"はぶ","t":"省"},{"t":"堂"},{"r":"こくご","t":"国語"},{"r":"じてん","t":"辞典"},{"t":" derives it instead from "},{"t":"竦める"},{"t":", \"to bind tight\". Either way the sense is a thing filled out with one quality and no remainder.\n\nWhich is why it takes only a small set of nouns and describes a totality rather than a mess: "},{"r":"くろ","t":"黒"},{"t":"ずくめ"},{"t":", "},{"t":"いいことずくめ"},{"t":", and "},{"r":"きそく","t":"規則"},{"t":"ずくめ"},{"t":" (that last one showing the totality can oppress rather than please). "},{"t":"だらけ"},{"t":" is a scattering of something; "},{"t":"ずくめ"},{"t":" leaves no room for anything else."}]}'::jsonb, 'ai', 900, 'pending'
