  AND g.segments = '[{"t":"The kana is the clue. It is written "},{"t":"ずくめ"},{"t":" and not "},{"t":"づくめ"},{"t":", which is itself a sign that lexicographers do not read it as a transparent "},{"r":"つ","t":"尽"},{"t":"く"},{"t":"; "},{"r":"さん","t":"三"},{"r":"はぶ","t":"省"},{"t":"堂"},{"r":"こくご","t":"国語"},{"r":"じてん","t":"辞典"},{"t":" derives it instead from "},{"t":"竦める"},{"t":", \"to bind tight\". Either way the sense is a thing filled out with one quality and no remainder.\n\nWhich is why it takes only a small set of nouns and describes a totality rather than a mess: "},{"r":"くろ","t":"黒"},{"t":"ずくめ"},{"t":", "},{"t":"いいことずくめ"},{"t":", and "},{"r":"きそく","t":"規則"},{"t":"ずくめ"},{"t":" (that last one showing the totality can oppress rather than please). "},{"t":"だらけ"},{"t":" is a scattering of something; "},{"t":"ずくめ"},{"t":" leaves no room for anything else."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜そうもない: 降りそう
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-f9b57a04c91d4791', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The そう that attaches to a stem and reports how something looks, with も adding \"even\" and ない denying it. 雨が降りそうもない says it does not even have the appearance.\n\nThe も is what makes it stronger than そうではない. Denying that something even looks likely rules it out further than denying that it is.","point":"〜そうもない","before":[{"t":"The "},{"t":"そう"},{"t":" that attaches to a stem and reports how something looks, with "},{"t":"も"},{"t":" adding \"even\" and "},{"t":"ない"},{"t":" denying it. "},{"t":"雨","r":"あめ"},{"t":"が"},{"t":"降","r":"お"},{"t":"りそうもない"},{"t":" says it does not even have the appearance.\n\nThe "},{"t":"も"},{"t":" is what makes it stronger than "},{"t":"そうではない"},{"t":". Denying that something even looks likely rules it out further than denying that it is."}],"after":[{"t":"The "},{"t":"そう"},{"t":" that attaches to a stem and reports how something looks, with "},{"t":"も"},{"t":" adding \"even\" and "},{"t":"ない"},{"t":" denying it. "},{"t":"雨","r":"あめ"},{"t":"が"},{"t":"降","r":"ふ"},{"t":"りそう"},{"t":"もない"},{"t":" says it does not even have the appearance.\n\nThe "},{"t":"も"},{"t":" is what makes it stronger than "},{"t":"そうではない"},{"t":". Denying that something even looks likely rules it out further than denying that it is."}],"changes":[{"word":"降りそう","from":[{"t":"降","r":"お"},{"t":"りそう"}],"to":[{"t":"降","r":"ふ"},{"t":"りそう"}],"why":"雨が降る is ふる."}]}'::jsonb, '{"furigana":[{"t":"The "},{"t":"そう"},{"t":" that attaches to a stem and reports how something looks, with "},{"t":"も"},{"t":" adding \"even\" and "},{"t":"ない"},{"t":" denying it. "},{"r":"あめ","t":"雨"},{"t":"が"},{"r":"お","t":"降"},{"t":"りそうもない"},{"t":" says it does not even have the appearance.\n\nThe "},{"t":"も"},{"t":" is what makes it stronger than "},{"t":"そうではない"},{"t":". Denying that something even looks likely rules it out further than denying that it is."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'f9b57a04c91d4791045f817433bbc11855268d37d14d756d0b4672c4967bcb61' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"t":"そう"},{"t":" that attaches to a stem and reports how something looks, with "},{"t":"も"},{"t":" adding \"even\" and "},{"t":"ない"},{"t":" denying it. "},{"r":"あめ","t":"雨"},{"t":"が"},{"r":"お","t":"降"},{"t":"りそうもない"},{"t":" says it does not even have the appearance.\n\nThe "},{"t":"も"},{"t":" is what makes it stronger than "},{"t":"そうではない"},{"t":". Denying that something even looks likely rules it out further than denying that it is."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

