SELECT 'crq-grammar-5d5934d78fa7cdc5', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Nearly the same word as 基づく, used differently. をもとに supplies raw material: 実話をもとにした映画 is a film made out of a true story.\n\nThat is the distinction from に基づいて, which supplies authority. A film is built from the story and free to change it; a decision 基づいて the rules is bound by them. Material against grounds.","point":"〜をもとに","before":[{"t":"Nearly the same word as "},{"t":"基","r":"もと"},{"t":"づく"},{"t":", used differently. "},{"t":"をもとに"},{"t":" supplies raw material: "},{"t":"実","r":"み"},{"t":"話","r":"わ"},{"t":"をもとにした"},{"t":"映画","r":"えいが"},{"t":" is a film made out of a true story.\n\nThat is the distinction from "},{"t":"に"},{"t":"基","r":"もと"},{"t":"づいて"},{"t":", which supplies authority. A film is built from the story and free to change it; a decision "},{"t":"基","r":"もと"},{"t":"づいて"},{"t":" the rules is bound by them. Material against grounds."}],"after":[{"t":"Nearly the same word as "},{"t":"基","r":"もと"},{"t":"づく"},{"t":", used differently. "},{"t":"をもとに"},{"t":" supplies raw material: "},{"t":"実話","r":"じつわ"},{"t":"をもとにした"},{"t":"映画","r":"えいが"},{"t":" is a film made out of a true story.\n\nThat is the distinction from "},{"t":"に"},{"t":"基","r":"もと"},{"t":"づいて"},{"t":", which supplies authority. A film is built from the story and free to change it; a decision "},{"t":"基","r":"もと"},{"t":"づいて"},{"t":" the rules is bound by them. Material against grounds."}],"changes":[{"word":"実話","from":[{"t":"実","r":"み"},{"t":"話","r":"わ"}],"to":[{"t":"実話","r":"じつわ"}],"why":"実話 is じつわ."}]}'::jsonb, '{"furigana":[{"t":"Nearly the same word as "},{"r":"もと","t":"基"},{"t":"づく"},{"t":", used differently. "},{"t":"をもとに"},{"t":" supplies raw material: "},{"r":"み","t":"実"},{"r":"わ","t":"話"},{"t":"をもとにした"},{"r":"えいが","t":"映画"},{"t":" is a film made out of a true story.\n\nThat is the distinction from "},{"t":"に"},{"r":"もと","t":"基"},{"t":"づいて"},{"t":", which supplies authority. A film is built from the story and free to change it; a decision "},{"r":"もと","t":"基"},{"t":"づいて"},{"t":" the rules is bound by them. Material against grounds."}]}'::jsonb, 'ai', 900, 'pending'
