-- 〜ものだ: 人は死ぬ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-53074140e2761b3e', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"若い頃はよく遊んだものだ and 人は死ぬものだ look unrelated until you read もの literally. Both say \"that is a thing\": the second about how the world reliably is, the first about how life reliably was.\n\nGenerality is the common element, and it is why ものだ cannot be used for a single occurrence. 昨日遊んだものだ is wrong: one afternoon is an event, not a thing that holds.","point":"〜ものだ","before":[{"t":"若","r":"わか"},{"t":"い"},{"t":"頃","r":"ごろ"},{"t":"はよく"},{"t":"遊","r":"あそ"},{"t":"んだものだ"},{"t":" and "},{"t":"人","r":"と"},{"t":"は"},{"t":"死","r":"し"},{"t":"ぬものだ"},{"t":" look unrelated until you read "},{"t":"もの"},{"t":" literally. Both say \"that is a thing\": the second about how the world reliably is, the first about how life reliably was.\n\nGenerality is the common element, and it is why "},{"t":"ものだ"},{"t":" cannot be used for a single occurrence. "},{"t":"昨日","r":"きのう"},{"t":"遊","r":"あそ"},{"t":"んだものだ"},{"t":" is wrong: one afternoon is an event, not a thing that holds."}],"after":[{"t":"若","r":"わか"},{"t":"い"},{"t":"頃","r":"ごろ"},{"t":"はよく"},{"t":"遊","r":"あそ"},{"t":"んだものだ"},{"t":" and "},{"t":"人","r":"ひと"},{"t":"は"},{"t":"死","r":"し"},{"t":"ぬ"},{"t":"ものだ"},{"t":" look unrelated until you read "},{"t":"もの"},{"t":" literally. Both say \"that is a thing\": the second about how the world reliably is, the first about how life reliably was.\n\nGenerality is the common element, and it is why "},{"t":"ものだ"},{"t":" cannot be used for a single occurrence. "},{"t":"昨日","r":"きのう"},{"t":"遊","r":"あそ"},{"t":"んだものだ"},{"t":" is wrong: one afternoon is an event, not a thing that holds."}],"changes":[{"word":"人は死ぬ","from":[{"t":"人","r":"と"},{"t":"は"},{"t":"死","r":"し"},{"t":"ぬ"}],"to":[{"t":"人","r":"ひと"},{"t":"は"},{"t":"死","r":"し"},{"t":"ぬ"}],"why":"Person is ひと."}]}'::jsonb, '{"furigana":[{"r":"わか","t":"若"},{"t":"い"},{"r":"ごろ","t":"頃"},{"t":"はよく"},{"r":"あそ","t":"遊"},{"t":"んだものだ"},{"t":" and "},{"r":"と","t":"人"},{"t":"は"},{"r":"し","t":"死"},{"t":"ぬものだ"},{"t":" look unrelated until you read "},{"t":"もの"},{"t":" literally. Both say \"that is a thing\": the second about how the world reliably is, the first about how life reliably was.\n\nGenerality is the common element, and it is why "},{"t":"ものだ"},{"t":" cannot be used for a single occurrence. "},{"r":"きのう","t":"昨日"},{"r":"あそ","t":"遊"},{"t":"んだものだ"},{"t":" is wrong: one afternoon is an event, not a thing that holds."}]}'::jsonb, 'ai', 900, 'pending'
