-- 〜たい: 好き
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d28230c7c85d88f1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"たい continues the Old Japanese auxiliary adjective たし. It was an adjective from the start, so 食べたい is grammatically an adjective phrase, not a verb.\n\nThat is the whole explanation for its behaviour: たかった, たくない and たければ are ordinary i-adjective forms, and the が-marked object appears because adjectives take が for what they are about, the same reason 水が好き uses が.","point":"〜たい","before":[{"t":"たい"},{"t":" continues the Old Japanese auxiliary adjective "},{"t":"たし"},{"t":". It was an adjective from the start, so "},{"t":"食","r":"た"},{"t":"べたい"},{"t":" is grammatically an adjective phrase, not a verb.\n\nThat is the whole explanation for its behaviour: "},{"t":"たかった"},{"t":", "},{"t":"たくない"},{"t":" and "},{"t":"たければ"},{"t":" are ordinary i-adjective forms, and the "},{"t":"が"},{"t":"-marked object appears because adjectives take "},{"t":"が"},{"t":" for what they are about, the same reason "},{"t":"水","r":"みず"},{"t":"が"},{"t":"好","r":"ず"},{"t":"き"},{"t":" uses "},{"t":"が"},{"t":"."}],"after":[{"t":"たい"},{"t":" continues the Old Japanese auxiliary adjective "},{"t":"たし"},{"t":". It was an adjective from the start, so "},{"t":"食","r":"た"},{"t":"べたい"},{"t":" is grammatically an adjective phrase, not a verb.\n\nThat is the whole explanation for its behaviour: "},{"t":"たかった"},{"t":", "},{"t":"たくない"},{"t":" and "},{"t":"たければ"},{"t":" are ordinary i-adjective forms, and the "},{"t":"が"},{"t":"-marked object appears because adjectives take "},{"t":"が"},{"t":" for what they are about, the same reason "},{"t":"水","r":"みず"},{"t":"が"},{"t":"好","r":"す"},{"t":"き"},{"t":" uses "},{"t":"が"},{"t":"."}],"changes":[{"word":"好き","from":[{"t":"好","r":"ず"},{"t":"き"}],"to":[{"t":"好","r":"す"},{"t":"き"}],"why":"Like is すき. / 好き is すき."}]}'::jsonb, '{"furigana":[{"t":"たい"},{"t":" continues the Old Japanese auxiliary adjective "},{"t":"たし"},{"t":". It was an adjective from the start, so "},{"r":"た","t":"食"},{"t":"べたい"},{"t":" is grammatically an adjective phrase, not a verb.\n\nThat is the whole explanation for its behaviour: "},{"t":"たかった"},{"t":", "},{"t":"たくない"},{"t":" and "},{"t":"たければ"},{"t":" are ordinary i-adjective forms, and the "},{"t":"が"},{"t":"-marked object appears because adjectives take "},{"t":"が"},{"t":" for what they are about, the same reason "},{"r":"みず","t":"水"},{"t":"が"},{"r":"ず","t":"好"},{"t":"き"},{"t":" uses "},{"t":"が"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
