-- 〜たところで: 今から謝, 所
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-579fca23240e2c4a', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"所 locates a moment. The past tense puts it after the act, and で marks it as where matters stand.\n\nSo 謝ったところで許されない pictures the apology as already made inside a supposition: even granting it done, nothing follows. The た is perfective inside an irrealis rather than a report of something that happened, which is why 今から謝ったところで works. What comes after must be negative in import, though 無駄だ and 同じことだ serve as well as ない.","point":"〜たところで","before":[{"t":"所","r":"しょ"},{"t":" locates a moment. The past tense puts it after the act, and "},{"t":"で"},{"t":" marks it as where matters stand.\n\nSo "},{"t":"謝","r":"あやま"},{"t":"ったところで"},{"t":"許","r":"ゆる"},{"t":"されない"},{"t":" pictures the apology as already made inside a supposition: even granting it done, nothing follows. The "},{"t":"た"},{"t":" is perfective inside an irrealis rather than a report of something that happened, which is why "},{"t":"今","r":"こん"},{"t":"から"},{"t":"謝","r":"あやま"},{"t":"ったところで"},{"t":" works. What comes after must be negative in import, though "},{"t":"無駄","r":"むだ"},{"t":"だ"},{"t":" and "},{"t":"同","r":"おな"},{"t":"じことだ"},{"t":" serve as well as "},{"t":"ない"},{"t":"."}],"after":[{"t":"所","r":"ところ"},{"t":" locates a moment. The past tense puts it after the act, and "},{"t":"で"},{"t":" marks it as where matters stand.\n\nSo "},{"t":"謝","r":"あやま"},{"t":"ったところで"},{"t":"許","r":"ゆる"},{"t":"されない"},{"t":" pictures the apology as already made inside a supposition: even granting it done, nothing follows. The "},{"t":"た"},{"t":" is perfective inside an irrealis rather than a report of something that happened, which is why "},{"t":"今","r":"いま"},{"t":"から"},{"t":"謝","r":"あやま"},{"t":"ったところで"},{"t":" works. What comes after must be negative in import, though "},{"t":"無駄","r":"むだ"},{"t":"だ"},{"t":" and "},{"t":"同","r":"おな"},{"t":"じことだ"},{"t":" serve as well as "},{"t":"ない"},{"t":"."}],"changes":[{"word":"今から謝","from":[{"t":"今","r":"こん"},{"t":"から"},{"t":"謝","r":"あやま"}],"to":[{"t":"今","r":"いま"},{"t":"から"},{"t":"謝","r":"あやま"}],"why":"FINAL dropped the reading on 謝"},{"word":"所","from":[{"t":"所","r":"しょ"}],"to":[{"t":"所","r":"ところ"}],"why":"The noun meaning place is ところ here."}]}'::jsonb, '{"furigana":[{"r":"しょ","t":"所"},{"t":" locates a moment. The past tense puts it after the act, and "},{"t":"で"},{"t":" marks it as where matters stand.\n\nSo "},{"r":"あやま","t":"謝"},{"t":"ったところで"},{"r":"ゆる","t":"許"},{"t":"されない"},{"t":" pictures the apology as already made inside a supposition: even granting it done, nothing follows. The "},{"t":"た"},{"t":" is perfective inside an irrealis rather than a report of something that happened, which is why "},{"r":"こん","t":"今"},{"t":"から"},{"r":"あやま","t":"謝"},{"t":"ったところで"},{"t":" works. What comes after must be negative in import, though "},{"r":"むだ","t":"無駄"},{"t":"だ"},{"t":" and "},{"r":"おな","t":"同"},{"t":"じことだ"},{"t":" serve as well as "},{"t":"ない"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '579fca23240e2c4ae5c3f58a63d58e794aca4357211fa8cc13f6cf47fbf7247a' AND l.code = 'ja'
  AND g.segments = '[{"r":"しょ","t":"所"},{"t":" locates a moment. The past tense puts it after the act, and "},{"t":"で"},{"t":" marks it as where matters stand.\n\nSo "},{"r":"あやま","t":"謝"},{"t":"ったところで"},{"r":"ゆる","t":"許"},{"t":"されない"},{"t":" pictures the apology as already made inside a supposition: even granting it done, nothing follows. The "},{"t":"た"},{"t":" is perfective inside an irrealis rather than a report of something that happened, which is why "},{"r":"こん","t":"今"},{"t":"から"},{"r":"あやま","t":"謝"},{"t":"ったところで"},{"t":" works. What comes after must be negative in import, though "},{"r":"むだ","t":"無駄"},{"t":"だ"},{"t":" and "},{"r":"おな","t":"同"},{"t":"じことだ"},{"t":" serve as well as "},{"t":"ない"},{"t":"."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
