-- 〜てたまらない: 堪る
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-fd9ae787f6296f13', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"堪る is an ordinary verb of enduring, close kin to 耐える. 暑くてたまらない is heat that cannot be borne.\n\nBecause the verb is about the speaker''s own endurance, the pattern only works on your own sensations and feelings. Another person''s unbearable heat needs たまらないらしい or 暑がっている, the same restriction that gives がる its job at N4.","point":"〜てたまらない","before":[{"t":"堪","r":"こら"},{"t":"る"},{"t":" is an ordinary verb of enduring, close kin to "},{"t":"耐","r":"た"},{"t":"える"},{"t":". "},{"t":"暑","r":"あつ"},{"t":"くてたまらない"},{"t":" is heat that cannot be borne.\n\nBecause the verb is about the speaker''s own endurance, the pattern only works on your own sensations and feelings. Another person''s unbearable heat needs "},{"t":"たまらないらしい"},{"t":" or "},{"t":"暑","r":"あつ"},{"t":"がっている"},{"t":", the same restriction that gives "},{"t":"がる"},{"t":" its job at N4."}],"after":[{"t":"堪","r":"たま"},{"t":"る"},{"t":" is an ordinary verb of enduring, close kin to "},{"t":"耐","r":"た"},{"t":"える"},{"t":". "},{"t":"暑","r":"あつ"},{"t":"くてたまらない"},{"t":" is heat that cannot be borne.\n\nBecause the verb is about the speaker''s own endurance, the pattern only works on your own sensations and feelings. Another person''s unbearable heat needs "},{"t":"たまらないらしい"},{"t":" or "},{"t":"暑","r":"あつ"},{"t":"がっている"},{"t":", the same restriction that gives "},{"t":"がる"},{"t":" its job at N4."}],"changes":[{"word":"堪る","from":[{"t":"堪","r":"こら"},{"t":"る"}],"to":[{"t":"堪","r":"たま"},{"t":"る"}],"why":"堪る is たまる."}]}'::jsonb, '{"furigana":[{"r":"こら","t":"堪"},{"t":"る"},{"t":" is an ordinary verb of enduring, close kin to "},{"r":"た","t":"耐"},{"t":"える"},{"t":". "},{"r":"あつ","t":"暑"},{"t":"くてたまらない"},{"t":" is heat that cannot be borne.\n\nBecause the verb is about the speaker''s own endurance, the pattern only works on your own sensations and feelings. Another person''s unbearable heat needs "},{"t":"たまらないらしい"},{"t":" or "},{"r":"あつ","t":"暑"},{"t":"がっている"},{"t":", the same restriction that gives "},{"t":"がる"},{"t":" its job at N4."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'fd9ae787f6296f1330e3721c0ca5f1ed7d06efc6fd01d02769759324d72cebd1' AND l.code = 'ja'
  AND g.segments = '[{"r":"こら","t":"堪"},{"t":"る"},{"t":" is an ordinary verb of enduring, close kin to "},{"r":"た","t":"耐"},{"t":"える"},{"t":". "},{"r":"あつ","t":"暑"},{"t":"くてたまらない"},{"t":" is heat that cannot be borne.\n\nBecause the verb is about the speaker''s own endurance, the pattern only works on your own sensations and feelings. Another person''s unbearable heat needs "},{"t":"たまらないらしい"},{"t":" or "},{"r":"あつ","t":"暑"},{"t":"がっている"},{"t":", the same restriction that gives "},{"t":"がる"},{"t":" its job at N4."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
