-- 〜たりとも: 一円
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-29690fad2cde1056', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Classical たり asserted identity, as なり did. とも is the concessive \"even if\". 一円たりとも is \"even were it one yen\".\n\nThat is why the pattern demands a number and a negative afterwards: it concedes the smallest possible case and then refuses even that. 一日たりとも忘れない.","point":"〜たりとも","before":[{"t":"Classical "},{"t":"たり"},{"t":" asserted identity, as "},{"t":"なり"},{"t":" did. "},{"t":"とも"},{"t":" is the concessive \"even if\". "},{"t":"一","r":"いっち"},{"t":"円","r":"えん"},{"t":"たりとも"},{"t":" is \"even were it one yen\".\n\nThat is why the pattern demands a number and a negative afterwards: it concedes the smallest possible case and then refuses even that. "},{"t":"一日","r":"いちにち"},{"t":"たりとも"},{"t":"忘","r":"わす"},{"t":"れない"},{"t":"."}],"after":[{"t":"Classical "},{"t":"たり"},{"t":" asserted identity, as "},{"t":"なり"},{"t":" did. "},{"t":"とも"},{"t":" is the concessive \"even if\". "},{"t":"一円","r":"いちえん"},{"t":"たりとも"},{"t":" is \"even were it one yen\".\n\nThat is why the pattern demands a number and a negative afterwards: it concedes the smallest possible case and then refuses even that. "},{"t":"一日","r":"いちにち"},{"t":"たりとも"},{"t":"忘","r":"わす"},{"t":"れない"},{"t":"."}],"changes":[{"word":"一円","from":[{"t":"一","r":"いっち"},{"t":"円","r":"えん"}],"to":[{"t":"一円","r":"いちえん"}],"why":"One yen is いちえん."}]}'::jsonb, '{"furigana":[{"t":"Classical "},{"t":"たり"},{"t":" asserted identity, as "},{"t":"なり"},{"t":" did. "},{"t":"とも"},{"t":" is the concessive \"even if\". "},{"r":"いっち","t":"一"},{"r":"えん","t":"円"},{"t":"たりとも"},{"t":" is \"even were it one yen\".\n\nThat is why the pattern demands a number and a negative afterwards: it concedes the smallest possible case and then refuses even that. "},{"r":"いちにち","t":"一日"},{"t":"たりとも"},{"r":"わす","t":"忘"},{"t":"れない"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '29690fad2cde105640939a9c016e1355d583ada9864e58322283005e7110851a' AND l.code = 'ja'
  AND g.segments = '[{"t":"Classical "},{"t":"たり"},{"t":" asserted identity, as "},{"t":"なり"},{"t":" did. "},{"t":"とも"},{"t":" is the concessive \"even if\". "},{"r":"いっち","t":"一"},{"r":"えん","t":"円"},{"t":"たりとも"},{"t":" is \"even were it one yen\".\n\nThat is why the pattern demands a number and a negative afterwards: it concedes the smallest possible case and then refuses even that. "},{"r":"いちにち","t":"一日"},{"t":"たりとも"},{"r":"わす","t":"忘"},{"t":"れない"},{"t":"."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

