SELECT 'crq-grammar-03fb0e1809ff5c55', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ばかり is 計り, from 計る, \"to measure\": an amount, narrowed to \"that amount and no more\". With a te-form and いる it measures the whole of someone''s activity as one thing.\n\n遊んでばかりいる is nothing but playing, and the いる matters; it makes it a state they are in rather than an act they performed, which is where the disapproval sits.","point":"〜てばかりいる","before":[{"t":"ばかり"},{"t":" is "},{"t":"計","r":"けい"},{"t":"り"},{"t":", from "},{"t":"計","r":"はか"},{"t":"る"},{"t":", \"to measure\": an amount, narrowed to \"that amount and no more\". With a te-form and "},{"t":"いる"},{"t":" it measures the whole of someone''s activity as one thing.\n\n"},{"t":"遊","r":"あそ"},{"t":"んでばかりいる"},{"t":" is nothing but playing, and the "},{"t":"いる"},{"t":" matters; it makes it a state they are in rather than an act they performed, which is where the disapproval sits."}],"after":[{"t":"ばかり"},{"t":" is "},{"t":"計","r":"ばか"},{"t":"り"},{"t":", from "},{"t":"計","r":"はか"},{"t":"る"},{"t":", \"to measure\": an amount, narrowed to \"that amount and no more\". With a te-form and "},{"t":"いる"},{"t":" it measures the whole of someone''s activity as one thing.\n\n"},{"t":"遊","r":"あそ"},{"t":"んでばかりいる"},{"t":" is nothing but playing, and the "},{"t":"いる"},{"t":" matters; it makes it a state they are in rather than an act they performed, which is where the disapproval sits."}],"changes":[{"word":"計り","from":[{"t":"計","r":"けい"},{"t":"り"}],"to":[{"t":"計","r":"ばか"},{"t":"り"}],"why":"The particle spelled this way is ばかり."}]}'::jsonb, '{"furigana":[{"t":"ばかり"},{"t":" is "},{"r":"けい","t":"計"},{"t":"り"},{"t":", from "},{"r":"はか","t":"計"},{"t":"る"},{"t":", \"to measure\": an amount, narrowed to \"that amount and no more\". With a te-form and "},{"t":"いる"},{"t":" it measures the whole of someone''s activity as one thing.\n\n"},{"r":"あそ","t":"遊"},{"t":"んでばかりいる"},{"t":" is nothing but playing, and the "},{"t":"いる"},{"t":" matters; it makes it a state they are in rather than an act they performed, which is where the disapproval sits."}]}'::jsonb, 'ai', 900, 'pending'
