WHERE g.text_hash = '03fb0e1809ff5c55acbd216acb4000cef688c1bcd27db2e21bfb091307685a91' AND l.code = 'ja'
  AND g.segments = '[{"t":"ばかり"},{"t":" is "},{"r":"けい","t":"計"},{"t":"り"},{"t":", from "},{"r":"はか","t":"計"},{"t":"る"},{"t":", \"to measure\": an amount, narrowed to \"that amount and no more\". With a te-form and "},{"t":"いる"},{"t":" it measures the whole of someone''s activity as one thing.\n\n"},{"r":"あそ","t":"遊"},{"t":"んでばかりいる"},{"t":" is nothing but playing, and the "},{"t":"いる"},{"t":" matters; it makes it a state they are in rather than an act they performed, which is where the disapproval sits."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜までだ: 断られた
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-126d7da840f4d75e', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"まで marks a limit. 断られたら諦めるまでだ says the giving up is where the matter stops, with nothing further to it.\n\nThe flatness is the particle. It is not resolve or defiance but a boundary drawn: that is as far as this goes. までのことだ is the same thing with こと inserted to make it a stated matter.","point":"〜までだ","before":[{"t":"まで"},{"t":" marks a limit. "},{"t":"断","r":"た"},{"t":"られたら"},{"t":"諦","r":"あきら"},{"t":"めるまでだ"},{"t":" says the giving up is where the matter stops, with nothing further to it.\n\nThe flatness is the particle. It is not resolve or defiance but a boundary drawn: that is as far as this goes. "},{"t":"までのことだ"},{"t":" is the same thing with "},{"t":"こと"},{"t":" inserted to make it a stated matter."}],"after":[{"t":"まで"},{"t":" marks a limit. "},{"t":"断","r":"ことわ"},{"t":"られた"},{"t":"ら"},{"t":"諦","r":"あきら"},{"t":"めるまでだ"},{"t":" says the giving up is where the matter stops, with nothing further to it.\n\nThe flatness is the particle. It is not resolve or defiance but a boundary drawn: that is as far as this goes. "},{"t":"までのことだ"},{"t":" is the same thing with "},{"t":"こと"},{"t":" inserted to make it a stated matter."}],"changes":[{"word":"断られた","from":[{"t":"断","r":"た"},{"t":"られた"}],"to":[{"t":"断","r":"ことわ"},{"t":"られた"}],"why":"Refuse is ことわる."}]}'::jsonb, '{"furigana":[{"t":"まで"},{"t":" marks a limit. "},{"r":"た","t":"断"},{"t":"られたら"},{"r":"あきら","t":"諦"},{"t":"めるまでだ"},{"t":" says the giving up is where the matter stops, with nothing further to it.\n\nThe flatness is the particle. It is not resolve or defiance but a boundary drawn: that is as far as this goes. "},{"t":"までのことだ"},{"t":" is the same thing with "},{"t":"こと"},{"t":" inserted to make it a stated matter."}]}'::jsonb, 'ai', 900, 'pending'
