-- 〜であれ: 大人であれ
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-5d5263f15b5480e1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"あれ is the classical imperative of あり. Telling a hypothetical to be whatever it likes is a way of saying it changes nothing.\n\n子供であれ大人であれ: be it a child, be it an adult. English does the same with \"be it\", a fossil imperative in both languages, doing concession rather than command.","point":"〜であれ","before":[{"t":"あれ"},{"t":" is the classical imperative of "},{"t":"あり"},{"t":". Telling a hypothetical to be whatever it likes is a way of saying it changes nothing.\n\n"},{"t":"子供","r":"こども"},{"t":"であれ"},{"t":"大人","r":"うし"},{"t":"であれ"},{"t":": be it a child, be it an adult. English does the same with \"be it\", a fossil imperative in both languages, doing concession rather than command."}],"after":[{"t":"あれ"},{"t":" is the classical imperative of "},{"t":"あり"},{"t":". Telling a hypothetical to be whatever it likes is a way of saying it changes nothing.\n\n"},{"t":"子供","r":"こども"},{"t":"であれ"},{"t":"大人","r":"おとな"},{"t":"であれ"},{"t":": be it a child, be it an adult. English does the same with \"be it\", a fossil imperative in both languages, doing concession rather than command."}],"changes":[{"word":"大人であれ","from":[{"t":"大人","r":"うし"},{"t":"であれ"}],"to":[{"t":"大人","r":"おとな"},{"t":"であれ"}],"why":"Adult is おとな."}]}'::jsonb, '{"furigana":[{"t":"あれ"},{"t":" is the classical imperative of "},{"t":"あり"},{"t":". Telling a hypothetical to be whatever it likes is a way of saying it changes nothing.\n\n"},{"r":"こども","t":"子供"},{"t":"であれ"},{"r":"うし","t":"大人"},{"t":"であれ"},{"t":": be it a child, be it an adult. English does the same with \"be it\", a fossil imperative in both languages, doing concession rather than command."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '5d5263f15b5480e1a19360299c2b23ba85321def2f6a9b7665adc26ed9196a53' AND l.code = 'ja'
  AND g.segments = '[{"t":"あれ"},{"t":" is the classical imperative of "},{"t":"あり"},{"t":". Telling a hypothetical to be whatever it likes is a way of saying it changes nothing.\n\n"},{"r":"こども","t":"子供"},{"t":"であれ"},{"r":"うし","t":"大人"},{"t":"であれ"},{"t":": be it a child, be it an adult. English does the same with \"be it\", a fossil imperative in both languages, doing concession rather than command."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜といっても: 六畳
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d7495665bd39299f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The whole N2 family of と言う compounds is built the same way, and reading them literally sorts them out. といっても concedes what was said and then cuts it down: 広いといっても、六畳だ.\n\nSee also からといって (just because it is said), とはいえ (that said), とは限らない (it is not limited to what is said). Four patterns, one verb of saying, each with a different particle doing the work.","point":"〜といっても","before":[{"t":"The whole N2 family of "},{"t":"と"},{"t":"言","r":"い"},{"t":"う"},{"t":" compounds is built the same way, and reading them literally sorts them out. "},{"t":"といっても"},{"t":" concedes what was said and then cuts it down: "},{"t":"広","r":"ひろ"},{"t":"いといっても"},{"t":"、"},{"t":"六","r":"りゅー"},{"t":"畳","r":"たとう"},{"t":"だ"},{"t":".\n\nSee also "},{"t":"からといって"},{"t":" (just because it is said), "},{"t":"とはいえ"},{"t":" (that said), "},{"t":"とは"},{"t":"限","r":"かぎ"},{"t":"らない"},{"t":" (it is not limited to what is said). Four patterns, one verb of saying, each with a different particle doing the work."}],"after":[{"t":"The whole N2 family of "},{"t":"と"},{"t":"言","r":"い"},{"t":"う"},{"t":" compounds is built the same way, and reading them literally sorts them out. "},{"t":"といっても"},{"t":" concedes what was said and then cuts it down: "},{"t":"広","r":"ひろ"},{"t":"いといっても"},{"t":"、"},{"t":"六畳","r":"ろくじょう"},{"t":"だ"},{"t":".\n\nSee also "},{"t":"からといって"},{"t":" (just because it is said), "},{"t":"とはいえ"},{"t":" (that said), "},{"t":"とは"},{"t":"限","r":"かぎ"},{"t":"らない"},{"t":" (it is not limited to what is said). Four patterns, one verb of saying, each with a different particle doing the work."}],"changes":[{"word":"六畳","from":[{"t":"六","r":"りゅー"},{"t":"畳","r":"たとう"}],"to":[{"t":"六畳","r":"ろくじょう"}],"why":"Six mats is ろくじょう."}]}'::jsonb, '{"furigana":[{"t":"The whole N2 family of "},{"t":"と"},{"r":"い","t":"言"},{"t":"う"},{"t":" compounds is built the same way, and reading them literally sorts them out. "},{"t":"といっても"},{"t":" concedes what was said and then cuts it down: "},{"r":"ひろ","t":"広"},{"t":"いといっても"},{"t":"、"},{"r":"りゅー","t":"六"},{"r":"たとう","t":"畳"},{"t":"だ"},{"t":".\n\nSee also "},{"t":"からといって"},{"t":" (just because it is said), "},{"t":"とはいえ"},{"t":" (that said), "},{"t":"とは"},{"r":"かぎ","t":"限"},{"t":"らない"},{"t":" (it is not limited to what is said). Four patterns, one verb of saying, each with a different particle doing the work."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'd7495665bd39299f324dcedec9abee609bdd23a31ad5a85a1093f8b5f2ab55fc' AND l.code = 'ja'
  AND g.segments = '[{"t":"The whole N2 family of "},{"t":"と"},{"r":"い","t":"言"},{"t":"う"},{"t":" compounds is built the same way, and reading them literally sorts them out. "},{"t":"といっても"},{"t":" concedes what was said and then cuts it down: "},{"r":"ひろ","t":"広"},{"t":"いといっても"},{"t":"、"},{"r":"りゅー","t":"六"},{"r":"たとう","t":"畳"},{"t":"だ"},{"t":".\n\nSee also "},{"t":"からといって"},{"t":" (just because it is said), "},{"t":"とはいえ"},{"t":" (that said), "},{"t":"とは"},{"r":"かぎ","t":"限"},{"t":"らない"},{"t":" (it is not limited to what is said). Four patterns, one verb of saying, each with a different particle doing the work."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜とき: 東京
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-675a64a9fdbf983f', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"子供のとき and 東京に行くとき are the same construction as 赤い本: something describing a noun, with nothing added to join them.\n\nSo the tense inside the clause is doing real work. 行くとき is on the way there, 行ったとき is after arriving, because the verb describes the state of the 時 rather than the state of the main sentence.","point":"〜とき","before":[{"t":"子供","r":"こども"},{"t":"のとき"},{"t":" and "},{"t":"東","r":"とん"},{"t":"京に"},{"t":"行","r":"い"},{"t":"くとき"},{"t":" are the same construction as "},{"t":"赤","r":"あか"},{"t":"い"},{"t":"本","r":"ほん"},{"t":": something describing a noun, with nothing added to join them.\n\nSo the tense inside the clause is doing real work. "},{"t":"行","r":"い"},{"t":"くとき"},{"t":" is on the way there, "},{"t":"行","r":"い"},{"t":"ったとき"},{"t":" is after arriving, because the verb describes the state of the "},{"t":"時","r":"とき"},{"t":" rather than the state of the main sentence."}],"after":[{"t":"子供","r":"こども"},{"t":"のとき"},{"t":" and "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":"行","r":"い"},{"t":"くとき"},{"t":" are the same construction as "},{"t":"赤","r":"あか"},{"t":"い"},{"t":"本","r":"ほん"},{"t":": something describing a noun, with nothing added to join them.\n\nSo the tense inside the clause is doing real work. "},{"t":"行","r":"い"},{"t":"くとき"},{"t":" is on the way there, "},{"t":"行","r":"い"},{"t":"ったとき"},{"t":" is after arriving, because the verb describes the state of the "},{"t":"時","r":"とき"},{"t":" rather than the state of the main sentence."}],"changes":[{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."}]}'::jsonb, '{"furigana":[{"r":"こども","t":"子供"},{"t":"のとき"},{"t":" and "},{"r":"とん","t":"東"},{"t":"京に"},{"r":"い","t":"行"},{"t":"くとき"},{"t":" are the same construction as "},{"r":"あか","t":"赤"},{"t":"い"},{"r":"ほん","t":"本"},{"t":": something describing a noun, with nothing added to join them.\n\nSo the tense inside the clause is doing real work. "},{"r":"い","t":"行"},{"t":"くとき"},{"t":" is on the way there, "},{"r":"い","t":"行"},{"t":"ったとき"},{"t":" is after arriving, because the verb describes the state of the "},{"r":"とき","t":"時"},{"t":" rather than the state of the main sentence."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '675a64a9fdbf983ff4f6ef3fed603aca989548d834781e17902dca85c0f64f47' AND l.code = 'ja'
  AND g.segments = '[{"r":"こども","t":"子供"},{"t":"のとき"},{"t":" and "},{"r":"とん","t":"東"},{"t":"京に"},{"r":"い","t":"行"},{"t":"くとき"},{"t":" are the same construction as "},{"r":"あか","t":"赤"},{"t":"い"},{"r":"ほん","t":"本"},{"t":": something describing a noun, with nothing added to join them.\n\nSo the tense inside the clause is doing real work. "},{"r":"い","t":"行"},{"t":"くとき"},{"t":" is on the way there, "},{"r":"い","t":"行"},{"t":"ったとき"},{"t":" is after arriving, because the verb describes the state of the "},{"r":"とき","t":"時"},{"t":" rather than the state of the main sentence."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

