-- 〜ところを: 所
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-8797e1989c36ca22', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"所 locates a moment as a place. The を marks that moment as what the speaker''s intrusion acts upon.\n\nお忙しいところをすみません apologises for the busy moment itself, not for anything done in it. That is why the pattern lives in apology and thanks (it names someone''s time as a thing you have taken), and equally in being caught or rescued mid-moment: 寝ているところを起こされた is the same intrusion from the other side.","point":"〜ところを","before":[{"t":"所","r":"しょ"},{"t":" locates a moment as a place. The "},{"t":"を"},{"t":" marks that moment as what the speaker''s intrusion acts upon.\n\n"},{"t":"お"},{"t":"忙","r":"いそが"},{"t":"しいところをすみません"},{"t":" apologises for the busy moment itself, not for anything done in it. That is why the pattern lives in apology and thanks (it names someone''s time as a thing you have taken), and equally in being caught or rescued mid-moment: "},{"t":"寝","r":"ね"},{"t":"ているところを"},{"t":"起","r":"お"},{"t":"こされた"},{"t":" is the same intrusion from the other side."}],"after":[{"t":"所","r":"ところ"},{"t":" locates a moment as a place. The "},{"t":"を"},{"t":" marks that moment as what the speaker''s intrusion acts upon.\n\n"},{"t":"お"},{"t":"忙","r":"いそが"},{"t":"しいところをすみません"},{"t":" apologises for the busy moment itself, not for anything done in it. That is why the pattern lives in apology and thanks (it names someone''s time as a thing you have taken), and equally in being caught or rescued mid-moment: "},{"t":"寝","r":"ね"},{"t":"ているところを"},{"t":"起","r":"お"},{"t":"こされた"},{"t":" is the same intrusion from the other side."}],"changes":[{"word":"所","from":[{"t":"所","r":"しょ"}],"to":[{"t":"所","r":"ところ"}],"why":"The noun meaning place is ところ here."}]}'::jsonb, '{"furigana":[{"r":"しょ","t":"所"},{"t":" locates a moment as a place. The "},{"t":"を"},{"t":" marks that moment as what the speaker''s intrusion acts upon.\n\n"},{"t":"お"},{"r":"いそが","t":"忙"},{"t":"しいところをすみません"},{"t":" apologises for the busy moment itself, not for anything done in it. That is why the pattern lives in apology and thanks (it names someone''s time as a thing you have taken), and equally in being caught or rescued mid-moment: "},{"r":"ね","t":"寝"},{"t":"ているところを"},{"r":"お","t":"起"},{"t":"こされた"},{"t":" is the same intrusion from the other side."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '8797e1989c36ca22b1413a4e3adbb89ad977d596cb59b01500a027e2ee412afa' AND l.code = 'ja'
  AND g.segments = '[{"r":"しょ","t":"所"},{"t":" locates a moment as a place. The "},{"t":"を"},{"t":" marks that moment as what the speaker''s intrusion acts upon.\n\n"},{"t":"お"},{"r":"いそが","t":"忙"},{"t":"しいところをすみません"},{"t":" apologises for the busy moment itself, not for anything done in it. That is why the pattern lives in apology and thanks (it names someone''s time as a thing you have taken), and equally in being caught or rescued mid-moment: "},{"r":"ね","t":"寝"},{"t":"ているところを"},{"r":"お","t":"起"},{"t":"こされた"},{"t":" is the same intrusion from the other side."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜として: 来た
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-22cacbfd30c68c9d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The と that quotes, and する doing what it does in ことにする: making it so. 医者として来た is coming, taken as a doctor.\n\nSo it is not a preposition but a small clause, which is why it stacks naturally into としては and としても, and why 〜をXとする (\"regard X as\") is the same construction with the pieces spread out.","point":"〜として","before":[{"t":"The "},{"t":"と"},{"t":" that quotes, and "},{"t":"する"},{"t":" doing what it does in "},{"t":"ことにする"},{"t":": making it so. "},{"t":"医者","r":"いしゃ"},{"t":"として"},{"t":"来","r":"らい"},{"t":"た"},{"t":" is coming, taken as a doctor.\n\nSo it is not a preposition but a small clause, which is why it stacks naturally into "},{"t":"としては"},{"t":" and "},{"t":"としても"},{"t":", and why 〜"},{"t":"を"},{"t":"X"},{"t":"とする"},{"t":" (\"regard X as\") is the same construction with the pieces spread out."}],"after":[{"t":"The "},{"t":"と"},{"t":" that quotes, and "},{"t":"する"},{"t":" doing what it does in "},{"t":"ことにする"},{"t":": making it so. "},{"t":"医者","r":"いしゃ"},{"t":"として"},{"t":"来","r":"き"},{"t":"た"},{"t":" is coming, taken as a doctor.\n\nSo it is not a preposition but a small clause, which is why it stacks naturally into "},{"t":"としては"},{"t":" and "},{"t":"としても"},{"t":", and why 〜"},{"t":"を"},{"t":"X"},{"t":"とする"},{"t":" (\"regard X as\") is the same construction with the pieces spread out."}],"changes":[{"word":"来た","from":[{"t":"来","r":"らい"},{"t":"た"}],"to":[{"t":"来","r":"き"},{"t":"た"}],"why":"来た is きた."}]}'::jsonb, '{"furigana":[{"t":"The "},{"t":"と"},{"t":" that quotes, and "},{"t":"する"},{"t":" doing what it does in "},{"t":"ことにする"},{"t":": making it so. "},{"r":"いしゃ","t":"医者"},{"t":"として"},{"r":"らい","t":"来"},{"t":"た"},{"t":" is coming, taken as a doctor.\n\nSo it is not a preposition but a small clause, which is why it stacks naturally into "},{"t":"としては"},{"t":" and "},{"t":"としても"},{"t":", and why 〜"},{"t":"を"},{"t":"X"},{"t":"とする"},{"t":" (\"regard X as\") is the same construction with the pieces spread out."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '22cacbfd30c68c9d0245f80c0c2e807eddd0f05cf6d63c2feded04ea3e430282' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"t":"と"},{"t":" that quotes, and "},{"t":"する"},{"t":" doing what it does in "},{"t":"ことにする"},{"t":": making it so. "},{"r":"いしゃ","t":"医者"},{"t":"として"},{"r":"らい","t":"来"},{"t":"た"},{"t":" is coming, taken as a doctor.\n\nSo it is not a preposition but a small clause, which is why it stacks naturally into "},{"t":"としては"},{"t":" and "},{"t":"としても"},{"t":", and why 〜"},{"t":"を"},{"t":"X"},{"t":"とする"},{"t":" (\"regard X as\") is the same construction with the pieces spread out."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜どころか: 下手だ, 所
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-b0d6e3e70532fb3a', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The 所 taught at N4 for a moment in time. どころか says the thing named is not even the place where the matter stands.\n\n上手どころか、下手だ dismisses \"skilled\" as the wrong location entirely and then supplies the right one. That is why どころか always overturns rather than merely qualifying: it has rejected the ground, not adjusted it.","point":"〜どころか","before":[{"t":"The "},{"t":"所","r":"しょ"},{"t":" taught at N4 for a moment in time. "},{"t":"どころか"},{"t":" says the thing named is not even the place where the matter stands.\n\n"},{"t":"上手","r":"じょうず"},{"t":"どころか"},{"t":"、"},{"t":"下手","r":"したて"},{"t":"だ"},{"t":" dismisses \"skilled\" as the wrong location entirely and then supplies the right one. That is why "},{"t":"どころか"},{"t":" always overturns rather than merely qualifying: it has rejected the ground, not adjusted it."}],"after":[{"t":"The "},{"t":"所","r":"ところ"},{"t":" taught at N4 for a moment in time. "},{"t":"どころか"},{"t":" says the thing named is not even the place where the matter stands.\n\n"},{"t":"上手","r":"じょうず"},{"t":"どころか"},{"t":"、"},{"t":"下手","r":"へた"},{"t":"だ"},{"t":" dismisses \"skilled\" as the wrong location entirely and then supplies the right one. That is why "},{"t":"どころか"},{"t":" always overturns rather than merely qualifying: it has rejected the ground, not adjusted it."}],"changes":[{"word":"下手だ","from":[{"t":"下手","r":"したて"},{"t":"だ"}],"to":[{"t":"下手","r":"へた"},{"t":"だ"}],"why":"Unskilled is へた."},{"word":"所","from":[{"t":"所","r":"しょ"}],"to":[{"t":"所","r":"ところ"}],"why":"The noun meaning place is ところ here."}]}'::jsonb, '{"furigana":[{"t":"The "},{"r":"しょ","t":"所"},{"t":" taught at N4 for a moment in time. "},{"t":"どころか"},{"t":" says the thing named is not even the place where the matter stands.\n\n"},{"r":"じょうず","t":"上手"},{"t":"どころか"},{"t":"、"},{"r":"したて","t":"下手"},{"t":"だ"},{"t":" dismisses \"skilled\" as the wrong location entirely and then supplies the right one. That is why "},{"t":"どころか"},{"t":" always overturns rather than merely qualifying: it has rejected the ground, not adjusted it."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'b0d6e3e70532fb3a0660eae20133b586f8dbcb008491df36429469678d1c2e81' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"r":"しょ","t":"所"},{"t":" taught at N4 for a moment in time. "},{"t":"どころか"},{"t":" says the thing named is not even the place where the matter stands.\n\n"},{"r":"じょうず","t":"上手"},{"t":"どころか"},{"t":"、"},{"r":"したて","t":"下手"},{"t":"だ"},{"t":" dismisses \"skilled\" as the wrong location entirely and then supplies the right one. That is why "},{"t":"どころか"},{"t":" always overturns rather than merely qualifying: it has rejected the ground, not adjusted it."}]'::jsonb
