-- 〜にとって: 体にとって, 私
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-02fbe622aee2c631', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"私にとって is standing where I stand and looking from there. The verb is the everyday 取る, doing the work English does with \"from the standpoint of\".\n\nThat is why にとって wants something whose interests or standpoint can be at stake (a person, a group, a country, even a body, since 日本にとって and 体にとって are perfectly ordinary), and why it pairs with judgements like 大切, 難しい and 必要 rather than with plain descriptions of fact.","point":"〜にとって","before":[{"t":"私","r":"わちき"},{"t":"にとって"},{"t":" is standing where I stand and looking from there. The verb is the everyday "},{"t":"取","r":"と"},{"t":"る"},{"t":", doing the work English does with \"from the standpoint of\".\n\nThat is why "},{"t":"にとって"},{"t":" wants something whose interests or standpoint can be at stake (a person, a group, a country, even a body, since "},{"t":"日本","r":"にほん"},{"t":"にとって"},{"t":" and "},{"t":"体","r":"たい"},{"t":"にとって"},{"t":" are perfectly ordinary), and why it pairs with judgements like "},{"t":"大切","r":"たいせつ"},{"t":", "},{"t":"難","r":"むずか"},{"t":"しい"},{"t":" and "},{"t":"必要","r":"ひつよう"},{"t":" rather than with plain descriptions of fact."}],"after":[{"t":"私","r":"わたし"},{"t":"にとって"},{"t":" is standing where I stand and looking from there. The verb is the everyday "},{"t":"取","r":"と"},{"t":"る"},{"t":", doing the work English does with \"from the standpoint of\".\n\nThat is why "},{"t":"にとって"},{"t":" wants something whose interests or standpoint can be at stake (a person, a group, a country, even a body, since "},{"t":"日本","r":"にほん"},{"t":"にとって"},{"t":" and "},{"t":"体","r":"からだ"},{"t":"にとって"},{"t":" are perfectly ordinary), and why it pairs with judgements like "},{"t":"大切","r":"たいせつ"},{"t":", "},{"t":"難","r":"むずか"},{"t":"しい"},{"t":" and "},{"t":"必要","r":"ひつよう"},{"t":" rather than with plain descriptions of fact."}],"changes":[{"word":"体にとって","from":[{"t":"体","r":"たい"},{"t":"にとって"}],"to":[{"t":"体","r":"からだ"},{"t":"にとって"}],"why":"Body is からだ."},{"word":"私","from":[{"t":"私","r":"わちき"}],"to":[{"t":"私","r":"わたし"}],"why":"I is わたし. / Standard reading of the pronoun is わたし. / Standard reading of 私 is わたし."}]}'::jsonb, '{"furigana":[{"r":"わちき","t":"私"},{"t":"にとって"},{"t":" is standing where I stand and looking from there. The verb is the everyday "},{"r":"と","t":"取"},{"t":"る"},{"t":", doing the work English does with \"from the standpoint of\".\n\nThat is why "},{"t":"にとって"},{"t":" wants something whose interests or standpoint can be at stake (a person, a group, a country, even a body, since "},{"r":"にほん","t":"日本"},{"t":"にとって"},{"t":" and "},{"r":"たい","t":"体"},{"t":"にとって"},{"t":" are perfectly ordinary), and why it pairs with judgements like "},{"r":"たいせつ","t":"大切"},{"t":", "},{"r":"むずか","t":"難"},{"t":"しい"},{"t":" and "},{"r":"ひつよう","t":"必要"},{"t":" rather than with plain descriptions of fact."}]}'::jsonb, 'ai', 900, 'pending'
