-- 〜とともに: 年をと
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-61186668f46af67c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A plain adverb built on a noun of sharing. とともに names two things as keeping company.\n\nThat covers both textbook senses without splitting them: accompanying (家族とともに) and moving in step (年をとるとともに). Company in space and company in change are the same idea, and Japanese did not separate them.","point":"〜とともに","before":[{"t":"A plain adverb built on a noun of sharing. "},{"t":"とともに"},{"t":" names two things as keeping company.\n\nThat covers both textbook senses without splitting them: accompanying ("},{"t":"家族","r":"かぞく"},{"t":"とともに"},{"t":") and moving in step ("},{"t":"年","r":"とせ"},{"t":"をとるとともに"},{"t":"). Company in space and company in change are the same idea, and Japanese did not separate them."}],"after":[{"t":"A plain adverb built on a noun of sharing. "},{"t":"とともに"},{"t":" names two things as keeping company.\n\nThat covers both textbook senses without splitting them: accompanying ("},{"t":"家族","r":"かぞく"},{"t":"とともに"},{"t":") and moving in step ("},{"t":"年","r":"とし"},{"t":"をと"},{"t":"るとともに"},{"t":"). Company in space and company in change are the same idea, and Japanese did not separate them."}],"changes":[{"word":"年をと","from":[{"t":"年","r":"とせ"},{"t":"をと"}],"to":[{"t":"年","r":"とし"},{"t":"をと"}],"why":"年をとる is としをとる."}]}'::jsonb, '{"furigana":[{"t":"A plain adverb built on a noun of sharing. "},{"t":"とともに"},{"t":" names two things as keeping company.\n\nThat covers both textbook senses without splitting them: accompanying ("},{"r":"かぞく","t":"家族"},{"t":"とともに"},{"t":") and moving in step ("},{"r":"とせ","t":"年"},{"t":"をとるとともに"},{"t":"). Company in space and company in change are the same idea, and Japanese did not separate them."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '61186668f46af67ce41326ce7d269769152fc17290fcd6c5adb531dce4134cb0' AND l.code = 'ja'
  AND g.segments = '[{"t":"A plain adverb built on a noun of sharing. "},{"t":"とともに"},{"t":" names two things as keeping company.\n\nThat covers both textbook senses without splitting them: accompanying ("},{"r":"かぞく","t":"家族"},{"t":"とともに"},{"t":") and moving in step ("},{"r":"とせ","t":"年"},{"t":"をとるとともに"},{"t":"). Company in space and company in change are the same idea, and Japanese did not separate them."}]'::jsonb
