-- どうして / なぜ: 何故
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-4c0a97cea69fe2c3', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"It asks by what means something came about, and asking that is asking why. なぜ is the plainer native word with no such construction inside it: 何故 is a kanji spelling, not a Sino-Japanese reading.\n\nThe literal reading also survives: どうして生きていくのか can genuinely mean \"how\", not \"why\". And it is why どうして carries more feeling than なぜ, which merely asks.","point":"どうして / なぜ","before":[{"t":"It asks by what means something came about, and asking that is asking why. "},{"t":"なぜ"},{"t":" is the plainer native word with no such construction inside it: "},{"t":"何","r":"なに"},{"t":"故","r":"こ"},{"t":" is a kanji spelling, not a Sino-Japanese reading.\n\nThe literal reading also survives: "},{"t":"どうして"},{"t":"生","r":"い"},{"t":"きていくのか"},{"t":" can genuinely mean \"how\", not \"why\". And it is why "},{"t":"どうして"},{"t":" carries more feeling than "},{"t":"なぜ"},{"t":", which merely asks."}],"after":[{"t":"It asks by what means something came about, and asking that is asking why. "},{"t":"なぜ"},{"t":" is the plainer native word with no such construction inside it: "},{"t":"何故","r":"なぜ"},{"t":" is a kanji spelling, not a Sino-Japanese reading.\n\nThe literal reading also survives: "},{"t":"どうして"},{"t":"生","r":"い"},{"t":"きていくのか"},{"t":" can genuinely mean \"how\", not \"why\". And it is why "},{"t":"どうして"},{"t":" carries more feeling than "},{"t":"なぜ"},{"t":", which merely asks."}],"changes":[{"word":"何故","from":[{"t":"何","r":"なに"},{"t":"故","r":"こ"}],"to":[{"t":"何故","r":"なぜ"}],"why":"何故 is なぜ."}]}'::jsonb, '{"furigana":[{"t":"It asks by what means something came about, and asking that is asking why. "},{"t":"なぜ"},{"t":" is the plainer native word with no such construction inside it: "},{"r":"なに","t":"何"},{"r":"こ","t":"故"},{"t":" is a kanji spelling, not a Sino-Japanese reading.\n\nThe literal reading also survives: "},{"t":"どうして"},{"r":"い","t":"生"},{"t":"きていくのか"},{"t":" can genuinely mean \"how\", not \"why\". And it is why "},{"t":"どうして"},{"t":" carries more feeling than "},{"t":"なぜ"},{"t":", which merely asks."}]}'::jsonb, 'ai', 900, 'pending'
