  AND g.segments = '[{"t":"It asks by what means something came about, and asking that is asking why. "},{"t":"なぜ"},{"t":" is the plainer native word with no such construction inside it: "},{"r":"なに","t":"何"},{"r":"こ","t":"故"},{"t":" is a kanji spelling, not a Sino-Japanese reading.\n\nThe literal reading also survives: "},{"t":"どうして"},{"r":"い","t":"生"},{"t":"きていくのか"},{"t":" can genuinely mean \"how\", not \"why\". And it is why "},{"t":"どうして"},{"t":" carries more feeling than "},{"t":"なぜ"},{"t":", which merely asks."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
