-- 分かる / できる: 分く
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-d58592cefad23f98', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Both are formations on the old root 分く, and 分かる is the intransitive one. To understand something is to have it separated out from what it is not: the thing does the coming-apart, in your mind.\n\nThat is why it takes が rather than を. 日本語が分かる is \"Japanese comes apart for me\", with no object to mark. を分かる survives only in pleas about feelings (気持ちを分かってほしい), where what is wanted is the effort, not the state.","point":"分かる / できる","before":[{"t":"Both are formations on the old root "},{"t":"分","r":"ふん"},{"t":"く"},{"t":", and "},{"t":"分","r":"わ"},{"t":"かる"},{"t":" is the intransitive one. To understand something is to have it separated out from what it is not: the thing does the coming-apart, in your mind.\n\nThat is why it takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":". "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"分","r":"わ"},{"t":"かる"},{"t":" is \"Japanese comes apart for me\", with no object to mark. "},{"t":"を"},{"t":"分","r":"わ"},{"t":"かる"},{"t":" survives only in pleas about feelings ("},{"t":"気持","r":"きも"},{"t":"ちを"},{"t":"分","r":"わ"},{"t":"かってほしい"},{"t":"), where what is wanted is the effort, not the state."}],"after":[{"t":"Both are formations on the old root "},{"t":"分","r":"わ"},{"t":"く"},{"t":", and "},{"t":"分","r":"わ"},{"t":"かる"},{"t":" is the intransitive one. To understand something is to have it separated out from what it is not: the thing does the coming-apart, in your mind.\n\nThat is why it takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":". "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"分","r":"わ"},{"t":"かる"},{"t":" is \"Japanese comes apart for me\", with no object to mark. "},{"t":"を"},{"t":"分","r":"わ"},{"t":"かる"},{"t":" survives only in pleas about feelings ("},{"t":"気持","r":"きも"},{"t":"ちを"},{"t":"分","r":"わ"},{"t":"かってほしい"},{"t":"), where what is wanted is the effort, not the state."}],"changes":[{"word":"分く","from":[{"t":"分","r":"ふん"},{"t":"く"}],"to":[{"t":"分","r":"わ"},{"t":"く"}],"why":"分く is わく."}]}'::jsonb, '{"furigana":[{"t":"Both are formations on the old root "},{"r":"ふん","t":"分"},{"t":"く"},{"t":", and "},{"r":"わ","t":"分"},{"t":"かる"},{"t":" is the intransitive one. To understand something is to have it separated out from what it is not: the thing does the coming-apart, in your mind.\n\nThat is why it takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":". "},{"r":"にほんご","t":"日本語"},{"t":"が"},{"r":"わ","t":"分"},{"t":"かる"},{"t":" is \"Japanese comes apart for me\", with no object to mark. "},{"t":"を"},{"r":"わ","t":"分"},{"t":"かる"},{"t":" survives only in pleas about feelings ("},{"r":"きも","t":"気持"},{"t":"ちを"},{"r":"わ","t":"分"},{"t":"かってほしい"},{"t":"), where what is wanted is the effort, not the state."}]}'::jsonb, 'ai', 900, 'pending'
