-- 何の / どんな: same 様
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-27ef089b73cef5f7', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"どのような contracted to どんな. So the word is the interrogative root ど with the same 様 that gives ようだ, ように and みたい, asking what manner a thing is of.\n\n何の asks which thing rather than which kind, and that is the whole distinction: 何の本 asks what the book is about, どんな本 what sort it is.","point":"何の / どんな","before":[{"t":"どのような"},{"t":" contracted to "},{"t":"どんな"},{"t":". So the word is the interrogative root "},{"t":"ど"},{"t":" with the same "},{"t":"様","r":"さま"},{"t":" that gives "},{"t":"ようだ"},{"t":", "},{"t":"ように"},{"t":" and "},{"t":"みたい"},{"t":", asking what manner a thing is of.\n\n"},{"t":"何","r":"なに"},{"t":"の"},{"t":" asks which thing rather than which kind, and that is the whole distinction: "},{"t":"何","r":"なに"},{"t":"の"},{"t":"本","r":"ほん"},{"t":" asks what the book is about, "},{"t":"どんな"},{"t":"本","r":"ほん"},{"t":" what sort it is."}],"after":[{"t":"どのような"},{"t":" contracted to "},{"t":"どんな"},{"t":". So the word is the interrogative root "},{"t":"ど"},{"t":" with the "},{"t":"same 様","r":"よう"},{"t":" that gives "},{"t":"ようだ"},{"t":", "},{"t":"ように"},{"t":" and "},{"t":"みたい"},{"t":", asking what manner a thing is of.\n\n"},{"t":"何","r":"なに"},{"t":"の"},{"t":" asks which thing rather than which kind, and that is the whole distinction: "},{"t":"何","r":"なに"},{"t":"の"},{"t":"本","r":"ほん"},{"t":" asks what the book is about, "},{"t":"どんな"},{"t":"本","r":"ほん"},{"t":" what sort it is."}],"changes":[{"word":"same 様","from":[{"t":"same "},{"t":"様","r":"さま"}],"to":[{"t":"same 様","r":"よう"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"}]}'::jsonb, '{"furigana":[{"t":"どのような"},{"t":" contracted to "},{"t":"どんな"},{"t":". So the word is the interrogative root "},{"t":"ど"},{"t":" with the same "},{"r":"さま","t":"様"},{"t":" that gives "},{"t":"ようだ"},{"t":", "},{"t":"ように"},{"t":" and "},{"t":"みたい"},{"t":", asking what manner a thing is of.\n\n"},{"r":"なに","t":"何"},{"t":"の"},{"t":" asks which thing rather than which kind, and that is the whole distinction: "},{"r":"なに","t":"何"},{"t":"の"},{"r":"ほん","t":"本"},{"t":" asks what the book is about, "},{"t":"どんな"},{"r":"ほん","t":"本"},{"t":" what sort it is."}]}'::jsonb, 'ai', 900, 'pending'
