-- 〜など: 等 is a kanji assigned, 等 would be
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-8f97d6ae89fb9925', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The derivation is phonetic: なにと contracted to など. 等 is a kanji assigned to write the word later, not the morpheme it descends from; read as Sino-Japanese, 等 would be トウ.\n\nWhat the original says is still what the particle does. A list trailing off into \"and what else\" is a list of samples, which is why など follows や so naturally. Worn down further it becomes なんか at N3, where the vagueness has curdled into dismissal.","point":"〜など","before":[{"t":"The derivation is phonetic: "},{"t":"なにと"},{"t":" contracted to "},{"t":"など"},{"t":". "},{"t":"等","r":"ひと"},{"t":" is a kanji assigned to write the word later, not the morpheme it descends from; read as Sino-Japanese, "},{"t":"等","r":"ひと"},{"t":" would be "},{"t":"トウ"},{"t":".\n\nWhat the original says is still what the particle does. A list trailing off into \"and what else\" is a list of samples, which is why "},{"t":"など"},{"t":" follows "},{"t":"や"},{"t":" so naturally. Worn down further it becomes "},{"t":"なんか"},{"t":" at N3, where the vagueness has curdled into dismissal."}],"after":[{"t":"The derivation is phonetic: "},{"t":"なにと"},{"t":" contracted to "},{"t":"など"},{"t":". "},{"t":"等","r":"など"},{"t":" is a kanji assigned"},{"t":" to write the word later, not the morpheme it descends from; read as Sino-Japanese, "},{"t":"等","r":"など"},{"t":" would be"},{"t":" "},{"t":"トウ"},{"t":".\n\nWhat the original says is still what the particle does. A list trailing off into \"and what else\" is a list of samples, which is why "},{"t":"など"},{"t":" follows "},{"t":"や"},{"t":" so naturally. Worn down further it becomes "},{"t":"なんか"},{"t":" at N3, where the vagueness has curdled into dismissal."}],"changes":[{"word":"等 is a kanji assigned","from":[{"t":"等","r":"ひと"},{"t":" is a kanji assigned"}],"to":[{"t":"等","r":"など"},{"t":" is a kanji assigned"}],"why":"等 here is など."},{"word":"等 would be","from":[{"t":"等","r":"ひと"},{"t":" would be"}],"to":[{"t":"等","r":"など"},{"t":" would be"}],"why":"等 here is など."}]}'::jsonb, '{"furigana":[{"t":"The derivation is phonetic: "},{"t":"なにと"},{"t":" contracted to "},{"t":"など"},{"t":". "},{"r":"ひと","t":"等"},{"t":" is a kanji assigned to write the word later, not the morpheme it descends from; read as Sino-Japanese, "},{"r":"ひと","t":"等"},{"t":" would be "},{"t":"トウ"},{"t":".\n\nWhat the original says is still what the particle does. A list trailing off into \"and what else\" is a list of samples, which is why "},{"t":"など"},{"t":" follows "},{"t":"や"},{"t":" so naturally. Worn down further it becomes "},{"t":"なんか"},{"t":" at N3, where the vagueness has curdled into dismissal."}]}'::jsonb, 'ai', 900, 'pending'
