-- 〜ばかり: 三日
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-42aa4293100a80ea', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A measure, an amount. That is the sense still visible in 三日ばかり, \"about three days\", which textbooks list as a separate meaning and which is really the original one.\n\nNarrow \"an amount of\" to \"that amount and no more\" and the other uses appear. 遊んでばかりいる is nothing but playing; 食べたばかり is only just eaten, a measure of time so small there is none to spare. One noun, measured tightly.","point":"〜ばかり","before":[{"t":"A measure, an amount. That is the sense still visible in "},{"t":"三","r":"さん"},{"t":"日","r":"にち"},{"t":"ばかり"},{"t":", \"about three days\", which textbooks list as a separate meaning and which is really the original one.\n\nNarrow \"an amount of\" to \"that amount and no more\" and the other uses appear. "},{"t":"遊","r":"あそ"},{"t":"んでばかりいる"},{"t":" is nothing but playing; "},{"t":"食","r":"た"},{"t":"べたばかり"},{"t":" is only just eaten, a measure of time so small there is none to spare. One noun, measured tightly."}],"after":[{"t":"A measure, an amount. That is the sense still visible in "},{"t":"三日","r":"みっか"},{"t":"ばかり"},{"t":", \"about three days\", which textbooks list as a separate meaning and which is really the original one.\n\nNarrow \"an amount of\" to \"that amount and no more\" and the other uses appear. "},{"t":"遊","r":"あそ"},{"t":"んでばかりいる"},{"t":" is nothing but playing; "},{"t":"食","r":"た"},{"t":"べたばかり"},{"t":" is only just eaten, a measure of time so small there is none to spare. One noun, measured tightly."}],"changes":[{"word":"三日","from":[{"t":"三","r":"さん"},{"t":"日","r":"にち"}],"to":[{"t":"三日","r":"みっか"}],"why":"Three days is みっか."}]}'::jsonb, '{"furigana":[{"t":"A measure, an amount. That is the sense still visible in "},{"r":"さん","t":"三"},{"r":"にち","t":"日"},{"t":"ばかり"},{"t":", \"about three days\", which textbooks list as a separate meaning and which is really the original one.\n\nNarrow \"an amount of\" to \"that amount and no more\" and the other uses appear. "},{"r":"あそ","t":"遊"},{"t":"んでばかりいる"},{"t":" is nothing but playing; "},{"r":"た","t":"食"},{"t":"べたばかり"},{"t":" is only just eaten, a measure of time so small there is none to spare. One noun, measured tightly."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '42aa4293100a80eaad005452fef5f6aaa2d5ed138b506aeccce21c9e22dd4845' AND l.code = 'ja'
  AND g.segments = '[{"t":"A measure, an amount. That is the sense still visible in "},{"r":"さん","t":"三"},{"r":"にち","t":"日"},{"t":"ばかり"},{"t":", \"about three days\", which textbooks list as a separate meaning and which is really the original one.\n\nNarrow \"an amount of\" to \"that amount and no more\" and the other uses appear. "},{"r":"あそ","t":"遊"},{"t":"んでばかりいる"},{"t":" is nothing but playing; "},{"r":"た","t":"食"},{"t":"べたばかり"},{"t":" is only just eaten, a measure of time so small there is none to spare. One noun, measured tightly."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜にして: 六十にして, 六十
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-61a87b92eedfad82', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"On a high number or a long span it means \"only at\": 六十にして始めた, not until sixty. On a small one it means \"even at\": 一瞬にして消えた, gone in a single instant.\n\nBoth are the same construction naming a point and remarking on it. What decides the reading is whether the point is surprisingly late or surprisingly small, and nothing in the grammar tells you which; the noun does.","point":"〜にして","before":[{"t":"On a high number or a long span it means \"only at\": "},{"t":"六","r":"りゅー"},{"t":"十","r":"しー"},{"t":"にして"},{"t":"始","r":"はじ"},{"t":"めた"},{"t":", not until sixty. On a small one it means \"even at\": "},{"t":"一瞬","r":"いっしゅん"},{"t":"にして"},{"t":"消","r":"き"},{"t":"えた"},{"t":", gone in a single instant.\n\nBoth are the same construction naming a point and remarking on it. What decides the reading is whether the point is surprisingly late or surprisingly small, and nothing in the grammar tells you which; the noun does."}],"after":[{"t":"On a high number or a long span it means \"only at\": "},{"t":"六十","r":"ろくじゅう"},{"t":"にして"},{"t":"始","r":"はじ"},{"t":"めた"},{"t":", not until sixty. On a small one it means \"even at\": "},{"t":"一瞬","r":"いっしゅん"},{"t":"にして"},{"t":"消","r":"き"},{"t":"えた"},{"t":", gone in a single instant.\n\nBoth are the same construction naming a point and remarking on it. What decides the reading is whether the point is surprisingly late or surprisingly small, and nothing in the grammar tells you which; the noun does."}],"changes":[{"word":"六十にして","from":[{"t":"六","r":"りゅー"},{"t":"十","r":"しー"},{"t":"にして"}],"to":[{"t":"六","r":"ろく"},{"t":"十","r":"じゅう"},{"t":"にして"}],"why":"六十 is ろくじゅう."},{"word":"六十","from":[{"t":"六","r":"ろく"},{"t":"十","r":"じゅう"}],"to":[{"t":"六十","r":"ろくじゅう"}],"why":"Sixty is ろくじゅう."}]}'::jsonb, '{"furigana":[{"t":"On a high number or a long span it means \"only at\": "},{"r":"りゅー","t":"六"},{"r":"しー","t":"十"},{"t":"にして"},{"r":"はじ","t":"始"},{"t":"めた"},{"t":", not until sixty. On a small one it means \"even at\": "},{"r":"いっしゅん","t":"一瞬"},{"t":"にして"},{"r":"き","t":"消"},{"t":"えた"},{"t":", gone in a single instant.\n\nBoth are the same construction naming a point and remarking on it. What decides the reading is whether the point is surprisingly late or surprisingly small, and nothing in the grammar tells you which; the noun does."}]}'::jsonb, 'ai', 900, 'pending'
