WHERE g.text_hash = '61a87b92eedfad82f7bd6d218e458b808faaaa2b5cab454ea12abf321c9a36ff' AND l.code = 'ja'
  AND g.segments = '[{"t":"On a high number or a long span it means \"only at\": "},{"r":"りゅー","t":"六"},{"r":"しー","t":"十"},{"t":"にして"},{"r":"はじ","t":"始"},{"t":"めた"},{"t":", not until sixty. On a small one it means \"even at\": "},{"r":"いっしゅん","t":"一瞬"},{"t":"にして"},{"r":"き","t":"消"},{"t":"えた"},{"t":", gone in a single instant.\n\nBoth are the same construction naming a point and remarking on it. What decides the reading is whether the point is surprisingly late or surprisingly small, and nothing in the grammar tells you which; the noun does."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

