SELECT 'crq-grammar-a6da6a405477b306', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"限る is the verb behind かぎり at N3: to set a limit. Negated, it says the limit does not hold.\n\n若者に限らず says the young are not the edge of it. It is the widening twin of に限り, which draws the boundary rather than denying it, and the two are one verb pointed opposite ways.","point":"〜に限らず","before":[{"t":"限","r":"かぎ"},{"t":"る"},{"t":" is the verb behind "},{"t":"かぎり"},{"t":" at N3: to set a limit. Negated, it says the limit does not hold.\n\n"},{"t":"若","r":"わか"},{"t":"者","r":"しゃ"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"らず"},{"t":" says the young are not the edge of it. It is the widening twin of "},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"り"},{"t":", which draws the boundary rather than denying it, and the two are one verb pointed opposite ways."}],"after":[{"t":"限","r":"かぎ"},{"t":"る"},{"t":" is the verb behind "},{"t":"かぎり"},{"t":" at N3: to set a limit. Negated, it says the limit does not hold.\n\n"},{"t":"若者","r":"わかもの"},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"らず"},{"t":" says the young are not the edge of it. It is the widening twin of "},{"t":"に"},{"t":"限","r":"かぎ"},{"t":"り"},{"t":", which draws the boundary rather than denying it, and the two are one verb pointed opposite ways."}],"changes":[{"word":"若者","from":[{"t":"若","r":"わか"},{"t":"者","r":"しゃ"}],"to":[{"t":"若者","r":"わかもの"}],"why":"Compound is わかもの."}]}'::jsonb, '{"furigana":[{"r":"かぎ","t":"限"},{"t":"る"},{"t":" is the verb behind "},{"t":"かぎり"},{"t":" at N3: to set a limit. Negated, it says the limit does not hold.\n\n"},{"r":"わか","t":"若"},{"r":"しゃ","t":"者"},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"らず"},{"t":" says the young are not the edge of it. It is the widening twin of "},{"t":"に"},{"r":"かぎ","t":"限"},{"t":"り"},{"t":", which draws the boundary rather than denying it, and the two are one verb pointed opposite ways."}]}'::jsonb, 'ai', 900, 'pending'
