SELECT 'crq-grammar-d43b9fe6f5197544', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ボールが弾む is a ball bouncing; 話が弾む is a conversation that takes off. The noun is momentum.\n\nSo 転んだはずみに is on the bounce of falling, the accident carried on into something else by its own momentum. That is why the pattern always describes something unintended: a bounce is not aimed.","point":"〜はずみに","before":[{"t":"ボールが"},{"t":"弾","r":"はず"},{"t":"む"},{"t":" is a ball bouncing; "},{"t":"話","r":"わ"},{"t":"が"},{"t":"弾","r":"はず"},{"t":"む"},{"t":" is a conversation that takes off. The noun is momentum.\n\nSo "},{"t":"転","r":"ころ"},{"t":"んだはずみに"},{"t":" is on the bounce of falling, the accident carried on into something else by its own momentum. That is why the pattern always describes something unintended: a bounce is not aimed."}],"after":[{"t":"ボールが"},{"t":"弾","r":"はず"},{"t":"む"},{"t":" is a ball bouncing; "},{"t":"話","r":"はなし"},{"t":"が"},{"t":"弾","r":"はず"},{"t":"む"},{"t":" is a conversation that takes off. The noun is momentum.\n\nSo "},{"t":"転","r":"ころ"},{"t":"んだはずみに"},{"t":" is on the bounce of falling, the accident carried on into something else by its own momentum. That is why the pattern always describes something unintended: a bounce is not aimed."}],"changes":[{"word":"話が弾","from":[{"t":"話","r":"わ"},{"t":"が"},{"t":"弾","r":"はず"}],"to":[{"t":"話","r":"はなし"},{"t":"が"},{"t":"弾","r":"はず"}],"why":"A conversation is はなし."}]}'::jsonb, '{"furigana":[{"t":"ボールが"},{"r":"はず","t":"弾"},{"t":"む"},{"t":" is a ball bouncing; "},{"r":"わ","t":"話"},{"t":"が"},{"r":"はず","t":"弾"},{"t":"む"},{"t":" is a conversation that takes off. The noun is momentum.\n\nSo "},{"r":"ころ","t":"転"},{"t":"んだはずみに"},{"t":" is on the bounce of falling, the accident carried on into something else by its own momentum. That is why the pattern always describes something unintended: a bounce is not aimed."}]}'::jsonb, 'ai', 900, 'pending'
