INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-abb11b6698ecfa99', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"べく plus あら plus ず, contracted. It is the negative branch of the same auxiliary that gives べき and べく.\n\nIt survives almost entirely on signage (立入るべからず), because that is where classical Japanese survives generally: notices, mottoes and set phrases keep old grammar long after speech has let it go.","point":"〜べからず","before":[{"t":"べく"},{"t":" plus "},{"t":"あら"},{"t":" plus "},{"t":"ず"},{"t":", contracted. It is the negative branch of the same auxiliary that gives "},{"t":"べき"},{"t":" and "},{"t":"べく"},{"t":".\n\nIt survives almost entirely on signage ("},{"t":"立","r":"た"},{"t":"入","r":"い"},{"t":"るべからず"},{"t":"), because that is where classical Japanese survives generally: notices, mottoes and set phrases keep old grammar long after speech has let it go."}],"after":[{"t":"べく"},{"t":" plus "},{"t":"あら"},{"t":" plus "},{"t":"ず"},{"t":", contracted. It is the negative branch of the same auxiliary that gives "},{"t":"べき"},{"t":" and "},{"t":"べく"},{"t":".\n\nIt survives almost entirely on signage ("},{"t":"立入","r":"たちい"},{"t":"るべからず"},{"t":"), because that is where classical Japanese survives generally: notices, mottoes and set phrases keep old grammar long after speech has let it go."}],"changes":[{"word":"立入るべからず","from":[{"t":"立","r":"た"},{"t":"入","r":"い"},{"t":"るべからず"}],"to":[{"t":"立入","r":"たちい"},{"t":"るべからず"}],"why":"立入る is たちいる."}]}'::jsonb, '{"furigana":[{"t":"べく"},{"t":" plus "},{"t":"あら"},{"t":" plus "},{"t":"ず"},{"t":", contracted. It is the negative branch of the same auxiliary that gives "},{"t":"べき"},{"t":" and "},{"t":"べく"},{"t":".\n\nIt survives almost entirely on signage ("},{"r":"た","t":"立"},{"r":"い","t":"入"},{"t":"るべからず"},{"t":"), because that is where classical Japanese survives generally: notices, mottoes and set phrases keep old grammar long after speech has let it go."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'abb11b6698ecfa990526528ee79f0e9a35fecdd9741b43bea67a4a926284a167' AND l.code = 'ja'
  AND g.segments = '[{"t":"べく"},{"t":" plus "},{"t":"あら"},{"t":" plus "},{"t":"ず"},{"t":", contracted. It is the negative branch of the same auxiliary that gives "},{"t":"べき"},{"t":" and "},{"t":"べく"},{"t":".\n\nIt survives almost entirely on signage ("},{"r":"た","t":"立"},{"r":"い","t":"入"},{"t":"るべからず"},{"t":"), because that is where classical Japanese survives generally: notices, mottoes and set phrases keep old grammar long after speech has let it go."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

