-- 〜よりほかない: 外 is the outside, same 外,
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-ca4b5c5441e4546c', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"より marks comparison, 外 is the outside of a thing. 諦めるよりほかない says that beyond giving up there is nothing.\n\nIt is the formal twin of しかない, and both draw the same picture: everything else has been excluded and one course is left standing. ほかならない at N2 is the same 外, denying that anything outside applies.","point":"〜よりほかない","before":[{"t":"より"},{"t":" marks comparison, "},{"t":"外","r":"がい"},{"t":" is the outside of a thing. "},{"t":"諦","r":"あきら"},{"t":"めるよりほかない"},{"t":" says that beyond giving up there is nothing.\n\nIt is the formal twin of "},{"t":"しかない"},{"t":", and both draw the same picture: everything else has been excluded and one course is left standing. "},{"t":"ほかならない"},{"t":" at N2 is the same "},{"t":"外","r":"がい"},{"t":", denying that anything outside applies."}],"after":[{"t":"より"},{"t":" marks comparison, "},{"t":"外","r":"ほか"},{"t":" is the outside"},{"t":" of a thing. "},{"t":"諦","r":"あきら"},{"t":"めるよりほかない"},{"t":" says that beyond giving up there is nothing.\n\nIt is the formal twin of "},{"t":"しかない"},{"t":", and both draw the same picture: everything else has been excluded and one course is left standing. "},{"t":"ほかならない"},{"t":" at N2 is the "},{"t":"same 外","r":"ほか"},{"t":","},{"t":" denying that anything outside applies."}],"changes":[{"word":"外 is the outside","from":[{"t":"外","r":"がい"},{"t":" is the outside"}],"to":[{"t":"外","r":"ほか"},{"t":" is the outside"}],"why":"外 here is ほか."},{"word":"same 外,","from":[{"t":"same "},{"t":"外","r":"がい"},{"t":","}],"to":[{"t":"same 外","r":"ほか"},{"t":","}],"why":"ほかならない is this 外, ほか."}]}'::jsonb, '{"furigana":[{"t":"より"},{"t":" marks comparison, "},{"r":"がい","t":"外"},{"t":" is the outside of a thing. "},{"r":"あきら","t":"諦"},{"t":"めるよりほかない"},{"t":" says that beyond giving up there is nothing.\n\nIt is the formal twin of "},{"t":"しかない"},{"t":", and both draw the same picture: everything else has been excluded and one course is left standing. "},{"t":"ほかならない"},{"t":" at N2 is the same "},{"r":"がい","t":"外"},{"t":", denying that anything outside applies."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'ca4b5c5441e4546c2cc87f1597f571749a428e1b54042164cc95578a3f0963a7' AND l.code = 'ja'
  AND g.segments = '[{"t":"より"},{"t":" marks comparison, "},{"r":"がい","t":"外"},{"t":" is the outside of a thing. "},{"r":"あきら","t":"諦"},{"t":"めるよりほかない"},{"t":" says that beyond giving up there is nothing.\n\nIt is the formal twin of "},{"t":"しかない"},{"t":", and both draw the same picture: everything else has been excluded and one course is left standing. "},{"t":"ほかならない"},{"t":" at N2 is the same "},{"r":"がい","t":"外"},{"t":", denying that anything outside applies."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

