SELECT 'crq-grammar-3491288c11dba0bf', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The なら is the 未然形 of the copula なり, not the verb なる. Classical ほかならず said outright \"is nothing other than\", which is exactly the modern meaning; nothing has shifted.\n\nWhich is why it is emphatic identification rather than a hedge: 努力の結果にほかならない insists there is no other account. It is worth keeping apart from なければならない, whose ならない really is なる.","point":"〜にほかならない","before":[{"t":"The "},{"t":"なら"},{"t":" is the "},{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"},{"t":" of the copula "},{"t":"なり"},{"t":", not the verb "},{"t":"なる"},{"t":". Classical "},{"t":"ほかならず"},{"t":" said outright \"is nothing other than\", which is exactly the modern meaning; nothing has shifted.\n\nWhich is why it is emphatic identification rather than a hedge: "},{"t":"努力","r":"どりょく"},{"t":"の"},{"t":"結果","r":"けっか"},{"t":"にほかならない"},{"t":" insists there is no other account. It is worth keeping apart from "},{"t":"なければならない"},{"t":", whose "},{"t":"ならない"},{"t":" really is "},{"t":"なる"},{"t":"."}],"after":[{"t":"The "},{"t":"なら"},{"t":" is the "},{"t":"未然形","r":"みぜんけい"},{"t":" of the copula "},{"t":"なり"},{"t":", not the verb "},{"t":"なる"},{"t":". Classical "},{"t":"ほかならず"},{"t":" said outright \"is nothing other than\", which is exactly the modern meaning; nothing has shifted.\n\nWhich is why it is emphatic identification rather than a hedge: "},{"t":"努力","r":"どりょく"},{"t":"の"},{"t":"結果","r":"けっか"},{"t":"にほかならない"},{"t":" insists there is no other account. It is worth keeping apart from "},{"t":"なければならない"},{"t":", whose "},{"t":"ならない"},{"t":" really is "},{"t":"なる"},{"t":"."}],"changes":[{"word":"未然形","from":[{"t":"未","r":"ま"},{"t":"然"},{"t":"形","r":"なり"}],"to":[{"t":"未然形","r":"みぜんけい"}],"why":"Grammar term is みぜんけい."}]}'::jsonb, '{"furigana":[{"t":"The "},{"t":"なら"},{"t":" is the "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" of the copula "},{"t":"なり"},{"t":", not the verb "},{"t":"なる"},{"t":". Classical "},{"t":"ほかならず"},{"t":" said outright \"is nothing other than\", which is exactly the modern meaning; nothing has shifted.\n\nWhich is why it is emphatic identification rather than a hedge: "},{"r":"どりょく","t":"努力"},{"t":"の"},{"r":"けっか","t":"結果"},{"t":"にほかならない"},{"t":" insists there is no other account. It is worth keeping apart from "},{"t":"なければならない"},{"t":", whose "},{"t":"ならない"},{"t":" really is "},{"t":"なる"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
