WHERE g.text_hash = '3491288c11dba0bf4080dc2da96e27e200b93ecefb953d0197e83727c3692ac1' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"t":"なら"},{"t":" is the "},{"r":"ま","t":"未"},{"t":"然"},{"r":"なり","t":"形"},{"t":" of the copula "},{"t":"なり"},{"t":", not the verb "},{"t":"なる"},{"t":". Classical "},{"t":"ほかならず"},{"t":" said outright \"is nothing other than\", which is exactly the modern meaning; nothing has shifted.\n\nWhich is why it is emphatic identification rather than a hedge: "},{"r":"どりょく","t":"努力"},{"t":"の"},{"r":"けっか","t":"結果"},{"t":"にほかならない"},{"t":" insists there is no other account. It is worth keeping apart from "},{"t":"なければならない"},{"t":", whose "},{"t":"ならない"},{"t":" really is "},{"t":"なる"},{"t":"."}]'::jsonb
