-- 〜みたい: because 様, same 様, みたいな人
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-de20ec4df2ea86ef', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"見た, the past of 見る, plus the same 様 that gives ようだ. The origin says outright what the grammar books say: it is ようだ for casual speech.\n\nAnd it explains the conjugation, which otherwise looks arbitrary. みたい inflects as a na-adjective (みたいな人, みたいに), because 様 is a noun and always was.","point":"〜みたい","before":[{"t":"見","r":"み"},{"t":"た"},{"t":", the past of "},{"t":"見","r":"み"},{"t":"る"},{"t":", plus the same "},{"t":"様","r":"さま"},{"t":" that gives "},{"t":"ようだ"},{"t":". The origin says outright what the grammar books say: it is "},{"t":"ようだ"},{"t":" for casual speech.\n\nAnd it explains the conjugation, which otherwise looks arbitrary. "},{"t":"みたい"},{"t":" inflects as a na-adjective ("},{"t":"みたいな"},{"t":"人","r":"と"},{"t":", "},{"t":"みたいに"},{"t":"), because "},{"t":"様","r":"さま"},{"t":" is a noun and always was."}],"after":[{"t":"見","r":"み"},{"t":"た"},{"t":", the past of "},{"t":"見","r":"み"},{"t":"る"},{"t":", plus the "},{"t":"same 様","r":"よう"},{"t":" that gives "},{"t":"ようだ"},{"t":". The origin says outright what the grammar books say: it is "},{"t":"ようだ"},{"t":" for casual speech.\n\nAnd it explains the conjugation, which otherwise looks arbitrary. "},{"t":"みたい"},{"t":" inflects as a na-adjective ("},{"t":"みたいな"},{"t":"人","r":"ひと"},{"t":", "},{"t":"みたいに"},{"t":"), "},{"t":"because 様","r":"よう"},{"t":" is a noun and always was."}],"changes":[{"word":"because 様","from":[{"t":"because "},{"t":"様","r":"さま"}],"to":[{"t":"because 様","r":"よう"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"},{"word":"same 様","from":[{"t":"same "},{"t":"様","r":"さま"}],"to":[{"t":"same 様","r":"よう"}],"why":"百名様 is さま; narrowed to the よう-etymology mentions"},{"word":"みたいな人","from":[{"t":"みたいな"},{"t":"人","r":"と"}],"to":[{"t":"みたいな"},{"t":"人","r":"ひと"}],"why":"A person is ひと."}]}'::jsonb, '{"furigana":[{"r":"み","t":"見"},{"t":"た"},{"t":", the past of "},{"r":"み","t":"見"},{"t":"る"},{"t":", plus the same "},{"r":"さま","t":"様"},{"t":" that gives "},{"t":"ようだ"},{"t":". The origin says outright what the grammar books say: it is "},{"t":"ようだ"},{"t":" for casual speech.\n\nAnd it explains the conjugation, which otherwise looks arbitrary. "},{"t":"みたい"},{"t":" inflects as a na-adjective ("},{"t":"みたいな"},{"r":"と","t":"人"},{"t":", "},{"t":"みたいに"},{"t":"), because "},{"r":"さま","t":"様"},{"t":" is a noun and always was."}]}'::jsonb, 'ai', 900, 'pending'
