-- 〜てもらう: 手伝って, 手伝って
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-cd712d72cb175ec7', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"友達が手伝ってくれた and 友達に手伝ってもらった describe one afternoon. くれる makes the helper the subject; もらう makes you the subject and demotes the helper to に.\n\nThat particle is the whole grammar of it. に marks the source a thing is received from, exactly as in 友達に本をもらう, so there is no separate rule to learn about who takes which particle in the compound.","point":"〜てもらう","before":[{"t":"友達","r":"ともだち"},{"t":"が"},{"t":"手","r":"て"},{"t":"伝","r":"つた"},{"t":"ってくれた"},{"t":" and "},{"t":"友達","r":"ともだち"},{"t":"に"},{"t":"手","r":"て"},{"t":"伝","r":"つた"},{"t":"ってもらった"},{"t":" describe one afternoon. "},{"t":"くれる"},{"t":" makes the helper the subject; "},{"t":"もらう"},{"t":" makes you the subject and demotes the helper to "},{"t":"に"},{"t":".\n\nThat particle is the whole grammar of it. "},{"t":"に"},{"t":" marks the source a thing is received from, exactly as in "},{"t":"友達","r":"ともだち"},{"t":"に"},{"t":"本","r":"ほん"},{"t":"をもらう"},{"t":", so there is no separate rule to learn about who takes which particle in the compound."}],"after":[{"t":"友達","r":"ともだち"},{"t":"が"},{"t":"手伝","r":"てつだ"},{"t":"って"},{"t":"くれた"},{"t":" and "},{"t":"友達","r":"ともだち"},{"t":"に"},{"t":"手伝","r":"てつだ"},{"t":"って"},{"t":"もらった"},{"t":" describe one afternoon. "},{"t":"くれる"},{"t":" makes the helper the subject; "},{"t":"もらう"},{"t":" makes you the subject and demotes the helper to "},{"t":"に"},{"t":".\n\nThat particle is the whole grammar of it. "},{"t":"に"},{"t":" marks the source a thing is received from, exactly as in "},{"t":"友達","r":"ともだち"},{"t":"に"},{"t":"本","r":"ほん"},{"t":"をもらう"},{"t":", so there is no separate rule to learn about who takes which particle in the compound."}],"changes":[{"word":"手伝って","from":[{"t":"手","r":"て"},{"t":"伝","r":"つた"},{"t":"って"}],"to":[{"t":"手伝","r":"てつだ"},{"t":"って"}],"why":"手伝う is てつだう."},{"word":"手伝って","from":[{"t":"手","r":"て"},{"t":"伝","r":"つた"},{"t":"って"}],"to":[{"t":"手伝","r":"てつだ"},{"t":"って"}],"why":"手伝う is てつだう."}]}'::jsonb, '{"furigana":[{"r":"ともだち","t":"友達"},{"t":"が"},{"r":"て","t":"手"},{"r":"つた","t":"伝"},{"t":"ってくれた"},{"t":" and "},{"r":"ともだち","t":"友達"},{"t":"に"},{"r":"て","t":"手"},{"r":"つた","t":"伝"},{"t":"ってもらった"},{"t":" describe one afternoon. "},{"t":"くれる"},{"t":" makes the helper the subject; "},{"t":"もらう"},{"t":" makes you the subject and demotes the helper to "},{"t":"に"},{"t":".\n\nThat particle is the whole grammar of it. "},{"t":"に"},{"t":" marks the source a thing is received from, exactly as in "},{"r":"ともだち","t":"友達"},{"t":"に"},{"r":"ほん","t":"本"},{"t":"をもらう"},{"t":", so there is no separate rule to learn about who takes which particle in the compound."}]}'::jsonb, 'ai', 900, 'pending'
