-- 〜ように (purpose): 声で話
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-ccb9685dc7e612e8', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"ために names a purpose you intend. ように names a manner you hope things fall into, and the difference is doing real work in the grammar.\n\nIt is why ように takes the verbs you cannot simply decide (potentials, negatives, things happening to other people), while ために takes the ones you can. 聞こえるように大きな声で話す, because being audible is not something you do; 勉強するために, because studying is. Same speaker, same intention, two constructions, and the verb decides which.","point":"〜ように (purpose)","before":[{"t":"ために"},{"t":" names a purpose you intend. "},{"t":"ように"},{"t":" names a manner you hope things fall into, and the difference is doing real work in the grammar.\n\nIt is why "},{"t":"ように"},{"t":" takes the verbs you cannot simply decide (potentials, negatives, things happening to other people), while "},{"t":"ために"},{"t":" takes the ones you can. "},{"t":"聞","r":"き"},{"t":"こえるように"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"声","r":"しょう"},{"t":"で"},{"t":"話","r":"はな"},{"t":"す"},{"t":", because being audible is not something you do; "},{"t":"勉強","r":"べんきょう"},{"t":"するために"},{"t":", because studying is. Same speaker, same intention, two constructions, and the verb decides which."}],"after":[{"t":"ために"},{"t":" names a purpose you intend. "},{"t":"ように"},{"t":" names a manner you hope things fall into, and the difference is doing real work in the grammar.\n\nIt is why "},{"t":"ように"},{"t":" takes the verbs you cannot simply decide (potentials, negatives, things happening to other people), while "},{"t":"ために"},{"t":" takes the ones you can. "},{"t":"聞","r":"き"},{"t":"こえるように"},{"t":"大","r":"おお"},{"t":"きな"},{"t":"声","r":"こえ"},{"t":"で"},{"t":"話","r":"はな"},{"t":"す"},{"t":", because being audible is not something you do; "},{"t":"勉強","r":"べんきょう"},{"t":"するために"},{"t":", because studying is. Same speaker, same intention, two constructions, and the verb decides which."}],"changes":[{"word":"声で話","from":[{"t":"声","r":"しょう"},{"t":"で"},{"t":"話","r":"はな"}],"to":[{"t":"声","r":"こえ"},{"t":"で"},{"t":"話","r":"はな"}],"why":"FINAL dropped the reading on 話"}]}'::jsonb, '{"furigana":[{"t":"ために"},{"t":" names a purpose you intend. "},{"t":"ように"},{"t":" names a manner you hope things fall into, and the difference is doing real work in the grammar.\n\nIt is why "},{"t":"ように"},{"t":" takes the verbs you cannot simply decide (potentials, negatives, things happening to other people), while "},{"t":"ために"},{"t":" takes the ones you can. "},{"r":"き","t":"聞"},{"t":"こえるように"},{"r":"おお","t":"大"},{"t":"きな"},{"r":"しょう","t":"声"},{"t":"で"},{"r":"はな","t":"話"},{"t":"す"},{"t":", because being audible is not something you do; "},{"r":"べんきょう","t":"勉強"},{"t":"するために"},{"t":", because studying is. Same speaker, same intention, two constructions, and the verb decides which."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'ccb9685dc7e612e80fc72a2837f75b3871a443893f19a32a704ddd72aec403d3' AND l.code = 'ja'
  AND g.segments = '[{"t":"ために"},{"t":" names a purpose you intend. "},{"t":"ように"},{"t":" names a manner you hope things fall into, and the difference is doing real work in the grammar.\n\nIt is why "},{"t":"ように"},{"t":" takes the verbs you cannot simply decide (potentials, negatives, things happening to other people), while "},{"t":"ために"},{"t":" takes the ones you can. "},{"r":"き","t":"聞"},{"t":"こえるように"},{"r":"おお","t":"大"},{"t":"きな"},{"r":"しょう","t":"声"},{"t":"で"},{"r":"はな","t":"話"},{"t":"す"},{"t":", because being audible is not something you do; "},{"r":"べんきょう","t":"勉強"},{"t":"するために"},{"t":", because studying is. Same speaker, same intention, two constructions, and the verb decides which."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜をよそに: 親の心配, よその人
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-764ec6c9c0e0b2fc', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"よそ見 is looking away; よその人 is an outsider. をよそに puts the thing named somewhere other than where the actor is attending.\n\nSo the disregard is spatial before it is moral. 親の心配をよそに says the worry was left in another place and walked away from, which is why the pattern always carries a hint of reproach.","point":"〜をよそに","before":[{"t":"よそ"},{"t":"見","r":"み"},{"t":" is looking away; "},{"t":"よその"},{"t":"人","r":"と"},{"t":" is an outsider. "},{"t":"をよそに"},{"t":" puts the thing named somewhere other than where the actor is attending.\n\nSo the disregard is spatial before it is moral. "},{"t":"親","r":"しん"},{"t":"の"},{"t":"心配","r":"しんぱい"},{"t":"をよそに"},{"t":" says the worry was left in another place and walked away from, which is why the pattern always carries a hint of reproach."}],"after":[{"t":"よそ"},{"t":"見","r":"み"},{"t":" is looking away; "},{"t":"よその"},{"t":"人","r":"ひと"},{"t":" is an outsider. "},{"t":"をよそに"},{"t":" puts the thing named somewhere other than where the actor is attending.\n\nSo the disregard is spatial before it is moral. "},{"t":"親","r":"おや"},{"t":"の"},{"t":"心配","r":"しんぱい"},{"t":"をよそに"},{"t":" says the worry was left in another place and walked away from, which is why the pattern always carries a hint of reproach."}],"changes":[{"word":"親の心配","from":[{"t":"親","r":"しん"},{"t":"の"},{"t":"心配","r":"しんぱい"}],"to":[{"t":"親","r":"おや"},{"t":"の"},{"t":"心配","r":"しんぱい"}],"why":"FINAL dropped the existing 心配[しんぱい] ruby"},{"word":"よその人","from":[{"t":"よその"},{"t":"人","r":"と"}],"to":[{"t":"よその"},{"t":"人","r":"ひと"}],"why":"よその人 is よそのひと."}]}'::jsonb, '{"furigana":[{"t":"よそ"},{"r":"み","t":"見"},{"t":" is looking away; "},{"t":"よその"},{"r":"と","t":"人"},{"t":" is an outsider. "},{"t":"をよそに"},{"t":" puts the thing named somewhere other than where the actor is attending.\n\nSo the disregard is spatial before it is moral. "},{"r":"しん","t":"親"},{"t":"の"},{"r":"しんぱい","t":"心配"},{"t":"をよそに"},{"t":" says the worry was left in another place and walked away from, which is why the pattern always carries a hint of reproach."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '764ec6c9c0e0b2fca44568dd200500959c92755d24d26082cba502576d490ed4' AND l.code = 'ja'
  AND g.segments = '[{"t":"よそ"},{"r":"み","t":"見"},{"t":" is looking away; "},{"t":"よその"},{"r":"と","t":"人"},{"t":" is an outsider. "},{"t":"をよそに"},{"t":" puts the thing named somewhere other than where the actor is attending.\n\nSo the disregard is spatial before it is moral. "},{"r":"しん","t":"親"},{"t":"の"},{"r":"しんぱい","t":"心配"},{"t":"をよそに"},{"t":" says the worry was left in another place and walked away from, which is why the pattern always carries a hint of reproach."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜をはじめ: 連用形
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-a3ea3a33005336bc', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The 連用形 used as a noun, the same shape as 限り and 通り. What it names is the leading example, and the rest follow from it.\n\nThat is the difference from 皮切りに, which needs the thing to spread outward, and from ばかりか, which escalates. をはじめ ranks: 社長をはじめ全員 names the most important and sweeps in the others behind.","point":"〜をはじめ","before":[{"t":"The "},{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"},{"t":" used as a noun, the same shape as "},{"t":"限","r":"かぎ"},{"t":"り"},{"t":" and "},{"t":"通","r":"とお"},{"t":"り"},{"t":". What it names is the leading example, and the rest follow from it.\n\nThat is the difference from "},{"t":"皮","r":"かわ"},{"t":"切","r":"き"},{"t":"りに"},{"t":", which needs the thing to spread outward, and from "},{"t":"ばかりか"},{"t":", which escalates. "},{"t":"をはじめ"},{"t":" ranks: "},{"t":"社長","r":"しゃちょう"},{"t":"をはじめ"},{"t":"全員","r":"ぜんいん"},{"t":" names the most important and sweeps in the others behind."}],"after":[{"t":"The "},{"t":"連用形","r":"れんようけい"},{"t":" used as a noun, the same shape as "},{"t":"限","r":"かぎ"},{"t":"り"},{"t":" and "},{"t":"通","r":"とお"},{"t":"り"},{"t":". What it names is the leading example, and the rest follow from it.\n\nThat is the difference from "},{"t":"皮","r":"かわ"},{"t":"切","r":"き"},{"t":"りに"},{"t":", which needs the thing to spread outward, and from "},{"t":"ばかりか"},{"t":", which escalates. "},{"t":"をはじめ"},{"t":" ranks: "},{"t":"社長","r":"しゃちょう"},{"t":"をはじめ"},{"t":"全員","r":"ぜんいん"},{"t":" names the most important and sweeps in the others behind."}],"changes":[{"word":"連用形","from":[{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"}],"to":[{"t":"連用形","r":"れんようけい"}],"why":"Grammar term 連用形 is れんようけい."}]}'::jsonb, '{"furigana":[{"t":"The "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" used as a noun, the same shape as "},{"r":"かぎ","t":"限"},{"t":"り"},{"t":" and "},{"r":"とお","t":"通"},{"t":"り"},{"t":". What it names is the leading example, and the rest follow from it.\n\nThat is the difference from "},{"r":"かわ","t":"皮"},{"r":"き","t":"切"},{"t":"りに"},{"t":", which needs the thing to spread outward, and from "},{"t":"ばかりか"},{"t":", which escalates. "},{"t":"をはじめ"},{"t":" ranks: "},{"r":"しゃちょう","t":"社長"},{"t":"をはじめ"},{"r":"ぜんいん","t":"全員"},{"t":" names the most important and sweeps in the others behind."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'a3ea3a33005336bc0f75fb09f225cb12ccd0d4697f492542dd1dff719d0e345f' AND l.code = 'ja'
  AND g.segments = '[{"t":"The "},{"r":"つ","t":"連"},{"r":"よう","t":"用"},{"r":"なり","t":"形"},{"t":" used as a noun, the same shape as "},{"r":"かぎ","t":"限"},{"t":"り"},{"t":" and "},{"r":"とお","t":"通"},{"t":"り"},{"t":". What it names is the leading example, and the rest follow from it.\n\nThat is the difference from "},{"r":"かわ","t":"皮"},{"r":"き","t":"切"},{"t":"りに"},{"t":", which needs the thing to spread outward, and from "},{"t":"ばかりか"},{"t":", which escalates. "},{"t":"をはじめ"},{"t":" ranks: "},{"r":"しゃちょう","t":"社長"},{"t":"をはじめ"},{"r":"ぜんいん","t":"全員"},{"t":" names the most important and sweeps in the others behind."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜一方で: 反面
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-bb40d1a42b822a7a', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"方 is the same 方 as ほうが and 〜方: a side or direction. 一方 names one of them and leaves the other implied.\n\nThat is why 一方で can set two quite separate matters beside each other while 反面 cannot; sides do not have to belong to the same object. And 一方 alone at the head of a sentence works as \"meanwhile\", the other side of the story.","point":"〜一方で","before":[{"t":"方","r":"かた"},{"t":" is the same "},{"t":"方","r":"かた"},{"t":" as "},{"t":"ほうが"},{"t":" and 〜"},{"t":"方","r":"かた"},{"t":": a side or direction. "},{"t":"一方","r":"いっぽう"},{"t":" names one of them and leaves the other implied.\n\nThat is why "},{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":" can set two quite separate matters beside each other while "},{"t":"反","r":"たん"},{"t":"面","r":"づら"},{"t":" cannot; sides do not have to belong to the same object. And "},{"t":"一方","r":"いっぽう"},{"t":" alone at the head of a sentence works as \"meanwhile\", the other side of the story."}],"after":[{"t":"方","r":"かた"},{"t":" is the same "},{"t":"方","r":"かた"},{"t":" as "},{"t":"ほうが"},{"t":" and 〜"},{"t":"方","r":"かた"},{"t":": a side or direction. "},{"t":"一方","r":"いっぽう"},{"t":" names one of them and leaves the other implied.\n\nThat is why "},{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":" can set two quite separate matters beside each other while "},{"t":"反面","r":"はんめん"},{"t":" cannot; sides do not have to belong to the same object. And "},{"t":"一方","r":"いっぽう"},{"t":" alone at the head of a sentence works as \"meanwhile\", the other side of the story."}],"changes":[{"word":"反面","from":[{"t":"反","r":"たん"},{"t":"面","r":"づら"}],"to":[{"t":"反面","r":"はんめん"}],"why":"反面 is はんめん."}]}'::jsonb, '{"furigana":[{"r":"かた","t":"方"},{"t":" is the same "},{"r":"かた","t":"方"},{"t":" as "},{"t":"ほうが"},{"t":" and 〜"},{"r":"かた","t":"方"},{"t":": a side or direction. "},{"r":"いっぽう","t":"一方"},{"t":" names one of them and leaves the other implied.\n\nThat is why "},{"r":"いっぽう","t":"一方"},{"t":"で"},{"t":" can set two quite separate matters beside each other while "},{"r":"たん","t":"反"},{"r":"づら","t":"面"},{"t":" cannot; sides do not have to belong to the same object. And "},{"r":"いっぽう","t":"一方"},{"t":" alone at the head of a sentence works as \"meanwhile\", the other side of the story."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = 'bb40d1a42b822a7a7e2eb81232d7a817175dc4551cfa1a12e6ba65296b215ade' AND l.code = 'ja'
  AND g.segments = '[{"r":"かた","t":"方"},{"t":" is the same "},{"r":"かた","t":"方"},{"t":" as "},{"t":"ほうが"},{"t":" and 〜"},{"r":"かた","t":"方"},{"t":": a side or direction. "},{"r":"いっぽう","t":"一方"},{"t":" names one of them and leaves the other implied.\n\nThat is why "},{"r":"いっぽう","t":"一方"},{"t":"で"},{"t":" can set two quite separate matters beside each other while "},{"r":"たん","t":"反"},{"r":"づら","t":"面"},{"t":" cannot; sides do not have to belong to the same object. And "},{"r":"いっぽう","t":"一方"},{"t":" alone at the head of a sentence works as \"meanwhile\", the other side of the story."}]'::jsonb
  AND NOT EXISTS (SELECT 1 FROM content_review_queue c WHERE c.target_table = 'grammar_furigana' AND c.target_id = g.text_hash AND c.status = 'pending')
ON CONFLICT DO NOTHING;

-- 〜の中 / 上 / 下 / 前 / 後ろ: 前 and
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-22d01690069f823b', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"上, 下, 中, 前 and 後ろ are nouns, not prepositions, which is why they take の.","point":"〜の中 / 上 / 下 / 前 / 後ろ","before":[{"t":"上","r":"うえ"},{"t":", "},{"t":"下","r":"した"},{"t":", "},{"t":"中","r":"なか"},{"t":", "},{"t":"前","r":"ぜん"},{"t":" and "},{"t":"後","r":"うし"},{"t":"ろ"},{"t":" are nouns, not prepositions, which is why they take "},{"t":"の"},{"t":"."}],"after":[{"t":"上","r":"うえ"},{"t":", "},{"t":"下","r":"した"},{"t":", "},{"t":"中","r":"なか"},{"t":", "},{"t":"前","r":"まえ"},{"t":" and"},{"t":" "},{"t":"後","r":"うし"},{"t":"ろ"},{"t":" are nouns, not prepositions, which is why they take "},{"t":"の"},{"t":"."}],"changes":[{"word":"前 and","from":[{"t":"前","r":"ぜん"},{"t":" and"}],"to":[{"t":"前","r":"まえ"},{"t":" and"}],"why":"前 here is まえ."}]}'::jsonb, '{"furigana":[{"r":"うえ","t":"上"},{"t":", "},{"r":"した","t":"下"},{"t":", "},{"r":"なか","t":"中"},{"t":", "},{"r":"ぜん","t":"前"},{"t":" and "},{"r":"うし","t":"後"},{"t":"ろ"},{"t":" are nouns, not prepositions, which is why they take "},{"t":"の"},{"t":"."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
