-- 〜の中 / 上 / 下 / 前 / 後ろ: 東京
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-e0dae410a66bef53', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"机の上 is literally \"the table''s top\". Japanese has no prepositions at all; it names a part of the thing and possesses it.\n\nSo 上に is a noun with に, exactly like 東京に, and the whole system works by ordinary grammar. It is also why the position word comes after the thing it belongs to, which is the reverse of English and consistent with everything else in the language.","point":"〜の中 / 上 / 下 / 前 / 後ろ","before":[{"t":"机","r":"つくえ"},{"t":"の"},{"t":"上","r":"うえ"},{"t":" is literally \"the table''s top\". Japanese has no prepositions at all; it names a part of the thing and possesses it.\n\nSo "},{"t":"上","r":"うえ"},{"t":"に"},{"t":" is a noun with "},{"t":"に"},{"t":", exactly like "},{"t":"東","r":"とん"},{"t":"京に"},{"t":", and the whole system works by ordinary grammar. It is also why the position word comes after the thing it belongs to, which is the reverse of English and consistent with everything else in the language."}],"after":[{"t":"机","r":"つくえ"},{"t":"の"},{"t":"上","r":"うえ"},{"t":" is literally \"the table''s top\". Japanese has no prepositions at all; it names a part of the thing and possesses it.\n\nSo "},{"t":"上","r":"うえ"},{"t":"に"},{"t":" is a noun with "},{"t":"に"},{"t":", exactly like "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":", and the whole system works by ordinary grammar. It is also why the position word comes after the thing it belongs to, which is the reverse of English and consistent with everything else in the language."}],"changes":[{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."}]}'::jsonb, '{"furigana":[{"r":"つくえ","t":"机"},{"t":"の"},{"r":"うえ","t":"上"},{"t":" is literally \"the table''s top\". Japanese has no prepositions at all; it names a part of the thing and possesses it.\n\nSo "},{"r":"うえ","t":"上"},{"t":"に"},{"t":" is a noun with "},{"t":"に"},{"t":", exactly like "},{"r":"とん","t":"東"},{"t":"京に"},{"t":", and the whole system works by ordinary grammar. It is also why the position word comes after the thing it belongs to, which is the reverse of English and consistent with everything else in the language."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
