-- 〜予定: The same 予
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-f1bed9da5aced5f1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same 予 as in 予約 and 予習. What makes 予定 different from つもり is in those characters: something has been fixed, by a timetable or by someone else, rather than intended by you.\n\nWhich is why 予定 takes の after a noun and behaves as the plain noun it is (会議の予定), and why it sounds odd for a private wish that nobody has arranged.","point":"〜予定","before":[{"t":"The same "},{"t":"予","r":"かね"},{"t":" as in "},{"t":"予約","r":"よやく"},{"t":" and "},{"t":"予習","r":"よしゅう"},{"t":". What makes "},{"t":"予定","r":"よてい"},{"t":" different from "},{"t":"つもり"},{"t":" is in those characters: something has been fixed, by a timetable or by someone else, rather than intended by you.\n\nWhich is why "},{"t":"予定","r":"よてい"},{"t":" takes "},{"t":"の"},{"t":" after a noun and behaves as the plain noun it is ("},{"t":"会議","r":"かいぎ"},{"t":"の"},{"t":"予定","r":"よてい"},{"t":"), and why it sounds odd for a private wish that nobody has arranged."}],"after":[{"t":"The same 予","r":"よ"},{"t":" as in "},{"t":"予約","r":"よやく"},{"t":" and "},{"t":"予習","r":"よしゅう"},{"t":". What makes "},{"t":"予定","r":"よてい"},{"t":" different from "},{"t":"つもり"},{"t":" is in those characters: something has been fixed, by a timetable or by someone else, rather than intended by you.\n\nWhich is why "},{"t":"予定","r":"よてい"},{"t":" takes "},{"t":"の"},{"t":" after a noun and behaves as the plain noun it is ("},{"t":"会議","r":"かいぎ"},{"t":"の"},{"t":"予定","r":"よてい"},{"t":"), and why it sounds odd for a private wish that nobody has arranged."}],"changes":[{"word":"The same 予","from":[{"t":"The same "},{"t":"予","r":"かね"}],"to":[{"t":"The same 予","r":"よ"}],"why":"予 here is よ."}]}'::jsonb, '{"furigana":[{"t":"The same "},{"r":"かね","t":"予"},{"t":" as in "},{"r":"よやく","t":"予約"},{"t":" and "},{"r":"よしゅう","t":"予習"},{"t":". What makes "},{"r":"よてい","t":"予定"},{"t":" different from "},{"t":"つもり"},{"t":" is in those characters: something has been fixed, by a timetable or by someone else, rather than intended by you.\n\nWhich is why "},{"r":"よてい","t":"予定"},{"t":" takes "},{"t":"の"},{"t":" after a noun and behaves as the plain noun it is ("},{"r":"かいぎ","t":"会議"},{"t":"の"},{"r":"よてい","t":"予定"},{"t":"), and why it sounds odd for a private wish that nobody has arranged."}]}'::jsonb, 'ai', 900, 'pending'
