-- 〜に伴って: 同伴, 伴奏
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-45bb90eba92fc9f7', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The same なう as in 損なう and 商う. 伴 is a kanji fitted to it afterwards; the ハン of 同伴 and 伴奏 is the unrelated Chinese reading of that character.\n\nに伴って sets two changes travelling in company. It sits with につれて and にしたがって as three ways of pairing change, each from a different image (連れる leads along, 従う follows, 伴う merely accompanies), and 伴う is the most neutral, which is why it suits reports and statistics.","point":"〜に伴って","before":[{"t":"The same "},{"t":"なう"},{"t":" as in "},{"t":"損","r":"そこ"},{"t":"なう"},{"t":" and "},{"t":"商う"},{"t":". "},{"t":"伴","r":"ともな"},{"t":" is a kanji fitted to it afterwards; the "},{"t":"ハン"},{"t":" of "},{"t":"同","r":"おな"},{"t":"伴","r":"ともな"},{"t":" and "},{"t":"伴","r":"ともな"},{"t":"奏"},{"t":" is the unrelated Chinese reading of that character.\n\n"},{"t":"に"},{"t":"伴","r":"ともな"},{"t":"って"},{"t":" sets two changes travelling in company. It sits with "},{"t":"につれて"},{"t":" and "},{"t":"にしたがって"},{"t":" as three ways of pairing change, each from a different image ("},{"t":"連","r":"つ"},{"t":"れる"},{"t":" leads along, "},{"t":"従","r":"したが"},{"t":"う"},{"t":" follows, "},{"t":"伴","r":"ともな"},{"t":"う"},{"t":" merely accompanies), and "},{"t":"伴","r":"ともな"},{"t":"う"},{"t":" is the most neutral, which is why it suits reports and statistics."}],"after":[{"t":"The same "},{"t":"なう"},{"t":" as in "},{"t":"損","r":"そこ"},{"t":"なう"},{"t":" and "},{"t":"商う"},{"t":". "},{"t":"伴","r":"ともな"},{"t":" is a kanji fitted to it afterwards; the "},{"t":"ハン"},{"t":" of "},{"t":"同伴","r":"どうはん"},{"t":" and "},{"t":"伴奏","r":"ばんそう"},{"t":" is the unrelated Chinese reading of that character.\n\n"},{"t":"に"},{"t":"伴","r":"ともな"},{"t":"って"},{"t":" sets two changes travelling in company. It sits with "},{"t":"につれて"},{"t":" and "},{"t":"にしたがって"},{"t":" as three ways of pairing change, each from a different image ("},{"t":"連","r":"つ"},{"t":"れる"},{"t":" leads along, "},{"t":"従","r":"したが"},{"t":"う"},{"t":" follows, "},{"t":"伴","r":"ともな"},{"t":"う"},{"t":" merely accompanies), and "},{"t":"伴","r":"ともな"},{"t":"う"},{"t":" is the most neutral, which is why it suits reports and statistics."}],"changes":[{"word":"同伴","from":[{"t":"同","r":"おな"},{"t":"伴","r":"ともな"}],"to":[{"t":"同伴","r":"どうはん"}],"why":"Compound is どうはん."},{"word":"伴奏","from":[{"t":"伴","r":"ともな"},{"t":"奏"}],"to":[{"t":"伴奏","r":"ばんそう"}],"why":"Compound is ばんそう."}]}'::jsonb, '{"furigana":[{"t":"The same "},{"t":"なう"},{"t":" as in "},{"r":"そこ","t":"損"},{"t":"なう"},{"t":" and "},{"t":"商う"},{"t":". "},{"r":"ともな","t":"伴"},{"t":" is a kanji fitted to it afterwards; the "},{"t":"ハン"},{"t":" of "},{"r":"おな","t":"同"},{"r":"ともな","t":"伴"},{"t":" and "},{"r":"ともな","t":"伴"},{"t":"奏"},{"t":" is the unrelated Chinese reading of that character.\n\n"},{"t":"に"},{"r":"ともな","t":"伴"},{"t":"って"},{"t":" sets two changes travelling in company. It sits with "},{"t":"につれて"},{"t":" and "},{"t":"にしたがって"},{"t":" as three ways of pairing change, each from a different image ("},{"r":"つ","t":"連"},{"t":"れる"},{"t":" leads along, "},{"r":"したが","t":"従"},{"t":"う"},{"t":" follows, "},{"r":"ともな","t":"伴"},{"t":"う"},{"t":" merely accompanies), and "},{"r":"ともな","t":"伴"},{"t":"う"},{"t":" is the most neutral, which is why it suits reports and statistics."}]}'::jsonb, 'ai', 900, 'pending'
