  AND g.segments = '[{"t":"The same "},{"t":"なう"},{"t":" as in "},{"r":"そこ","t":"損"},{"t":"なう"},{"t":" and "},{"t":"商う"},{"t":". "},{"r":"ともな","t":"伴"},{"t":" is a kanji fitted to it afterwards; the "},{"t":"ハン"},{"t":" of "},{"r":"おな","t":"同"},{"r":"ともな","t":"伴"},{"t":" and "},{"r":"ともな","t":"伴"},{"t":"奏"},{"t":" is the unrelated Chinese reading of that character.\n\n"},{"t":"に"},{"r":"ともな","t":"伴"},{"t":"って"},{"t":" sets two changes travelling in company. It sits with "},{"t":"につれて"},{"t":" and "},{"t":"にしたがって"},{"t":" as three ways of pairing change, each from a different image ("},{"r":"つ","t":"連"},{"t":"れる"},{"t":" leads along, "},{"r":"したが","t":"従"},{"t":"う"},{"t":" follows, "},{"r":"ともな","t":"伴"},{"t":"う"},{"t":" merely accompanies), and "},{"r":"ともな","t":"伴"},{"t":"う"},{"t":" is the most neutral, which is why it suits reports and statistics."}]'::jsonb
