-- 〜を余儀なくされる: 余儀, 余儀, 余儀
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-97fd7369d09cc9ae', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"余 is the 余 of 余る, what is left over; 儀 is a matter or a manner. 余儀 is the other course available, and 余儀ない says there is not one.\n\nThe passive then supplies who was left without it: 中止を余儀なくされた is being put in a position where no other course remained. Nobody in the sentence chose anything, which is why the construction is the language of disasters and closures.","point":"〜を余儀なくされる","before":[{"t":"余","r":"あま"},{"t":" is the "},{"t":"余","r":"あま"},{"t":" of "},{"t":"余","r":"あま"},{"t":"る"},{"t":", what is left over; "},{"t":"儀"},{"t":" is a matter or a manner. "},{"t":"余","r":"あま"},{"t":"儀"},{"t":" is the other course available, and "},{"t":"余","r":"あま"},{"t":"儀ない"},{"t":" says there is not one.\n\nThe passive then supplies who was left without it: "},{"t":"中止","r":"ちゅうし"},{"t":"を"},{"t":"余","r":"あま"},{"t":"儀なくされた"},{"t":" is being put in a position where no other course remained. Nobody in the sentence chose anything, which is why the construction is the language of disasters and closures."}],"after":[{"t":"余","r":"あま"},{"t":" is the "},{"t":"余","r":"あま"},{"t":" of "},{"t":"余","r":"あま"},{"t":"る"},{"t":", what is left over; "},{"t":"儀"},{"t":" is a matter or a manner. "},{"t":"余儀","r":"よぎ"},{"t":" is the other course available, and "},{"t":"余儀","r":"よぎ"},{"t":"ない"},{"t":" says there is not one.\n\nThe passive then supplies who was left without it: "},{"t":"中止","r":"ちゅうし"},{"t":"を"},{"t":"余儀","r":"よぎ"},{"t":"なくされた"},{"t":" is being put in a position where no other course remained. Nobody in the sentence chose anything, which is why the construction is the language of disasters and closures."}],"changes":[{"word":"余儀","from":[{"t":"余","r":"あま"},{"t":"儀"}],"to":[{"t":"余儀","r":"よぎ"}],"why":"Compound is よぎ. / 余儀 is よぎ."},{"word":"余儀","from":[{"t":"余","r":"あま"},{"t":"儀"}],"to":[{"t":"余儀","r":"よぎ"}],"why":"Compound is よぎ. / 余儀 is よぎ."},{"word":"余儀","from":[{"t":"余","r":"あま"},{"t":"儀"}],"to":[{"t":"余儀","r":"よぎ"}],"why":"Compound is よぎ. / 余儀 is よぎ."}]}'::jsonb, '{"furigana":[{"r":"あま","t":"余"},{"t":" is the "},{"r":"あま","t":"余"},{"t":" of "},{"r":"あま","t":"余"},{"t":"る"},{"t":", what is left over; "},{"t":"儀"},{"t":" is a matter or a manner. "},{"r":"あま","t":"余"},{"t":"儀"},{"t":" is the other course available, and "},{"r":"あま","t":"余"},{"t":"儀ない"},{"t":" says there is not one.\n\nThe passive then supplies who was left without it: "},{"r":"ちゅうし","t":"中止"},{"t":"を"},{"r":"あま","t":"余"},{"t":"儀なくされた"},{"t":" is being put in a position where no other course remained. Nobody in the sentence chose anything, which is why the construction is the language of disasters and closures."}]}'::jsonb, 'ai', 900, 'pending'
