  AND g.segments = '[{"r":"で","t":"出"},{"t":"る"},{"t":" plus "},{"r":"く","t":"来"},{"t":"る"},{"t":". Before it meant \"can\", "},{"r":"で","t":"出"},{"r":"く","t":"来"},{"t":"る"},{"t":" meant something was produced or came about, a sense still plain in "},{"r":"できあ","t":"出来上"},{"t":"がる"},{"t":" and in "},{"r":"できごと","t":"出来事"},{"t":", \"an occurrence\".\n\nSo "},{"r":"はな","t":"話"},{"t":"すことができる"},{"t":" says the speaking-of-it comes about. That is a whole noun phrase with a verb after it, not an ending on a verb, and it is why the construction is the formal one: it takes the long way round, naming the act before saying it is possible."}]'::jsonb
