SELECT 'crq-grammar-9230bf77454fcace', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A plain Sino-Japanese verb meaning to go against. に反して sets the outcome facing the wrong way from what was named.\n\nIt wants an expectation, a rule or a prediction to contradict (予想に反して, 規則に反して) because only those are things a result can run counter to. A mere alternative gives it nothing to oppose.","point":"〜に反して","before":[{"t":"A plain Sino-Japanese verb meaning to go against. "},{"t":"に"},{"t":"反","r":"たん"},{"t":"して"},{"t":" sets the outcome facing the wrong way from what was named.\n\nIt wants an expectation, a rule or a prediction to contradict ("},{"t":"予想","r":"よそう"},{"t":"に"},{"t":"反","r":"たん"},{"t":"して"},{"t":", "},{"t":"規則","r":"きそく"},{"t":"に"},{"t":"反","r":"たん"},{"t":"して"},{"t":") because only those are things a result can run counter to. A mere alternative gives it nothing to oppose."}],"after":[{"t":"A plain Sino-Japanese verb meaning to go against. "},{"t":"に"},{"t":"反","r":"はん"},{"t":"して"},{"t":" sets the outcome facing the wrong way from what was named.\n\nIt wants an expectation, a rule or a prediction to contradict ("},{"t":"予想","r":"よそう"},{"t":"に"},{"t":"反","r":"はん"},{"t":"して"},{"t":", "},{"t":"規則","r":"きそく"},{"t":"に"},{"t":"反","r":"はん"},{"t":"して"},{"t":") because only those are things a result can run counter to. A mere alternative gives it nothing to oppose."}],"changes":[{"word":"反して","from":[{"t":"反","r":"たん"},{"t":"して"}],"to":[{"t":"反","r":"はん"},{"t":"して"}],"why":"に反して is はんして."},{"word":"反して","from":[{"t":"反","r":"たん"},{"t":"して"}],"to":[{"t":"反","r":"はん"},{"t":"して"}],"why":"に反して is はんして."},{"word":"反して","from":[{"t":"反","r":"たん"},{"t":"して"}],"to":[{"t":"反","r":"はん"},{"t":"して"}],"why":"に反して is はんして."}]}'::jsonb, '{"furigana":[{"t":"A plain Sino-Japanese verb meaning to go against. "},{"t":"に"},{"r":"たん","t":"反"},{"t":"して"},{"t":" sets the outcome facing the wrong way from what was named.\n\nIt wants an expectation, a rule or a prediction to contradict ("},{"r":"よそう","t":"予想"},{"t":"に"},{"r":"たん","t":"反"},{"t":"して"},{"t":", "},{"r":"きそく","t":"規則"},{"t":"に"},{"r":"たん","t":"反"},{"t":"して"},{"t":") because only those are things a result can run counter to. A mere alternative gives it nothing to oppose."}]}'::jsonb, 'ai', 900, 'pending'
