INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-09f0908730b4b0d5', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Where 極まりない denies that a peak exists, の極み names it and puts the thing on top of it. 贅沢の極み is the very peak of luxury.\n\nOne kanji, two patterns, opposite constructions: the negated verb says there is no limit, the plain noun says here is the limit and this is it.","point":"〜の極み","before":[{"t":"Where "},{"t":"極","r":"ごく"},{"t":"まりない"},{"t":" denies that a peak exists, "},{"t":"の"},{"t":"極","r":"ごく"},{"t":"み"},{"t":" names it and puts the thing on top of it. "},{"t":"贅沢","r":"ぜいたく"},{"t":"の"},{"t":"極","r":"ごく"},{"t":"み"},{"t":" is the very peak of luxury.\n\nOne kanji, two patterns, opposite constructions: the negated verb says there is no limit, the plain noun says here is the limit and this is it."}],"after":[{"t":"Where "},{"t":"極","r":"きわ"},{"t":"まりない"},{"t":" denies that a peak exists, "},{"t":"の"},{"t":"極","r":"きわ"},{"t":"み"},{"t":" names it and puts the thing on top of it. "},{"t":"贅沢","r":"ぜいたく"},{"t":"の"},{"t":"極","r":"きわ"},{"t":"み"},{"t":" is the very peak of luxury.\n\nOne kanji, two patterns, opposite constructions: the negated verb says there is no limit, the plain noun says here is the limit and this is it."}],"changes":[{"word":"極まりない","from":[{"t":"極","r":"ごく"},{"t":"まりない"}],"to":[{"t":"極","r":"きわ"},{"t":"まりない"}],"why":"The verb 極まる is きわまる."},{"word":"極み","from":[{"t":"極","r":"ごく"},{"t":"み"}],"to":[{"t":"極","r":"きわ"},{"t":"み"}],"why":"極み is きわみ."},{"word":"極み","from":[{"t":"極","r":"ごく"},{"t":"み"}],"to":[{"t":"極","r":"きわ"},{"t":"み"}],"why":"極み is きわみ."}]}'::jsonb, '{"furigana":[{"t":"Where "},{"r":"ごく","t":"極"},{"t":"まりない"},{"t":" denies that a peak exists, "},{"t":"の"},{"r":"ごく","t":"極"},{"t":"み"},{"t":" names it and puts the thing on top of it. "},{"r":"ぜいたく","t":"贅沢"},{"t":"の"},{"r":"ごく","t":"極"},{"t":"み"},{"t":" is the very peak of luxury.\n\nOne kanji, two patterns, opposite constructions: the negated verb says there is no limit, the plain noun says here is the limit and this is it."}]}'::jsonb, 'ai', 900, 'pending'
