-- 〜反面: 反面, 反面, 反面
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-68e68c998cc623d9', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"A noun naming the other side of the same thing. That is what makes it different from 一方で.\n\n反面 needs the two halves to belong to one subject: 便利な反面、高い describes a single object from two faces. 一方で can hold two separate things apart. Using 反面 for two different subjects is the mistake the kanji predicts.","point":"〜反面","before":[{"t":"A noun naming the other side of the same thing. That is what makes it different from "},{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":".\n\n"},{"t":"反","r":"たん"},{"t":"面","r":"づら"},{"t":" needs the two halves to belong to one subject: "},{"t":"便利","r":"べんり"},{"t":"な"},{"t":"反","r":"たん"},{"t":"面","r":"づら"},{"t":"、"},{"t":"高","r":"たか"},{"t":"い"},{"t":" describes a single object from two faces. "},{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":" can hold two separate things apart. Using "},{"t":"反","r":"たん"},{"t":"面","r":"づら"},{"t":" for two different subjects is the mistake the kanji predicts."}],"after":[{"t":"A noun naming the other side of the same thing. That is what makes it different from "},{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":".\n\n"},{"t":"反面","r":"はんめん"},{"t":" needs the two halves to belong to one subject: "},{"t":"便利","r":"べんり"},{"t":"な"},{"t":"反面","r":"はんめん"},{"t":"、"},{"t":"高","r":"たか"},{"t":"い"},{"t":" describes a single object from two faces. "},{"t":"一方","r":"いっぽう"},{"t":"で"},{"t":" can hold two separate things apart. Using "},{"t":"反面","r":"はんめん"},{"t":" for two different subjects is the mistake the kanji predicts."}],"changes":[{"word":"反面","from":[{"t":"反","r":"たん"},{"t":"面","r":"づら"}],"to":[{"t":"反面","r":"はんめん"}],"why":"反面 is はんめん."},{"word":"反面","from":[{"t":"反","r":"たん"},{"t":"面","r":"づら"}],"to":[{"t":"反面","r":"はんめん"}],"why":"反面 is はんめん."},{"word":"反面","from":[{"t":"反","r":"たん"},{"t":"面","r":"づら"}],"to":[{"t":"反面","r":"はんめん"}],"why":"反面 is はんめん."}]}'::jsonb, '{"furigana":[{"t":"A noun naming the other side of the same thing. That is what makes it different from "},{"r":"いっぽう","t":"一方"},{"t":"で"},{"t":".\n\n"},{"r":"たん","t":"反"},{"r":"づら","t":"面"},{"t":" needs the two halves to belong to one subject: "},{"r":"べんり","t":"便利"},{"t":"な"},{"r":"たん","t":"反"},{"r":"づら","t":"面"},{"t":"、"},{"r":"たか","t":"高"},{"t":"い"},{"t":" describes a single object from two faces. "},{"r":"いっぽう","t":"一方"},{"t":"で"},{"t":" can hold two separate things apart. Using "},{"r":"たん","t":"反"},{"r":"づら","t":"面"},{"t":" for two different subjects is the mistake the kanji predicts."}]}'::jsonb, 'ai', 900, 'pending'
