INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-6d0ea399b3f1ef62', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Both halves are kun readings: ば is 場 read natively (its on-reading is ジョウ), and あい is from 合う. The situation where things come together, written in kanji but Japanese underneath.\n\nIt names a situation as a thing, which is why a clause in front modifies it as it would any noun and a noun needs の: 火事の場合. That noun-ness is the difference from たら (たら supposes an occasion, 場合 names one), and it is why it belongs to notices and rules.","point":"〜場合","before":[{"t":"Both halves are kun readings: "},{"t":"ば"},{"t":" is "},{"t":"場","r":"ば"},{"t":" read natively (its on-reading is "},{"t":"ジョウ"},{"t":"), and "},{"t":"あい"},{"t":" is from "},{"t":"合","r":"あ"},{"t":"う"},{"t":". The situation where things come together, written in kanji but Japanese underneath.\n\nIt names a situation as a thing, which is why a clause in front modifies it as it would any noun and a noun needs "},{"t":"の"},{"t":": "},{"t":"火事","r":"かじ"},{"t":"の"},{"t":"場合","r":"ばやい"},{"t":". That noun-ness is the difference from "},{"t":"たら"},{"t":" ("},{"t":"たら"},{"t":" supposes an occasion, "},{"t":"場合","r":"ばやい"},{"t":" names one), and it is why it belongs to notices and rules."}],"after":[{"t":"Both halves are kun readings: "},{"t":"ば"},{"t":" is "},{"t":"場","r":"ば"},{"t":" read natively (its on-reading is "},{"t":"ジョウ"},{"t":"), and "},{"t":"あい"},{"t":" is from "},{"t":"合","r":"あ"},{"t":"う"},{"t":". The situation where things come together, written in kanji but Japanese underneath.\n\nIt names a situation as a thing, which is why a clause in front modifies it as it would any noun and a noun needs "},{"t":"の"},{"t":": "},{"t":"火事","r":"かじ"},{"t":"の"},{"t":"場合","r":"ばあい"},{"t":". That noun-ness is the difference from "},{"t":"たら"},{"t":" ("},{"t":"たら"},{"t":" supposes an occasion, "},{"t":"場合","r":"ばあい"},{"t":" names one), and it is why it belongs to notices and rules."}],"changes":[{"word":"場合","from":[{"t":"場合","r":"ばやい"}],"to":[{"t":"場合","r":"ばあい"}],"why":"場合 is ばあい."},{"word":"場合","from":[{"t":"場合","r":"ばやい"}],"to":[{"t":"場合","r":"ばあい"}],"why":"場合 is ばあい."}]}'::jsonb, '{"furigana":[{"t":"Both halves are kun readings: "},{"t":"ば"},{"t":" is "},{"r":"ば","t":"場"},{"t":" read natively (its on-reading is "},{"t":"ジョウ"},{"t":"), and "},{"t":"あい"},{"t":" is from "},{"r":"あ","t":"合"},{"t":"う"},{"t":". The situation where things come together, written in kanji but Japanese underneath.\n\nIt names a situation as a thing, which is why a clause in front modifies it as it would any noun and a noun needs "},{"t":"の"},{"t":": "},{"r":"かじ","t":"火事"},{"t":"の"},{"r":"ばやい","t":"場合"},{"t":". That noun-ness is the difference from "},{"t":"たら"},{"t":" ("},{"t":"たら"},{"t":" supposes an occasion, "},{"r":"ばやい","t":"場合"},{"t":" names one), and it is why it belongs to notices and rules."}]}'::jsonb, 'ai', 900, 'pending'
