SELECT 'crq-grammar-d3e3d9430eb669c0', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The noun means how something turned out, and it survives in 始末書, the written account of an incident you are answerable for.\n\nBecause it names the entire course, 始末だ always follows a stated sequence of events and delivers the verdict on it. And because you only write a 始末書 when things went wrong, the verdict is always bad.","point":"〜始末だ","before":[{"t":"The noun means how something turned out, and it survives in "},{"t":"始末","r":"しまつ"},{"t":"書","r":"か"},{"t":", the written account of an incident you are answerable for.\n\nBecause it names the entire course, "},{"t":"始末","r":"しまつ"},{"t":"だ"},{"t":" always follows a stated sequence of events and delivers the verdict on it. And because you only write a "},{"t":"始末","r":"しまつ"},{"t":"書","r":"か"},{"t":" when things went wrong, the verdict is always bad."}],"after":[{"t":"The noun means how something turned out, and it survives in "},{"t":"始末書","r":"しまつしょ"},{"t":", the written account of an incident you are answerable for.\n\nBecause it names the entire course, "},{"t":"始末","r":"しまつ"},{"t":"だ"},{"t":" always follows a stated sequence of events and delivers the verdict on it. And because you only write a "},{"t":"始末書","r":"しまつしょ"},{"t":" when things went wrong, the verdict is always bad."}],"changes":[{"word":"始末書","from":[{"t":"始末","r":"しまつ"},{"t":"書","r":"か"}],"to":[{"t":"始末書","r":"しまつしょ"}],"why":"Compound is しまつしょ."},{"word":"始末書","from":[{"t":"始末","r":"しまつ"},{"t":"書","r":"か"}],"to":[{"t":"始末書","r":"しまつしょ"}],"why":"Compound is しまつしょ."}]}'::jsonb, '{"furigana":[{"t":"The noun means how something turned out, and it survives in "},{"r":"しまつ","t":"始末"},{"r":"か","t":"書"},{"t":", the written account of an incident you are answerable for.\n\nBecause it names the entire course, "},{"r":"しまつ","t":"始末"},{"t":"だ"},{"t":" always follows a stated sequence of events and delivers the verdict on it. And because you only write a "},{"r":"しまつ","t":"始末"},{"r":"か","t":"書"},{"t":" when things went wrong, the verdict is always bad."}]}'::jsonb, 'ai', 900, 'pending'
