SELECT 'crq-grammar-881c15cce2a18525', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"The noun in 末っ子 and 週末. 末に puts the outcome at the far end of a long stretch.\n\nSo it needs the stretch. 悩んだ末に決めた works because the worrying went on; a quick decision has no 末 to arrive at. Unlike あげく, 末 passes no judgement on how it turned out.","point":"〜末に","before":[{"t":"The noun in "},{"t":"末","r":"すえ"},{"t":"っ"},{"t":"子","r":"こ"},{"t":" and "},{"t":"週","r":"しゅう"},{"t":"末","r":"うれ"},{"t":". "},{"t":"末","r":"うれ"},{"t":"に"},{"t":" puts the outcome at the far end of a long stretch.\n\nSo it needs the stretch. "},{"t":"悩","r":"なや"},{"t":"んだ"},{"t":"末","r":"うれ"},{"t":"に"},{"t":"決","r":"き"},{"t":"めた"},{"t":" works because the worrying went on; a quick decision has no "},{"t":"末","r":"うれ"},{"t":" to arrive at. Unlike "},{"t":"あげく"},{"t":", "},{"t":"末","r":"うれ"},{"t":" passes no judgement on how it turned out."}],"after":[{"t":"The noun in "},{"t":"末","r":"すえ"},{"t":"っ"},{"t":"子","r":"こ"},{"t":" and "},{"t":"週末","r":"しゅうまつ"},{"t":". "},{"t":"末","r":"すえ"},{"t":"に"},{"t":" puts the outcome at the far end of a long stretch.\n\nSo it needs the stretch. "},{"t":"悩","r":"なや"},{"t":"んだ"},{"t":"末","r":"すえ"},{"t":"に"},{"t":"決","r":"き"},{"t":"めた"},{"t":" works because the worrying went on; a quick decision has "},{"t":"no 末","r":"すえ"},{"t":" to"},{"t":" arrive at. Unlike "},{"t":"あげく"},{"t":", 末","r":"すえ"},{"t":" passes"},{"t":" no judgement on how it turned out."}],"changes":[{"word":"あげく, 末 passes","from":[{"t":"あげく"},{"t":", "},{"t":"末","r":"うれ"},{"t":" passes"}],"to":[{"t":"あげく"},{"t":", 末","r":"すえ"},{"t":" passes"}],"why":"末に is すえに."},{"word":"no 末 to","from":[{"t":"no "},{"t":"末","r":"うれ"},{"t":" to"}],"to":[{"t":"no 末","r":"すえ"},{"t":" to"}],"why":"末に is すえに."},{"word":"末に","from":[{"t":"末","r":"うれ"},{"t":"に"}],"to":[{"t":"末","r":"すえ"},{"t":"に"}],"why":"末に is すえに."},{"word":"末に","from":[{"t":"末","r":"うれ"},{"t":"に"}],"to":[{"t":"末","r":"すえ"},{"t":"に"}],"why":"末に is すえに."},{"word":"週末","from":[{"t":"週","r":"しゅう"},{"t":"末","r":"うれ"}],"to":[{"t":"週末","r":"しゅうまつ"}],"why":"Weekend is しゅうまつ."}]}'::jsonb, '{"furigana":[{"t":"The noun in "},{"r":"すえ","t":"末"},{"t":"っ"},{"r":"こ","t":"子"},{"t":" and "},{"r":"しゅう","t":"週"},{"r":"うれ","t":"末"},{"t":". "},{"r":"うれ","t":"末"},{"t":"に"},{"t":" puts the outcome at the far end of a long stretch.\n\nSo it needs the stretch. "},{"r":"なや","t":"悩"},{"t":"んだ"},{"r":"うれ","t":"末"},{"t":"に"},{"r":"き","t":"決"},{"t":"めた"},{"t":" works because the worrying went on; a quick decision has no "},{"r":"うれ","t":"末"},{"t":" to arrive at. Unlike "},{"t":"あげく"},{"t":", "},{"r":"うれ","t":"末"},{"t":" passes no judgement on how it turned out."}]}'::jsonb, 'ai', 900, 'pending'
