-- 〜極まりない: 極まりない, 極 of, 極まる, 極まる, 極まり
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-5a6bd77f540cfb24', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"極まる is \"to reach the furthest point\", the 極 of 北極 and 極端, and 極まり is the point reached. 失礼極まりない says the rudeness has no such point, so it goes on without bound.\n\nRead that way the puzzle disappears: the ない is doing ordinary negative work on a noun, not bleached negation on a verb. It is also why 失礼極まる means much the same thing rather than the opposite; one says the extreme is reached, the other that no bound exists.","point":"〜極まりない","before":[{"t":"極","r":"ごく"},{"t":"まる"},{"t":" is \"to reach the furthest point\", the "},{"t":"極","r":"ごく"},{"t":" of "},{"t":"北極","r":"ほっきょく"},{"t":" and "},{"t":"極端","r":"きょくたん"},{"t":", and "},{"t":"極","r":"ごく"},{"t":"まり"},{"t":" is the point reached. "},{"t":"失礼","r":"しつれい"},{"t":"極","r":"ごく"},{"t":"まりない"},{"t":" says the rudeness has no such point, so it goes on without bound.\n\nRead that way the puzzle disappears: the "},{"t":"ない"},{"t":" is doing ordinary negative work on a noun, not bleached negation on a verb. It is also why "},{"t":"失礼","r":"しつれい"},{"t":"極","r":"ごく"},{"t":"まる"},{"t":" means much the same thing rather than the opposite; one says the extreme is reached, the other that no bound exists."}],"after":[{"t":"極","r":"きわ"},{"t":"まる"},{"t":" is \"to reach the furthest point\", the "},{"t":"極","r":"きょく"},{"t":" of"},{"t":" "},{"t":"北極","r":"ほっきょく"},{"t":" and "},{"t":"極端","r":"きょくたん"},{"t":", and "},{"t":"極","r":"きわ"},{"t":"まり"},{"t":" is the point reached. "},{"t":"失礼","r":"しつれい"},{"t":"極","r":"きわ"},{"t":"まりない"},{"t":" says the rudeness has no such point, so it goes on without bound.\n\nRead that way the puzzle disappears: the "},{"t":"ない"},{"t":" is doing ordinary negative work on a noun, not bleached negation on a verb. It is also why "},{"t":"失礼","r":"しつれい"},{"t":"極","r":"きわ"},{"t":"まる"},{"t":" means much the same thing rather than the opposite; one says the extreme is reached, the other that no bound exists."}],"changes":[{"word":"極まりない","from":[{"t":"極","r":"ごく"},{"t":"まりない"}],"to":[{"t":"極","r":"きわ"},{"t":"まりない"}],"why":"The verb 極まる is きわまる."},{"word":"極 of","from":[{"t":"極","r":"ごく"},{"t":" of"}],"to":[{"t":"極","r":"きょく"},{"t":" of"}],"why":"On-reading きょく in 北極."},{"word":"極まる","from":[{"t":"極","r":"ごく"},{"t":"まる"}],"to":[{"t":"極","r":"きわ"},{"t":"まる"}],"why":"The verb 極まる is きわまる."},{"word":"極まる","from":[{"t":"極","r":"ごく"},{"t":"まる"}],"to":[{"t":"極","r":"きわ"},{"t":"まる"}],"why":"The verb 極まる is きわまる."},{"word":"極まり","from":[{"t":"極","r":"ごく"},{"t":"まり"}],"to":[{"t":"極","r":"きわ"},{"t":"まり"}],"why":"極まり is きわまり."}]}'::jsonb, '{"furigana":[{"r":"ごく","t":"極"},{"t":"まる"},{"t":" is \"to reach the furthest point\", the "},{"r":"ごく","t":"極"},{"t":" of "},{"r":"ほっきょく","t":"北極"},{"t":" and "},{"r":"きょくたん","t":"極端"},{"t":", and "},{"r":"ごく","t":"極"},{"t":"まり"},{"t":" is the point reached. "},{"r":"しつれい","t":"失礼"},{"r":"ごく","t":"極"},{"t":"まりない"},{"t":" says the rudeness has no such point, so it goes on without bound.\n\nRead that way the puzzle disappears: the "},{"t":"ない"},{"t":" is doing ordinary negative work on a noun, not bleached negation on a verb. It is also why "},{"r":"しつれい","t":"失礼"},{"r":"ごく","t":"極"},{"t":"まる"},{"t":" means much the same thing rather than the opposite; one says the extreme is reached, the other that no bound exists."}]}'::jsonb, 'ai', 900, 'pending'
