SELECT 'crq-grammar-f79c4e2bdbb16655', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"Both kanji mean sequence. The noun names how matters are arranged, and every use follows from that.\n\n着き次第 is \"in the order following arrival\", hence as soon as. 天気次第 is according to how things fall. And ご説明した次第です, the one that baffles people, is simply \"such is the sequence of it\", a formal way of closing an account.","point":"〜次第","before":[{"t":"Both kanji mean sequence. The noun names how matters are arranged, and every use follows from that.\n\n"},{"t":"着","r":"き"},{"t":"き"},{"t":"次第","r":"しだい"},{"t":" is \"in the order following arrival\", hence as soon as. "},{"t":"天気","r":"てんき"},{"t":"次第","r":"しだい"},{"t":" is according to how things fall. And "},{"t":"ご"},{"t":"説明","r":"せつめい"},{"t":"した"},{"t":"次第","r":"しだい"},{"t":"です"},{"t":", the one that baffles people, is simply \"such is the sequence of it\", a formal way of closing an account."}],"after":[{"t":"Both kanji mean sequence. The noun names how matters are arranged, and every use follows from that.\n\n"},{"t":"着","r":"つ"},{"t":"き"},{"t":"次第","r":"しだい"},{"t":" is \"in the order following arrival\", hence as soon as. "},{"t":"天気","r":"てんき"},{"t":"次第","r":"しだい"},{"t":" is according to how things fall. And "},{"t":"ご"},{"t":"説明","r":"せつめい"},{"t":"した"},{"t":"次第","r":"しだい"},{"t":"です"},{"t":", the one that baffles people, is simply \"such is the sequence of it\", a formal way of closing an account."}],"changes":[{"word":"着き次第","from":[{"t":"着","r":"き"},{"t":"き"},{"t":"次第","r":"しだい"}],"to":[{"t":"着","r":"つ"},{"t":"き"},{"t":"次第","r":"しだい"}],"why":"FINAL dropped the existing 次第[しだい] ruby"}]}'::jsonb, '{"furigana":[{"t":"Both kanji mean sequence. The noun names how matters are arranged, and every use follows from that.\n\n"},{"r":"き","t":"着"},{"t":"き"},{"r":"しだい","t":"次第"},{"t":" is \"in the order following arrival\", hence as soon as. "},{"r":"てんき","t":"天気"},{"r":"しだい","t":"次第"},{"t":" is according to how things fall. And "},{"t":"ご"},{"r":"せつめい","t":"説明"},{"t":"した"},{"r":"しだい","t":"次第"},{"t":"です"},{"t":", the one that baffles people, is simply \"such is the sequence of it\", a formal way of closing an account."}]}'::jsonb, 'ai', 900, 'pending'
