-- 〜気味: 気 is the same 気 as in
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-675bc923ede24f58', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"気 is the same 気 as in 元気 and 天気; 味 is taste. Together they name a slight quality detectable in something.\n\nWhich is why 気味 is always a small amount and usually an unwelcome one: 風邪気味 is a touch of a cold, 遅れ気味 is running a little late. A trace is what you notice when something is going slightly wrong.","point":"〜気味","before":[{"t":"気","r":"げ"},{"t":" is the same "},{"t":"気","r":"げ"},{"t":" as in "},{"t":"元気","r":"げんき"},{"t":" and "},{"t":"天気","r":"てんき"},{"t":"; "},{"t":"味","r":"あじ"},{"t":" is taste. Together they name a slight quality detectable in something.\n\nWhich is why "},{"t":"気味","r":"ぎみ"},{"t":" is always a small amount and usually an unwelcome one: "},{"t":"風邪","r":"かぜ"},{"t":"気味","r":"ぎみ"},{"t":" is a touch of a cold, "},{"t":"遅","r":"おく"},{"t":"れ"},{"t":"気味","r":"ぎみ"},{"t":" is running a little late. A trace is what you notice when something is going slightly wrong."}],"after":[{"t":"気","r":"き"},{"t":" is the same 気","r":"き"},{"t":" as in"},{"t":" "},{"t":"元気","r":"げんき"},{"t":" and "},{"t":"天気","r":"てんき"},{"t":"; "},{"t":"味","r":"あじ"},{"t":" is taste. Together they name a slight quality detectable in something.\n\nWhich is why "},{"t":"気味","r":"ぎみ"},{"t":" is always a small amount and usually an unwelcome one: "},{"t":"風邪","r":"かぜ"},{"t":"気味","r":"ぎみ"},{"t":" is a touch of a cold, "},{"t":"遅","r":"おく"},{"t":"れ"},{"t":"気味","r":"ぎみ"},{"t":" is running a little late. A trace is what you notice when something is going slightly wrong."}],"changes":[{"word":"気 is the same 気 as in","from":[{"t":"気","r":"げ"},{"t":" is the same "},{"t":"気","r":"げ"},{"t":" as in"}],"to":[{"t":"気","r":"き"},{"t":" is the same 気","r":"き"},{"t":" as in"}],"why":"The 気 of 元気 and 天気 is き."}]}'::jsonb, '{"furigana":[{"r":"げ","t":"気"},{"t":" is the same "},{"r":"げ","t":"気"},{"t":" as in "},{"r":"げんき","t":"元気"},{"t":" and "},{"r":"てんき","t":"天気"},{"t":"; "},{"r":"あじ","t":"味"},{"t":" is taste. Together they name a slight quality detectable in something.\n\nWhich is why "},{"r":"ぎみ","t":"気味"},{"t":" is always a small amount and usually an unwelcome one: "},{"r":"かぜ","t":"風邪"},{"r":"ぎみ","t":"気味"},{"t":" is a touch of a cold, "},{"r":"おく","t":"遅"},{"t":"れ"},{"r":"ぎみ","t":"気味"},{"t":" is running a little late. A trace is what you notice when something is going slightly wrong."}]}'::jsonb, 'ai', 900, 'pending'
