SELECT 'crq-grammar-9ac580a5a4d8adf4', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"橋を渡る, to cross a bridge. にわたって stretches the sentence across a span the way a crossing stretches over water.\n\nSo it needs breadth to cross. 三年にわたって works because three years is a distance; a single moment is not something you can cross, which is why にわたって never takes a point in time.","point":"〜にわたって","before":[{"t":"橋","r":"はし"},{"t":"を"},{"t":"渡","r":"わた"},{"t":"る"},{"t":", to cross a bridge. "},{"t":"にわたって"},{"t":" stretches the sentence across a span the way a crossing stretches over water.\n\nSo it needs breadth to cross. "},{"t":"三","r":"さん"},{"t":"年","r":"とせ"},{"t":"にわたって"},{"t":" works because three years is a distance; a single moment is not something you can cross, which is why "},{"t":"にわたって"},{"t":" never takes a point in time."}],"after":[{"t":"橋","r":"はし"},{"t":"を"},{"t":"渡","r":"わた"},{"t":"る"},{"t":", to cross a bridge. "},{"t":"にわたって"},{"t":" stretches the sentence across a span the way a crossing stretches over water.\n\nSo it needs breadth to cross. "},{"t":"三","r":"さん"},{"t":"年","r":"ねん"},{"t":"にわたって"},{"t":" works because three years is a distance; a single moment is not something you can cross, which is why "},{"t":"にわたって"},{"t":" never takes a point in time."}],"changes":[{"word":"三年","from":[{"t":"三","r":"さん"},{"t":"年","r":"とせ"}],"to":[{"t":"三","r":"さん"},{"t":"年","r":"ねん"}],"why":"Three years is さんねん."}]}'::jsonb, '{"furigana":[{"r":"はし","t":"橋"},{"t":"を"},{"r":"わた","t":"渡"},{"t":"る"},{"t":", to cross a bridge. "},{"t":"にわたって"},{"t":" stretches the sentence across a span the way a crossing stretches over water.\n\nSo it needs breadth to cross. "},{"r":"さん","t":"三"},{"r":"とせ","t":"年"},{"t":"にわたって"},{"t":" works because three years is a distance; a single moment is not something you can cross, which is why "},{"t":"にわたって"},{"t":" never takes a point in time."}]}'::jsonb, 'ai', 900, 'pending'
FROM content.grammar_furigana g, languages l
WHERE g.text_hash = '9ac580a5a4d8adf453ffcca1984f6e91f6f28b5a5a93635d1290da578a4eec7b' AND l.code = 'ja'
  AND g.segments = '[{"r":"はし","t":"橋"},{"t":"を"},{"r":"わた","t":"渡"},{"t":"る"},{"t":", to cross a bridge. "},{"t":"にわたって"},{"t":" stretches the sentence across a span the way a crossing stretches over water.\n\nSo it needs breadth to cross. "},{"r":"さん","t":"三"},{"r":"とせ","t":"年"},{"t":"にわたって"},{"t":" works because three years is a distance; a single moment is not something you can cross, which is why "},{"t":"にわたって"},{"t":" never takes a point in time."}]'::jsonb
