SELECT 'crq-grammar-3b0a2a9c56df5ef1', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"至る is the verb on road signs, 東京に至る. 光栄の至り is honour arrived at its furthest.\n\nIt pairs with の極み as the two formal superlatives, and they differ by image rather than degree: 至り is where something got to, 極み is the top of it. Both belong to speeches and letters, and both take only abstract nouns.","point":"〜の至り","before":[{"t":"至","r":"いた"},{"t":"る"},{"t":" is the verb on road signs, "},{"t":"東","r":"とん"},{"t":"京に"},{"t":"至","r":"いた"},{"t":"る"},{"t":". "},{"t":"光","r":"ひかり"},{"t":"栄","r":"さか"},{"t":"の"},{"t":"至","r":"いた"},{"t":"り"},{"t":" is honour arrived at its furthest.\n\nIt pairs with "},{"t":"の"},{"t":"極","r":"ごく"},{"t":"み"},{"t":" as the two formal superlatives, and they differ by image rather than degree: "},{"t":"至","r":"いた"},{"t":"り"},{"t":" is where something got to, "},{"t":"極","r":"ごく"},{"t":"み"},{"t":" is the top of it. Both belong to speeches and letters, and both take only abstract nouns."}],"after":[{"t":"至","r":"いた"},{"t":"る"},{"t":" is the verb on road signs, "},{"t":"東京","r":"とうきょう"},{"t":"に"},{"t":"至","r":"いた"},{"t":"る"},{"t":". "},{"t":"光栄","r":"こうえい"},{"t":"の"},{"t":"至","r":"いた"},{"t":"り"},{"t":" is honour arrived at its furthest.\n\nIt pairs with "},{"t":"の"},{"t":"極","r":"きわ"},{"t":"み"},{"t":" as the two formal superlatives, and they differ by image rather than degree: "},{"t":"至","r":"いた"},{"t":"り"},{"t":" is where something got to, "},{"t":"極","r":"きわ"},{"t":"み"},{"t":" is the top of it. Both belong to speeches and letters, and both take only abstract nouns."}],"changes":[{"word":"極み","from":[{"t":"極","r":"ごく"},{"t":"み"}],"to":[{"t":"極","r":"きわ"},{"t":"み"}],"why":"極み is きわみ."},{"word":"極み","from":[{"t":"極","r":"ごく"},{"t":"み"}],"to":[{"t":"極","r":"きわ"},{"t":"み"}],"why":"極み is きわみ."},{"word":"東京","from":[{"t":"東","r":"とん"},{"t":"京"}],"to":[{"t":"東京","r":"とうきょう"}],"why":"Tokyo is とうきょう."},{"word":"光栄","from":[{"t":"光","r":"ひかり"},{"t":"栄","r":"さか"}],"to":[{"t":"光栄","r":"こうえい"}],"why":"光栄 is こうえい."}]}'::jsonb, '{"furigana":[{"r":"いた","t":"至"},{"t":"る"},{"t":" is the verb on road signs, "},{"r":"とん","t":"東"},{"t":"京に"},{"r":"いた","t":"至"},{"t":"る"},{"t":". "},{"r":"ひかり","t":"光"},{"r":"さか","t":"栄"},{"t":"の"},{"r":"いた","t":"至"},{"t":"り"},{"t":" is honour arrived at its furthest.\n\nIt pairs with "},{"t":"の"},{"r":"ごく","t":"極"},{"t":"み"},{"t":" as the two formal superlatives, and they differ by image rather than degree: "},{"r":"いた","t":"至"},{"t":"り"},{"t":" is where something got to, "},{"r":"ごく","t":"極"},{"t":"み"},{"t":" is the top of it. Both belong to speeches and letters, and both take only abstract nouns."}]}'::jsonb, 'ai', 900, 'pending'
