  AND g.segments = '[{"r":"いた","t":"至"},{"t":"る"},{"t":" is the verb on road signs, "},{"r":"とん","t":"東"},{"t":"京に"},{"r":"いた","t":"至"},{"t":"る"},{"t":". "},{"r":"ひかり","t":"光"},{"r":"さか","t":"栄"},{"t":"の"},{"r":"いた","t":"至"},{"t":"り"},{"t":" is honour arrived at its furthest.\n\nIt pairs with "},{"t":"の"},{"r":"ごく","t":"極"},{"t":"み"},{"t":" as the two formal superlatives, and they differ by image rather than degree: "},{"r":"いた","t":"至"},{"t":"り"},{"t":" is where something got to, "},{"r":"ごく","t":"極"},{"t":"み"},{"t":" is the top of it. Both belong to speeches and letters, and both take only abstract nouns."}]'::jsonb
