-- 〜を込めて: 心を込めて, 弾を込める
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-ebece6c1d3a9613d', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"弾を込める is loading a round. 心を込めて is loading the feeling in, and the metaphor is as physical in Japanese as it sounds.\n\nWhich is why を込めて only takes feelings and intentions, never facts or objects: what you load a thing with is something that fills it. The related 込む as a suffix (詰め込む, 話し込む) is the same verb doing the same work.","point":"〜を込めて","before":[{"t":"弾","r":"だん"},{"t":"を"},{"t":"込","r":"こ"},{"t":"める"},{"t":" is loading a round. "},{"t":"心","r":"しん"},{"t":"を"},{"t":"込","r":"こ"},{"t":"めて"},{"t":" is loading the feeling in, and the metaphor is as physical in Japanese as it sounds.\n\nWhich is why "},{"t":"を"},{"t":"込","r":"こ"},{"t":"めて"},{"t":" only takes feelings and intentions, never facts or objects: what you load a thing with is something that fills it. The related "},{"t":"込","r":"こ"},{"t":"む"},{"t":" as a suffix ("},{"t":"詰","r":"つ"},{"t":"め"},{"t":"込","r":"こ"},{"t":"む"},{"t":", "},{"t":"話","r":"はな"},{"t":"し"},{"t":"込","r":"こ"},{"t":"む"},{"t":") is the same verb doing the same work."}],"after":[{"t":"弾","r":"たま"},{"t":"を"},{"t":"込","r":"こ"},{"t":"める"},{"t":" is loading a round. "},{"t":"心","r":"こころ"},{"t":"を"},{"t":"込","r":"こ"},{"t":"めて"},{"t":" is loading the feeling in, and the metaphor is as physical in Japanese as it sounds.\n\nWhich is why "},{"t":"を"},{"t":"込","r":"こ"},{"t":"めて"},{"t":" only takes feelings and intentions, never facts or objects: what you load a thing with is something that fills it. The related "},{"t":"込","r":"こ"},{"t":"む"},{"t":" as a suffix ("},{"t":"詰","r":"つ"},{"t":"め"},{"t":"込","r":"こ"},{"t":"む"},{"t":", "},{"t":"話","r":"はな"},{"t":"し"},{"t":"込","r":"こ"},{"t":"む"},{"t":") is the same verb doing the same work."}],"changes":[{"word":"心を込めて","from":[{"t":"心","r":"しん"},{"t":"を"},{"t":"込","r":"こ"},{"t":"めて"}],"to":[{"t":"心","r":"こころ"},{"t":"を"},{"t":"込","r":"こ"},{"t":"めて"}],"why":"心 is こころ."},{"word":"弾を込める","from":[{"t":"弾","r":"だん"},{"t":"を"},{"t":"込","r":"こ"},{"t":"める"}],"to":[{"t":"弾","r":"たま"},{"t":"を"},{"t":"込","r":"こ"},{"t":"める"}],"why":"FINAL dropped the reading on 込"}]}'::jsonb, '{"furigana":[{"r":"だん","t":"弾"},{"t":"を"},{"r":"こ","t":"込"},{"t":"める"},{"t":" is loading a round. "},{"r":"しん","t":"心"},{"t":"を"},{"r":"こ","t":"込"},{"t":"めて"},{"t":" is loading the feeling in, and the metaphor is as physical in Japanese as it sounds.\n\nWhich is why "},{"t":"を"},{"r":"こ","t":"込"},{"t":"めて"},{"t":" only takes feelings and intentions, never facts or objects: what you load a thing with is something that fills it. The related "},{"r":"こ","t":"込"},{"t":"む"},{"t":" as a suffix ("},{"r":"つ","t":"詰"},{"t":"め"},{"r":"こ","t":"込"},{"t":"む"},{"t":", "},{"r":"はな","t":"話"},{"t":"し"},{"r":"こ","t":"込"},{"t":"む"},{"t":") is the same verb doing the same work."}]}'::jsonb, 'ai', 900, 'pending'
