-- 〜に難くない: 難くない
INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, current, origin, priority, status)
SELECT 'crq-grammar-c4624098485cbae8', l.id, 'grammar_furigana', g.text_hash, 'update', '{"type":"grammar","text":"がたい at N3 says hard to bring oneself to. かたくない says the opposite: not hard at all.\n\n想像に難くない is \"it is not difficult to imagine\", a formal way of saying anyone can see it. Same kanji, same meaning, and the whole pattern is the negative doing its ordinary work.","point":"〜に難くない","before":[{"t":"がたい"},{"t":" at N3 says hard to bring oneself to. "},{"t":"かたくない"},{"t":" says the opposite: not hard at all.\n\n"},{"t":"想像","r":"そうぞう"},{"t":"に"},{"t":"難","r":"なん"},{"t":"くない"},{"t":" is \"it is not difficult to imagine\", a formal way of saying anyone can see it. Same kanji, same meaning, and the whole pattern is the negative doing its ordinary work."}],"after":[{"t":"がたい"},{"t":" at N3 says hard to bring oneself to. "},{"t":"かたくない"},{"t":" says the opposite: not hard at all.\n\n"},{"t":"想像","r":"そうぞう"},{"t":"に"},{"t":"難","r":"かた"},{"t":"くない"},{"t":" is \"it is not difficult to imagine\", a formal way of saying anyone can see it. Same kanji, same meaning, and the whole pattern is the negative doing its ordinary work."}],"changes":[{"word":"難くない","from":[{"t":"難","r":"なん"},{"t":"くない"}],"to":[{"t":"難","r":"かた"},{"t":"くない"}],"why":"難くない is かたくない."}]}'::jsonb, '{"furigana":[{"t":"がたい"},{"t":" at N3 says hard to bring oneself to. "},{"t":"かたくない"},{"t":" says the opposite: not hard at all.\n\n"},{"r":"そうぞう","t":"想像"},{"t":"に"},{"r":"なん","t":"難"},{"t":"くない"},{"t":" is \"it is not difficult to imagine\", a formal way of saying anyone can see it. Same kanji, same meaning, and the whole pattern is the negative doing its ordinary work."}]}'::jsonb, 'ai', 900, 'pending'
